// phaneslight-generated v3.7.2 api-diff
// Diffs the current API surface against a git ref. Outputs added, removed and changed
// signatures with file references, for <projectSlug>-closure to cross-check against the
// active plan's API-changes section.
//
// The OLD surface is extracted from that ref's SOURCE, never from a historical baseline
// file. This is deliberate and load-bearing: .phaneslight/registry/ is gitignored in this
// project, so no historical copy exists to read -- and even where one did, a baseline
// committed at some past moment proves only what someone regenerated then, while the
// source at a ref is the truth about that ref.
//
// Usage: node .phaneslight/scripts/api-diff.js <since-ref> [module]
// Exit 0 always (advisory): drift is REPORTED, never enforced. Closure grades it.

'use strict';

const path = require('path');
const lib = require(path.join(__dirname, 'registry-lib.js'));

const root = lib.findRoot();
if (!root) {
  console.error('api-diff: .phaneslight/config.json not found from this directory');
  process.exit(1);
}

const ref = process.argv[2];
if (!ref) {
  console.error('api-diff: usage: phaneslight api-diff <since-ref> [module]');
  console.error('api-diff: <since-ref> is any git ref -- a sha, tag, branch, or HEAD~N.');
  process.exit(1);
}
const onlyModule = process.argv[3] || null;

let config;
try {
  config = lib.loadConfig(root);
} catch (e) {
  console.error('api-diff: .phaneslight/config.json unreadable or malformed: ' + e.message);
  process.exit(1);
}

const ts = lib.loadTypeScript(root);

let oldBuild;
try {
  oldBuild = lib.buildSlices(lib.gitRefSource(root, ref), config, ts);
} catch (e) {
  console.error(e.message);
  process.exit(1);
}
const newBuild = lib.buildSlices(lib.workingTreeSource(root, config.modulePaths), config, ts);

// Key on file + name: the same exported name in two files is two contracts, and a move
// between files is a removal plus an addition, which is exactly what a reader needs to see.
const keyOf = e => e.f + '::' + e.n;

function diffSlice(oldEntries, newEntries) {
  const o = new Map(oldEntries.map(e => [keyOf(e), e]));
  const n = new Map(newEntries.map(e => [keyOf(e), e]));
  const added = [];
  const removed = [];
  const changed = [];
  for (const [k, e] of n) if (!o.has(k)) added.push(e);
  for (const [k, e] of o) if (!n.has(k)) removed.push(e);
  for (const [k, e] of n) {
    const prev = o.get(k);
    // The hash is of the whole declaration; the signature is body-stripped. Comparing the
    // hash alone would flag every body-only refactor as an API change, so a difference is
    // only reported when the SIGNATURE moved.
    if (prev && prev.h !== e.h && prev.s !== e.s) changed.push({ before: prev, after: e });
  }
  return { added, removed, changed };
}

const names = [...newBuild.slices.keys()];
let totalAdded = 0, totalRemoved = 0, totalChanged = 0;
const report = [];

for (const name of names) {
  if (onlyModule && onlyModule !== name) continue;
  const d = diffSlice(oldBuild.slices.get(name) || [], newBuild.slices.get(name) || []);
  if (!d.added.length && !d.removed.length && !d.changed.length) continue;
  totalAdded += d.added.length;
  totalRemoved += d.removed.length;
  totalChanged += d.changed.length;
  report.push({ name, ...d });
}

console.log('api-diff: ' + ref + ' -> working tree');
console.log('api-diff: extractor ' + (ts ? 'tsc-api' : 'regex-fallback') +
  ((oldBuild.degraded || newBuild.degraded) ? ' [DEGRADED -- typescript not resolvable; treat this diff as indicative only]' : ''));
console.log('');

if (!report.length) {
  console.log('No API surface changes detected across ' + names.length + ' slice(s).');
  console.log('');
  console.log('api-diff: added 0, removed 0, changed 0');
  process.exit(0);
}

for (const slice of report) {
  console.log('=== ' + slice.name + ' ===');
  // Removals first: a removed export is the change most likely to break a caller, so it
  // is the one a reader must not have to scroll past an addition list to find.
  for (const e of slice.removed) console.log('  REMOVED  ' + e.k + ' ' + e.n + '  (' + e.f + ':' + e.l + ')');
  for (const c of slice.changed) {
    console.log('  CHANGED  ' + c.after.k + ' ' + c.after.n + '  (' + c.after.f + ':' + c.after.l + ')');
    console.log('           before: ' + c.before.s);
    console.log('           after:  ' + c.after.s);
  }
  for (const e of slice.added) console.log('  ADDED    ' + e.k + ' ' + e.n + '  (' + e.f + ':' + e.l + ')');
  console.log('');
}

console.log('api-diff: added ' + totalAdded + ', removed ' + totalRemoved + ', changed ' + totalChanged +
  ' across ' + report.length + ' slice(s)');
console.log('');
console.log('Cross-check every line above against the active plan\'s API-changes section and report:');
console.log('  planned-and-found / planned-and-missing / UNPLANNED ADDITIONS.');
console.log('An unplanned change is drift even when it compiles.');
process.exit(0);

#!/usr/bin/env node
// phaneslight-template v3.7.2 cli
// Cross-shell entry point: `node .phaneslight/scripts/cli.js <subcommand> [args]` resolves identically
// in PowerShell, cmd, and Git Bash, so agents never depend on PATH or a shell-specific launcher.
// It forwards to the platform dispatcher sibling (phaneslight.ps1 on Windows, the POSIX `phaneslight`
// elsewhere), which owns all subcommand routing: one source of truth, no duplicated dispatch logic.
'use strict';

const { spawnSync } = require('child_process');
const path = require('path');

const here = __dirname;
const args = process.argv.slice(2);
const isWindows = process.platform === 'win32';

let cmd;
let cmdArgs;
if (isWindows) {
  cmd = 'powershell';
  cmdArgs = ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', path.join(here, 'phaneslight.ps1'), ...args];
} else {
  cmd = 'sh';
  cmdArgs = [path.join(here, 'phaneslight'), ...args];
}

const result = spawnSync(cmd, cmdArgs, { stdio: 'inherit' });
if (result.error) {
  process.stderr.write('cli.js: failed to launch the phaneslight dispatcher (' + result.error.message + ')\n');
  process.exit(1);
}
process.exit(result.status === null ? 1 : result.status);

// phaneslight-generated v3.7.2 regen-registry
// Regenerates the API baseline at .phaneslight/registry/<module>.json from current source.
//
// generatedNotFetched: the extractors are language-specific, so no language-independent
// template can exist for this. Authored for THIS project: TypeScript/TSX via the compiler
// API (already a devDependency), an ordered SQL migration ledger, and a network-contract
// slice covering Next.js route handlers and 'use server' action modules.
//
// The baseline is <projectSlug>-closure's diff substrate and list-apis' data source. It is
// NOT documentation: no agent reads these files directly, and it lives outside
// documentation/ so it escapes every doc-discipline rule.
//
// Usage: node .phaneslight/scripts/regen-registry.js [module]

'use strict';

const fs = require('fs');
const path = require('path');
const lib = require(path.join(__dirname, 'registry-lib.js'));

const root = lib.findRoot();
if (!root) {
  console.error('regen-registry: .phaneslight/config.json not found from this directory');
  process.exit(1);
}

let config;
try {
  config = lib.loadConfig(root);
} catch (e) {
  // Refuse rather than regenerate against a config we cannot trust: a baseline built from
  // a half-read config would silently omit whole modules and then read as clean.
  console.error('regen-registry: .phaneslight/config.json unreadable or malformed: ' + e.message);
  process.exit(1);
}

const modules = Array.isArray(config.modules) ? config.modules : [];
const only = process.argv[2] || null;
if (only && only !== 'api-contract' && !modules.includes(only)) {
  console.error("regen-registry: unknown module '" + only + "'. Known: " + modules.join(' ') + ' api-contract');
  process.exit(1);
}

const ts = lib.loadTypeScript(root);
const source = lib.workingTreeSource(root, config.modulePaths);
const { slices, stats, degraded } = lib.buildSlices(source, config, ts);

const registryDir = path.join(root, '.phaneslight', 'registry');
fs.mkdirSync(registryDir, { recursive: true });

const stamp = new Date().toISOString();
let wrote = 0;

for (const [name, entries] of slices) {
  if (only && only !== name) continue;
  const st = stats.get(name) || { fileCount: 0, parsedCount: 0, unextracted: {} };
  const unx = st.unextracted || {};
  const unxTotal = Object.values(unx).reduce((a, b) => a + b, 0);
  const payload = {
    module: name,
    generatedAt: stamp,
    extractor: ts ? 'tsc-api' : 'regex-fallback',
    degraded,
    paths: (config.modulePaths || {})[name] || [],
    fileCount: st.fileCount,
    parsedCount: st.parsedCount,
    unextractedCount: unxTotal,
    unextractedByExtension: unx,
    coverageNote: unxTotal
      ? 'This slice covers .ts/.tsx/.sql only. ' + unxTotal + ' file(s) in this module were NOT examined (' +
        Object.entries(unx).map(([k, v]) => v + ' .' + k).join(', ') +
        '). A low or zero export count here does NOT mean the module has no surface.'
      : 'Every file in this module was examined.',
    exportCount: entries.length,
    exports: entries
  };
  if (name === 'api-contract') {
    payload.kind = 'next-route-handlers + server-actions';
    payload.note = 'No OpenAPI or GraphQL SDL exists in this repository, so the network contract is extracted from the route and action definitions themselves.';
    payload.httpRoutes = entries.filter(e => e.k === 'http-route').length;
    payload.serverActions = entries.filter(e => e.k === 'server-action').length;
  }
  fs.writeFileSync(path.join(registryDir, name + '.json'), JSON.stringify(payload, null, 1) + '\n', 'utf8');
  wrote++;
  console.log(name + ': ' + entries.length + ' entries from ' + st.parsedCount + '/' + st.fileCount + ' files' +
    (unxTotal ? '  [' + unxTotal + ' not extracted: ' + Object.entries(unx).map(([k, v]) => v + ' .' + k).join(', ') + ']' : ''));
}

if (degraded) {
  console.log('regen-registry: DEGRADED -- the typescript compiler API was not resolvable from ' + root + '.');
  console.log('regen-registry: the regex fallback ran instead. Run `npm install`, then regenerate for a full baseline.');
}
console.log('regen-registry: wrote ' + wrote + ' slice(s) to .phaneslight/registry/');
process.exit(0);

// phaneslight-generated v3.7.2 registry-lib
// Shared extraction library for regen-registry and api-diff.
//
// Both scripts must run the SAME extractors, but over different sources: regen-registry
// reads the working tree, api-diff reads a git ref. Duplicating the extractors would mean
// a diff computed by one implementation against a baseline computed by another, and every
// divergence between the two would surface as phantom API drift. So the extractors live
// here once and take an injectable source: {listFiles(), readFile(rel)}.
//
// Not a dispatcher subcommand. It has no .ps1/.sh sibling and is never invoked directly.

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execFileSync } = require('child_process');

// ---------------------------------------------------------------- root + config

function findRoot(start) {
  let d = start || process.cwd();
  for (;;) {
    if (fs.existsSync(path.join(d, '.phaneslight', 'config.json'))) return d;
    const p = path.dirname(d);
    if (!p || p === d) return null;
    d = p;
  }
}

function loadConfig(root) {
  return JSON.parse(fs.readFileSync(path.join(root, '.phaneslight', 'config.json'), 'utf8'));
}

// Resolved from the PROJECT's node_modules, never installed by these scripts. Absence is
// a documented degrade, not a failure; callers record which extractor produced a slice so
// a degraded result can never be mistaken for a full one.
function loadTypeScript(root) {
  try {
    return require(require.resolve('typescript', { paths: [root] }));
  } catch (_) {
    return null;
  }
}

// ---------------------------------------------------------------- sources

function workingTreeSource(root, modulePaths) {
  let files;
  try {
    files = execFileSync('git', ['ls-files'], { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 })
      .split('\n').map(s => s.trim()).filter(Boolean);
  } catch (_) {
    // No git, or not a repository. Walk the configured module paths instead: slower, and
    // it cannot honour .gitignore, but a baseline from a walk beats no baseline at all.
    const acc = [];
    const walk = (rel) => {
      const abs = path.join(root, rel);
      let st;
      try { st = fs.statSync(abs); } catch (_) { return; }
      if (st.isDirectory()) {
        if (/(^|\/)(node_modules|\.next|\.git)$/.test(rel)) return;
        for (const e of fs.readdirSync(abs)) walk(rel.replace(/\\/g, '/') + '/' + e);
      } else acc.push(rel.replace(/\\/g, '/'));
    };
    for (const paths of Object.values(modulePaths || {})) for (const p of paths) walk(p);
    files = acc;
  }
  return {
    label: 'working tree',
    listFiles: () => files,
    readFile: (rel) => {
      try { return fs.readFileSync(path.join(root, rel), 'utf8'); } catch (_) { return null; }
    }
  };
}

function gitRefSource(root, ref) {
  let files;
  try {
    files = execFileSync('git', ['ls-tree', '-r', '--name-only', ref], {
      cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024
    }).split('\n').map(s => s.trim()).filter(Boolean);
  } catch (e) {
    const err = new Error("api-diff: cannot list files at ref '" + ref + "'. Is it a valid git ref?");
    err.cause = e;
    throw err;
  }
  const cache = new Map();
  return {
    label: ref,
    listFiles: () => files,
    readFile: (rel) => {
      if (cache.has(rel)) return cache.get(rel);
      let text = null;
      try {
        text = execFileSync('git', ['show', ref + ':' + rel], {
          cwd: root, encoding: 'utf8', maxBuffer: 32 * 1024 * 1024
        });
      } catch (_) { text = null; }
      cache.set(rel, text);
      return text;
    }
  };
}

// ---------------------------------------------------------------- helpers

const sha = s => crypto.createHash('sha256').update(s).digest('hex').slice(0, 12);
const squash = s => s.replace(/\s+/g, ' ').trim();
const cap = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);

const isTs = f => /\.(ts|tsx)$/.test(f);
const isSql = f => /\.sql$/.test(f);
// A test file is not API surface. Excluding them keeps the baseline about the contract
// the project publishes rather than about how it is checked.
const isTest = f => /\.(test|spec)\.(ts|tsx)$/.test(f) || /(^|\/)tests?\//.test(f);

const VERBS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS'];

// ---------------------------------------------------------------- extractor

function makeExtractor(ts) {
  function hasMod(node, kind) {
    return !!(node.modifiers || []).some(m => m.kind === kind);
  }

  // Strips a function/class BODY out of the declaration text. Drift detection cares about
  // the shape of the contract, not its implementation: a refactor that rewrites a body
  // without touching the signature must NOT read as an API change, or every refactor
  // becomes a false drift flag and the signal stops being worth reading.
  function signatureOf(node, src) {
    const text = node.getText(src);
    const brace = text.indexOf('{');
    const arrow = text.indexOf('=>');
    let cut = text.length;
    if (node.body && brace !== -1 && (arrow === -1 || brace < arrow)) cut = brace;
    return cap(squash(text.slice(0, cut)), 220);
  }

  function memberDigest(src, members) {
    const names = (members || [])
      .map(m => (m.name && m.name.getText ? m.name.getText(src) : null))
      .filter(Boolean);
    return cap(squash(names.join(', ')), 220);
  }

  // Fallback only. Declared-export forms are regular enough to catch with line anchors;
  // multiline signatures and the word 'export' inside a string or comment are its known
  // blind spots, which is why any slice built this way is marked degraded.
  function extractRegex(rel, text) {
    const out = [];
    const re = /^\s*export\s+(?:default\s+)?(?:declare\s+)?(?:async\s+)?(function|class|interface|type|enum|const|let|var)\s+([A-Za-z0-9_$]+)/;
    text.split('\n').forEach((line, i) => {
      const m = re.exec(line);
      if (!m) return;
      const k = (m[1] === 'let' || m[1] === 'var') ? 'const' : m[1];
      out.push({ n: m[2], k, f: rel, l: i + 1, s: cap(squash(line), 220), h: sha(squash(line)) });
    });
    return out;
  }

  function extractTs(rel, text) {
    if (text == null) return { exports: [] };
    if (!ts) return { exports: extractRegex(rel, text), degraded: true };

    let src;
    try {
      src = ts.createSourceFile(rel, text, ts.ScriptTarget.Latest, true,
        rel.endsWith('.tsx') ? ts.ScriptKind.TSX : ts.ScriptKind.TS);
    } catch (_) {
      return { exports: extractRegex(rel, text), degraded: true };
    }

    const K = ts.SyntaxKind;
    const out = [];
    const lineOf = n => src.getLineAndCharacterOfPosition(n.getStart(src)).line + 1;
    const push = (name, kind, node, signature) =>
      out.push({ n: name, k: kind, f: rel, l: lineOf(node), s: signature, h: sha(squash(node.getText(src))) });

    for (const st of src.statements) {
      const exported = hasMod(st, K.ExportKeyword);
      const dflt = hasMod(st, K.DefaultKeyword);

      if (st.kind === K.FunctionDeclaration && exported) {
        push(dflt ? 'default' : (st.name ? st.name.getText(src) : 'default'), 'function', st, signatureOf(st, src));
      } else if (st.kind === K.ClassDeclaration && exported) {
        push(dflt ? 'default' : (st.name ? st.name.getText(src) : 'default'), 'class', st, memberDigest(src, st.members));
      } else if (st.kind === K.InterfaceDeclaration && exported) {
        push(st.name.getText(src), 'interface', st, memberDigest(src, st.members));
      } else if (st.kind === K.TypeAliasDeclaration && exported) {
        push(st.name.getText(src), 'type', st, cap(squash(st.type.getText(src)), 220));
      } else if (st.kind === K.EnumDeclaration && exported) {
        push(st.name.getText(src), 'enum', st, memberDigest(src, st.members));
      } else if (st.kind === K.VariableStatement && exported) {
        for (const d of st.declarationList.declarations) {
          const name = d.name.getText(src);
          const typed = d.type ? ': ' + squash(d.type.getText(src)) : '';
          const init = d.initializer ? signatureOf(d.initializer, src) : '';
          push(name, 'const', d, cap(squash(name + typed + (init ? ' = ' + init : '')), 220));
        }
      } else if (st.kind === K.ExportDeclaration && st.exportClause && st.exportClause.elements) {
        // `export { a, b as c }` names a contract this file publishes even though it
        // declares none of it, so it belongs in the baseline.
        for (const el of st.exportClause.elements) push(el.name.getText(src), 're-export', el, squash(el.getText(src)));
      } else if (st.kind === K.ExportDeclaration && !st.exportClause && st.moduleSpecifier) {
        push('*', 'star-re-export', st, squash(st.getText(src)));
      } else if (st.kind === K.ExportAssignment) {
        push('default', 'default', st, cap(squash(st.expression.getText(src)), 220));
      }
    }
    return { exports: out };
  }

  // Migrations are ordered and append-only. The contract that must not drift is not the
  // DDL but the SET: a migration renamed, reordered, removed, or EDITED AFTER BEING
  // APPLIED is the failure this catches. Content is hashed, never parsed -- migrate.ts
  // already refuses an edited applied migration, and this makes the same drift visible at
  // close time rather than at the next migration run.
  function extractSql(rel, text) {
    if (text == null) return null;
    return {
      n: path.posix.basename(rel),
      k: 'migration',
      f: rel,
      l: 1,
      s: 'lines: ' + text.split('\n').length,
      h: sha(text.replace(/\r\n/g, '\n'))
    };
  }

  function routePathOf(rel) {
    // src/app/api/coaches/[id]/opponent-record/route.ts -> /api/coaches/[id]/opponent-record
    let p = rel.replace(/^src\/app/, '').replace(/\/route\.tsx?$/, '');
    p = p.replace(/\/\([^/]+\)/g, ''); // route groups are not part of the URL
    return p || '/';
  }

  function extractRoutes(rel, text) {
    if (text == null) return [];
    const isRoute = /\/route\.tsx?$/.test(rel);
    const isAction = /^\s*['"]use server['"]/m.test(text);
    if (!isRoute && !isAction) return [];
    const out = [];
    for (const e of extractTs(rel, text).exports) {
      if (isRoute && VERBS.includes(e.n)) {
        out.push({ n: e.n + ' ' + routePathOf(rel), k: 'http-route', f: rel, l: e.l, s: e.s, h: e.h });
      } else if (isAction && (e.k === 'function' || e.k === 'const')) {
        out.push({ n: e.n, k: 'server-action', f: rel, l: e.l, s: e.s, h: e.h });
      }
    }
    return out;
  }

  return { extractTs, extractSql, extractRoutes };
}

// ---------------------------------------------------------------- slice building

function filesForModule(allFiles, modulePaths, mod) {
  const prefixes = (modulePaths[mod] || []).map(p => p.replace(/\\/g, '/').replace(/\/+$/, ''));
  if (!prefixes.length) return [];
  return allFiles.filter(f => prefixes.some(p => f === p || f.startsWith(p + '/')));
}

// Builds every slice for one source. Returns {slices: Map<name, entries[]>, degraded, stats}.
function buildSlices(source, config, ts) {
  const ex = makeExtractor(ts);
  const modules = Array.isArray(config.modules) ? config.modules : [];
  const modulePaths = config.modulePaths || {};
  const all = source.listFiles();
  const slices = new Map();
  const stats = new Map();
  let degraded = !ts;

  for (const mod of modules) {
    const files = filesForModule(all, modulePaths, mod);
    const entries = [];
    const unextracted = {};
    let parsed = 0;
    for (const f of files) {
      if (isTs(f) && !isTest(f)) {
        const r = ex.extractTs(f, source.readFile(f));
        if (r.degraded) degraded = true;
        entries.push(...r.exports);
        parsed++;
      } else if (isSql(f)) {
        const e = ex.extractSql(f, source.readFile(f));
        if (e) { entries.push(e); parsed++; }
      } else {
        // Counted, never silently dropped. A slice reading "0 entries from 0 files" is
        // otherwise indistinguishable from "this module has no API surface", and this
        // project has whole modules of Python and shell (tools/migration is 33 .py files)
        // that these extractors do not cover. An unverified negative stated as a fact is
        // exactly the failure the bootstrap-snapshot rule warns about, so the slice
        // records WHAT it did not look at rather than implying there was nothing to see.
        const ext = (f.match(/\.([A-Za-z0-9]+)$/) || [null, 'none'])[1].toLowerCase();
        unextracted[ext] = (unextracted[ext] || 0) + 1;
      }
    }
    entries.sort((a, b) => (a.f === b.f ? a.n.localeCompare(b.n) : a.f.localeCompare(b.f)));
    slices.set(mod, entries);
    stats.set(mod, { fileCount: files.length, parsedCount: parsed, unextracted });
  }

  // The network-facing contract is a slice of its own: for a project that exposes an API,
  // the PUBLIC contract is what must not drift silently, and internal exported symbols are
  // a different surface. A removed verb or a changed action signature shows up here even
  // when the symbol extraction above looks unchanged.
  const routes = [];
  for (const f of all) {
    if (!isTs(f) || isTest(f) || !/^src\/app\//.test(f)) continue;
    routes.push(...ex.extractRoutes(f, source.readFile(f)));
  }
  routes.sort((a, b) => (a.n === b.n ? a.f.localeCompare(b.f) : a.n.localeCompare(b.n)));
  slices.set('api-contract', routes);
  stats.set('api-contract', { fileCount: routes.length, parsedCount: routes.length });

  return { slices, stats, degraded };
}

module.exports = {
  findRoot, loadConfig, loadTypeScript,
  workingTreeSource, gitRefSource,
  makeExtractor, buildSlices, filesForModule,
  isTs, isSql, isTest, sha, squash, cap
};

'use client';

import Link, { useLinkStatus } from 'next/link';
import { usePathname } from 'next/navigation';
import { useEffect, useState } from 'react';

import { adminLogout } from '@/app/admin/logout-action';
import {
  isCurrentAdminPath,
  type AdminNavGroup,
} from '@/app/admin/nav-model';

/**
 * The admin sidebar.
 *
 * The admin area used to navigate from a single row of interpuncted links in
 * the breadcrumb slot. That worked while there were four destinations; there
 * are now ten across four unrelated concerns, and a flat row gives no clue
 * which of them is which — "Beta access" and "Page content" read as peers of
 * "Upload" when one is people, one is publishing and one is data.
 *
 * So: grouped, down the side, with the current page marked. Collapsing is
 * REMEMBERED rather than reset per page, because the reason to collapse it is
 * a wide form (the content editor, the settings screen) and those are exactly
 * the pages a person moves between while working. Held in localStorage rather
 * than a cookie: it is a display preference, it never needs to reach the
 * server, and a cookie would make every admin response vary on it.
 *
 * Read in an effect rather than during render. The server has no localStorage,
 * so consulting it while rendering would hydrate a different tree than was
 * sent; the cost of doing it properly is one frame with the sidebar open,
 * which is the state most people want anyway.
 */

const STORAGE_KEY = 'afldb.admin.nav';

/**
 * Pending feedback for the link that was actually clicked.
 *
 * This is what replaced src/app/admin/loading.tsx, and the replacement was
 * forced rather than chosen (AFLDB-ISSUE-166). A route-level loading file is
 * a Suspense boundary, and React commits the shell -- HTTP status line and
 * all -- as soon as its fallback is ready, which is BEFORE the page component
 * and therefore before the page's requireCapability() has run. Next can then
 * no longer express the guard's redirect() as a 307, and degrades it to a
 * <meta http-equiv="refresh"> inside a 200 OK body. Browsers obeyed that a
 * second later; fetch(), curl, crawlers and monitors obeyed nothing and
 * recorded a denied admin route as a success.
 *
 * useLinkStatus is Next's own answer for precisely the case that boundary
 * covered -- a dynamic destination with no loading.js -- and it runs on the
 * client, so it opens no server boundary above the guards. The feedback also
 * lands on the link the reader pressed rather than blanking the whole page,
 * which is the better answer to the 2026-08-19 report that started this
 * ("I clicked it and nothing happened").
 *
 * Must be a child of the <Link> it reports on: the hook reads the pending
 * state from the Link above it, and returns `false` anywhere else.
 */
function NavPending() {
  const { pending } = useLinkStatus();
  if (!pending) return null;
  // role="status" so the wait is announced, not only drawn.
  return <span className="admin-nav-pending" role="status" aria-label="Loading" />;
}

export function AdminNav({
  groups,
  email,
  roleLabel,
}: {
  groups: AdminNavGroup[];
  email: string;
  roleLabel: string;
}) {
  const pathname = usePathname();
  const [open, setOpen] = useState(true);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    try {
      const stored = window.localStorage.getItem(STORAGE_KEY);
      // Default to collapsed on a narrow screen, where a 15rem sidebar above
      // the page would push the actual work off the first screenful.
      if (stored === 'open' || stored === 'closed') setOpen(stored === 'open');
      else setOpen(window.innerWidth > 760);
    } catch {
      // Private browsing, or storage disabled. The default stands.
    }
    setReady(true);
  }, []);

  function toggle() {
    setOpen((previous) => {
      const next = !previous;
      try {
        window.localStorage.setItem(STORAGE_KEY, next ? 'open' : 'closed');
      } catch {
        // Not being able to remember the choice does not stop it being made.
      }
      return next;
    });
  }

  return (
    <nav
      className={`admin-nav${open ? '' : ' collapsed'}`}
      aria-label="Admin sections"
      // Until the stored preference has been read, the sidebar is in its
      // server-rendered state and a transition would animate a value nobody
      // chose. See `.admin-nav:not(.ready)` in globals.css.
      data-ready={ready ? 'yes' : 'no'}
    >
      <div className="admin-nav-head">
        <button
          type="button"
          className="admin-nav-toggle"
          onClick={toggle}
          aria-expanded={open}
          aria-controls="admin-nav-body"
          title={open ? 'Collapse the menu' : 'Expand the menu'}
        >
          <span aria-hidden="true">{open ? '«' : '»'}</span>
          <span className="visually-hidden">
            {open ? 'Collapse the admin menu' : 'Expand the admin menu'}
          </span>
        </button>
        {open && <span className="admin-nav-brand">Admin</span>}
      </div>

      <div id="admin-nav-body" className="admin-nav-body" hidden={!open}>
        {groups.map((group) => (
          <div key={group.id} className="admin-nav-group">
            <h2 className="admin-nav-group-label">{group.label}</h2>
            <ul>
              {group.links.map((link) => (
                <li key={link.href}>
                  <Link
                    href={link.href}
                    aria-current={isCurrentAdminPath(pathname, link) ? 'page' : undefined}
                  >
                    {link.label}
                    <NavPending />
                  </Link>
                </li>
              ))}
            </ul>
          </div>
        ))}

        <div className="admin-nav-group admin-nav-foot">
          <p className="admin-nav-who">
            {email}
            <span>{roleLabel}</span>
          </p>
          <ul>
            <li><Link href="/">View site</Link></li>
          </ul>
          {/* A server action in a client component: the form posts to it
              directly, so signing out needs no route of its own. */}
          <form action={adminLogout}>
            <button className="btn btn-secondary" type="submit">Sign out</button>
          </form>
        </div>
      </div>
    </nav>
  );
}

