'use client';

import { useEffect, useState } from 'react';

/**
 * One collapsible section of a long admin form.
 *
 * The content editor is eight sections and some nine hundred lines of form;
 * the settings screen is not much shorter. Editing the footer meant scrolling
 * past the whole page's copy, and finding the hero statistics meant scrolling
 * past the footer. Sections that fold solve that, and folding is only useful
 * if it STAYS folded — so each one remembers its own state under its own key,
 * and a person who only ever touches the hero can leave everything else shut.
 *
 * `<details>`, not a div and a state variable, so the section still works
 * before hydration, keyboard support comes from the browser, and — the part
 * that matters inside a form — the fields stay in the DOM while collapsed and
 * therefore still submit. A React-conditional section would silently drop
 * everything the author had typed into it.
 *
 * The stored state is read in an effect for the reason `AdminNav` gives: the
 * server cannot see localStorage, so consulting it during render would hydrate
 * a tree different from the one that was sent.
 */

const STORAGE_PREFIX = 'afldb.admin.section.';

export function AdminSection({
  id,
  title,
  note,
  defaultOpen = true,
  children,
}: {
  /** Stable across renders and deploys: it is the storage key. */
  id: string;
  title: string;
  /** A word or two beside the heading, e.g. how many cards are inside. */
  note?: string;
  defaultOpen?: boolean;
  children: React.ReactNode;
}) {
  const [open, setOpen] = useState(defaultOpen);

  useEffect(() => {
    try {
      const stored = window.localStorage.getItem(STORAGE_PREFIX + id);
      if (stored === 'open' || stored === 'closed') setOpen(stored === 'open');
    } catch {
      // Storage unavailable; the default stands.
    }
  }, [id]);

  function remember(next: boolean) {
    setOpen(next);
    try {
      window.localStorage.setItem(STORAGE_PREFIX + id, next ? 'open' : 'closed');
    } catch {
      // As above: the choice still applies to this page view.
    }
  }

  return (
    <details
      className="section admin-section"
      open={open}
      // onToggle rather than an onClick on the summary: the element can also
      // be opened by find-in-page and by the keyboard, and both go through
      // the toggle event only.
      onToggle={(event) => {
        const isOpen = (event.currentTarget as HTMLDetailsElement).open;
        if (isOpen !== open) remember(isOpen);
      }}
    >
      <summary>
        <h2>{title}</h2>
        {note && <span className="admin-section-note">{note}</span>}
      </summary>
      <div className="admin-section-body">{children}</div>
    </details>
  );
}

'use server';

import { revalidatePath } from 'next/cache';

import { authSql } from '@/db/authClient';
import { deleteMedia as deleteMediaRow } from '@/db/queries/site-content';
import { audit, requireCapability } from '@/lib/auth/session';
import { describePublishResult, publishApex } from '@/lib/apex-publish';
import { parseApexContent, parseSiteFooter } from '@/lib/site-content';
import { SETTING_KEYS, parsePageIntros } from '@/lib/site-settings';

export type ContentState = { error?: string; message?: string };

/**
 * Save the apex page's content and the shared footer, then publish.
 *
 * The order matters and is not negotiable: the database is written first and
 * the files second. A failed publish therefore costs the publish alone — the
 * edit survives, the admin is told what went wrong, and pressing Publish
 * again is the whole retry. The reverse order would risk a page on disk that
 * nothing in the database describes.
 *
 * Both documents arrive as one JSON field each from the client editor and are
 * re-parsed here through the same functions the read path uses. The editor is
 * a convenience, never the validation: a hand-posted document lands on the
 * normalised, clamped, allowlisted version of itself or on the defaults.
 */
export async function saveSiteContent(
  _previous: ContentState,
  formData: FormData,
): Promise<ContentState> {
  const admin = await requireCapability('site.content');

  const decode = (field: string): unknown => {
    try {
      return JSON.parse(String(formData.get(field) ?? 'null'));
    } catch {
      // Undecodable means "no submission", which the parsers turn into the
      // stored-or-default document rather than an error. One mangled field
      // must not block the other from saving.
      return null;
    }
  };

  const content = parseApexContent(decode('content'));
  const footer = parseSiteFooter(decode('footer'));
  const pageIntros = parsePageIntros(decode('pageIntros'));

  await authSql.begin(async (tx) => {
    for (const [key, value] of [
      [SETTING_KEYS.apexContent, content],
      [SETTING_KEYS.siteFooter, footer],
      [SETTING_KEYS.pageIntros, pageIntros],
    ] as const) {
      await tx`
        INSERT INTO site_settings (key, value, updated_by)
        VALUES (${key}, ${JSON.stringify(value)}::jsonb, ${admin.id})
        ON CONFLICT (key) DO UPDATE
          SET value = EXCLUDED.value, updated_by = EXCLUDED.updated_by, updated_at = now()
      `;
    }
  });

  const result = await publishApex();

  await audit('content.saved', {
    features: content.features.items.length,
    notes: content.notes.items.length,
    stats: content.hero.stats.length,
    footerLines: footer.lines.length,
    // The running order and what is switched off, so the audit log answers
    // "when did the wide shot disappear from the front door" without anyone
    // having to diff two settings rows by hand.
    sections: content.sections
      .map((section) => (section.visible ? section.id : `${section.id}:hidden`))
      .join(','),
    published: result.ok,
    ...(result.ok ? { written: result.written, pruned: result.pruned } : { reason: result.reason }),
  }, { userId: admin.id, label: admin.email });

  // The footer is in the root layout, so every page carries it. 'layout' scope
  // is what reaches them all — revalidating '/' alone would leave the footer
  // stale on every other page until its own ISR window rolled over.
  revalidatePath('/', 'layout');

  return result.ok
    ? { message: `Saved and published. ${describePublishResult(result)}` }
    : { error: describePublishResult(result) };
}

/**
 * Publish without saving.
 *
 * Its own action and its own form, so it cannot carry a half-edited document
 * to disk — the same separation /admin/settings draws around its test-email
 * button. This is the recovery path: it rebuilds the published directory from
 * what is already in the database, which is how a rebuilt server, a deleted
 * /var/www/afldb-soon or a deploy that changed style.css gets back in step.
 */
export async function republishApex(
  _previous: ContentState,
  _formData: FormData,
): Promise<ContentState> {
  const admin = await requireCapability('site.content');

  const result = await publishApex();

  await audit('content.published', {
    ok: result.ok,
    ...(result.ok
      ? { written: result.written, pruned: result.pruned, target: result.target }
      : { reason: result.reason }),
  }, { userId: admin.id, label: admin.email });

  return result.ok
    ? { message: describePublishResult(result) }
    : { error: describePublishResult(result) };
}

/**
 * Remove an uploaded image.
 *
 * Deliberately does NOT rewrite the content document to drop references to
 * it. A slot still pointing at a deleted image keeps its src, which the
 * editor renders as a visible "missing" marker rather than silently reverting
 * to a stock screenshot the admin did not choose. Publishing prunes the file;
 * the page slot is the admin's to repoint.
 */
export async function deleteMedia(
  _previous: ContentState,
  formData: FormData,
): Promise<ContentState> {
  const admin = await requireCapability('site.content');
  const name = String(formData.get('name') ?? '');
  if (!name) return { error: 'No image named.' };

  await deleteMediaRow(name);
  await audit('content.media_deleted', { name }, { userId: admin.id, label: admin.email });

  revalidatePath('/admin/content');
  return { message: `Deleted ${name}. Publish to remove it from the live page.` };
}

import type { Metadata } from 'next';
import Link from 'next/link';

import { CreateMatchForm } from '@/app/admin/data-editor/CreateMatchForm';
import { CreatePlayerForm } from '@/app/admin/data-editor/CreatePlayerForm';
import { EditorForm } from '@/app/admin/data-editor/EditorForm';
import { MatchSheetEditor } from '@/app/admin/data-editor/MatchSheetEditor';
import { PlayerFinder } from '@/app/admin/data-editor/PlayerFinder';
import { sql } from '@/db/client';
import { listClubs } from '@/db/queries/clubs';
import { loadMatchSheetAuthoritySummary, loadMatchSheetStaleToken } from '@/db/queries/match-sheet';
import { listVenues } from '@/db/queries/venues';
import { getMatch, getMatchPlayers, getRecentClubLineup } from '@/db/queries/matches';
import { getEditableRow } from '@/db/queries/data-edits';
import { searchAdminMatches } from '@/db/queries/match-admin';
import { listSeasons } from '@/db/queries/seasons';
import { requireCapability } from '@/lib/auth/session';
import { formatDate, formatRoundShort } from '@/lib/format';
import { firstValue, parseSeason } from '@/lib/params';
import { isEditableEntity } from '@/lib/edit/spec';
import { MatchBrowser } from '@/app/admin/data-editor/MatchBrowser';

export const metadata: Metadata = { title: 'Data editor', robots: { index: false, follow: false } };
export const dynamic = 'force-dynamic';

/**
 * Manual corrections, player bio creation, and match creation & sheet editing.
 *
 * Find or create a player, find or create a match, or edit match player statistics.
 *
 * Two domains have left this page for surfaces of their own and are pointed at rather than
 * edited here: draft selections (`/admin/draft`, AFLDB-ISSUE-160 D-5) and awards, Hall of Fame
 * and representative-team selections (`/admin/awards`, AFLDB-ISSUE-165 §10). The awards move
 * was not a tidy-up: a create-only form could not express correction, voiding or replacement,
 * and the rows it wrote carried no durable record, so nothing it created survived a rebuild.
 *
 * Every save is audited in data_edits; the CSV pipeline remains the path for bulk jobs.
 */
export default async function DataEditorPage(
  { searchParams }: { searchParams: Promise<Record<string, string | string[] | undefined>> },
) {
  await requireCapability('data.dataEditor');
  const params = await searchParams;

  const mode = firstValue(params.mode) ?? '';
  const entityParam = firstValue(params.entity) ?? '';
  const entity = isEditableEntity(entityParam) ? entityParam : null;
  const id = Number(firstValue(params.id));
  const seasonParam = parseSeason(firstValue(params.season) ?? '');
  const clubIdParam = Number(firstValue(params.club_id)) || null;
  const roundParam = Number(firstValue(params.round)) || null;
  const matchQueryParam = firstValue(params.match_q)?.trim() ?? '';

  const [clubs, venues, seasonsList] = await Promise.all([
    listClubs(),
    listVenues(),
    listSeasons(),
  ]);

  const matchForSheet = (mode === 'match-sheet' && Number.isInteger(id) && id > 0)
    ? await getMatch(id)
    : null;
  // Token FIRST: if a settle lands between the two reads the token is the older
  // one, so the save is refused as stale rather than blessing rows never shown.
  const matchSheetToken = matchForSheet ? await loadMatchSheetStaleToken(sql, id) : '';
  const matchSheetPlayers = matchForSheet ? await getMatchPlayers(id) : [];
  // ISSUE-257 D-257-6: the match's active durable decisions (import-role read; fails
  // closed to "unavailable", never to "none").
  const authoritySummary = matchForSheet ? await loadMatchSheetAuthoritySummary(id) : null;

  const [homeRecentLineup, awayRecentLineup] = matchForSheet
      ? await Promise.all([
        getRecentClubLineup(matchForSheet.homeClubId, matchForSheet.id),
        getRecentClubLineup(matchForSheet.awayClubId, matchForSheet.id),
      ])
    : [[], []];

  const row = (mode !== 'match-sheet' && entity && Number.isInteger(id) && id > 0)
    ? await getEditableRow(entity, id)
    : null;

  const adminMatchesResult = (!matchForSheet && !row && entity !== 'draft_picks')
    ? await searchAdminMatches({
        season: seasonParam,
        clubId: clubIdParam,
        roundNumber: roundParam,
        query: matchQueryParam,
        limit: 35,
      })
    : { rows: [], total: 0 };

  return (
    <>
      <div className="page-header">
        <h1>Data editor</h1>
        <p className="subtitle">
          One-off corrections, player creation, and match creation &amp; sheets, saved with a note and audited.
        </p>
      </div>

      <section className="section" style={{ display: 'grid', gap: '1.5rem' }}>
        <div>
          <h2>Players & recruitment</h2>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '1rem', alignItems: 'center' }}>
            <PlayerFinder />
            <CreatePlayerForm />
          </div>
        </div>

        <div>
          <h2>Awards, Hall of Fame &amp; representative teams</h2>
          <p className="muted">
            Award winners, Hall of Fame inductions and representative-team selections moved to
            their own surface (AFLDB-ISSUE-165): <Link href="/admin/awards">Awards &amp; honours</Link>.
            This page no longer records or edits them. The new surface adds what this one never
            had — correction, voiding, reinstatement and replacement, each recorded durably enough
            to survive a source reload and a full rebuild.
          </p>
        </div>

        <div>
          <h2>Matches</h2>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '1.25rem', alignItems: 'end', marginBottom: '0.75rem' }}>
            <CreateMatchForm clubs={clubs} venues={venues} />
          </div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '1.5rem', alignItems: 'end' }}>
            <form method="get" style={{ display: 'flex', gap: '0.5rem', alignItems: 'end' }}>
              <input type="hidden" name="entity" value="matches" />
              <label style={{ display: 'grid', gap: '0.2rem', fontSize: '0.85rem' }}>
                Jump to match details (scores/venue)
                <input type="number" name="id" min={1} placeholder="Match ID" defaultValue={mode !== 'match-sheet' && entity === 'matches' && id > 0 ? id : undefined} />
              </label>
              <button type="submit">Open details</button>
            </form>
            <form method="get" style={{ display: 'flex', gap: '0.5rem', alignItems: 'end' }}>
              <input type="hidden" name="mode" value="match-sheet" />
              <label style={{ display: 'grid', gap: '0.2rem', fontSize: '0.85rem' }}>
                Jump to match sheet (lineup & player stats)
                <input type="number" name="id" min={1} placeholder="Match ID" defaultValue={mode === 'match-sheet' && id > 0 ? id : undefined} />
              </label>
              <button type="submit" className="btn btn-primary">Open match sheet</button>
            </form>
          </div>
        </div>

        <div>
          <h2>Draft picks</h2>
          <p className="muted">
            Draft selections and new-player-through-draft intake moved to their own surface
            (AFLDB-ISSUE-160): <Link href="/admin/draft">Draft administration</Link>. This page no
            longer edits them.
          </p>
        </div>
      </section>

      {!matchForSheet && !row && entity !== 'draft_picks' && (
        <MatchBrowser
          matches={adminMatchesResult.rows}
          total={adminMatchesResult.total}
          clubs={clubs}
          seasons={seasonsList}
          currentSeason={seasonParam}
          currentClubId={clubIdParam}
          currentRound={roundParam}
          currentQuery={matchQueryParam}
        />
      )}

      {matchForSheet && (
        <MatchSheetEditor
          match={matchForSheet}
          initialPlayers={matchSheetPlayers}
          staleToken={matchSheetToken}
          authoritySummary={authoritySummary ?? { status: 'unavailable', reason: 'Not loaded.' }}
          homeRecentLineup={homeRecentLineup}
          awayRecentLineup={awayRecentLineup}
        />
      )}

      {mode === 'match-sheet' && id > 0 && !matchForSheet && (
        <section className="section">
          <div className="empty"><h3>No match with id #{id} found</h3></div>
        </section>
      )}

      {mode !== 'match-sheet' && entity === 'draft_picks' && id > 0 && (
        <section className="section">
          <div className="empty">
            <h3>Draft selections are edited in Draft administration</h3>
            <p><Link href={`/admin/draft/${id}`}>Open selection #{id} in Draft administration</Link></p>
          </div>
        </section>
      )}

      {mode !== 'match-sheet' && entity && entity !== 'draft_picks' && id > 0 && !row && (
        <section className="section">
          <div className="empty"><h3>No {entity === 'players' ? 'player' : 'match'} with id {id}</h3></div>
        </section>
      )}

      {row && (
        <EditorForm
          entityKey={row.entity}
          rowId={row.rowId}
          title={row.title}
          values={row.values}
        />
      )}
    </>
  );
}

