'use client';

import { useActionState, useEffect, useState } from 'react';

import { clearTelemetry, type NlClearTelemetryState } from './actions';
import { NL_TELEMETRY_CLEAR_PHRASE } from './telemetry-clear-phrase';
import { formatNumber } from '@/lib/format';

const INITIAL: NlClearTelemetryState = {};

function plural(n: number, noun: string): string {
  return `${formatNumber(n)} ${noun}${n === 1 ? '' : 's'}`;
}

/**
 * Super Admin-only destructive control for /admin/nl-search
 * (AFLDB-ISSUE-119 §10). Follows DeleteMatchButton's
 * reveal-warning-confirm-cancel pattern, with an added exact-phrase gate:
 * the submit button stays disabled until the typed text matches
 * NL_TELEMETRY_CLEAR_PHRASE exactly. This is a misclick guard only -- the
 * action re-checks the same phrase server-side (§6), so a forged submit
 * with the field blank or wrong is refused there regardless of what this
 * component allows.
 */
export function ClearTelemetryForm() {
  const [isConfirming, setIsConfirming] = useState(false);
  const [confirmation, setConfirmation] = useState('');
  const [state, formAction, isPending] = useActionState<NlClearTelemetryState, FormData>(
    clearTelemetry,
    INITIAL,
  );

  // Collapse back to the initial button once a clear actually commits --
  // state.counts is only ever set on committed success, never on error.
  useEffect(() => {
    if (state.counts) {
      setIsConfirming(false);
      setConfirmation('');
    }
  }, [state.counts]);

  function cancel() {
    setIsConfirming(false);
    setConfirmation('');
  }

  const phraseMatches = confirmation === NL_TELEMETRY_CLEAR_PHRASE;

  return (
    <div style={{ display: 'grid', gap: '0.5rem' }}>
      {!isConfirming ? (
        <button
          type="button"
          onClick={() => setIsConfirming(true)}
          className="btn"
          style={{
            background: 'transparent',
            border: '1px solid var(--color-warn)',
            color: 'var(--color-warn)',
            fontSize: '0.85rem',
          }}
        >
          🗑 Clear search telemetry
        </button>
      ) : (
        <div style={{
          border: '1px solid var(--color-warn)',
          borderRadius: '6px',
          padding: '0.75rem 1rem',
          background: 'var(--bg-raised)',
          display: 'grid',
          gap: '0.5rem',
          maxWidth: '34rem',
        }}>
          <p style={{ margin: 0, fontWeight: 600, color: 'var(--color-warn)', fontSize: '0.85rem' }}>
            ⚠ Clear search telemetry
          </p>
          <p className="muted" style={{ margin: 0, fontSize: '0.8rem' }}>
            Permanently deletes disposable <code>nl_search_log</code> rows — ones with no
            admin review and no matching reader feedback, plus any otherwise-unprotected
            ancestor of a row that does. Every review, every piece of reader feedback, and
            the log rows they reference are retained no matter what. This does not pause
            logging: searches after the clear are recorded as usual.
          </p>

          {state.error && (
            <p style={{ margin: 0, color: 'var(--color-warn)', fontSize: '0.8rem' }} role="alert">
              ⚠ {state.error}
            </p>
          )}

          <form action={formAction} style={{ display: 'grid', gap: '0.5rem' }}>
            <label style={{ display: 'grid', gap: '0.2rem', fontSize: '0.8rem' }}>
              Type <code>{NL_TELEMETRY_CLEAR_PHRASE}</code> to confirm
              <input
                type="text"
                name="confirmation"
                value={confirmation}
                onChange={(e) => setConfirmation(e.target.value)}
                disabled={isPending}
                autoComplete="off"
                spellCheck={false}
                style={{ fontSize: '0.8rem' }}
              />
            </label>

            <div style={{ display: 'flex', gap: '0.5rem' }}>
              <button
                type="submit"
                disabled={isPending || !phraseMatches}
                style={{
                  background: 'var(--color-warn)',
                  color: '#fff',
                  border: 'none',
                  fontSize: '0.8rem',
                  padding: '0.3rem 0.6rem',
                }}
              >
                {isPending ? 'Clearing…' : 'Yes, clear search telemetry'}
              </button>
              <button
                type="button"
                className="btn btn-secondary"
                onClick={cancel}
                disabled={isPending}
                style={{ fontSize: '0.8rem', padding: '0.3rem 0.6rem' }}
              >
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}

      {state.counts && (
        <p className="notice" style={{ display: 'grid', gap: '0.15rem' }}>
          <strong>{state.message}</strong>
          <span className="muted" style={{ fontSize: '0.8rem' }}>
            Retained: {plural(state.counts.retainedReviewRows, 'review')},{' '}
            {plural(state.counts.retainedFeedbackRows, 'feedback row')}.{' '}
            {plural(state.counts.detachedAppHealthLinks, 'app-health link')} detached from cleared rows.
          </span>
        </p>
      )}
    </div>
  );
}

'use client';

import { useRouter } from 'next/navigation';
import { useActionState, useEffect, useState } from 'react';

import {
  approveSuggestion,
  confirmUnlinked,
  createAndLinkPlayer,
  linkPlayer,
  type PlayerLinkActionState,
} from '@/app/admin/player-links/actions';
import { postPublicRevalidate } from '@/app/admin/player-links/post-public-revalidate';
import { PlayerPicker } from '@/components/PlayerPicker';

const INITIAL: PlayerLinkActionState = {};

type EvidenceItem = {
  family: string; signal: string; detail: string; points: number;
  /** Reviewer-facing wording, produced server-side from the same signal. */
  label?: string;
};
type ConflictItem = { reason: string; detail: string; label?: string };

/** What kind of source record this is, and how to identify it. */
export type SourceRecordView = { typeLabel: string; lines: string[] };

export type SuggestedMatch = {
  playerId: number;
  playerName: string;
  playerSlug: string;
  /** "Essendon · 1987-1998 · 243 games · 46 goals" */
  playerSummary: string;
  score: number;
  band: string;
  gap: number | null;
  ambiguous: boolean;
  hardConflict: boolean;
  bulkEligible: boolean;
  /**
   * The bulk criteria, evaluated. Sent for EVERY suggested row, not only
   * eligible ones: a reviewer has to be able to see which criterion a
   * capped row misses (AFLDB-ISSUE-164 §11 item 3).
   */
  bulkCriteria: { label: string; met: boolean }[];
  /** Typed limit reasons, already worded server-side, most important first. */
  limitReasons: string[];
  /** "Highest score this record type can reach: 61 — never Very High". */
  ceiling: string | null;
  /** The source names a club, but the text resolves to no AFLDB club. */
  clubTextUnresolved: boolean;
  evidence: EvidenceItem[];
  conflicts: ConflictItem[];
  algorithmVersion: string;
  /** The version the running matcher declares, from the server. */
  currentAlgorithmVersion: string;
  /** Cached under a different version than the code now running. */
  stale: boolean;
  alternatives: {
    playerId: number;
    playerName: string;
    playerSummary: string;
    score: number;
    evidence: EvidenceItem[];
    conflicts: ConflictItem[];
  }[];
};

const BAND_LABELS: Record<string, string> = {
  very_high: 'Very high',
  high: 'High',
  medium: 'Medium',
  low: 'Low',
  none: 'No suggestion',
};

/**
 * The score, itemised.
 *
 * A reviewer approving an identity is entitled to see what the number
 * was made of, so every signal that paid and every contradiction found
 * is listed. A bare percentage would be asking for trust rather than
 * offering evidence.
 */
function EvidenceTable({
  evidence, conflicts, total,
}: {
  evidence: EvidenceItem[];
  conflicts: ConflictItem[];
  total?: number;
}) {
  return (
    <div style={{ fontSize: '0.8rem' }}>
      {evidence.map((item) => (
        <div key={item.signal} style={{ display: 'flex', justifyContent: 'space-between', gap: '0.75rem' }}>
          <span>
            {item.label ?? item.detail}
            <span className="muted"> — {item.detail}</span>
          </span>
          <span className="nowrap" style={{ fontVariantNumeric: 'tabular-nums' }}>+{item.points}</span>
        </div>
      ))}
      {evidence.length === 0 && <div className="muted">No evidence scored.</div>}
      {conflicts.map((conflict) => (
        <div key={conflict.reason} className="badge badge-warn" style={{ marginTop: '0.35rem', display: 'block' }}>
          {conflict.label ?? conflict.detail}
          <span className="muted"> — {conflict.detail}</span>
        </div>
      ))}
      {total !== undefined && (
        <div style={{
          display: 'flex', justifyContent: 'space-between', gap: '0.75rem',
          borderTop: '1px solid var(--border-subtle)', marginTop: '0.35rem', paddingTop: '0.25rem',
          fontWeight: 600,
        }}>
          <span>Total</span>
          <span style={{ fontVariantNumeric: 'tabular-nums' }}>{total}</span>
        </div>
      )}
    </div>
  );
}

/**
 * The resolve panel for one unresolved honours or draft row (see changeLog.md).
 *
 * Three options:
 * 1. Link to an existing AFLDB player found via autocomplete.
 * 2. Create a new player record (with bio info like DOB, height, weight, notes)
 *    and link immediately (ideal for draftees like Riley Onley & Fred Rodriguez).
 * 3. Confirm the person is genuinely not an AFL/VFL player.
 */
export function ResolveControls({
  targets,
  playerName,
  context,
  linkStatus,
  suggestions,
  match,
  sourceRecord,
}: {
  targets: { table: string; id: number; linkStatus?: string }[];
  playerName?: string;
  context?: string;
  linkStatus: string;
  suggestions: { id: number; suggestedName: string; note: string | null }[];
  match?: SuggestedMatch | null;
  sourceRecord?: SourceRecordView | null;
}) {
  const router = useRouter();
  const [tab, setTab] = useState<'link' | 'create' | 'unlinked'>('link');

  const [approveState, approveAction, approvePending] = useActionState(approveSuggestion, INITIAL);
  const [linkState, linkAction, linkPending] = useActionState(linkPlayer, INITIAL);
  const [createState, createAction, createPending] = useActionState(createAndLinkPlayer, INITIAL);
  const [confirmState, confirmAction, confirmPending] = useActionState(confirmUnlinked, INITIAL);
  const [picked, setPicked] = useState<{ id: number; label: string } | null>(null);

  const done = approveState.message ?? linkState.message ?? createState.message ?? confirmState.message;
  const warning = approveState.warning ?? linkState.warning ?? createState.warning ?? confirmState.warning;

  const targetsRaw = targets.map(t => `${t.table}:${t.id}:${t.linkStatus ?? ''}`).join(',');

  // Split name for create pre-fill
  const cleanName = (playerName ?? '').trim();
  const parts = cleanName.split(/\s+/);
  const initialGiven = parts.length > 1 ? parts.slice(0, -1).join(' ') : '';
  const initialSurname = parts.length > 1 ? parts[parts.length - 1] : parts[0] || '';

  // The approval committed, whatever its audit warning says: revalidate the
  // public pages in a follow-up request, not inside the action (AFLDB-ISSUE-308).
  // Keyed on the result object so a second committed approval posts again.
  useEffect(() => {
    if (approveState.revalidatePublic) void postPublicRevalidate();
  }, [approveState]);

  useEffect(() => {
    if (done && !warning) {
      document.dispatchEvent(new CustomEvent('player-links-resolved'));
      router.refresh();
    }
  }, [done, warning, router]);

  if (done) {
    return (
      <div style={{ padding: '0.75rem', background: 'var(--bg-subtle)', borderRadius: '6px', marginTop: '0.5rem' }}>
        <p style={{ margin: 0, fontWeight: 600, color: 'var(--accent)' }}>✓ {done}</p>
        {warning && (
          <p className="badge badge-warn" style={{ margin: '0.5rem 0 0' }}>{warning}</p>
        )}
      </div>
    );
  }

  return (
    <div style={{ display: 'grid', gap: '0.75rem', padding: '0.5rem 0' }}>
      {suggestions.length > 0 && (
        <div className="muted" style={{ fontSize: '0.85rem' }}>
          <strong>Reader suggestions:</strong>
          <ul style={{ margin: '0.25rem 0 0 1.1rem' }}>
            {suggestions.map((s) => (
              <li key={s.id}>
                {s.suggestedName}
                {s.note && <> — {s.note}</>}
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* What this record actually is, in its own terms. */}
      {sourceRecord && (
        <div>
          <div className="muted" style={{ fontSize: '0.72rem', letterSpacing: '0.06em' }}>
            SOURCE RECORD
          </div>
          <strong>{playerName}</strong>
          <div><span className="badge">{sourceRecord.typeLabel}</span></div>
          {sourceRecord.lines.map((line) => (
            <div key={line} className="muted" style={{ fontSize: '0.85rem' }}>{line}</div>
          ))}
        </div>
      )}

      {/* Suggested match, with the evidence behind its score. */}
      {match && (
        <div style={{
          padding: '0.6rem 0.75rem',
          borderRadius: '6px',
          background: 'var(--bg-subtle)',
          border: '1px solid var(--border-subtle)',
          display: 'grid',
          gap: '0.6rem',
        }}>
          <div>
            <div className="muted" style={{ fontSize: '0.72rem', letterSpacing: '0.06em' }}>
              SUGGESTED AFLDB PLAYER
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', gap: '0.5rem', alignItems: 'baseline' }}>
              <strong>{match.playerName}</strong>
              <span className={match.hardConflict ? 'badge badge-warn' : 'badge'}>
                {BAND_LABELS[match.band] ?? match.band} · {match.score}/100
              </span>
            </div>
            {match.playerSummary && (
              <div className="muted" style={{ fontSize: '0.85rem' }}>{match.playerSummary}</div>
            )}
          </div>

          <div>
            <div className="muted" style={{ fontSize: '0.72rem', letterSpacing: '0.06em' }}>
              MATCH EVIDENCE
            </div>
            <EvidenceTable
              evidence={match.evidence}
              conflicts={match.conflicts}
              total={match.score}
            />
          </div>

          <div className="muted" style={{ fontSize: '0.78rem' }}>
            {match.gap === null
              ? 'No credible alternative candidate.'
              : `Next best candidate is ${match.gap} points behind.`}
            {' · '}algorithm {match.algorithmVersion}
            {match.stale && <> (current: {match.currentAlgorithmVersion})</>}
          </div>

          {match.stale && (
            <p className="badge badge-warn" style={{ margin: 0 }}>
              Stale suggestion: this score and its evidence were computed by matcher{' '}
              {match.algorithmVersion}, and the current matcher is {match.currentAlgorithmVersion}.
              Nothing here is approved on the number shown — approving rescores the record under{' '}
              {match.currentAlgorithmVersion} and refuses if the fresh evidence names a different
              player or no longer supports the match.
            </p>
          )}

          {/* Bulk criteria, shown whether or not this row passes them.
              Showing them only on eligible rows was the reason a capped
              row and an unlucky one looked identical on the queue. */}
          {match.bulkCriteria.length > 0 && (
            <div>
              <div className="muted" style={{ fontSize: '0.72rem', letterSpacing: '0.06em' }}>
                {match.bulkEligible ? 'BULK-READY' : 'BULK READINESS'}
              </div>
              {match.bulkCriteria.map((criterion) => (
                <div
                  key={criterion.label}
                  style={{ fontSize: '0.8rem' }}
                  className={criterion.met ? undefined : 'muted'}
                >
                  {criterion.met ? '✓' : '✗'} {criterion.label}
                </div>
              ))}
              {match.ceiling && (
                <div className="muted" style={{ fontSize: '0.8rem', marginTop: '0.25rem' }}>
                  {match.ceiling}
                </div>
              )}
              {match.clubTextUnresolved && (
                <div className="muted" style={{ fontSize: '0.8rem' }}>
                  The club this record names is not an AFLDB club we could resolve, so it
                  counts neither for nor against this player.
                </div>
              )}
              {!match.bulkEligible && match.limitReasons.length > 0 && (
                <ul style={{ margin: '0.35rem 0 0 1.1rem', fontSize: '0.8rem' }}>
                  {match.limitReasons.map((reason) => (
                    <li key={reason}>{reason}</li>
                  ))}
                </ul>
              )}
            </div>
          )}

          {match.hardConflict ? (
            <p className="badge badge-warn" style={{ margin: 0 }}>
              Not approvable as a suggestion: the source evidence contradicts this candidate.
              Link manually below if you can verify it another way.
            </p>
          ) : match.ambiguous ? (
            <p className="badge badge-warn" style={{ margin: 0 }}>
              Needs review: another candidate scores almost as highly. Compare the
              alternatives before approving.
            </p>
          ) : null}

          {!match.hardConflict && targets.length === 1 && (
            <form action={approveAction} style={{ display: 'grid', gap: '0.4rem' }}>
              <input type="hidden" name="targets" value={targetsRaw} />
              <input type="hidden" name="playerId" value={match.playerId} />
              <input
                type="text"
                name="note"
                maxLength={2000}
                placeholder="Verification note (optional)"
                style={{ fontSize: '0.85rem', width: '100%' }}
              />
              <button type="submit" className="btn btn-primary" disabled={approvePending}>
                {approvePending ? 'Approving…' : `Approve match: ${match.playerName}`}
              </button>
              {approveState.error && (
                <span className="badge badge-warn" style={{ fontSize: '0.8rem' }}>{approveState.error}</span>
              )}
            </form>
          )}

          {match.alternatives.length > 0 && (
            <details>
              <summary style={{ fontSize: '0.85rem', cursor: 'pointer' }}>
                ALTERNATIVES ({match.alternatives.length})
              </summary>
              <div style={{ display: 'grid', gap: '0.5rem', marginTop: '0.4rem' }}>
                {match.alternatives.map((alt, index) => (
                  <div key={alt.playerId} style={{ borderTop: '1px solid var(--border-subtle)', paddingTop: '0.4rem' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', gap: '0.5rem' }}>
                      <span>{index + 2}. {alt.playerName}</span>
                      <span className="muted" style={{ fontSize: '0.8rem' }}>{alt.score}/100</span>
                    </div>
                    {alt.playerSummary && (
                      <div className="muted" style={{ fontSize: '0.8rem' }}>{alt.playerSummary}</div>
                    )}
                    <EvidenceTable evidence={alt.evidence} conflicts={alt.conflicts} />
                    {/* Choosing an alternative is a manual decision and is
                        recorded as one: it is not the model's suggestion. */}
                    <form action={linkAction} style={{ marginTop: '0.3rem' }}>
                      <input type="hidden" name="targets" value={targetsRaw} />
                      <input type="hidden" name="playerId" value={alt.playerId} />
                      <button type="submit" className="btn btn-secondary" disabled={linkPending}
                        style={{ fontSize: '0.78rem', padding: '0.25rem 0.5rem' }}>
                        Link this player instead
                      </button>
                    </form>
                  </div>
                ))}
              </div>
            </details>
          )}
        </div>
      )}

      {/* Tab Navigation */}
      <div style={{ display: 'flex', gap: '0.35rem', borderBottom: '1px solid var(--border-subtle)', paddingBottom: '0.5rem' }}>
        <button
          type="button"
          className={`btn ${tab === 'link' ? 'btn-primary' : 'btn-secondary'}`}
          onClick={() => setTab('link')}
          style={{ fontSize: '0.8rem', padding: '0.3rem 0.6rem' }}
        >
          Link existing
        </button>
        <button
          type="button"
          className={`btn ${tab === 'create' ? 'btn-primary' : 'btn-secondary'}`}
          onClick={() => setTab('create')}
          style={{ fontSize: '0.8rem', padding: '0.3rem 0.6rem' }}
        >
          Create & link new
        </button>
        <button
          type="button"
          className={`btn ${tab === 'unlinked' ? 'btn-primary' : 'btn-secondary'}`}
          onClick={() => setTab('unlinked')}
          style={{ fontSize: '0.8rem', padding: '0.3rem 0.6rem' }}
        >
          Not a player
        </button>
      </div>

      {/* Tab 1: Link Existing Player */}
      {tab === 'link' && (
        <form action={linkAction} style={{ display: 'grid', gap: '0.6rem' }}>
          <input type="hidden" name="targets" value={targetsRaw} />
          <input type="hidden" name="playerId" value={picked?.id ?? ''} />
          <div>
            <PlayerPicker label="Find AFLDB player" onSelect={setPicked} />
          </div>
          <div>
            <label style={{ display: 'grid', gap: '0.2rem', fontSize: '0.8rem' }}>
              Verification note (optional)
              <input
                type="text"
                name="note"
                maxLength={2000}
                placeholder="e.g. Sourced from club debut records"
                style={{ fontSize: '0.85rem', width: '100%' }}
              />
            </label>
          </div>
          <button type="submit" disabled={linkPending || !picked}>
            {linkPending ? 'Linking…' : 'Link player'}
          </button>
          {linkState.error && (
            <span className="badge badge-warn" style={{ fontSize: '0.8rem' }}>{linkState.error}</span>
          )}
        </form>
      )}

      {/* Tab 2: Create & Link New Player */}
      {tab === 'create' && (
        <form action={createAction} style={{ display: 'grid', gap: '0.6rem' }}>
          <input type="hidden" name="targets" value={targetsRaw} />

          <div style={{ display: 'grid', gap: '0.5rem' }}>
            <label style={{ display: 'grid', gap: '0.2rem', fontSize: '0.8rem' }}>
              Display name *
              <input
                type="text"
                name="displayName"
                defaultValue={cleanName}
                required
                maxLength={100}
                style={{ fontSize: '0.85rem' }}
              />
            </label>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem' }}>
              <label style={{ display: 'grid', gap: '0.2rem', fontSize: '0.8rem' }}>
                Given name
                <input
                  type="text"
                  name="givenName"
                  defaultValue={initialGiven}
                  maxLength={60}
                  style={{ fontSize: '0.85rem' }}
                />
              </label>
              <label style={{ display: 'grid', gap: '0.2rem', fontSize: '0.8rem' }}>
                Surname
                <input
                  type="text"
                  name="surname"
                  defaultValue={initialSurname}
                  maxLength={60}
                  style={{ fontSize: '0.85rem' }}
                />
              </label>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem' }}>
              <label style={{ display: 'grid', gap: '0.2rem', fontSize: '0.8rem' }}>
                Date of birth (YYYY-MM-DD)
                <input
                  type="date"
                  name="dob"
                  style={{ fontSize: '0.85rem' }}
                />
              </label>
              <label style={{ display: 'grid', gap: '0.2rem', fontSize: '0.8rem' }}>
                DOB confidence
                <select name="dobConfidence" defaultValue="sourced" style={{ fontSize: '0.85rem' }}>
                  <option value="sourced">sourced (verified)</option>
                  <option value="estimated">estimated</option>
                  <option value="derived">derived</option>
                  <option value="unknown">unknown</option>
                </select>
              </label>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem' }}>
              <label style={{ display: 'grid', gap: '0.2rem', fontSize: '0.8rem' }}>
                Height (cm)
                <input
                  type="number"
                  name="heightCm"
                  min={120}
                  max={230}
                  placeholder="e.g. 195"
                  style={{ fontSize: '0.85rem' }}
                />
              </label>
              <label style={{ display: 'grid', gap: '0.2rem', fontSize: '0.8rem' }}>
                Weight (kg)
                <input
                  type="number"
                  name="weightKg"
                  min={40}
                  max={160}
                  placeholder="e.g. 88"
                  style={{ fontSize: '0.85rem' }}
                />
              </label>
            </div>

            <label style={{ display: 'grid', gap: '0.2rem', fontSize: '0.8rem' }}>
              Bio details / notes (optional)
              <textarea
                name="notes"
                maxLength={2000}
                rows={2}
                placeholder={context ? `Context: ${context}` : 'e.g. Drafted 2025 rookie draft, original club Murray Bushrangers'}
                style={{ fontSize: '0.85rem', resize: 'vertical' }}
              />
            </label>
          </div>

          <button type="submit" disabled={createPending}>
            {createPending ? 'Creating & linking…' : 'Create player & link record'}
          </button>
          {createState.error && (
            <span className="badge badge-warn" style={{ fontSize: '0.8rem' }}>{createState.error}</span>
          )}
        </form>
      )}

      {/* Tab 3: Confirm Not an AFL/VFL Player */}
      {tab === 'unlinked' && (
        <form action={confirmAction} style={{ display: 'grid', gap: '0.6rem' }}>
          <input type="hidden" name="targets" value={targetsRaw} />
          <p className="muted" style={{ fontSize: '0.85rem', margin: 0 }}>
            Mark this record as vetted non-AFL/VFL player (e.g. state-league or pioneer recipient).
          </p>
          <label style={{ display: 'grid', gap: '0.2rem', fontSize: '0.8rem' }}>
            Reason / note (optional)
            <input
              type="text"
              name="note"
              maxLength={2000}
              placeholder="e.g. SANFL/WAFL player only"
              style={{ fontSize: '0.85rem', width: '100%' }}
            />
          </label>
          <button type="submit" disabled={confirmPending} className="btn btn-secondary">
            {confirmPending ? 'Saving…' : 'Confirm not an AFL/VFL player'}
          </button>
          {confirmState.error && (
            <span className="badge badge-warn" style={{ fontSize: '0.8rem' }}>{confirmState.error}</span>
          )}
        </form>
      )}
    </div>
  );
}

'use server';

import { revalidatePath } from 'next/cache';

import { revalidatePublicLinkPages } from '@/app/admin/player-links/public-link-pages';
import { authSql } from '@/db/authClient';
import { sql } from '@/db/client';
import {
  confirmUnlinked as confirmUnlinkedQuery,
  createPlayerAndResolveLink,
  isLinkTargetTable,
  resolveLink,
  resolveLinkFromSuggestion,
  setSuggestionStatus,
  type LinkTargetTable,
} from '@/db/queries/player-links';
import {
  readCachedSuggestionVersions,
  refreshMatchCandidates,
} from '@/db/queries/player-match-candidates';
import { audit, requireCapability } from '@/lib/auth/session';

export type PlayerLinkActionState = {
  error?: string;
  message?: string;
  warning?: string;
  /**
   * A suggestion approval committed at least one link. The approval actions
   * cannot revalidate the public pages themselves (see `public-link-pages.ts`),
   * so the browser posts to `/admin/player-links/revalidate` when this is set
   * (AFLDB-ISSUE-308).
   */
  revalidatePublic?: true;
};

const ACTIVITY_AUDIT_WARNING =
  'The change succeeded, but its administrative activity audit failed. '
  + 'Do not submit it again; ask an administrator to reconcile the audit log.';

function combineWarnings(...warnings: Array<string | undefined>): string | undefined {
  return warnings.filter(Boolean).join(' ') || undefined;
}

// A multi-target action resolves each target in its own transaction, so a later
// failure cannot undo an earlier commit (AFLDB-ISSUE-309). Failures are collected
// per target and reported once the loop has finished.
type TargetFailure = { label: string; error: string };

const MAX_LISTED_FAILURES = 5;

function listFailures(failed: TargetFailure[], describe: (failure: TargetFailure) => string): string {
  return failed.slice(0, MAX_LISTED_FAILURES).map(describe).join('; ')
    + (failed.length > MAX_LISTED_FAILURES ? ' …' : '');
}

/** Nothing committed: the refusal(s), in the single-target wording. */
function allFailedError(failed: TargetFailure[]): string {
  return listFailures(failed, f => `Error on ${f.label}: ${f.error}`);
}

/** Something committed: the targets that were left unchanged. */
function notChangedWarning(failed: TargetFailure[]): string | undefined {
  if (failed.length === 0) return undefined;
  return `${failed.length} record(s) were not changed: ${listFailures(failed, f => `${f.label} — ${f.error}`)}`;
}

function parseTargets(formData: FormData): {
  targets?: Array<{ targetTable: LinkTargetTable; targetId: number; previousStatus?: string }>;
  error?: string;
} {
  const targetsRaw = String(formData.get('targets') ?? '');
  const rawList = targetsRaw.split(',').filter(Boolean).map(t => {
    const [table, idStr, previousStatus] = t.split(':');
    return { targetTable: table as LinkTargetTable, targetId: Number(idStr), previousStatus };
  });

  if (rawList.length === 0) return { error: 'No targets selected.' };
  if (rawList.some(t => !isLinkTargetTable(t.targetTable))) return { error: 'Unknown table in targets.' };
  if (rawList.some(t => !Number.isInteger(t.targetId) || t.targetId <= 0)) return { error: 'Bad row id in targets.' };

  return { targets: rawList };
}

export async function linkPlayer(
  _prev: PlayerLinkActionState,
  formData: FormData,
): Promise<PlayerLinkActionState> {
  const admin = await requireCapability('data.playerLinks');

  const { targets, error } = parseTargets(formData);
  if (error || !targets) return { error };

  const playerId = Number(formData.get('playerId'));
  if (!Number.isInteger(playerId) || playerId <= 0) {
    return { error: 'Pick a player first.' };
  }

  const note = String(formData.get('note') ?? '').trim();
  if (note.length > 2000) return { error: 'Notes are limited to 2000 characters.' };

  let linked = 0;
  const failed: TargetFailure[] = [];
  let warning: string | undefined;

  for (const { targetTable, targetId } of targets) {
    const result = await resolveLink({
      targetTable, targetId, playerId, adminUserId: admin.id, note,
    });
    if (!result.ok) {
      failed.push({ label: `${targetTable}:${targetId}`, error: result.error });
      continue;
    }
    linked += 1;

    try {
      await audit('player_link.linked', { targetTable, targetId, playerId },
        { userId: admin.id, label: admin.email });
    } catch (error) {
      console.error('Failed to log administrative audit for player link', error);
      warning = combineWarnings(warning, ACTIVITY_AUDIT_WARNING);
    }
  }

  if (linked === 0) return { error: allFailedError(failed) };

  revalidatePublicLinkPages();
  return {
    message: failed.length === 0
      ? `Player linked to ${linked} record(s).`
      : `Player linked to ${linked} of ${targets.length} record(s).`,
    warning: combineWarnings(warning, notChangedWarning(failed)),
  };
}

export async function confirmUnlinked(
  _prev: PlayerLinkActionState,
  formData: FormData,
): Promise<PlayerLinkActionState> {
  const admin = await requireCapability('data.playerLinks');

  const { targets, error } = parseTargets(formData);
  if (error || !targets) return { error };

  const note = String(formData.get('note') ?? '').trim();
  if (note.length > 2000) return { error: 'Notes are limited to 2000 characters.' };

  let confirmed = 0;
  const failed: TargetFailure[] = [];
  let warning: string | undefined;

  for (const { targetTable, targetId } of targets) {
    const result = await confirmUnlinkedQuery({
      targetTable, targetId, adminUserId: admin.id, note,
    });
    if (!result.ok) {
      failed.push({ label: `${targetTable}:${targetId}`, error: result.error });
      continue;
    }
    confirmed += 1;

    try {
      await audit('player_link.confirmed_unlinked', { targetTable, targetId },
        { userId: admin.id, label: admin.email });
    } catch (error) {
      console.error('Failed to log administrative audit for confirmed-unlinked', error);
      warning = combineWarnings(warning, ACTIVITY_AUDIT_WARNING);
    }
  }

  if (confirmed === 0) return { error: allFailedError(failed) };

  revalidatePublicLinkPages();
  return {
    message: failed.length === 0
      ? `Recorded ${confirmed} record(s) as vetted — genuinely unlinked.`
      : `Recorded ${confirmed} of ${targets.length} record(s) as vetted — genuinely unlinked.`,
    warning: combineWarnings(warning, notChangedWarning(failed)),
  };
}

export async function reviewSuggestion(
  _prev: PlayerLinkActionState,
  formData: FormData,
): Promise<PlayerLinkActionState> {
  const admin = await requireCapability('data.playerLinks');

  const id = Number(formData.get('suggestionId'));
  if (!Number.isInteger(id) || id <= 0) return { error: 'Bad suggestion id.' };

  const status = String(formData.get('status') ?? '');
  if (status !== 'accepted' && status !== 'dismissed') {
    return { error: 'Unknown suggestion status.' };
  }

  await setSuggestionStatus(id, status, admin.id);

  let warning: string | undefined;
  try {
    await audit('player_link.suggestion_reviewed', { suggestionId: id, status },
      { userId: admin.id, label: admin.email });
  } catch (error) {
    console.error('Failed to log administrative audit for suggestion review', error);
    warning = ACTIVITY_AUDIT_WARNING;
  }

  return { message: `Suggestion ${status}.`, warning };
}

export async function createAndLinkPlayer(
  _prev: PlayerLinkActionState,
  formData: FormData,
): Promise<PlayerLinkActionState> {
  const admin = await requireCapability('data.playerLinks');

  const { targets, error } = parseTargets(formData);
  if (error || !targets) return { error };

  const displayName = String(formData.get('displayName') ?? '').trim();
  if (!displayName || displayName.length > 100) {
    return { error: 'Player display name is required (max 100 characters).' };
  }

  const givenName = String(formData.get('givenName') ?? '').trim() || null;
  const surname = String(formData.get('surname') ?? '').trim() || null;
  const dob = String(formData.get('dob') ?? '').trim() || null;
  const dobConfidence = (String(formData.get('dobConfidence') ?? 'sourced') || 'sourced') as 'sourced' | 'estimated' | 'derived' | 'unknown';

  const rawHeight = formData.get('heightCm');
  const heightCm = rawHeight && Number.isInteger(Number(rawHeight)) ? Number(rawHeight) : null;

  const rawWeight = formData.get('weightKg');
  const weightKg = rawWeight && Number.isInteger(Number(rawWeight)) ? Number(rawWeight) : null;

  const notes = String(formData.get('notes') ?? '').trim() || null;
  const note = String(formData.get('note') ?? '').trim();
  if (note.length > 2000) return { error: 'Notes are limited to 2000 characters.' };

  const playerFields = {
    displayName, givenName, surname, dob, dobConfidence, heightCm, weightKg, notes,
  };

  let first = true;
  let createdPlayerId = 0;
  let createdPlayerName = '';
  let linked = 0;
  const failed: TargetFailure[] = [];
  let warning: string | undefined;

  for (const { targetTable, targetId } of targets) {
    if (first) {
      const result = await createPlayerAndResolveLink({
        targetTable,
        targetId,
        adminUserId: admin.id,
        note,
        player: playerFields,
      });
      // No player exists yet, so nothing has committed and there is nothing
      // for the remaining targets to link to.
      if (!result.ok) return { error: result.error };
      const { player } = result;
      linked += 1;
      createdPlayerId = player.id;
      createdPlayerName = player.displayName;
      try {
        await audit('player_link.created_and_linked', {
          targetTable,
          targetId,
          playerId: player.id,
          playerName: player.displayName,
        }, { userId: admin.id, label: admin.email });
      } catch (error) {
        console.error('Failed to log administrative audit for create-and-link', error);
        warning = combineWarnings(warning, ACTIVITY_AUDIT_WARNING);
      }
      first = false;
    } else {
      const result = await resolveLink({
        targetTable, targetId, playerId: createdPlayerId, adminUserId: admin.id, note,
      });
      if (!result.ok) {
        failed.push({ label: `${targetTable}:${targetId}`, error: result.error });
        continue;
      }
      linked += 1;
      try {
        await audit('player_link.linked', { targetTable, targetId, playerId: createdPlayerId },
          { userId: admin.id, label: admin.email });
      } catch (error) {
        console.error('Failed to log administrative audit for player link', error);
        warning = combineWarnings(warning, ACTIVITY_AUDIT_WARNING);
      }
    }
  }

  revalidatePublicLinkPages();
  revalidatePath('/players');
  revalidatePath('/admin/data-editor');
  return {
    message: failed.length === 0
      ? `Created player ${createdPlayerName} (ID #${createdPlayerId}) and linked successfully to ${linked} record(s).`
      : `Created player ${createdPlayerName} (ID #${createdPlayerId}) and linked to ${linked} of ${targets.length} record(s).`,
    warning: combineWarnings(warning, notChangedWarning(failed)),
  };
}

/**
 * Approve one suggested match.
 *
 * The browser sends a target and a player id and nothing else that
 * matters: any score or band it might post is ignored, because
 * resolveLinkFromSuggestion recomputes the match server-side inside the
 * writing transaction and refuses the link unless that fresh
 * calculation still names the same player. Choosing an ALTERNATIVE
 * candidate deliberately does not come through here -- it goes through
 * linkPlayer and is recorded as a manual decision, because that is what
 * it is.
 *
 * No revalidatePath: the client refreshes once the action settles (see
 * reviewSuggestion and SuggestionControls). The public pages are revalidated
 * the same way -- the result sets `revalidatePublic` and the browser posts to
 * `/admin/player-links/revalidate` afterwards (AFLDB-ISSUE-308).
 */
export async function approveSuggestion(
  _prev: PlayerLinkActionState,
  formData: FormData,
): Promise<PlayerLinkActionState> {
  const admin = await requireCapability('data.playerLinks');

  const { targets, error } = parseTargets(formData);
  if (error || !targets) return { error };
  if (targets.length !== 1) {
    return { error: 'Approve suggested matches one record at a time.' };
  }

  const playerId = Number(formData.get('playerId'));
  if (!Number.isInteger(playerId) || playerId <= 0) {
    return { error: 'The suggestion did not carry a player.' };
  }

  const note = String(formData.get('note') ?? '').trim();
  if (note.length > 2000) return { error: 'Notes are limited to 2000 characters.' };

  const { targetTable, targetId } = targets[0];
  // What the queue showed, read from the cache here rather than taken
  // from the request. Used only to report staleness afterwards.
  const displayed = (await readCachedSuggestionVersions(sql, [{ targetTable, targetId }]))
    .get(`${targetTable}:${targetId}`) ?? null;

  const result = await resolveLinkFromSuggestion({
    targetTable, targetId, playerId, adminUserId: admin.id, method: 'suggested', note, displayed,
  });
  if (!result.ok) return { error: result.error };

  let warning: string | undefined = result.notice;
  try {
    await audit('player_link.suggestion_approved', { targetTable, targetId, playerId },
      { userId: admin.id, label: admin.email });
  } catch (auditError) {
    console.error('Failed to log administrative audit for suggestion approval', auditError);
    warning = combineWarnings(warning, ACTIVITY_AUDIT_WARNING);
  }

  return { message: 'Suggested match approved.', warning, revalidatePublic: true };
}

/**
 * Approve a batch of suggestions.
 *
 * Only the target ids are taken from the request. Every row is locked,
 * re-read and rescored on its own, and must still be bulk-eligible at
 * that moment -- so a row whose evidence changed, or which another
 * admin resolved a second earlier, is skipped rather than forced
 * through. One failure does not abandon the batch and does not link
 * anything else incorrectly: each row succeeds or is reported.
 */
export async function bulkApproveSuggestions(
  _prev: PlayerLinkActionState,
  formData: FormData,
): Promise<PlayerLinkActionState> {
  const admin = await requireCapability('data.playerLinks');

  const { targets, error } = parseTargets(formData);
  if (error || !targets) return { error };

  const note = String(formData.get('note') ?? '').trim();
  if (note.length > 2000) return { error: 'Notes are limited to 2000 characters.' };

  const playerIds = String(formData.get('playerIds') ?? '').split(',');
  if (playerIds.length !== targets.length) {
    return { error: 'The selection did not match its candidates. Refresh and try again.' };
  }

  let approved = 0;
  const skipped: string[] = [];
  const stale: string[] = [];
  let warning: string | undefined;

  // One set-wise read of what the queue showed, so every row in the
  // batch is checked for staleness on the same terms as a single
  // approval -- and from the database, not the request.
  const displayedByTarget = await readCachedSuggestionVersions(sql, targets);

  for (const [index, { targetTable, targetId }] of targets.entries()) {
    const playerId = Number(playerIds[index]);
    if (!Number.isInteger(playerId) || playerId <= 0) {
      skipped.push(`${targetTable}:${targetId} (no candidate)`);
      continue;
    }

    const result = await resolveLinkFromSuggestion({
      targetTable,
      targetId,
      playerId,
      adminUserId: admin.id,
      method: 'bulk_suggested',
      note,
      displayed: displayedByTarget.get(`${targetTable}:${targetId}`) ?? null,
    });
    if (!result.ok) {
      skipped.push(`${targetTable}:${targetId} — ${result.error}`);
      continue;
    }
    if (result.notice) stale.push(`${targetTable}:${targetId} — ${result.notice}`);
    approved += 1;

    try {
      await audit('player_link.bulk_suggestion_approved', { targetTable, targetId, playerId },
        { userId: admin.id, label: admin.email });
    } catch (auditError) {
      console.error('Failed to log administrative audit for bulk approval', auditError);
      warning = ACTIVITY_AUDIT_WARNING;
    }
  }

  const summary = `Approved ${approved} suggested match(es).`;
  const staleWarning = stale.length > 0
    ? `${stale.length} row(s) were shown under an older algorithm version and were approved on `
      + `the current one: ${stale.slice(0, 5).join('; ')}${stale.length > 5 ? ' …' : ''}`
    : undefined;
  const revalidatePublic = approved > 0 ? { revalidatePublic: true as const } : {};
  if (skipped.length > 0) {
    return {
      message: summary,
      warning: combineWarnings(
        warning,
        `${skipped.length} left for review: ${skipped.slice(0, 5).join('; ')}`
        + (skipped.length > 5 ? ' …' : ''),
        staleWarning,
      ),
      ...revalidatePublic,
    };
  }
  return { message: summary, warning: combineWarnings(warning, staleWarning), ...revalidatePublic };
}

/**
 * Recompute every suggestion in the queue.
 *
 * Wholesale, so the entire cache carries one algorithm version, and
 * cheap enough to run on demand: candidate generation is three indexed
 * lookups per source row and the scoring itself is pure arithmetic.
 */
export async function refreshSuggestions(
  _prev: PlayerLinkActionState,
  _formData: FormData,
): Promise<PlayerLinkActionState> {
  const admin = await requireCapability('data.playerLinks');

  try {
    const result = await refreshMatchCandidates(sql, authSql);
    await audit('player_link.suggestions_refreshed', result,
      { userId: admin.id, label: admin.email });
    return {
      message:
        `Scored ${result.entities} queue record(s): ${result.suggestions} candidate(s) cached, `
        + `${result.bulkEligible} eligible for bulk approval (${result.algorithmVersion}).`,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return { error: `Suggestions could not be recomputed: ${message}` };
  }
}

