'use client';

import { useEffect, useState } from 'react';

import { AdminSection } from '@/app/admin/AdminSection';
import {
  SEARCH_ANIMATIONS,
  type SearchAnimationType,
} from '@/lib/site-settings';

/**
 * Super Admin editor for dynamic search box placeholders & fillout animation (see changeLog.md).
 * Includes an interactive live preview so the administrator can test typing/fade/slide animations.
 */
export function SearchPlaceholderSettings({
  placeholdersAfl,
  placeholdersAflw,
  intervalSeconds,
  animation,
}: {
  placeholdersAfl: string[];
  placeholdersAflw: string[];
  intervalSeconds: number;
  animation: SearchAnimationType;
}) {
  const [aflText, setAflText] = useState(placeholdersAfl.join('\n'));
  const [aflwText, setAflwText] = useState(placeholdersAflw.join('\n'));
  const [interval, setIntervalVal] = useState(intervalSeconds);
  const [selectedAnimation, setSelectedAnimation] = useState<SearchAnimationType>(animation);
  const [previewScope, setPreviewScope] = useState<'afl' | 'aflw'>('afl');

  // Preview animation state
  const currentList = (previewScope === 'afl' ? aflText : aflwText)
    .split('\n')
    .map((s) => s.trim())
    .filter(Boolean);
  const effectiveList = currentList.length > 0 ? currentList : ['Search…'];

  const [previewIndex, setPreviewIndex] = useState(0);
  const [previewText, setPreviewText] = useState(effectiveList[0] ?? '');
  const [isTyping, setIsTyping] = useState(true);

  useEffect(() => {
    setPreviewIndex(0);
    setPreviewText(effectiveList[0] ?? '');
  }, [previewScope, aflText, aflwText]);

  useEffect(() => {
    const target = effectiveList[previewIndex % effectiveList.length] ?? '';

    if (selectedAnimation === 'typewriter') {
      let charIdx = 0;
      let isDeleting = false;
      let timeoutId: NodeJS.Timeout;

      function step() {
        if (!isDeleting) {
          charIdx++;
          setPreviewText(target.slice(0, charIdx));
          if (charIdx >= target.length) {
            isDeleting = true;
            timeoutId = setTimeout(step, Math.max(1000, interval * 1000));
          } else {
            timeoutId = setTimeout(step, 40);
          }
        } else {
          charIdx--;
          setPreviewText(target.slice(0, charIdx));
          if (charIdx <= 0) {
            isDeleting = false;
            setPreviewIndex((prev) => (prev + 1) % effectiveList.length);
          } else {
            timeoutId = setTimeout(step, 25);
          }
        }
      }

      timeoutId = setTimeout(step, 100);
      return () => clearTimeout(timeoutId);
    } else {
      setPreviewText(target);
      const timer = setTimeout(() => {
        setPreviewIndex((prev) => (prev + 1) % effectiveList.length);
      }, Math.max(1000, interval * 1000));
      return () => clearTimeout(timer);
    }
  }, [previewIndex, selectedAnimation, interval, effectiveList]);

  return (
    <AdminSection id="settings-search-placeholders" title="Search box placeholders & animation">
      <p className="section-note">
        Configure rotating sample queries displayed in the main AFL and AFLW search boxes,
        the rotation interval, and the placeholder animation style.
      </p>

      {/* Live Preview Box */}
      <div
        style={{
          background: 'var(--bg-subtle)',
          border: '1px solid var(--border)',
          borderRadius: 'var(--radius)',
          padding: '1rem',
          marginBottom: '1.5rem',
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.75rem' }}>
          <strong style={{ fontSize: '0.88rem' }}>Live Animation Preview</strong>
          <div style={{ display: 'flex', gap: '0.5rem' }}>
            <button
              type="button"
              className={`btn btn-small ${previewScope === 'afl' ? 'btn-primary' : 'btn-secondary'}`}
              onClick={() => setPreviewScope('afl')}
              style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }}
            >
              AFL Preview
            </button>
            <button
              type="button"
              className={`btn btn-small ${previewScope === 'aflw' ? 'btn-primary' : 'btn-secondary'}`}
              onClick={() => setPreviewScope('aflw')}
              style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }}
            >
              AFLW Preview
            </button>
          </div>
        </div>

        <div style={{ position: 'relative', maxWidth: '540px' }}>
          <input
            type="text"
            readOnly
            placeholder={previewText + (selectedAnimation === 'typewriter' ? '▍' : '')}
            style={{
              width: '100%',
              padding: '0.65rem 1rem',
              borderRadius: 'var(--radius)',
              border: '1px solid var(--border-strong)',
              background: 'var(--bg-raised)',
              fontSize: '0.95rem',
              transition: selectedAnimation === 'fade' ? 'all 0.4s ease' : undefined,
            }}
          />
        </div>
        <p className="muted" style={{ fontSize: '0.75rem', marginTop: '0.4rem', marginBottom: 0 }}>
          Simulating {selectedAnimation} mode with a {interval}s rotation period.
        </p>
      </div>

      <div className="grid" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '1.25rem' }}>
        <div>
          <label htmlFor="searchPlaceholdersAfl">
            AFL search sample queries
            <span className="muted" style={{ display: 'block', fontSize: '0.75rem', fontWeight: 'normal' }}>
              One query per line. These will rotate in the global and home search boxes.
            </span>
          </label>
          <textarea
            id="searchPlaceholdersAfl"
            name="searchPlaceholdersAfl"
            rows={6}
            value={aflText}
            onChange={(e) => setAflText(e.target.value)}
            style={{
              width: '100%',
              fontFamily: 'monospace',
              fontSize: '0.85rem',
              lineHeight: 1.4,
              padding: '0.5rem',
            }}
          />
        </div>

        <div>
          <label htmlFor="searchPlaceholdersAflw">
            AFLW search sample queries
            <span className="muted" style={{ display: 'block', fontSize: '0.75rem', fontWeight: 'normal' }}>
              One query per line. These will rotate in the AFLW search boxes.
            </span>
          </label>
          <textarea
            id="searchPlaceholdersAflw"
            name="searchPlaceholdersAflw"
            rows={6}
            value={aflwText}
            onChange={(e) => setAflwText(e.target.value)}
            style={{
              width: '100%',
              fontFamily: 'monospace',
              fontSize: '0.85rem',
              lineHeight: 1.4,
              padding: '0.5rem',
            }}
          />
        </div>
      </div>

      <div style={{ marginTop: '1.25rem' }}>
        <label htmlFor="searchPlaceholderInterval">
          Rotation interval (seconds)
        </label>
        <input
          id="searchPlaceholderInterval"
          name="searchPlaceholderInterval"
          type="number"
          min={2}
          max={60}
          value={interval}
          onChange={(e) => setIntervalVal(Math.max(2, Math.min(60, Number(e.target.value) || 5)))}
          style={{ width: '120px', display: 'block', marginBottom: '1.25rem' }}
        />

        <label style={{ display: 'block', marginBottom: '0.5rem' }}>
          Placeholder fillout animation
        </label>
        <div className="grid" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: '0.5rem' }}>
          {SEARCH_ANIMATIONS.map((anim) => (
            <label
              key={anim.value}
              style={{
                display: 'block',
                padding: '0.5rem 0.75rem',
                border: '1px solid var(--border)',
                borderRadius: 'var(--radius)',
                background: selectedAnimation === anim.value ? 'var(--bg-hover)' : 'var(--bg-subtle)',
                cursor: 'pointer',
              }}
            >
              <input
                type="radio"
                name="searchPlaceholderAnimation"
                value={anim.value}
                checked={selectedAnimation === anim.value}
                onChange={() => setSelectedAnimation(anim.value)}
                style={{ marginRight: '0.45rem' }}
              />
              <strong>{anim.label}</strong>
              <span className="muted" style={{ display: 'block', fontSize: '0.75rem', marginTop: '0.2rem' }}>
                {anim.help}
              </span>
            </label>
          ))}
        </div>
      </div>
    </AdminSection>
  );
}

import type { Metadata } from 'next';
import Link from 'next/link';
import { notFound } from 'next/navigation';

import { Breadcrumbs } from '@/components/Breadcrumbs';
import { CollapsibleTable } from '@/components/CollapsibleTable';
import { ReorderableSections } from '@/components/ReorderableSections';
import {
  getAflwMatch,
  getAflwMatchPlayers,
  getAflwMatchScoring,
} from '@/db/queries/aflw';
import {
  aflwClubPath,
  aflwMatchPath,
  aflwPlayerPath,
  aflwSeasonPath,
  formatDateLong,
  formatNumber,
  formatRound,
  formatScore,
} from '@/lib/format';
import { notFoundMetadata, pageMetadata } from '@/lib/seo';

export const dynamic = 'force-dynamic';

export async function generateMetadata({
  params,
}: {
  params: Promise<{ key: string }>;
}): Promise<Metadata> {
  const { key } = await params;
  const match = await getAflwMatch(decodeURIComponent(key));
  if (!match) return notFoundMetadata('AFLW match');
  return pageMetadata({
    title:
      `${match.homeClubName} v ${match.awayClubName} — ${match.seasonLabel} AFLW Match`,
    description:
      `AFLW: ${match.homeClubName} ${match.homeScore} v ${match.awayClubName} `
      + `${match.awayScore} at ${match.venueName}.`,
    path: aflwMatchPath(match.matchKey),
    ogType: 'article',
  });
}

const PERIOD_LABELS = ['First quarter', 'Second quarter', 'Third quarter', 'Fourth quarter'];

export default async function AflwMatchPage({
  params,
}: {
  params: Promise<{ key: string }>;
}) {
  const { key: rawKey } = await params;
  const matchKey = decodeURIComponent(rawKey);

  // The team sheet and the scoring events are keyed by the match key, not
  // by anything on the match row, so all three run together.
  const [match, players, scoring] = await Promise.all([
    getAflwMatch(matchKey),
    getAflwMatchPlayers(matchKey),
    getAflwMatchScoring(matchKey),
  ]);
  if (!match) notFound();

  const teams = [
    { code: match.homeTeamCode, name: match.homeClubName, score: match.homeScore },
    { code: match.awayTeamCode, name: match.awayClubName, score: match.awayScore },
  ];
  const periods = [...new Set(scoring.map((event) => event.period))].sort();
  // The source names its scorers only up to 2021; from Season Six it
  // names the club alone. Saying which of the two this match is beats
  // rendering a column of blanks.
  const namesScorers = scoring.some((event) => event.playerName !== '');

  const sections: { id: string; label: string; node: React.ReactNode }[] = [];

  for (const team of teams) {
    sections.push({
      id: `team-sheet-${team.code}`,
      label: `${team.name} — team sheet`,
      node: (
        <section className="section">
          <CollapsibleTable
            title={`${team.name} — team sheet`}
            note={`${players.filter((p) => p.teamCode === team.code).length} players`}
          >
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th scope="col" className="num">#</th>
                    <th scope="col">Player</th>
                    <th scope="col">Pos</th>
                    <th scope="col" className="num">G</th>
                    <th scope="col" className="num">B</th>
                    <th scope="col" className="num">K</th>
                    <th scope="col" className="num">H</th>
                    <th scope="col" className="num">D</th>
                    <th scope="col" className="num">CP</th>
                    <th scope="col" className="num">M</th>
                    <th scope="col" className="num">T</th>
                    <th scope="col" className="num">HO</th>
                    <th scope="col" className="num">Metres</th>
                    <th scope="col" className="num">FP</th>
                  </tr>
                </thead>
                <tbody>
                  {players
                    .filter((player) => player.teamCode === team.code)
                    .map((player) => (
                      <tr key={player.playerSlug}>
                        <td className="num">{player.jumperNumber}</td>
                        <td className="wide">
                          <Link href={aflwPlayerPath(player.playerSlug)}>
                            {player.playerName}
                          </Link>
                        </td>
                        <td className="muted">{player.position}</td>
                        <td className="num">{player.goals}</td>
                        <td className="num">{player.behinds}</td>
                        <td className="num">{player.kicks}</td>
                        <td className="num">{player.handballs}</td>
                        <td className="num">{player.disposals}</td>
                        <td className="num">{player.contested}</td>
                        <td className="num">{player.marks}</td>
                        <td className="num">{player.tackles}</td>
                        <td className="num">{player.hitouts}</td>
                        <td className="num">{formatNumber(player.metresGained)}</td>
                        <td className="num">{player.fantasyPoints}</td>
                      </tr>
                    ))}
                </tbody>
              </table>
            </div>
          </CollapsibleTable>
        </section>
      ),
    });
  }

  sections.push({
    id: 'scoring-progression',
    label: 'Scoring progression',
    node: (
      <section className="section">
        <CollapsibleTable
          title="Scoring progression"
          note={`${scoring.length} scores`}
          defaultOpen={false}
        >
          <div className="table-wrap">
            <table>
              <caption>
                {namesScorers
                  ? 'Every score in order, as published.'
                  : 'Every score in order. This source stops naming its scorers after '
                    + '2021 and names only the club, so the scorer column is empty by '
                    + 'omission rather than unrecorded.'}
              </caption>
              <thead>
                <tr>
                  <th scope="col">Qtr</th>
                  <th scope="col" className="num">Clock</th>
                  <th scope="col">Club</th>
                  <th scope="col">Score</th>
                  {namesScorers && <th scope="col">Scorer</th>}
                  <th scope="col" className="num">Progressive</th>
                </tr>
              </thead>
              <tbody>
                {scoring.map((event) => (
                  <tr key={event.eventSeq}>
                    <td className="nowrap">
                      {PERIOD_LABELS[event.period - 1] ?? `Period ${event.period}`}
                    </td>
                    <td className="num nowrap">{event.clock}</td>
                    <td className="wide">
                      <Link href={aflwClubPath(event.teamCode)}>{event.clubName}</Link>
                    </td>
                    <td className="nowrap">{event.eventType}</td>
                    {namesScorers && (
                      <td className="wide">
                        {event.playerName || <span className="not-recorded">—</span>}
                      </td>
                    )}
                    <td className="num nowrap">
                      {event.homeGoals}.{event.homeBehinds} –{' '}
                      {event.awayGoals}.{event.awayBehinds}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CollapsibleTable>
      </section>
    ),
  });

  return (
    <>
      <Breadcrumbs items={[
        { label: 'AFLW', href: '/aflw' },
        { label: match.seasonLabel, href: aflwSeasonPath(match.seasonKey) },
        { label: `${match.homeClubName} v ${match.awayClubName}` },
      ]} />

      <div className="page-header">
        <h1>{match.homeClubName} v {match.awayClubName}</h1>
        <p className="subtitle">
          {formatDateLong(match.matchDate)}
          {match.matchTime ? ` · ${match.matchTime}` : ''}
          {' · '}
          {formatRound(match.roundType, match.roundNumber, match.roundCode)}
          {' · '}{match.venueName}
          {match.weatherRaw ? ` · ${match.weatherRaw}` : ''}
        </p>
      </div>

      <div className="stat-strip">
        <div className="stat">
          <div className="value">
            {formatScore(match.homeGoals, match.homeBehinds, match.homeScore)}
          </div>
          <div className="label">
            <Link href={aflwClubPath(match.homeTeamCode)}>{match.homeClubName}</Link>
          </div>
        </div>
        <div className="stat">
          <div className="value">
            {formatScore(match.awayGoals, match.awayBehinds, match.awayScore)}
          </div>
          <div className="label">
            <Link href={aflwClubPath(match.awayTeamCode)}>{match.awayClubName}</Link>
          </div>
        </div>
        <div className="stat">
          <div className="value">
            {match.result === 'draw' ? 'Draw' : `${match.margin}`}
          </div>
          <div className="label">
            {match.result === 'draw' ? 'Result' : 'Margin (points)'}
          </div>
        </div>
      </div>

      <p className="notice">
        Attendance and umpires are not published by this source, so they are absent
        rather than recorded as zero.
      </p>

      <ReorderableSections storageKey={aflwMatchPath(match.matchKey)} sections={sections} />
    </>
  );
}

import type { Metadata } from 'next';
import Link from 'next/link';
import { notFound } from 'next/navigation';

import { Breadcrumbs } from '@/components/Breadcrumbs';
import { CollapsibleTable } from '@/components/CollapsibleTable';
import { FilterErrors } from '@/components/FilterErrors';
import { ReorderableSections } from '@/components/ReorderableSections';
import { SortableTable } from '@/components/SortableTable';
import { TableFilters } from '@/components/TableFilters';
import { UnmatchedPlayer } from '@/components/UnmatchedPlayer';
import {
  getAward,
  getAwardLeaders,
  getAwardWinners,
  getNominationSeasons,
  getNominationsByClub,
  listAwards,
} from '@/db/queries/awards';
import {
  awardPath,
  awardSeasonPath,
  clubPath,
  formatNumber,
  formatSpan,
  isLinked,
  playerPath,
  seasonPath,
  shouldShowUnmatched,
} from '@/lib/format';
import { notFoundMetadata, pageMetadata } from '@/lib/seo';
import { SEASON_MAX, SEASON_MIN } from '@/search/list-filters';
import { type FilterField, parseFilterValues } from '@/search/table-filters';

// Reading searchParams already makes this render per request; the route
// keeps its generateStaticParams so the award list still seeds the cache.
export const revalidate = 86400;

const RISING_STAR = 'rising-star';
const ALL_AUSTRALIAN = 'all-australian';

export async function generateStaticParams() {
  const awards = await listAwards();
  return awards.map((a) => ({ slug: a.slug }));
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const { slug } = await params;
  const award = await getAward(slug);
  if (!award) return notFoundMetadata('Award');

  return pageMetadata({
    title: `${award.name} — Every Winner and Full History`,
    description:
      award.description
      ?? `Every ${award.name} winner, ${formatSpan(award.firstSeason, award.lastSeason)}.`,
    path: awardPath(award.slug),
  });
}

export default async function AwardPage({
  params,
  searchParams,
}: {
  params: Promise<{ slug: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const [{ slug }, query] = await Promise.all([params, searchParams]);
  const award = await getAward(slug);
  if (!award) notFound();

  const isRisingStar = award.slug === RISING_STAR;
  const isTeam = award.category === 'honour_team';

  const [winners, leaders, nominationSeasons, nominationClubs] = await Promise.all([
    getAwardWinners(award.id),
    getAwardLeaders(award.id),
    isRisingStar ? getNominationSeasons(award.id) : Promise.resolve([]),
    isRisingStar ? getNominationsByClub(award.id) : Promise.resolve([]),
  ]);

  // A representative team has twenty-odd names a season; listing them all
  // on one page would bury the seasons. Seasons index them instead.
  const seasonsOfTeam = isTeam
    ? [...new Set(winners.map((w) => w.season).filter((s): s is number => s !== null))]
      .sort((a, b) => b - a)
    : [];

  const unlinked = winners.filter((w) => !isLinked(w.linkStatus)).length;

  // An award's winner list is one row a season, so it is filtered here
  // rather than in SQL: the rows are already loaded for the summary
  // counts above and a second query would read the same handful again.
  const winnerFields: FilterField[] = [
    { kind: 'text', key: 'q', label: 'Player', placeholder: 'Search by name' },
    {
      kind: 'select', key: 'club', label: 'Club', anyLabel: 'Any club',
      options: [...new Map(
        winners
          .filter((w) => w.clubSlug && w.clubName)
          .map((w) => [w.clubSlug!, { value: w.clubSlug!, label: w.clubName! }]),
      ).values()].sort((a, b) => a.label.localeCompare(b.label)),
    },
    {
      kind: 'range', key: 'season', label: 'Season',
      min: award.firstSeason ?? SEASON_MIN, max: award.lastSeason ?? SEASON_MAX,
    },
  ];
  const winnerValues = parseFilterValues(winnerFields, query);
  const nameTerm = winnerValues.text.q?.toLowerCase();
  const clubSlug = winnerValues.select.club;
  const seasonRange = winnerValues.range.season;
  const filteredWinners = winners.filter((w) => {
    if (nameTerm && !w.playerName.toLowerCase().includes(nameTerm)) return false;
    if (clubSlug && w.clubSlug !== clubSlug) return false;
    // A winner with no recorded season is outside any season range, the
    // same way a NULL fails both halves of a SQL BETWEEN. Substituting a
    // sentinel would drop those rows from a minimum and keep them under a
    // maximum, which is the one thing a range filter must not do.
    if (seasonRange && w.season === null) return false;
    if (seasonRange?.min !== undefined && w.season! < seasonRange.min) return false;
    if (seasonRange?.max !== undefined && w.season! > seasonRange.max) return false;
    return true;
  });
  const showVotes = winners.some((w) => w.votes !== null);

  const sections: { id: string; label: string; node: React.ReactNode }[] = [];

  if (isRisingStar) {
    sections.push({
      id: 'nominations-by-season',
      label: 'Nominations by season',
      node: (
        <section className="section">
          <p className="section-note">
            One player is nominated each round. Every nomination since 1993 is recorded,
            with the match statistics that earned it.
          </p>
          <CollapsibleTable title="Nominations by season">
          <div className="table-wrap">
            <SortableTable
              defaultSort="season"
              defaultDir="desc"
              columns={[
                { key: 'season', label: 'Season', sortType: 'number' },
                { key: 'nominations', label: 'Nominations', sortType: 'number', className: 'num' },
                { key: 'winner', label: 'Winner', sortType: 'text' },
              ]}
              items={nominationSeasons.map((s) => ({
                id: String(s.season),
                values: {
                  season: s.season,
                  nominations: s.nominations,
                  winner: s.winner ?? '',
                },
                element: (
                  <tr key={s.season}>
                    <td>
                      <Link href={awardSeasonPath(award.slug, s.season)}>{s.season}</Link>
                    </td>
                    <td className="num">{s.nominations}</td>
                    <td className="wide">{s.winner ?? <span className="muted">—</span>}</td>
                  </tr>
                ),
              }))}
            />
          </div>
          </CollapsibleTable>
        </section>
      ),
    });
  }

  if (isTeam) {
    sections.push({
      id: 'teams-by-season',
      label: 'Teams by season',
      node: (
        <section className="section">
          <CollapsibleTable title="Teams by season">
          <div className="table-wrap">
            <SortableTable
              defaultSort="season"
              defaultDir="desc"
              columns={[
                { key: 'season', label: 'Season', sortType: 'number' },
                { key: 'selected', label: 'Selected', sortType: 'number', className: 'num' },
                { key: 'captain', label: 'Captain', sortType: 'text' },
              ]}
              items={seasonsOfTeam.map((season) => {
                const members = winners.filter((w) => w.season === season);
                const captain = members.find((m) => m.isCaptain);
                return {
                  id: String(season),
                  values: {
                    season,
                    selected: members.length,
                    captain: captain?.playerName ?? '',
                  },
                  element: (
                    <tr key={season}>
                      <td>
                        <Link href={awardSeasonPath(award.slug, season)}>{season}</Link>
                      </td>
                      <td className="num">{members.length}</td>
                      <td className="wide">
                        {captain
                          ? captain.playerId && isLinked(captain.linkStatus)
                            ? (
                              <Link href={playerPath(captain.playerSlug!, captain.playerId)}>
                                {captain.playerName}
                              </Link>
                            )
                            : captain.playerName
                          : <span className="muted">—</span>}
                      </td>
                    </tr>
                  ),
                };
              })}
            />
          </div>
          </CollapsibleTable>
        </section>
      ),
    });
  }

  if (leaders.length > 0) {
    // The span AFLDB actually holds, from the winner rows themselves —
    // a state-league award loaded from 1980 must not imply its 1920s
    // winners were counted.
    const winnerSeasons = winners
      .map((w) => w.season)
      .filter((s): s is number => s !== null);
    const coverage = winnerSeasons.length > 0
      ? `${Math.min(...winnerSeasons)}–${Math.max(...winnerSeasons)}`
      : null;

    sections.push({
      id: 'multiple-winners',
      label: 'Multiple winners',
      node: (
        <section className="section">
          {coverage && (
            <p className="section-note">
              Counted across the seasons AFLDB holds for this award ({coverage}).
            </p>
          )}
          <CollapsibleTable title="Multiple winners">
          <div className="table-wrap">
            <SortableTable
              defaultSort="wins"
              defaultDir="desc"
              columns={[
                { key: 'player', label: 'Player', sortType: 'text' },
                { key: 'wins', label: 'Wins', sortType: 'number', className: 'num' },
                { key: 'seasons', label: 'Seasons', sortType: 'text' },
              ]}
              items={leaders.map((l) => ({
                id: l.playerId ? String(l.playerId) : l.displayName,
                values: {
                  player: l.displayName,
                  wins: l.wins,
                  seasons: l.seasons,
                },
                element: (
                  <tr key={l.playerId ?? l.displayName}>
                    <td className="wide">
                      {l.playerId !== null && l.slug !== null ? (
                        <Link href={playerPath(l.slug, l.playerId)}>{l.displayName}</Link>
                      ) : (
                        <span title="Not linked to an AFLDB player">{l.displayName}</span>
                      )}
                    </td>
                    <td className="num">{l.wins}</td>
                    <td className="wide muted">{l.seasons}</td>
                  </tr>
                ),
              }))}
            />
          </div>
          </CollapsibleTable>
        </section>
      ),
    });
  }

  if (isRisingStar && nominationClubs.length > 0) {
    sections.push({
      id: 'nominations-by-club',
      label: 'Nominations by club',
      node: (
        <section className="section">
          <p className="section-note">
            Counted by club as a continuing entity, so Footscray and Western Bulldogs
            nominations are one club’s.
          </p>
          <CollapsibleTable title="Nominations by club">
          <div className="table-wrap">
            <SortableTable
              defaultSort="nominations"
              defaultDir="desc"
              columns={[
                { key: 'club', label: 'Club', sortType: 'text' },
                { key: 'nominations', label: 'Nominations', sortType: 'number', className: 'num' },
                { key: 'winners', label: 'Winners', sortType: 'number', className: 'num' },
              ]}
              items={nominationClubs.map((c) => ({
                id: String(c.clubId),
                values: {
                  club: c.name,
                  nominations: c.nominations,
                  winners: c.winners,
                },
                element: (
                  <tr key={c.clubId}>
                    <td className="wide"><Link href={clubPath(c.slug)}>{c.name}</Link></td>
                    <td className="num">{c.nominations}</td>
                    <td className="num">{c.winners}</td>
                  </tr>
                ),
              }))}
            />
          </div>
          </CollapsibleTable>
        </section>
      ),
    });
  }

  if (!isTeam) {
    sections.push({
      id: 'every-winner',
      label: 'Every winner',
      node: (
        <section className="section">
          <CollapsibleTable
            id="winners"
            title="Every winner"
            note={
              filteredWinners.length === winners.length
                ? `${winners.length} winners`
                : `${filteredWinners.length} of ${winners.length} winners`
            }
            filters={
              <TableFilters
                action={awardPath(award.slug)}
                anchor="winners"
                fields={winnerFields}
                values={winnerValues}
                title="Filter winners"
                submitLabel="Apply"
              />
            }
          >
          <FilterErrors errors={winnerValues.errors} />
          {filteredWinners.length === 0 ? (
            <div className="empty">
              <h2>No winners match those filters</h2>
              <p>Try clearing the club or widening the season range.</p>
            </div>
          ) : (
          <div className="table-wrap">
            <SortableTable
              defaultSort="season"
              defaultDir="desc"
              columns={[
                { key: 'season', label: 'Season', sortType: 'number' },
                { key: 'player', label: 'Player', sortType: 'text' },
                { key: 'club', label: 'Club', sortType: 'text' },
                ...(showVotes ? [{ key: 'votes', label: 'Votes', sortType: 'number' as const, className: 'num' }] : []),
              ]}
              items={filteredWinners.map((w) => ({
                id: String(w.id),
                values: {
                  season: w.season,
                  player: w.playerName,
                  club: w.clubNameRaw ?? w.clubName ?? '',
                  votes: w.votes,
                },
                element: (
                  <tr key={w.id}>
                    <td>
                      {w.season
                        ? <Link href={seasonPath(w.season)}>{w.season}</Link>
                        : <span className="muted">—</span>}
                    </td>
                    <td className="wide">
                      {w.playerId && isLinked(w.linkStatus) ? (
                        <Link href={playerPath(w.playerSlug!, w.playerId)}>
                          {w.playerName}
                        </Link>
                      ) : (
                        <span title="Not linked to an AFLDB player">{w.playerName}</span>
                      )}
                      {shouldShowUnmatched({
                        linkStatus: w.linkStatus,
                        clubName: w.clubNameRaw ?? w.clubName,
                        clubId: w.clubId,
                      }) && <UnmatchedPlayer targetTable="award_winners" targetId={w.id} />}
                    </td>
                    <td>
                      {w.clubSlug
                        ? <Link href={clubPath(w.clubSlug)}>{w.clubName}</Link>
                        : <span className="muted">{w.clubNameRaw ?? '—'}</span>}
                    </td>
                    {showVotes && (
                      <td className="num">{w.votes ?? <span className="muted">—</span>}</td>
                    )}
                  </tr>
                ),
              }))}
            />
          </div>
          )}
          </CollapsibleTable>
        </section>
      ),
    });
  }

  return (
    <>
      <Breadcrumbs items={[
        { label: 'Awards', href: '/awards' },
        { label: award.name },
      ]} />

      <div className="page-header">
        <h1>{award.name}</h1>
        <p className="subtitle">
          {award.clubSlug && (
            <>
              <Link href={clubPath(award.clubSlug)}>{award.clubName}</Link>
              {' · '}
            </>
          )}
          {award.competition ? `${award.competition} · ` : ''}
          {formatSpan(award.firstSeason, award.lastSeason)}
        </p>
      </div>

      {award.description && <p className="notice">{award.description}</p>}

      <div className="stat-strip">
        <div className="stat">
          <div className="value">{formatNumber(award.seasonCount)}</div>
          <div className="label">Seasons</div>
        </div>
        <div className="stat">
          <div className="value">{formatNumber(award.winnerCount)}</div>
          <div className="label">{isTeam ? 'Selections' : 'Winners'}</div>
        </div>
        {isRisingStar && (
          <div className="stat">
            <div className="value">
              {formatNumber(nominationSeasons.reduce((n, s) => n + s.nominations, 0))}
            </div>
            <div className="label">Nominations</div>
          </div>
        )}
        {unlinked > 0 && (
          <div className="stat">
            <div className="value">{formatNumber(unlinked)}</div>
            <div className="label">Unlinked names</div>
          </div>
        )}
      </div>

      {unlinked > 0 && (
        <p className="notice">
          {formatNumber(unlinked)} of these {formatNumber(award.winnerCount)} entries name
          a player AFLDB could not identify with confidence — most often a state-league
          footballer with no VFL/AFL record. They are listed as the source spelled them,
          without a link.
        </p>
      )}

      <ReorderableSections storageKey={`/awards/${award.slug}`} sections={sections} />
    </>
  );
}

'use server';

import { redirect } from 'next/navigation';

import { authSql } from '@/db/authClient';
import { generateToken, sha256Hex } from '@/lib/auth/crypto';
import { RateLimiter } from '@/lib/auth/rate-limit';
import { audit, grantBetaAccess, requestIp } from '@/lib/auth/session';
import { sendEmail } from '@/lib/email/send';

/**
 * The two ways into the beta: an access code, or a magic link to an
 * allowlisted email.
 *
 * Both paths deliberately return the same message on failure. "That code
 * is revoked", "that email is not on the list" and "that code never
 * existed" are three different facts internally and one sentence
 * externally, because the difference is only useful to someone probing.
 */

export type BetaFormState = {
  error?: string;
  sent?: boolean;
};

export type JoinRequestState = {
  error?: string;
  requested?: boolean;
};

const GENERIC_FAILURE =
  'That code or email was not accepted. Check it and try again, or contact the person who invited you.';

// A visitor who fails repeatedly is guessing. Small in-memory limiters, per
// worker: crude, but the right shape for a beta of dozens of people. Keyed on
// the caller's IP, never on the code or email they supply — keying on content
// let an attacker rotate it to dodge the limit, and because every real code
// starts "afldb-" it also collapsed all genuine redemptions into one bucket a
// few bad guesses could exhaust for everyone.
const REDEEM_LIMIT = new RateLimiter(10, 15 * 60 * 1000);
const MAGIC_LINK_LIMIT = new RateLimiter(5, 15 * 60 * 1000);
const JOIN_REQUEST_LIMIT = new RateLimiter(5, 15 * 60 * 1000);

/** Where to send an admitted visitor: only ever an internal path. */
function safeDestination(from: FormDataEntryValue | null): string {
  if (typeof from !== 'string') return '/';
  // Must be an absolute same-origin path: a leading '/' whose next character
  // is neither '/' nor '\'. Browsers fold '/\' (and '\/') into '//', so the
  // old '//' check alone let `/\evil.com` through as a protocol-relative,
  // off-origin redirect. Also reject control characters (header/redirect
  // splitting).
  if (!/^\/[^/\\]/.test(from)) return '/';
  // eslint-disable-next-line no-control-regex
  if (/[\x00-\x1f\x7f]/.test(from)) return '/';
  return from;
}

export async function redeemAccessCode(
  _previous: BetaFormState,
  formData: FormData,
): Promise<BetaFormState> {
  const code = String(formData.get('code') ?? '').trim();
  const destination = safeDestination(formData.get('from'));

  if (code.length < 8 || code.length > 100) {
    return { error: GENERIC_FAILURE };
  }
  if (REDEEM_LIMIT.check(`ip:${(await requestIp()) ?? 'unknown'}`)) {
    return { error: 'Too many attempts. Wait a few minutes and try again.' };
  }

  // Atomic redeem: the use is counted in the same statement that checks
  // the limits, so a code cannot be double-spent by two racing requests.
  //
  // A NULL max_uses means unlimited (migration 036), matching the NULL
  // expires_at convention on the line above. Without the explicit IS NULL
  // test this comparison would be NULL rather than true, and an unlimited
  // code would be refused every time — the failure mode is silent, because
  // "not accepted" is the same message a wrong code gets.
  const [row] = await authSql<{ id: number; label: string }[]>`
    UPDATE beta_access_codes
       SET use_count = use_count + 1
     WHERE code_hash = ${sha256Hex(code)}
       AND revoked_at IS NULL
       AND (expires_at IS NULL OR expires_at > now())
       AND (max_uses IS NULL OR use_count < max_uses)
    RETURNING id, label
  `;

  if (!row) {
    await audit('beta.code_rejected', null, { label: 'anonymous' });
    return { error: GENERIC_FAILURE };
  }

  await audit('beta.code_redeemed', { codeId: row.id, label: row.label }, { label: row.label });
  await grantBetaAccess(`code:${row.id}`);
  redirect(destination);
}

export async function requestMagicLink(
  _previous: BetaFormState,
  formData: FormData,
): Promise<BetaFormState> {
  const email = String(formData.get('email') ?? '').trim().toLowerCase();

  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) || email.length > 200) {
    return { error: GENERIC_FAILURE };
  }
  if (MAGIC_LINK_LIMIT.check(`ip:${(await requestIp()) ?? 'unknown'}`)) {
    return { error: 'Too many attempts. Wait a few minutes and try again.' };
  }

  const [allowed] = await authSql<{ id: number }[]>`
    SELECT id FROM beta_allowed_emails
     WHERE email = ${email} AND revoked_at IS NULL
  `;

  // The response is the same either way; only an allowlisted email gets
  // a token. An attacker cannot enumerate the list from this form.
  if (allowed) {
    const token = generateToken();
    await authSql`
      INSERT INTO beta_login_tokens (email, token_hash, expires_at)
      VALUES (${email}, ${sha256Hex(token)}, now() + interval '30 minutes')
    `;

    const base = process.env.AFLDB_BASE_URL ?? 'http://localhost:3100';
    const link = `${base}/beta/verify?token=${token}`;

    const delivery = await sendEmail({
      to: email,
      subject: 'Your AFLDB sign-in link',
      text: [
        'Here is your sign-in link for the AFLDB beta:',
        '',
        link,
        '',
        'It expires in 30 minutes and can be used once.',
        '',
        'If you did not ask for this, nothing has happened and you can ignore',
        'this message — the link is useless without this mailbox.',
      ].join('\n'),
    });

    // The link carries a live 30-minute credential, so it must never reach a
    // production log. With no relay configured there is nowhere to send it,
    // which is the normal state in development: the operator reads it from
    // the journal and passes it on. In production that fallback would write a
    // working credential into the log, so it is withheld and the failure is
    // reported without it.
    if (!delivery.ok) {
      if (process.env.AFLDB_ENV === 'production') {
        console.warn(`[beta] magic link for ${email} could not be sent (${delivery.reason})`);
      } else {
        console.info(`[beta] magic link for ${email}: ${link}`);
      }
    }

    // `delivered` is worth auditing: a request that was accepted but never
    // reached anybody looks identical from the outside, and this is the only
    // record that separates the two.
    await audit('beta.magic_link_issued', { email, delivered: delivery.ok }, { label: email });
  } else {
    await audit('beta.magic_link_refused', { email }, { label: email });
  }

  return { sent: true };
}

/**
 * A visitor with neither a code nor an allowlisted email can ask instead.
 * This never admits anyone by itself — it only queues a row for a human at
 * /admin/access to approve or deny, at which point approval allowlists the
 * email through the normal path.
 */
export async function requestJoin(
  _previous: JoinRequestState,
  formData: FormData,
): Promise<JoinRequestState> {
  const email = String(formData.get('email') ?? '').trim().toLowerCase();
  const name = String(formData.get('name') ?? '').trim().slice(0, 200) || null;
  const message = String(formData.get('message') ?? '').trim().slice(0, 1000) || null;

  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) || email.length > 200) {
    return { error: 'That is not an email address.' };
  }
  if (JOIN_REQUEST_LIMIT.check(`ip:${(await requestIp()) ?? 'unknown'}`)) {
    return { error: 'Too many attempts. Wait a few minutes and try again.' };
  }

  const ip = await requestIp();
  await authSql`
    INSERT INTO beta_join_requests (email, name, message, ip)
    VALUES (${email}, ${name}, ${message}, ${ip})
    ON CONFLICT (email) WHERE status = 'pending' DO NOTHING
  `;
  await audit('beta.join_requested', { email }, { label: email });

  return { requested: true };
}

