              <tr>
                <th scope="row">Clubs</th>
                <td>{player.clubsPlayed}</td>
                <th scope="row">Best game (goals)</th>
                <td>{formatStat(player.bestGoalsGame)}</td>
              </tr>
              <tr>
                <th scope="row">Best game (disposals)</th>
