            </tbody>
          </table>
        </div>
        </CollapsibleTable>
      </section>
    ),
  });

  if (draftHistory.length > 0) {
    sections.push({
      id: 'draft',
      label: 'Draft & recruitment',
      node: (
        <section className="section">
          <CollapsibleTable title="Draft & recruitment">
