  if (honours.total > 0) {
    sections.push({
      id: 'honours',
      label: 'Honours',
      node: (
        <section className="section">
          <CollapsiblePanel title="Honours">
          <ul className="ruled-list">
            {honours.hallOfFame && (
              <li>
                <strong>Australian Football Hall of Fame</strong>
