            <SortableTable
              defaultSort="seasons"
              defaultDir="desc"
              columns={[
                { key: 'club', label: 'Club', sortType: 'text' },
                { key: 'seasons', label: 'Seasons', sortType: 'number', className: 'num nowrap' },
                { key: 'games', label: 'Games', sortType: 'number', className: 'num' },
                { key: 'goals', label: 'Goals', sortType: 'number', className: 'num' },
