            items={seasons.map((s) => ({
              id: String(s.season),
              values: {
                season: s.season,
                club: s.clubName ?? '',
                gm: s.games,
                wld: s.wins, // Sort W-L-D by wins
                g: s.goals ?? -1,
                b: s.behinds ?? -1,
                d: s.disposals ?? -1,
                m: s.marks ?? -1,
