  sections.push({
    id: 'match-log',
    label: 'Match log',
    node: (
      <section className="section">
        <CollapsibleTable title="Match log">
        <div className="table-wrap">
          <table>
            <caption>
              {matches.total > MATCH_PAGE_SIZE
