'use client';

import { useEffect, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';

import { CoachOpponentRecordBody } from '@/components/CoachCareerRecord';
import type { ComparisonOrganization } from '@/db/queries/club-comparison';
import type { CoachOpponentSelection } from '@/lib/coach-opponent-history';

/**
 * The player-linked coaching surface's Stage 1C opponent selector
 * (AFLDB-ISSUE-170 Stage 1D).
 *
 * A deliberate, narrowly scoped exception to two conventions the shared
 * presentation in `CoachCareerRecord` never breaks anywhere else on this
 * surface: it fetches over the network, and it does not work without
 * JavaScript.
 *
 * `/players/[slug]` is static ISR, seeded for ~13,000 players, and its
 * own comment says reading `searchParams` there "would force dynamic
 * rendering and cost roughly 2s per request under load" — this repo does
 * not set `cacheComponents`, so that cost is real and would apply to
 * every player page, not only linked coaches. Reading the URL here
 * instead, via `useSearchParams` inside the `<Suspense>` boundary
 * `PlayerCoachingCareer` wraps this in, only bails that one subtree out
 * to client-side rendering (the standard Next.js CSR-bailout pattern for
 * `useSearchParams` under static rendering) — the rest of the player page
 * stays exactly as static as before.
 *
 * The standalone `/coaches/[slug]` page has no such constraint (18
 * coach-only identities) and resolves the identical selection fully
 * server-rendered, with a plain GET form and no client fetch at all — see
 * `CoachOpponentSelector` and `resolveCoachOpponentSelection`, which this
 * component's target route handler also calls, so an unresolvable
 * opponent reads the same "is not a club on record" way on both surfaces.
 */
export function CoachOpponentHistoryClient({
  coachId,
  organizations,
  showCoachedClub,
}: {
  coachId: number;
  organizations: ComparisonOrganization[];
  showCoachedClub: boolean;
}) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const requested = searchParams.get('opponent') ?? '';

  const [selection, setSelection] = useState<CoachOpponentSelection>({ kind: 'none' });
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!requested) {
      setSelection({ kind: 'none' });
      return;
    }
    let cancelled = false;
    setLoading(true);
    fetch(`/api/coaches/${coachId}/opponent-record?organization=${encodeURIComponent(requested)}`)
      .then((res) => res.json() as Promise<CoachOpponentSelection>)
      .then((data) => {
        if (!cancelled) setSelection(data);
      })
      .catch(() => {
        if (!cancelled) setSelection({ kind: 'invalid', requested });
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [coachId, requested]);

  function onChange(slug: string) {
    const params = new URLSearchParams(searchParams.toString());
    if (slug) params.set('opponent', slug);
    else params.delete('opponent');
    const query = params.toString();
    router.push(query ? `?${query}` : '?', { scroll: false });
  }

  const current = organizations.filter((o) => o.isActive);
  const former = organizations.filter((o) => !o.isActive);

  return (
    <div className="filter-group">
      <label htmlFor="player-coach-opponent">History against club</label>{' '}
      <select id="player-coach-opponent" value={requested} onChange={(e) => onChange(e.target.value)}>
        <option value="">Choose an opponent…</option>
        {current.length > 0 && (
          <optgroup label="Current clubs">
            {current.map((o) => <option key={o.id} value={o.slug}>{o.name}</option>)}
          </optgroup>
        )}
        {former.length > 0 && (
          <optgroup label="Former clubs">
            {former.map((o) => <option key={o.id} value={o.slug}>{o.name}</option>)}
          </optgroup>
        )}
      </select>

      {loading && <p className="muted">Loading…</p>}
      {!loading && selection.kind === 'invalid' && (
        <p className="muted">{selection.requested} is not a club on record.</p>
      )}
      {!loading && selection.kind === 'resolved' && (
        <>
          <h4>vs {selection.organization.name}</h4>
          <CoachOpponentRecordBody record={selection.record} showCoachedClub={showCoachedClub} />
        </>
      )}
    </div>
  );
}

'use client';

import Link from 'next/link';
import { useEffect, useState } from 'react';

import { setConsent } from '@/app/consent-action';
import { isConsentChoice, readConsentCookie } from '@/lib/consent';

/**
 * The analytics-storage banner.
 *
 * WHY THIS IS A CLIENT COMPONENT, having started as a server one: it
 * lives in the root layout, so the cookie read that decides whether to
 * show it was a cookie read in the root layout -- which makes every route
 * in the site dynamic, prerendered home page and 60-odd ISR club, match
 * and season pages included. A consent banner is not worth turning the
 * whole site into per-request rendering, and it does not have to be: the
 * consent cookie is deliberately not httpOnly (see consent-action.ts), so
 * the browser can answer the same question itself.
 *
 * The submission is still a <form> posting to a server action rather than
 * an onClick fetch: the cookie is written by the server, once, in response
 * to a real form post.
 *
 * The banner is absent from the server-rendered HTML and appears on
 * mount, which is the fail-closed direction: a visitor with no scripting
 * sees no banner, records no choice, and gets no analytics cookie, since
 * middleware mints nl_sid only on an explicit "accepted".
 *
 * It renders only while the visitor has not answered. Both buttons are
 * equally weighted and equally easy to press -- a banner where declining
 * is harder than accepting is not collecting consent, it is collecting a
 * click.
 *
 * "Accept" and "Decline" both dismiss it permanently, because both are
 * answers; there is deliberately no close-without-choosing control that
 * would leave the question to be asked again on the next page. Dismissal
 * is local state rather than a re-read of the cookie, because a server
 * action's re-render reconciles against this same markup and would leave
 * a banner the reader has already answered sitting on screen.
 */
export function ConsentBanner() {
  const [answered, setAnswered] = useState(true);

  useEffect(() => {
    setAnswered(isConsentChoice(readConsentCookie()));
  }, []);

  // Awaited, not raced: the banner goes away because the choice was
  // recorded, so a write that fails leaves the question on screen instead
  // of pretending to have answered it. Hiding first and posting after
  // would also unmount the form mid-submission.
  async function record(formData: FormData) {
    await setConsent(formData);
    setAnswered(true);
  }

  if (answered) return null;

  return (
    <aside className="consent-banner" role="region" aria-label="Cookies">
      <div className="container consent-banner-inner">
        <p>
          AFLDB would like to set one anonymous cookie that links the searches you make in a
          single visit, so we can see where the search engine misreads a question. It expires
          after 30 minutes, is never shared, and identifies nobody. The site works exactly the
          same if you decline.{' '}
          <Link href="/privacy">What we store</Link>
        </p>
        <div className="consent-banner-actions">
          <form action={record}>
            <input type="hidden" name="choice" value="accepted" />
            <button type="submit" className="btn">Accept</button>
          </form>
          <form action={record}>
            <input type="hidden" name="choice" value="declined" />
            <button type="submit" className="btn">Decline</button>
          </form>
        </div>
      </div>
    </aside>
  );
}

import { jsonLdHtml } from '@/lib/structured-data';

/**
 * A Schema.org block, embedded as `application/ld+json`.
 *
 * The serialisation — including the `</script>` escape that keeps a database
 * string from closing this element early — lives in `jsonLdHtml`, so the
 * rule can be tested without a JSX transform.
 *
 * A Server Component, and it must stay one: this markup exists for crawlers,
 * so it has to be in the HTML the server sends rather than added on
 * hydration.
 */
export function JsonLd({ data }: { data: object | object[] }) {
  return (
    <script
      type="application/ld+json"
      // eslint-disable-next-line react/no-danger
      dangerouslySetInnerHTML={{ __html: jsonLdHtml(data) }}
    />
  );
}

'use client';

import { useState } from 'react';

import { NL_FEEDBACK_MAX_LENGTH } from '@/search/nl/feedback-spec';

export function NlAnswerFeedbackControls() {
  const [choice, setChoice] = useState<'none' | 'incorrect'>('none');
  const [dismissed, setDismissed] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  if (dismissed) return null;

  if (submitted) {
    return (
      <p className="muted" style={{ fontSize: '0.85rem', marginTop: 0 }}>
        Thanks - that goes straight to the people improving search.
      </p>
    );
  }

  return (
    <>
      <span className="muted" style={{ fontSize: '0.85rem' }}>
        Did AFLDB understand this question?
      </span>

      <button
        type="submit"
        name="verdict"
        value="correct"
        onClick={() => setSubmitted(true)}
        style={{ fontSize: '0.85rem' }}
      >
        Yes
      </button>

      <button
        type="submit"
        name="verdict"
        value="incorrect"
        onClick={(event) => {
          if (choice === 'none') {
            event.preventDefault();
            setChoice('incorrect');
          } else {
            setSubmitted(true);
          }
        }}
        style={{ fontSize: '0.85rem' }}
      >
        No
      </button>

      <button
        type="button"
        onClick={() => setDismissed(true)}
        className="muted"
        aria-label="Dismiss this question"
        style={{ fontSize: '0.85rem', background: 'none', border: 'none', cursor: 'pointer' }}
      >
        Dismiss
      </button>

      {choice === 'incorrect' && (
        <div style={{ flexBasis: '100%', marginTop: '0.4rem' }}>
          <label
            htmlFor="nl-feedback-expected"
            className="muted"
            style={{ display: 'block', fontSize: '0.85rem', marginBottom: '0.3rem' }}
          >
            What should the answer have been? (optional)
          </label>
          <textarea
            id="nl-feedback-expected"
            name="expectedAnswer"
            rows={3}
            maxLength={NL_FEEDBACK_MAX_LENGTH}
            placeholder="e.g. it should have been Tony Lockett's 1997 season, not his career total"
            style={{ width: '100%', fontSize: '0.85rem' }}
          />
          <p className="muted" style={{ fontSize: '0.75rem', marginTop: '0.3rem' }}>
            Please don't include anything personal - this is stored anonymously.
          </p>
        </div>
      )}
    </>
  );
}

