'use client';

import { useEffect, useId, useRef, useState } from 'react';

import { MIN_QUERY_LENGTH } from '@/search/constants';

type PlayerSuggestion = {
  id: number;
  slug: string;
  title: string;
  subtitle: string | null;
};

/**
 * A "fill a slot" player picker, for /players/compare and the grid
 * solver's Teammates category -- unlike SearchBox, which navigates on
 * selection, this holds the chosen player as local state and submits it
 * as a hidden field, so a parent <form method="get"> carries it through
 * as a plain query param.
 *
 * searchPlayers()'s subtitle ("<clubs> · <span> · <games> games") already
 * disambiguates same-named players, so this needs no separate
 * disambiguation UI of its own.
 *
 * There is no meaningful no-JS fallback here: choosing a specific player
 * id from a name genuinely requires the autocomplete round trip when two
 * people share a name, unlike SearchBox's free-text search, which is
 * still a valid query without JS.
 */
export function PlayerPicker({
  name,
  label,
  initialSelected = null,
  onSelect,
}: {
  /** The hidden field's name, e.g. "a" or "b". Omit when only `onSelect` is used (no wrapping native form). */
  name?: string;
  label: string;
  initialSelected?: { id: number; label: string } | null;
  /** Called with the new selection (or null on "Change"), for a parent that holds its own state instead of relying on the hidden field -- e.g. GridSolverForm, which has no native form submission at all. */
  onSelect?: (selected: { id: number; label: string } | null) => void;
}) {
  const listId = useId();
  const [selected, setSelected] = useState(initialSelected);
  const [query, setQuery] = useState('');
  const [suggestions, setSuggestions] = useState<PlayerSuggestion[]>([]);
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const abortRef = useRef<AbortController | null>(null);
  const boxRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const term = query.trim();
    if (term.length < MIN_QUERY_LENGTH) {
      setSuggestions([]);
      setOpen(false);
      return;
    }

    const timer = setTimeout(async () => {
      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;
      try {
        const res = await fetch(`/api/search/autocomplete?q=${encodeURIComponent(term)}&scope=players`, {
          signal: controller.signal,
        });
        if (!res.ok) return;
        const data = (await res.json()) as { results: PlayerSuggestion[] };
        setSuggestions(data.results);
        setOpen(data.results.length > 0);
        setActive(-1);
      } catch {
        // Aborted or offline: leave the previous suggestions in place.
      }
    }, 180);

    return () => clearTimeout(timer);
  }, [query]);

  useEffect(() => {
    function onClickOutside(event: MouseEvent) {
      if (!boxRef.current?.contains(event.target as Node)) setOpen(false);
    }
    document.addEventListener('mousedown', onClickOutside);
    return () => document.removeEventListener('mousedown', onClickOutside);
  }, []);

  function choose(suggestion: PlayerSuggestion) {
    const next = { id: suggestion.id, label: suggestion.title };
    setSelected(next);
    setQuery('');
    setSuggestions([]);
    setOpen(false);
    onSelect?.(next);
  }

  function change() {
    setSelected(null);
    setQuery('');
    onSelect?.(null);
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (!open || suggestions.length === 0) return;
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      setActive((i) => (i + 1) % suggestions.length);
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      setActive((i) => (i <= 0 ? suggestions.length - 1 : i - 1));
    } else if (event.key === 'Enter' && active >= 0) {
      event.preventDefault();
      choose(suggestions[active]);
    } else if (event.key === 'Escape') {
      setOpen(false);
    }
  }

  if (selected) {
    return (
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
        {name && <input type="hidden" name={name} value={selected.id} />}
        <strong>{selected.label}</strong>
        <button type="button" className="btn btn-secondary" onClick={change}>
          Change
        </button>
      </div>
    );
  }

  return (
    <div ref={boxRef} style={{ position: 'relative' }}>
      <label htmlFor={`${listId}-input`} className="visually-hidden">{label}</label>
      <input
        id={`${listId}-input`}
        type="search"
        value={query}
        placeholder={label}
        autoComplete="off"
        role="combobox"
        aria-expanded={open}
        aria-controls={listId}
        aria-autocomplete="list"
        aria-activedescendant={active >= 0 ? `${listId}-opt-${active}` : undefined}
        onChange={(e) => setQuery(e.target.value)}
        onKeyDown={onKeyDown}
      />

      {open && (
        <ul
          id={listId}
          role="listbox"
          aria-label={`${label} suggestions`}
          style={{
            position: 'absolute',
            zIndex: 30,
            left: 0,
            right: 0,
            margin: '4px 0 0',
            padding: 0,
            listStyle: 'none',
            background: 'var(--bg-raised)',
            border: '1px solid var(--border-strong)',
            borderRadius: 'var(--radius)',
            boxShadow: '0 6px 20px rgba(0,0,0,0.12)',
            textAlign: 'left',
            maxHeight: '20rem',
            overflowY: 'auto',
          }}
        >
          {suggestions.map((s, i) => (
            <li
              key={s.id}
              id={`${listId}-opt-${i}`}
              role="option"
              aria-selected={i === active}
              onMouseDown={(e) => { e.preventDefault(); choose(s); }}
              onMouseEnter={() => setActive(i)}
              style={{
                padding: '0.4rem 0.6rem',
                cursor: 'pointer',
                background: i === active ? 'var(--bg-hover)' : 'transparent',
                borderBottom: '1px solid var(--border)',
              }}
            >
              <div style={{ fontWeight: 550 }}>{s.title}</div>
              {s.subtitle && (
                <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)' }}>{s.subtitle}</div>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';

/**
 * Lets a reader drag a page's table sections into whatever order suits
 * them, remembered per page (by pathname) in localStorage.
 *
 * Renders the default order first -- the same markup the server sent --
 * and only reorders after mount, once localStorage has been read. That
 * keeps hydration matching the server render; a reader with a saved order
 * sees one reflow right after load rather than a hydration mismatch.
 *
 * One control does this, the grab handle: drag it with a mouse, or focus it
 * and press the arrow keys. Both drive the same `move`/`reorder` state, so
 * the drag gesture is a shortcut rather than the only way in — which is what
 * keeps the handle usable from the keyboard and legible to a screen reader,
 * now that the Move up/down buttons that used to sit beside it are gone.
 *
 * The one input this leaves out is touch: HTML5 drag-and-drop does not fire
 * for a finger, and there is no longer a button to tap instead. A phone
 * therefore reads the default order, which is the order the server sent.
 */
export function ReorderableSections({
  storageKey,
  sections,
}: {
  /** Unique per page -- callers pass the pathname. */
  storageKey: string;
  sections: { id: string; label: string; node: React.ReactNode }[];
}) {
  const defaultOrder = sections.map((s) => s.id);
  const dragId = useRef<string | null>(null);
  const [dragOverId, setDragOverId] = useState<string | null>(null);

  const fullKey = `afldb:table-order:${storageKey}`;
  // What the held order is an order OF. The App Router keeps a client
  // component mounted across a navigation that only changes route params
  // (/clubs/a to /clubs/b, one season to the next), so without this the
  // state would still hold the previous page's ids -- and since the render
  // below is `order.map`, any section the new page has that the old one
  // lacked would silently never appear. Rebuilding on either half changing
  // is React's "adjust state during render" pattern, not an effect, so no
  // wrong-page render is ever committed.
  const signature = `${fullKey}|${defaultOrder.join()}`;

  const [state, setState] = useState({ signature, order: defaultOrder });
  if (state.signature !== signature) setState({ signature, order: defaultOrder });
  const order = state.signature === signature ? state.order : defaultOrder;

  // The restored order awaiting a re-anchor, held by identity rather than as
  // a flag: on mount both effects run back to back, before the restore's
  // setState has re-rendered anything, so the effect below has to be able to
  // tell "the DOM you are looking at is already the reordered one" from "the
  // reorder has not painted yet".
  const reanchorFor = useRef<string[] | null>(null);

  useEffect(() => {
    let saved: string[] | null = null;
    try {
      const raw = localStorage.getItem(fullKey);
      saved = raw ? JSON.parse(raw) : null;
    } catch {
      saved = null;
    }
    if (!saved || !Array.isArray(saved)) return;

    // A page's sections can change between visits (a filter changing what
    // renders, a deploy adding one); keep only ids that still exist, and
    // append any new ones at the end rather than dropping them.
    const known = new Set(defaultOrder);
    const restored = saved.filter((id): id is string => known.has(id));
    const missing = defaultOrder.filter((id) => !restored.includes(id));
    const next = [...restored, ...missing];
    if (next.join() === defaultOrder.join()) return;
    reanchorFor.current = next;
    setState({ signature, order: next });
    // Re-read whenever the page or its section list changes; `signature`
    // covers both, and `defaultOrder` is derived from it.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [signature]);

  useEffect(() => {
    if (reanchorFor.current !== order) return;
    reanchorFor.current = null;
    // A filtered table returns to its own anchor (see TableFilters), and the
    // browser scrolled there against the server's default order. The reorder
    // has now painted and moved that element, so put the viewport back on it.
    const hash = window.location.hash.slice(1);
    if (!hash) return;
    document.getElementById(decodeURIComponent(hash))?.scrollIntoView();
  }, [order]);

  function persist(next: string[]) {
    setState({ signature, order: next });
    try {
      localStorage.setItem(fullKey, JSON.stringify(next));
    } catch {
      // Private browsing / storage full: reordering still works for this
      // page view, it just won't be remembered next time.
    }
  }

  function move(id: string, direction: -1 | 1) {
    const i = order.indexOf(id);
    const j = i + direction;
    if (j < 0 || j >= order.length) return;
    const next = [...order];
    [next[i], next[j]] = [next[j], next[i]];
    persist(next);
  }

  function dropOn(targetId: string) {
    const draggedId = dragId.current;
    dragId.current = null;
    setDragOverId(null);
    if (!draggedId || draggedId === targetId) return;
    const from = order.indexOf(draggedId);
    const to = order.indexOf(targetId);
    if (from < 0 || to < 0) return;
    const next = order.filter((id) => id !== draggedId);
    // Dropping onto a section BELOW means "put it after that one", which is
    // also the only way to reach the last position -- there is no drop
    // target past the final section to aim at. Dragging upwards keeps the
    // other reading, before the target.
    next.splice(next.indexOf(targetId) + (from < to ? 1 : 0), 0, draggedId);
    persist(next);
  }

  const byId = new Map(sections.map((s) => [s.id, s]));

  return (
    <>
      {order.map((id, i) => {
        const section = byId.get(id);
        if (!section) return null;
        return (
          <div
            key={id}
            className={`reorderable-section${dragOverId === id ? ' is-drag-over' : ''}`}
            onDragOver={(e) => {
              e.preventDefault();
              // Highlighting from dragover rather than dragenter: dragenter
              // fires per child boundary, so the pair raced each other and
              // the outline flickered off while the cursor sat over a table.
              // dragover repeats for as long as the cursor is here, and React
              // bails out of a set to the same id, so this does not re-render.
              if (dragId.current && dragId.current !== id) setDragOverId(id);
            }}
            onDragLeave={(e) => {
              // dragleave also fires on every child boundary and bubbles;
              // relatedTarget is where the cursor went, so a move deeper into
              // this section is not a leave.
              const to = e.relatedTarget as Node | null;
              if (to && e.currentTarget.contains(to)) return;
              setDragOverId((current) => (current === id ? null : current));
            }}
            onDrop={(e) => { e.preventDefault(); dropOn(id); }}
          >
            <div
              className="reorder-handle"
              role="button"
              tabIndex={0}
              aria-label={
                `Reorder ${section.label}. Position ${i + 1} of ${order.length}. `
                + 'Press the up or down arrow key to move it.'
              }
              title="Drag, or press ↑ / ↓, to reorder"
              draggable
              onDragStart={(e) => {
                dragId.current = id;
                // Firefox starts no drag at all unless dragstart puts
                // something on the DataTransfer; the ref alone left the
                // handle inert there, with no other way to reorder.
                e.dataTransfer.setData('text/plain', id);
                e.dataTransfer.effectAllowed = 'move';
              }}
              onDragEnd={() => { dragId.current = null; setDragOverId(null); }}
              onKeyDown={(e) => {
                if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
                // Or the page scrolls under the reorder, leaving the reader
                // looking at whatever the section used to sit above.
                e.preventDefault();
                move(id, e.key === 'ArrowUp' ? -1 : 1);
                // Focus rides along: the ids are React keys, so a reorder
                // moves these DOM nodes rather than rebuilding them, and the
                // handle keeps focus through as many presses as it takes.
              }}
            >
              ⠿⠿
            </div>
            <div className="reorderable-section-content">{section.node}</div>
          </div>
        );
      })}
    </>
  );
}

