'use client';

import { useRouter } from 'next/navigation';
import { useEffect, useId, useRef, useState } from 'react';

import type { SearchAnimationType } from '@/lib/site-settings';
import {
  MIN_QUERY_LENGTH,
  SEARCH_TYPE_LABELS,
  searchResultHref,
  type SearchResultType,
} from '@/search/constants';

type Suggestion = {
  type: SearchResultType;
  id: number;
  slug: string;
  title: string;
  subtitle: string | null;
};

/**
 * Global search with keyboard-accessible autocomplete and dynamic animated placeholders (see changeLog.md).
 *
 * Requests are debounced and require a minimum query length, so typing
 * does not issue a query per keystroke. In-flight requests are aborted
 * when superseded.
 */
export function SearchBox({
  autoFocus = false,
  placeholder,
  placeholders,
  intervalSeconds = 5,
  animation = 'typewriter',
  initialQuery = '',
  scope,
}: {
  autoFocus?: boolean;
  placeholder?: string;
  placeholders?: string[];
  intervalSeconds?: number;
  animation?: SearchAnimationType;
  initialQuery?: string;
  /** Restrict search to AFLW players and clubs, on `/aflw` and `/search?scope=aflw`. */
  scope?: 'aflw';
}) {
  const router = useRouter();
  const listId = useId();
  const [query, setQuery] = useState(initialQuery);
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const [isFocused, setIsFocused] = useState(false);
  const abortRef = useRef<AbortController | null>(null);
  const boxRef = useRef<HTMLDivElement>(null);

  // Dynamic placeholder animation
  const candidateList = (placeholders && placeholders.length > 0)
    ? placeholders
    : [placeholder || (scope === 'aflw' ? 'Search AFLW players and clubs…' : 'Search players, clubs, venues, seasons…')];

  const [placeholderIndex, setPlaceholderIndex] = useState(0);
  const [displayedPlaceholder, setDisplayedPlaceholder] = useState(candidateList[0] || '');

  useEffect(() => {
    if (candidateList.length <= 1) {
      setDisplayedPlaceholder(candidateList[0] || '');
      return;
    }

    if (isFocused || query.length > 0) {
      setDisplayedPlaceholder(candidateList[placeholderIndex % candidateList.length] || '');
      return;
    }

    const currentTarget = candidateList[placeholderIndex % candidateList.length] || '';

    if (animation === 'typewriter') {
      let charIdx = 0;
      let isDeleting = false;
      let timeoutId: NodeJS.Timeout;

      function step() {
        if (!isDeleting) {
          charIdx++;
          setDisplayedPlaceholder(currentTarget.slice(0, charIdx));
          if (charIdx >= currentTarget.length) {
            isDeleting = true;
            timeoutId = setTimeout(step, Math.max(1200, intervalSeconds * 1000));
          } else {
            timeoutId = setTimeout(step, 40);
          }
        } else {
          charIdx--;
          setDisplayedPlaceholder(currentTarget.slice(0, charIdx));
          if (charIdx <= 0) {
            isDeleting = false;
            setPlaceholderIndex((prev) => (prev + 1) % candidateList.length);
          } else {
            timeoutId = setTimeout(step, 25);
          }
        }
      }

      timeoutId = setTimeout(step, 100);
      return () => clearTimeout(timeoutId);
    } else {
      setDisplayedPlaceholder(currentTarget);
      const timer = setTimeout(() => {
        setPlaceholderIndex((prev) => (prev + 1) % candidateList.length);
      }, Math.max(1200, intervalSeconds * 1000));
      return () => clearTimeout(timer);
    }
  }, [candidateList, placeholderIndex, intervalSeconds, animation, isFocused, query]);

  useEffect(() => {
    const term = query.trim();
    if (term.length < MIN_QUERY_LENGTH) {
      setSuggestions([]);
      setOpen(false);
      return;
    }

    const timer = setTimeout(async () => {
      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;
      try {
        const scopeParam = scope ? `&scope=${scope}` : '';
        const res = await fetch(`/api/search/autocomplete?q=${encodeURIComponent(term)}${scopeParam}`, {
          signal: controller.signal,
        });
        if (!res.ok) return;
        const data = (await res.json()) as { results: Suggestion[] };
        setSuggestions(data.results);
        setOpen(data.results.length > 0);
        setActive(-1);
      } catch {
        // Aborted or offline: leave the previous suggestions in place.
      }
    }, 180);

    return () => clearTimeout(timer);
  }, [query, scope]);

  useEffect(() => {
    function onClickOutside(event: MouseEvent) {
      if (!boxRef.current?.contains(event.target as Node)) setOpen(false);
    }
    document.addEventListener('mousedown', onClickOutside);
    return () => document.removeEventListener('mousedown', onClickOutside);
  }, []);

  function go(suggestion: Suggestion) {
    setOpen(false);
    router.push(searchResultHref(suggestion));
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (!open || suggestions.length === 0) return;
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      setActive((i) => (i + 1) % suggestions.length);
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      setActive((i) => (i <= 0 ? suggestions.length - 1 : i - 1));
    } else if (event.key === 'Enter' && active >= 0) {
      event.preventDefault();
      go(suggestions[active]);
    } else if (event.key === 'Escape') {
      setOpen(false);
    }
  }

  return (
    <div ref={boxRef} style={{ position: 'relative' }}>
      <form className="search-form" action="/search" role="search">
        <label htmlFor={`${listId}-input`} className="visually-hidden">
          {scope === 'aflw' ? 'Search AFLW' : 'Search AFL history'}
        </label>
        {scope && <input type="hidden" name="scope" value={scope} />}
        <input
          id={`${listId}-input`}
          name="q"
          type="search"
          value={query}
          placeholder={displayedPlaceholder || placeholder || 'Search…'}
          autoComplete="off"
          // eslint-disable-next-line jsx-a11y/no-autofocus
          autoFocus={autoFocus}
          role="combobox"
          aria-expanded={open}
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={active >= 0 ? `${listId}-opt-${active}` : undefined}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={onKeyDown}
        />
        <button className="btn" type="submit">Search</button>
      </form>

      {open && (
        <ul
          id={listId}
          role="listbox"
          aria-label="Search suggestions"
          style={{
            position: 'absolute',
            zIndex: 30,
            left: 0,
            right: 0,
            margin: '4px 0 0',
            padding: 0,
            listStyle: 'none',
            background: 'var(--bg-raised)',
            border: '1px solid var(--border-strong)',
            borderRadius: 'var(--radius)',
            boxShadow: '0 6px 20px rgba(0,0,0,0.12)',
            textAlign: 'left',
            maxHeight: '20rem',
            overflowY: 'auto',
          }}
        >
          {suggestions.map((s, i) => (
            <li
              key={`${s.type}-${s.id}`}
              id={`${listId}-opt-${i}`}
              role="option"
              aria-selected={active === i}
              style={{
                padding: '0.6rem 0.9rem',
                cursor: 'pointer',
                background: active === i ? 'var(--bg-hover)' : 'transparent',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'baseline',
                borderBottom: '1px solid var(--border-subtle)',
              }}
              onMouseEnter={() => setActive(i)}
              onMouseDown={(e) => {
                e.preventDefault();
                go(s);
              }}
            >
              <span>
                <strong>{s.title}</strong>
                {s.subtitle && <span className="muted" style={{ marginLeft: '0.5rem', fontSize: '0.85rem' }}>{s.subtitle}</span>}
              </span>
              <span className="badge" style={{ fontSize: '0.75rem' }}>{SEARCH_TYPE_LABELS[s.type]}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

'use client';

import { useMemo, useState } from 'react';

import { compareValues, SortDirection, SortType } from '@/lib/sorting';
import { SortableHeader } from './SortableHeader';

export interface SortableColumn<TKey extends string> {
  key: TKey;
  label: React.ReactNode;
  sortable?: boolean;
  sortType?: SortType;
  className?: string;
  initialDirection?: SortDirection;
}

export interface SortableItem<TKey extends string> {
  id: string | number;
  values: Record<TKey, any>;
  element: React.ReactNode;
}

export interface SortableTableProps<TKey extends string> {
  columns: SortableColumn<TKey>[];
  items: SortableItem<TKey>[];
  defaultSort?: TKey;
  defaultDir?: SortDirection;
  caption?: React.ReactNode;
  className?: string;
}

export function SortableTable<TKey extends string>({
  columns,
  items,
  defaultSort,
  defaultDir = 'desc',
  caption,
  className,
}: SortableTableProps<TKey>) {
  const [sortKey, setSortKey] = useState<TKey | undefined>(defaultSort);
  const [sortDir, setSortDir] = useState<SortDirection>(defaultDir);

  const sortedItems = useMemo(() => {
    if (!sortKey) return items;

    const col = columns.find((c) => c.key === sortKey);
    if (!col) return items;

    const type = col.sortType ?? 'text';

    return [...items].sort((a, b) => {
      const valA = a.values[sortKey];
      const valB = b.values[sortKey];
      return compareValues(valA, valB, type, sortDir);
    });
  }, [items, sortKey, sortDir, columns]);

  const handleSort = (key: TKey) => {
    const col = columns.find((c) => c.key === key);
    if (col && col.sortable === false) return;

    if (sortKey === key) {
      setSortDir(sortDir === 'asc' ? 'desc' : 'asc');
    } else {
      setSortKey(key);
      const defaultForCol =
        col?.initialDirection ??
        (col?.sortType === 'number' || col?.sortType === 'date' ? 'desc' : 'asc');
      setSortDir(defaultForCol);
    }
  };

  return (
    <table className={className}>
      {caption && <caption>{caption}</caption>}
      <thead>
        <tr>
          {columns.map((col) => {
            const isSortable =
              col.sortable !== false && (col.sortType !== undefined || col.sortable === true);

            if (!isSortable) {
              return (
                <th key={col.key} scope="col" className={col.className}>
                  {col.label}
                </th>
              );
            }

            return (
              <SortableHeader
                key={col.key}
                label={col.label}
                active={sortKey === col.key}
                direction={sortDir}
                onClick={() => handleSort(col.key)}
                className={col.className}
              />
            );
          })}
        </tr>
      </thead>
      <tbody>
        {sortedItems.map((item) => item.element)}
      </tbody>
    </table>
  );
}

/**
 * PostgreSQL client for the operational auth/submission tables.
 *
 * A second pool with a second role, on purpose. The public site runs as
 * afldb_app, which is read-only — an invariant established by the migration
 * GRANTs (afldb_app is granted SELECT only) and enforced against the live
 * cluster by tests/integration/privileges.test.ts, which interrogates the
 * catalogue so it also catches privileges the role holds but has never
 * exercised. Logins and uploads genuinely write, so they run as afldb_auth,
 * whose grants cover ONLY the tables from migration 023 — the same test file
 * asserts that role holds no write on the statistical tables. A SQL injection
 * in a public page still cannot write; a compromise of the auth path still
 * cannot touch statistics.
 *
 * Required statistical-mutation audits (data_edits, linked
 * player_link_resolutions) do NOT ride this pool: since migration 066
 * (AFLDB-ISSUE-027) they are written by afldb_import inside the same
 * transaction as the mutation, via src/db/queries/audit-log.ts. This
 * pool keeps the operational writes: sessions, submissions,
 * suggestions, confirmed-unlinked resolutions, and the best-effort
 * auth_audit_log activity trail.
 */
import 'server-only';

import postgres from 'postgres';

import { assertTestProcessDsn } from './test-process-guard';

declare global {
  // eslint-disable-next-line no-var
  var __afldbAuthSql: ReturnType<typeof postgres> | undefined;
}

function createClient() {
  const connectionString = process.env.AFLDB_AUTH_DATABASE_URL;
  if (!connectionString) {
    throw new Error(
      'AFLDB_AUTH_DATABASE_URL is not set. '
      + 'Run tools/maintenance/02_add_auth_role.sh on the server.',
    );
  }
  // AFLDB V2 plan D5: a no-op outside a test process; inside one, only a _test database.
  assertTestProcessDsn('AFLDB_AUTH_DATABASE_URL', connectionString);

  return postgres(connectionString, {
    // Auth traffic is a trickle next to page traffic.
    max: 3,
    idle_timeout: 30,
    connect_timeout: 10,
    connection: { statement_timeout: 5000 },
    onnotice: () => {},
    transform: { undefined: null },
  });
}

function getClient(): ReturnType<typeof postgres> {
  if (!globalThis.__afldbAuthSql) {
    globalThis.__afldbAuthSql = createClient();
  }
  return globalThis.__afldbAuthSql;
}

/**
 * Lazy: the pool (and the env check) exist only once a query runs.
 * `next build` imports every route while collecting page data, and a
 * build must not require auth credentials — only serving does.
 */
export const authSql: ReturnType<typeof postgres> = new Proxy(
  // The target must be callable for the tagged-template form.
  ((..._args: never[]) => undefined) as unknown as ReturnType<typeof postgres>,
  {
    apply(_target, _thisArg, args: unknown[]) {
      return Reflect.apply(getClient() as unknown as (...a: unknown[]) => unknown, undefined, args);
    },
    get(_target, property) {
      return Reflect.get(getClient(), property);
    },
  },
);

/**
 * PostgreSQL client.
 *
 * `server-only` makes importing this from a Client Component a build
 * error, so database credentials can never reach a browser bundle.
 */
import 'server-only';

import postgres from 'postgres';

import { assertTestProcessDsn } from './test-process-guard';

declare global {
  // eslint-disable-next-line no-var
  var __afldbSql: ReturnType<typeof postgres> | undefined;
}

function createClient() {
  const connectionString = process.env.DATABASE_URL;
  if (!connectionString) {
    throw new Error('DATABASE_URL is not set');
  }
  // AFLDB V2 plan D5: a no-op outside a test process; inside one, only a _test database.
  assertTestProcessDsn('DATABASE_URL', connectionString);

  const statementTimeout = Number(process.env.AFLDB_STATEMENT_TIMEOUT_MS ?? 5000);

  // Next.js prerenders with several worker processes, each of which
  // builds its own pool. At the serving default that multiplies out past
  // PostgreSQL's max_connections and the build fails with "too many
  // clients". Prerendering is throughput-bound, not latency-bound, so a
  // small pool per worker is sufficient.
  const isBuild = process.env.NEXT_PHASE === 'phase-production-build';
  const poolMax = isBuild ? 2 : Number(process.env.AFLDB_POOL_MAX ?? 10);

  return postgres(connectionString, {
    max: poolMax,
    idle_timeout: 30,
    connect_timeout: 10,
    // A public Advanced Search could otherwise pin a backend indefinitely.
    connection: { statement_timeout: statementTimeout },
    // Never let query text or parameters reach the logs.
    onnotice: () => {},
    transform: { undefined: null },
  });
}

// Next.js dev-mode hot reload re-evaluates modules; without this the
// connection pool would be recreated on every edit until PostgreSQL
// refused new connections.
export const sql = globalThis.__afldbSql ?? createClient();

if (process.env.NODE_ENV !== 'production') {
  globalThis.__afldbSql = sql;
}

import 'server-only';

import { sql } from '@/db/client';
import { FIELDS, SORTS, type AdvancedQuery } from '@/search/advanced-spec';

export type AdvancedResultRow = {
  id: number;
  slug: string;
  displayName: string;
  debutSeason: number | null;
  finalSeason: number | null;
  games: number;
  goals: number;
  finals: number;
  premierships: number;
  brownlowVotes: number;
  clubsPlayed: number;
  clubNames: string | null;
};

/**
 * Execute a validated Advanced Search specification.
 *
 * Every SQL identifier here comes from the FIELDS/SORTS allowlists in
 * advanced-spec.ts; user input only ever reaches the database as a bound
 * parameter. `sql.unsafe` is used solely for the fixed column and
 * ORDER BY fragments looked up in those tables.
 */
export async function runAdvancedSearch(
  query: AdvancedQuery,
): Promise<{ rows: AdvancedResultRow[]; total: number }> {
  const conditions: ReturnType<typeof sql>[] = [];

  for (const filter of query.filters) {
    const def = FIELDS[filter.field];
    // Defensive: parseAdvancedQuery already rejects unknown fields.
    if (!def) continue;
    const column = sql.unsafe(def.column);

    if (filter.min !== undefined) {
      conditions.push(sql`${column} >= ${filter.min}`);
    }
    if (filter.max !== undefined) {
      conditions.push(sql`${column} <= ${filter.max}`);
    }
  }

  if (query.clubSlugs.length > 0) {
    conditions.push(sql`
      EXISTS (
        SELECT 1 FROM player_clubs pc
          JOIN clubs cl ON cl.id = pc.club_id
         WHERE pc.player_id = p.id AND cl.slug = ANY(${query.clubSlugs})
      )
    `);
  }

  const where = conditions.length
    ? conditions.reduce((acc, cond) => sql`${acc} AND ${cond}`)
    : sql`TRUE`;

  const orderBy = sql.unsafe(SORTS[query.sort]?.sql ?? SORTS.games.sql);
  const offset = (query.page - 1) * query.pageSize;

  const rows = await sql<(AdvancedResultRow & { total: string })[]>`
    SELECT p.id, p.slug, p.display_name AS "displayName",
           c.debut_season AS "debutSeason", c.final_season AS "finalSeason",
           c.games, c.goals, c.finals, c.premierships,
           c.brownlow_votes AS "brownlowVotes",
           c.clubs_played   AS "clubsPlayed",
           (SELECT string_agg(DISTINCT cl.short_name, ', ' ORDER BY cl.short_name)
              FROM player_clubs pc JOIN clubs cl ON cl.id = pc.club_id
             WHERE pc.player_id = p.id) AS "clubNames",
           count(*) OVER () AS total
      FROM players p
      JOIN player_career_stats c ON c.player_id = p.id
     WHERE ${where}
     ORDER BY ${orderBy}
     LIMIT ${query.pageSize} OFFSET ${offset}
  `;

  return {
    rows: rows.map(({ total: _total, ...rest }) => rest),
    total: rows.length > 0 ? Number(rows[0].total) : 0,
  };
}

/** Clubs for the filter control. */
export async function getClubOptions() {
  return sql<{ slug: string; name: string; isCurrent: boolean }[]>`
    SELECT slug, name, is_current_afl_club AS "isCurrent"
      FROM clubs
     ORDER BY is_current_afl_club DESC, name
  `;
}

/**
 * Club organizations (lineage-level, not the 24 historical identities)
 * for the grid solver's club-scoped builders -- "played for" means the
 * continuing club, so a Footscray-era row must match a Western Bulldogs
 * pick the same way club pages already treat the lineage as one entity.
 */
export async function getClubOrganizationOptions() {
  return sql<{ id: number; name: string; isActive: boolean }[]>`
    SELECT id, name, is_active AS "isActive"
      FROM club_organizations
     ORDER BY is_active DESC, name
  `;
}

/** Venues for a picker, e.g. the grid solver's Grounds & venues category. */
export async function getVenueOptions() {
  return sql<{ id: number; name: string }[]>`
    SELECT id, canonical_name AS name
      FROM venues
     ORDER BY canonical_name
  `;
}

