/**
 * AFLDB-ISSUE-235 §7.2 — the `afl_api` human identity adjudication query module.
 *
 * Reads run on the public/auth clients; writes run on a short-lived
 * `AFLDB_IMPORT_DATABASE_URL` connection, exactly the `resolveLink()` pattern
 * `player-links.ts` already establishes — one required audit row in the same
 * transaction as the statistical write (migration 066, AFLDB-ISSUE-027).
 */

type Sql = postgres.Sql;
type Tx = postgres.TransactionSql;

const AFL_API_SOURCE_KEY = 'afl_api';

// ISSUE-235 §6 / ISSUE-228 §6.2: provider CD_T identity is resolved
// only through the tracked identity map, then clubs.legacy_club_hist.
const AFL_API_IDENTITIES = parseAflApiIdentities(aflApiIdentitiesJson);

async function fetchAflApiSourceId(db: Sql | Tx): Promise<number> {
  const [row] = await db<{ id: number }[]>`SELECT id FROM sources WHERE key = ${AFL_API_SOURCE_KEY}`;
  if (!row) throw new Error("sources.key = 'afl_api' not found; migration 077 must be applied.");
  return row.id;
}

async function readExistingIdentity(
  db: Sql | Tx, sourceId: number, providerId: string,
): Promise<AflApiIdentityRow | null> {
  const [row] = await db<AflApiIdentityRow[]>`
    SELECT id, status::text AS status, player_id AS "playerId", match_method AS "matchMethod"
      FROM external_identities
     WHERE source_id = ${sourceId} AND external_id = ${providerId}
  `;
  return row ?? null;
}

const CONTINUITY_CONTRACT_SEGMENTS = ['tools', 'rebuild', 'fitzroy', 'fitzroy-contract.json'] as const;

/** The player's accepted identity rows, the two namespaces §5's forward lookup reads. */
async function readPlayerIdentityRows(
  db: Sql | Tx, playerId: number,
): Promise<{ playerId: number; externalId: string; sourceKey: string }[]> {
  return db<{ playerId: number; externalId: string; sourceKey: string }[]>`
    SELECT ei.player_id AS "playerId", ei.external_id AS "externalId", s.key AS "sourceKey"
      FROM external_identities ei
      JOIN sources s ON s.id = ei.source_id
     WHERE ((s.key = 'afltables' AND ei.match_method = 'afltables_profile_url')
            OR (s.key = 'manual_admin_edit' AND ei.match_method = 'manual_admin_edit'))
       AND ei.status IN ('unique', 'resolved')
       AND ei.player_id = ${playerId}
  `;
}

/**
 * D6-3 / AFLDB-ISSUE-310: the player's own stable identity by the SAME rule as every forward
 * lookup -- `classifyAflApiForwardIdentity`, never the collation-dependent first row. `null`
 * covers both `no_identity` and `ambiguous` (two paths no tracked continuity rule names, or
 * two manual tokens): T7 refuses a link to such a player, as the rebuild would refuse it.
 * An unreadable continuity contract is only consulted for exactly two paths and fails closed
 * to `ambiguous` (an empty rule set names no pair).
 */
async function readPlayerStableIdentity(db: Sql | Tx, playerId: number): Promise<string | null> {
  const rows = await readPlayerIdentityRows(db, playerId);
  const twoPaths = new Set(rows.filter((r) => r.sourceKey === 'afltables').map((r) => r.externalId)).size === 2;
  const loaded = twoPaths
    ? loadContinuityRulesFailClosed(join(process.cwd(), ...CONTINUITY_CONTRACT_SEGMENTS))
    : null;
  const continuityRules = loaded?.ok
    ? loaded.rules
    : ([] as unknown as ValidatedFitzroyProfileContinuityRules);
  const result = classifyAflApiForwardIdentityRows({ playerIds: [playerId], rows, continuityRules }).get(playerId);
  return result?.ok ? result.identity : null;
}

/**
 * The identity string for a REVOKE's ledger row. Undoing a link must stay possible even when
 * the player has since gained a second path, and `player_identity` is NOT NULL, so this keeps
 * the forward identity when there is one and otherwise the deterministic first accepted row.
 * Only the link path (and the page that previews it) is gated on the strict rule.
 */
async function readPlayerRecordedIdentity(db: Sql | Tx, playerId: number): Promise<string | null> {
  const forward = await readPlayerStableIdentity(db, playerId);
  if (forward !== null) return forward;
  const rows = await readPlayerIdentityRows(db, playerId);
  rows.sort((a, b) => Number(a.sourceKey !== 'afltables') - Number(b.sourceKey !== 'afltables')
    || (a.externalId < b.externalId ? -1 : a.externalId > b.externalId ? 1 : 0));
  return rows[0]?.externalId ?? null;
}

/** D6-2: does this player already hold a DIFFERENT afl_api provider row? */
async function readPlayerOtherAflApiRow(
  db: Sql | Tx, sourceId: number, playerId: number, excludingProviderId?: string,
): Promise<{ externalId: string; status: string; matchMethod: string | null } | null> {
  const [row] = await db<{ externalId: string; status: string; matchMethod: string | null }[]>`
    SELECT external_id AS "externalId", status::text AS status, match_method AS "matchMethod"
      FROM external_identities
     WHERE source_id = ${sourceId} AND player_id = ${playerId}
       AND external_id <> ${excludingProviderId ?? ''}
  `;
  return row ?? null;
}

async function readPendingCandidates(
  db: Sql | Tx, sourceId: number, providerId: string,
): Promise<readonly { id: number; sourceVersionSeq: number; season: number }[]> {
  const rows = await db<{ id: number; sourceVersionSeq: number; season: number }[]>`
    SELECT id, source_version_seq AS "sourceVersionSeq", season
      FROM promotion_candidates
     WHERE source_id = ${sourceId} AND verb = 'unresolved_identity' AND status = 'pending'
       AND split_part(external_record_id, '|', 3) = ${providerId}
     ORDER BY id
  `;
  return rows;
}

async function readLatestAdjudicationId(db: Sql | Tx, providerId: string): Promise<number | null> {
  const [row] = await db<{ id: number }[]>`
    SELECT id FROM afl_api_identity_adjudications
     WHERE source_key = ${AFL_API_SOURCE_KEY} AND external_id = ${providerId}
     ORDER BY id DESC LIMIT 1
  `;
  return row?.id ?? null;
}

/**
 * AFLDB-ISSUE-238 §8.6: the provider's NET ledger action (its latest row), or null with no row.
 * The revoke needs it because the identity row alone classifies a corrected provider as `L-H`.
 * Kept separate from `readLatestAdjudicationId`, which feeds the fingerprint unchanged.
 */
async function readLatestAdjudicationAction(db: Sql | Tx, providerId: string): Promise<AflApiLedgerNetAction | null> {
  const [row] = await db<{ action: string }[]>`
    SELECT action FROM afl_api_identity_adjudications
     WHERE source_key = ${AFL_API_SOURCE_KEY} AND external_id = ${providerId}
     ORDER BY id DESC LIMIT 1
  `;
  if (!row) return null;
  if (!(AFL_API_LEDGER_ACTIONS as readonly string[]).includes(row.action)) {
    throw new Error(`afl_api_identity_adjudications holds an unknown action ${JSON.stringify(row.action)} for ${providerId}.`);
  }
  return row.action as AflApiLedgerNetAction;
}

