export const AFLW_VENUE_FILTER_COLUMNS: Record<string, string> = {
  matches: 'v.matches',
};

export async function listAflwVenues(filters: {
  q?: string;
  ranges?: FilterValues;
} = {}): Promise<AflwVenueRow[]> {
  const conditions = filters.ranges
    ? rangeConditions(filters.ranges, AFLW_VENUE_FILTER_COLUMNS)
    : [];
  if (filters.q) conditions.push(sql`v.name ILIKE ${containsPattern(filters.q)}`);
  const where = allOf(conditions);

  return sql<AflwVenueRow[]>`
    SELECT v.slug, v.name, v.matches,
           fs.display_label AS "firstSeasonLabel",
           ls.display_label AS "lastSeasonLabel"
      FROM aflw.venues v
      LEFT JOIN aflw.seasons fs ON fs.ordinal = v.first_season_ordinal
      LEFT JOIN aflw.seasons ls ON ls.ordinal = v.last_season_ordinal
     WHERE ${where}
     ORDER BY v.matches DESC, v.name
  `;
}

export type AflwOverview = {
  seasons: number;
  clubs: number;
  players: number;
  matches: number;
  playerMatchRows: number;
  scoringEvents: number;
  firstDate: Date | null;
  lastDate: Date | null;
};

export async function getAflwOverview(): Promise<AflwOverview> {
  const [row] = await sql<AflwOverview[]>`
    SELECT (SELECT count(*) FROM aflw.seasons)::int AS seasons,
           (SELECT count(*) FROM aflw.clubs)::int AS clubs,
           (SELECT count(*) FROM aflw.players)::int AS players,
           (SELECT count(*) FROM aflw.matches)::int AS matches,
           (SELECT count(*) FROM aflw.player_match_stats)::int AS "playerMatchRows",
           (SELECT count(*) FROM aflw.scoring_events)::int AS "scoringEvents",
           (SELECT min(match_date) FROM aflw.matches) AS "firstDate",
           (SELECT max(match_date) FROM aflw.matches) AS "lastDate"
  `;
  return row;
}

// --- Global search ---

export type AflwSearchRow = {
  slug: string;
  title: string;
  subtitle: string | null;
  rank: number;
};

/**
 * AFLW players for the site-wide search.
 *
 * The AFL side normalises names in the database through
 * `afldb_normalise_name` and a stored `search_name`. There is no such
 * column here — these are views — so matching is a case-insensitive
 * contains against the display name, which is enough for 960 players and
 * costs one scan of a small view.
 */
export async function searchAflwPlayers(query: string, limit = 6): Promise<AflwSearchRow[]> {
  return sql<AflwSearchRow[]>`
    SELECT p.slug,
           p.display_name AS title,
           COALESCE(c.club_names, '') || ' · ' || c.games || ' games' AS subtitle,
           (CASE WHEN lower(p.display_name) = lower(${query}) THEN 1000
                 WHEN lower(p.display_name) LIKE lower(${prefixPattern(query)}) THEN 500
                 ELSE 250 END + LEAST(c.games, 100) / 10.0)::float AS rank
      FROM aflw.players p
      JOIN aflw.player_careers c ON c.player_slug = p.slug
     WHERE p.display_name ILIKE ${containsPattern(query)}
     ORDER BY rank DESC, c.games DESC, p.sort_name
     LIMIT ${limit}
  `;
}

export async function searchAflwClubs(query: string, limit = 3): Promise<AflwSearchRow[]> {
  return sql<AflwSearchRow[]>`
    SELECT c.code AS slug,
           c.name AS title,
           'AFLW club · ' || t.matches || ' matches' AS subtitle,
           (CASE WHEN lower(c.name) = lower(${query}) THEN 1000
                 WHEN lower(c.name) LIKE lower(${prefixPattern(query)}) THEN 500
                 ELSE 250 END)::float AS rank
      FROM aflw.clubs c
      JOIN aflw.club_totals t ON t.code = c.code
     WHERE c.name ILIKE ${containsPattern(query)}
     ORDER BY rank DESC, c.name
     LIMIT ${limit}
  `;
}

import 'server-only';

import { sql } from '@/db/client';
import { allOf, containsPattern, rangeConditions } from '@/db/queries/filters';
import type { FilterValues } from '@/search/table-filters';

/**
 * Brownlow Medal queries.
 *
 * Totals come from `brownlow_season_votes`, the authoritative season
 * count, never from summing per-game votes — those exist only for
 * 1931-1934 and 1984 onward, so a sum would understate most careers.
 */

export type BrownlowWinnerRow = {
  season: number;
  playerId: number;
  slug: string;
  displayName: string;
  votes: number;
  clubName: string | null;
  clubSlug: string | null;
};

export const BROWNLOW_WINNER_FILTER_COLUMNS: Record<string, string> = {
  season: 'b.season',
  votes: 'b.votes',
};

/**
 * Winners, with the club each represented that season.
 *
 * The club is read from `player_season_stats`, not from
 * `brownlow_season_votes.club_id`: that column exists but is unpopulated
 * for all 112 winners, so joining it would render every club as an em
 * dash and make a club filter match nothing. The player-season grain is
 * also the right one — a Brownlow is won across a season, and for a
 * player who transferred mid-year `primary_club_id` names the club of
 * most games rather than picking one arbitrarily.
 */
export async function getBrownlowWinners(filters: {
  q?: string;
  club?: string;
  ranges?: FilterValues;
} = {}): Promise<BrownlowWinnerRow[]> {
  const conditions = filters.ranges
    ? rangeConditions(filters.ranges, BROWNLOW_WINNER_FILTER_COLUMNS)
    : [];
  if (filters.q) conditions.push(sql`p.display_name ILIKE ${containsPattern(filters.q)}`);
  if (filters.club) conditions.push(sql`cl.slug = ${filters.club}`);
  const where = allOf(conditions);

  return sql<BrownlowWinnerRow[]>`
    SELECT b.season, p.id AS "playerId", p.slug,
           p.display_name AS "displayName", b.votes,
           cl.name AS "clubName", cl.slug AS "clubSlug"
      FROM brownlow_season_votes b
      JOIN players p ON p.id = b.player_id
      LEFT JOIN player_season_stats ps
        ON ps.player_id = b.player_id AND ps.season = b.season
      LEFT JOIN clubs cl ON cl.id = COALESCE(b.club_id, ps.primary_club_id)
     WHERE b.is_winner AND ${where}
     ORDER BY b.season DESC, p.sort_name
  `;
}

export type BrownlowLeaderRow = {
  rank: number;
  playerId: number;
  slug: string;
  displayName: string;
  votes: number;
  medals: number;
  games: number;
};

export const BROWNLOW_LEADER_FILTER_COLUMNS: Record<string, string> = {
  lvotes: 'r.votes',
  lmedals: 'r.medals',
  lgames: 'r.games',
};

/**
 * Career vote leaders.
 *
 * The filter keys are prefixed `l` because this table and the winners
 * table share one URL: unprefixed `votes` belongs to the winners panel,
 * and two panels writing the same parameter would move each other's
 * controls.
 *
 * Rank is computed over every player with a vote and the filters applied
 * outside that subquery, for the reason the record boards state: a
 * narrowed leaderboard must show real positions rather than renumbering
 * whoever survives the filter into an all-time lead they do not hold.
 */
export async function getBrownlowCareerLeaders(filters: {
  q?: string;
  ranges?: FilterValues;
  limit: number;
} = { limit: 25 }): Promise<{ rows: BrownlowLeaderRow[]; total: number }> {
  const conditions = filters.ranges
    ? rangeConditions(filters.ranges, BROWNLOW_LEADER_FILTER_COLUMNS)
    : [];
  if (filters.q) conditions.push(sql`r."displayName" ILIKE ${containsPattern(filters.q)}`);
  const where = allOf(conditions);

  const rows = await sql<(BrownlowLeaderRow & { total: string })[]>`
    WITH ranked AS (
      SELECT rank() OVER (ORDER BY c.brownlow_votes DESC)::int AS rank,
             p.id AS "playerId", p.slug, p.display_name AS "displayName",
             p.sort_name AS "sortName",
             c.brownlow_votes AS votes, c.brownlow_medals AS medals, c.games
        FROM player_career_stats c
        JOIN players p ON p.id = c.player_id
       WHERE c.brownlow_votes > 0
    )
    SELECT r.rank, r."playerId", r.slug, r."displayName",
           r.votes, r.medals, r.games,
           count(*) OVER () AS total
      FROM ranked r
     WHERE ${where}
     ORDER BY r.votes DESC, r."sortName"
     LIMIT ${filters.limit}
  `;

  return {
    rows: rows.map(({ total: _total, ...rest }) => rest),
    total: rows.length > 0 ? Number(rows[0].total) : 0,
  };
}

export type MultipleBrownlowWinnerRow = {
  playerId: number;
  slug: string;
  displayName: string;
  medals: number;
  seasons: number[];
};

/**
 * Players who have won more than one Brownlow Medal.
 */
export async function getMultipleBrownlowWinners(): Promise<MultipleBrownlowWinnerRow[]> {
  return sql<MultipleBrownlowWinnerRow[]>`
    SELECT p.id AS "playerId", p.slug, p.display_name AS "displayName",
           COUNT(b.season)::int AS medals,
           array_agg(b.season ORDER BY b.season) AS seasons
      FROM brownlow_season_votes b
      JOIN players p ON p.id = b.player_id
     WHERE b.is_winner
     GROUP BY p.id, p.slug, p.display_name, p.sort_name
    HAVING COUNT(b.season) > 1
     ORDER BY medals DESC, p.sort_name
  `;
}

import 'server-only';

import { sql } from '@/db/client';

/**
 * Queries backing /clubs/compare (AFLDB-ISSUE-144).
 *
 * Stage 1 covers the head-to-head core: pair scoping, summary, meetings,
 * venues, records and streaks. Stage 2 adds the connected-player
 * (crossover) layer. Stage 3 adds H2H player leaders, the runtime
 * metric-coverage abstraction, authoritative club Brownlow history and
 * its selected-season primitive, and H2H match-vote totals with their
 * coverage. Stage 4 adds the season-generic selected-season layer:
 * canonical season discovery, identity-at-season resolution, the
 * home-and-away record, team metrics with runtime coverage, and season
 * player leaders. Stage 6 adds the extended rivalry analytics layer:
 * head-to-head by decade, period-score rivalry records with pair-level
 * coverage, and coverage-aware H2H player average leaderboards. The
 * route and its presentation are later stages.
 *
 * Identity model, per the approved runbook:
 *
 *   - `matches.home_club_id` / `away_club_id` are historical
 *     identity-at-match grain (`clubs.id`).
 *   - The comparison grain is `club_organizations.id`.
 *   - Every meeting is therefore scoped by joining BOTH match identities
 *     through `clubs.organization_id`. Renames and relocations inside one
 *     organisation (Footscray/Western Bulldogs, South Melbourne/Sydney,
 *     Kangaroos/North Melbourne) combine for free.
 *   - `club_organization_relations` is NEVER traversed to enlarge the
 *     match population: Brisbane Bears, Fitzroy and Brisbane Lions stay
 *     statistically separate even though two of them merged into the
 *     third. Relations are navigation context only.
 *
 * Rendered rows keep the historical identity that actually played, so a
 * 1990 meeting reads "Footscray", not "Western Bulldogs".
 */

// --- Shared pair scoping ---

export type MatchType = 'all' | 'home-and-away' | 'finals';

/** Result of a meeting from organisation A's point of view. */
export type H2HOutcome = 'a-win' | 'b-win' | 'draw';

export const MEETINGS_PAGE_SIZE = 25;

/**
 * A meeting as rendered: identity-at-match names and scores in home/away
 * order, plus the A/B perspective the summary and records aggregate on.
 */
export type H2HMeeting = {
  matchId: number;
  season: number;
  matchDate: Date | null;
  roundCode: string | null;
  roundNumber: number | null;
  roundType: string;
  isFinalsSeries: boolean;
  isGrandFinal: boolean;
  venueId: number | null;
  venueName: string | null;
  homeClubId: number;
  homeClubName: string;
  homeClubSlug: string;
  homeScore: number | null;
  awayClubId: number;
  awayClubName: string;
  awayClubSlug: string;
  awayScore: number | null;
  aScore: number | null;
  bScore: number | null;
  margin: number | null;
  attendance: number | null;
  outcome: H2HOutcome;
};

/**
 * The only place a comparison is rejected. Related-but-distinct
 * organisations (Brisbane Bears vs Brisbane Lions) are a legitimate
 * comparison; an organisation against itself is not, and would report
 * every one of its matches as both a win and a loss.
 */
function assertDistinct(orgA: number, orgB: number): void {
  if (orgA === orgB) {
    throw new Error(`club-comparison: organisation ${orgA} cannot be compared with itself`);
  }
}

/**
 * `finals` is `matches.is_finals_series` and nothing else -- never a
 * round-code string or a display label. Wildcard Finals carry
 * `round_type = 'wildcard_final'` with `is_finals_series = false`, so
 * they stay visible under `all`, count as home-and-away, and are never
 * counted as finals-series meetings. `IS TRUE` / `IS NOT TRUE` keeps the
 * two filters exact complements even if the column is ever null.
 */
function matchTypeFilter(matchType: MatchType) {
  if (matchType === 'finals') return sql`AND m.is_finals_series IS TRUE`;
  if (matchType === 'home-and-away') return sql`AND m.is_finals_series IS NOT TRUE`;
  return sql``;
}

/**
 * THE shared organisation-pair scoping fragment. Every Stage 1 query
 * builds its `meetings` CTE from this and nothing else, so all of them
 * see an identical match population and identical outcome semantics.
 *
 * `era` is a decade's first season (1990 for the 1990s), applied as
 * `[era, era + 10)`. It narrows the SAME population `getHeadToHeadByDecade`
 * already groups by decade -- it is never a second population definition,
 * and callers pass it only where the Club Rivalry Explorer follow-up
 * (FR-2) allows a chosen era to narrow the result: single-match records
 * and the meetings list. The summary, streaks, venues, decade breakdown,
 * player leaders/averages and Brownlow sections stay all-time regardless
 * of any era in the URL.
 */
function h2hScope(orgA: number, orgB: number, matchType: MatchType = 'all', era?: number) {
  return sql`
    SELECT m.id,
           m.season,
           m.match_date,
           m.round_code,
           m.round_number,
           m.round_type::text AS round_type,
           COALESCE(m.is_finals_series, false) AS is_finals_series,
           (m.round_type = 'grand_final') AS is_grand_final,
           m.venue_id,
           m.venue_raw,
           COALESCE(v.canonical_name, m.venue_raw) AS venue_name,
           m.home_club_id, hc.name AS home_club_name, hc.slug AS home_club_slug,
           m.away_club_id, ac.name AS away_club_name, ac.slug AS away_club_slug,
           m.home_score, m.away_score, m.margin, m.attendance,
           CASE WHEN hc.organization_id = ${orgA} THEN m.home_score ELSE m.away_score END AS a_score,
           CASE WHEN hc.organization_id = ${orgA} THEN m.away_score ELSE m.home_score END AS b_score,
           CASE WHEN wc.organization_id = ${orgA} THEN 'a-win'
                WHEN wc.organization_id = ${orgB} THEN 'b-win'
                ELSE 'draw' END AS outcome
      FROM matches m
      JOIN clubs hc ON hc.id = m.home_club_id
      JOIN clubs ac ON ac.id = m.away_club_id
      LEFT JOIN clubs wc ON wc.id = m.winner_club_id
      LEFT JOIN venues v ON v.id = m.venue_id
     WHERE ((hc.organization_id = ${orgA} AND ac.organization_id = ${orgB})
         OR (hc.organization_id = ${orgB} AND ac.organization_id = ${orgA}))
       ${matchTypeFilter(matchType)}
       ${era !== undefined ? sql`AND m.season >= ${era} AND m.season < ${era + 10}` : sql``}
  `;
}

/** The meeting columns, aliased for the wire. Shared by every row-returning query. */
const MEETING_COLUMNS = sql`
  m.id AS "matchId", m.season, m.match_date AS "matchDate",
  m.round_code AS "roundCode", m.round_number AS "roundNumber", m.round_type AS "roundType",
  m.is_finals_series AS "isFinalsSeries", m.is_grand_final AS "isGrandFinal",
  m.venue_id AS "venueId", m.venue_name AS "venueName",
  m.home_club_id AS "homeClubId", m.home_club_name AS "homeClubName", m.home_club_slug AS "homeClubSlug",
  m.home_score AS "homeScore",
  m.away_club_id AS "awayClubId", m.away_club_name AS "awayClubName", m.away_club_slug AS "awayClubSlug",
  m.away_score AS "awayScore",
  m.a_score AS "aScore", m.b_score AS "bScore",
  m.margin, m.attendance, m.outcome
`;

// --- Organisation resolution ---

export type ComparisonOrganization = {
  id: number;
  name: string;
  slug: string;
  firstSeason: number | null;
  lastSeason: number | null;
  isActive: boolean;
};

/**
 * Organisation grain only: `footscray` is a historical identity, not an
 * organisation slug, and deliberately does not resolve here.
 */
export async function getOrganizationBySlug(slug: string): Promise<ComparisonOrganization | null> {
  const [row] = await sql<ComparisonOrganization[]>`
    SELECT id, name, slug,
           first_season AS "firstSeason", last_season AS "lastSeason",
           is_active AS "isActive"
      FROM club_organizations
     WHERE slug = ${slug}
  `;
  return row ?? null;
}

/**
 * Every canonical organisation, ordered for a selector: current
 * organisations first, then historical/defunct ones, alphabetically
 * within each group.
 *
 * Organisation grain only, which is the whole point: `footscray` and
 * `south-melbourne` are historical identities inside a continuing
 * organisation and are deliberately absent, so a selector built from
 * this list cannot offer a club against itself under an older name.
 * Nothing here is filtered by a year or by a hand-kept club list.
 */
export async function getComparisonOrganizations(): Promise<ComparisonOrganization[]> {
  return sql<ComparisonOrganization[]>`
    SELECT id, name, slug,
           first_season AS "firstSeason", last_season AS "lastSeason",
           is_active AS "isActive"
      FROM club_organizations
     ORDER BY is_active DESC, name
  `;
}

// --- Summary ---

export type H2HMeetingRef = {
  matchId: number;
  season: number;
  matchDate: Date | null;
};

export type H2HSummary = {
  meetings: number;
  aWins: number;
  bWins: number;
  draws: number;
  /** 100 x (wins + 0.5 x draws) / meetings. Null when there are no meetings. */
  aWinPercentage: number | null;
  bWinPercentage: number | null;
  firstMeeting: H2HMeetingRef | null;
  latestMeeting: H2HMeetingRef | null;
  finalsSeriesMeetings: number;
  grandFinalMeetings: number;
};

function winPercentage(wins: number, draws: number, meetings: number): number | null {
  if (meetings <= 0) return null;
  return (100 * (wins + 0.5 * draws)) / meetings;
}

/**
 * Aggregates over the whole pair history -- the summary is never filtered
 * by match type, because "41 meetings, two of them finals" is one
 * statement about the rivalry, not a view of it.
 */
export async function getHeadToHeadSummary(orgA: number, orgB: number): Promise<H2HSummary> {
  assertDistinct(orgA, orgB);
  const [row] = await sql<{
    meetings: number; aWins: number; bWins: number; draws: number;
    finalsSeriesMeetings: number; grandFinalMeetings: number;
    firstMatchId: number | null; firstSeason: number | null; firstMatchDate: Date | null;
    latestMatchId: number | null; latestSeason: number | null; latestMatchDate: Date | null;
  }[]>`
    WITH meetings AS (${h2hScope(orgA, orgB)})
    SELECT count(*)::int AS meetings,
           count(*) FILTER (WHERE outcome = 'a-win')::int AS "aWins",
           count(*) FILTER (WHERE outcome = 'b-win')::int AS "bWins",
           count(*) FILTER (WHERE outcome = 'draw')::int AS draws,
           count(*) FILTER (WHERE is_finals_series)::int AS "finalsSeriesMeetings",
           count(*) FILTER (WHERE is_grand_final)::int AS "grandFinalMeetings",
           (SELECT id FROM meetings ORDER BY match_date, season, id LIMIT 1) AS "firstMatchId",
           (SELECT season FROM meetings ORDER BY match_date, season, id LIMIT 1) AS "firstSeason",
           (SELECT match_date FROM meetings ORDER BY match_date, season, id LIMIT 1) AS "firstMatchDate",
           (SELECT id FROM meetings ORDER BY match_date DESC, season DESC, id DESC LIMIT 1) AS "latestMatchId",
           (SELECT season FROM meetings ORDER BY match_date DESC, season DESC, id DESC LIMIT 1) AS "latestSeason",
           (SELECT match_date FROM meetings ORDER BY match_date DESC, season DESC, id DESC LIMIT 1) AS "latestMatchDate"
      FROM meetings
  `;
  return {
    meetings: row.meetings,
    aWins: row.aWins,
    bWins: row.bWins,
    draws: row.draws,
    aWinPercentage: winPercentage(row.aWins, row.draws, row.meetings),
    bWinPercentage: winPercentage(row.bWins, row.draws, row.meetings),
    firstMeeting: row.firstMatchId === null
      ? null
      : { matchId: row.firstMatchId, season: row.firstSeason as number, matchDate: row.firstMatchDate },
    latestMeeting: row.latestMatchId === null
      ? null
      : { matchId: row.latestMatchId, season: row.latestSeason as number, matchDate: row.latestMatchDate },
    finalsSeriesMeetings: row.finalsSeriesMeetings,
    grandFinalMeetings: row.grandFinalMeetings,
  };
}

// --- Complete meetings, filtered and paginated ---

export type MeetingsPage = {
  meetings: H2HMeeting[];
  matchType: MatchType;
  era: number | null;
  page: number;
  pageSize: number;
  totalMeetings: number;
  totalPages: number;
  hasPreviousPage: boolean;
  hasNextPage: boolean;
};

/**
 * `page` is one-based. Out-of-range pages return no rows but honest
 * pagination metadata -- deciding whether that is a redirect is route
 * behaviour, not query behaviour.
 *
 * `era`, when supplied, is a decade's first season (Club Rivalry Explorer
 * follow-up, FR-2) and narrows the population `h2hScope` already scopes;
 * it is the caller's responsibility to have validated it against the
 * pair's own decade population first.
 */
export async function getHeadToHeadMeetings(
  orgA: number,
  orgB: number,
  options: { matchType?: MatchType; page?: number; era?: number } = {},
): Promise<MeetingsPage> {
  assertDistinct(orgA, orgB);
  const matchType = options.matchType ?? 'all';
  const era = options.era ?? null;
  const page = Math.max(1, Math.trunc(options.page ?? 1));
  const offset = (page - 1) * MEETINGS_PAGE_SIZE;

  const [countRow] = await sql<{ total: number }[]>`
    WITH meetings AS (${h2hScope(orgA, orgB, matchType, era ?? undefined)})
    SELECT count(*)::int AS total FROM meetings
  `;
  const totalMeetings = countRow.total;

  const meetings = await sql<H2HMeeting[]>`
    WITH meetings AS (${h2hScope(orgA, orgB, matchType, era ?? undefined)})
    SELECT ${MEETING_COLUMNS} FROM meetings m
     ORDER BY m.match_date DESC NULLS LAST, m.season DESC, m.id DESC
     LIMIT ${MEETINGS_PAGE_SIZE} OFFSET ${offset}
  `;

  const totalPages = Math.max(1, Math.ceil(totalMeetings / MEETINGS_PAGE_SIZE));
  return {
    meetings: [...meetings],
    matchType,
    era,
    page,
    pageSize: MEETINGS_PAGE_SIZE,
    totalMeetings,
    totalPages,
    hasPreviousPage: page > 1,
    hasNextPage: page < totalPages,
  };
}

// --- Venue records ---

export type H2HVenueRecord = {
  venueId: number | null;
  venueName: string | null;
  meetings: number;
  aWins: number;
  bWins: number;
  draws: number;
  firstMeeting: Date | null;
  latestMeeting: Date | null;
};

/**
 * Grouped by canonical `venue_id`; a meeting with no canonical venue
 * groups only by its exact `venue_raw`. Stage 1 deliberately does not
 * alias unmatched raw names onto canonical venues -- inventing that
 * mapping here would silently merge grounds the venue table has not
 * reconciled.
 */
export async function getHeadToHeadVenueRecords(orgA: number, orgB: number): Promise<H2HVenueRecord[]> {
  assertDistinct(orgA, orgB);
  const rows = await sql<H2HVenueRecord[]>`
    WITH meetings AS (${h2hScope(orgA, orgB)})
    SELECT venue_id AS "venueId",
           min(venue_name) AS "venueName",
           count(*)::int AS meetings,
           count(*) FILTER (WHERE outcome = 'a-win')::int AS "aWins",
           count(*) FILTER (WHERE outcome = 'b-win')::int AS "bWins",
           count(*) FILTER (WHERE outcome = 'draw')::int AS draws,
           min(match_date) AS "firstMeeting",
           max(match_date) AS "latestMeeting"
      FROM meetings
     GROUP BY venue_id, CASE WHEN venue_id IS NULL THEN venue_raw END
     ORDER BY count(*) DESC, min(venue_name), venue_id
  `;
  return [...rows];
}

// --- Records ---

export type H2HRecordKind =
  | 'biggest-win-a'
  | 'biggest-win-b'
  | 'closest-game'
  | 'highest-score-a'
  | 'highest-score-b'
  | 'lowest-score-a'
  | 'lowest-score-b'
  | 'highest-combined-score';

/** A record-holding meeting: the full meeting plus the value it holds. */
export type H2HRecordEntry = H2HMeeting & { value: number };

export type H2HRecords = Record<H2HRecordKind, H2HRecordEntry[]>;

const RECORD_KINDS: H2HRecordKind[] = [
  'biggest-win-a', 'biggest-win-b', 'closest-game',
  'highest-score-a', 'highest-score-b', 'lowest-score-a', 'lowest-score-b',
  'highest-combined-score',
];

/**
 * One pass over the scoped meetings, eight extreme-value branches, every
 * tie kept. Collapsing a tie to one arbitrary row is how "lowest score"
 * quietly loses half its witnesses -- Adelaide's 44 against Brisbane
 * Lions happens twice.
 *
 * `scored` excludes null scores: a match with no recorded score is "not
 * recorded", never a nil-all record.
 *
 * Draws never enter closest-game: a nil margin is not the closest win.
 *
 * `era`, when supplied, is a decade's first season (Club Rivalry Explorer
 * follow-up, FR-2): the eight records are then each held within that one
 * decade of the rivalry rather than across its whole history. The caller
 * is responsible for validating it against the pair's own decade
 * population first -- this function only narrows `h2hScope`.
 */
export async function getHeadToHeadRecords(
  orgA: number,
  orgB: number,
  options: { era?: number } = {},
): Promise<H2HRecords> {
  assertDistinct(orgA, orgB);
  const rows = await sql<(H2HRecordEntry & { kind: H2HRecordKind })[]>`
    WITH meetings AS (${h2hScope(orgA, orgB, 'all', options.era)}),
    scored AS (SELECT * FROM meetings WHERE a_score IS NOT NULL AND b_score IS NOT NULL),
    picks AS (
      SELECT 'biggest-win-a'::text AS kind, id, (a_score - b_score)::int AS value
        FROM scored WHERE a_score > b_score
         AND a_score - b_score = (SELECT max(a_score - b_score) FROM scored WHERE a_score > b_score)
      UNION ALL
      SELECT 'biggest-win-b', id, (b_score - a_score)::int
        FROM scored WHERE b_score > a_score
         AND b_score - a_score = (SELECT max(b_score - a_score) FROM scored WHERE b_score > a_score)
      UNION ALL
      SELECT 'closest-game', id, abs(a_score - b_score)::int
        FROM scored WHERE a_score <> b_score
         AND abs(a_score - b_score) = (SELECT min(abs(a_score - b_score)) FROM scored WHERE a_score <> b_score)
      UNION ALL
      SELECT 'highest-score-a', id, a_score::int
        FROM scored WHERE a_score = (SELECT max(a_score) FROM scored)
      UNION ALL
      SELECT 'highest-score-b', id, b_score::int
        FROM scored WHERE b_score = (SELECT max(b_score) FROM scored)
      UNION ALL
      SELECT 'lowest-score-a', id, a_score::int
        FROM scored WHERE a_score = (SELECT min(a_score) FROM scored)
      UNION ALL
      SELECT 'lowest-score-b', id, b_score::int
        FROM scored WHERE b_score = (SELECT min(b_score) FROM scored)
      UNION ALL
      SELECT 'highest-combined-score', id, (a_score + b_score)::int
        FROM scored WHERE a_score + b_score = (SELECT max(a_score + b_score) FROM scored)
    )
    SELECT p.kind, p.value, ${MEETING_COLUMNS}
      FROM picks p JOIN meetings m ON m.id = p.id
     ORDER BY p.kind, m.match_date, m.season, m.id
  `;

  const records = Object.fromEntries(RECORD_KINDS.map((kind) => [kind, [] as H2HRecordEntry[]])) as H2HRecords;
  for (const row of rows) {
    const { kind, ...entry } = row;
    records[kind].push(entry);
  }
  return records;
}

// --- Streaks ---

export type H2HStreak = {
  outcome: H2HOutcome;
  length: number;
  fromMatchId: number;
  fromSeason: number;
  fromMatchDate: Date | null;
  toMatchId: number;
  toSeason: number;
  toMatchDate: Date | null;
};

export type H2HStreaks = {
  /** Longest run of consecutive A wins. A draw breaks it. */
  longestA: H2HStreak | null;
  longestB: H2HStreak | null;
  /** Consecutive identical results counted back from the latest meeting; may be a draw. */
  current: H2HStreak | null;
};

type StreakRow = { matchId: number; season: number; matchDate: Date | null; outcome: H2HOutcome };

/**
 * Runs are derived from the meetings in true chronological order
 * (`match_date`, `season`, `id`) -- never from the presentation order the
 * paginated meetings list uses, which is the reverse and page-bounded.
 *
 * Where two runs of an organisation tie for longest, the earlier one is
 * returned, so the answer is stable between requests.
 */
export async function getHeadToHeadStreaks(orgA: number, orgB: number): Promise<H2HStreaks> {
  assertDistinct(orgA, orgB);
  const rows = await sql<StreakRow[]>`
    WITH meetings AS (${h2hScope(orgA, orgB)})
    SELECT id AS "matchId", season, match_date AS "matchDate", outcome
      FROM meetings
     ORDER BY match_date, season, id
  `;

  const runs: H2HStreak[] = [];
  for (const row of rows) {
    const open = runs[runs.length - 1];
    if (open && open.outcome === row.outcome) {
      open.length += 1;
      open.toMatchId = row.matchId;
      open.toSeason = row.season;
      open.toMatchDate = row.matchDate;
      continue;
    }
    runs.push({
      outcome: row.outcome,
      length: 1,
      fromMatchId: row.matchId,
      fromSeason: row.season,
      fromMatchDate: row.matchDate,
      toMatchId: row.matchId,
      toSeason: row.season,
      toMatchDate: row.matchDate,
    });
  }

  const longest = (outcome: H2HOutcome): H2HStreak | null => {
    let best: H2HStreak | null = null;
    for (const run of runs) {
      if (run.outcome === outcome && (best === null || run.length > best.length)) best = run;
    }
    return best;
  };

  return {
    longestA: longest('a-win'),
    longestB: longest('b-win'),
    current: runs.length > 0 ? runs[runs.length - 1] : null,
  };
}

// --- Connected (crossover) players ---

/**
 * Which target organisation the player represented FIRST. This is a
 * statement about chronology and nothing else: `a-to-b` means A's first
 * recorded appearance precedes B's, not that the player was traded,
 * delisted, drafted or transferred between them. A player may have
 * played elsewhere in between, may have returned, and may have reached
 * the second organisation by any route at all.
 *
 * `unknown` covers both "the two first appearances cannot be ordered"
 * and the (schema-possible) case of an unresolvable match reference on
 * either side.
 */
export type CrossoverDirection = 'a-to-b' | 'b-to-a' | 'unknown';

/** A third organisation represented between the two target debuts. */
export type CrossoverOrganizationRef = {
  organizationId: number;
  name: string;
  slug: string;
};

/**
 * One organisation's share of a crossover player's career, summed across
 * every historical identity inside that organisation. Brad Johnson's
 * 52 Footscray games and 312 Western Bulldogs games are ONE
 * representation of 364, not two.
 */
export type CrossoverRepresentation = {
  games: number;
  goals: number;
  firstMatchId: number | null;
  firstMatchDate: Date | null;
  lastMatchId: number | null;
  lastMatchDate: Date | null;
};

export type CrossoverPlayer = {
  playerId: number;
  displayName: string;
  sortName: string;
  slug: string;
  a: CrossoverRepresentation;
  b: CrossoverRepresentation;
  combinedGames: number;
  combinedGoals: number;
  /** From player_career_stats; null when the player has no derived row. */
  careerGames: number | null;
  careerGoals: number | null;
  direction: CrossoverDirection;
  /**
   * The date on which the player had represented BOTH organisations --
   * the later of the two first-representation dates. Never the career
   * debut, and never the start of the first stint.
   */
  completionDate: Date | null;
  completionMatchId: number | null;
  interveningOrganizations: CrossoverOrganizationRef[];
};

type CrossoverRow = {
  playerId: number;
  displayName: string;
  sortName: string;
  slug: string;
  aGames: number; aGoals: number;
  aFirstMatchId: number | null; aFirstMatchDate: Date | null;
  aLastMatchId: number | null; aLastMatchDate: Date | null;
  bGames: number; bGoals: number;
  bFirstMatchId: number | null; bFirstMatchDate: Date | null;
  bLastMatchId: number | null; bLastMatchDate: Date | null;
  combinedGames: number;
  combinedGoals: number;
  careerGames: number | null;
  careerGoals: number | null;
  direction: CrossoverDirection;
  completionDate: Date | null;
  completionMatchId: number | null;
  interveningOrganizations: CrossoverOrganizationRef[] | null;
};

/**
 * THE shared crossover scoping fragment. Both exported crossover
 * functions select from this and differ only in ORDER BY, so the list
 * and the summary can never disagree about who crossed over or when.
 *
 * Shape, in order:
 *
 *   - `stints`   -- player_clubs at its native (player, club identity)
 *                   grain, with each stint's first and last match
 *                   dereferenced. Chronology comes from the referenced
 *                   match row, NEVER from the numeric match id alone;
 *                   the id is only the deterministic tie-breaker for two
 *                   matches on the same date.
 *   - `org_rep`  -- the same stints re-aggregated through
 *                   clubs.organization_id: games and goals summed, first
 *                   representation the earliest stint debut, last
 *                   representation the latest stint finale. This is the
 *                   step that stops a rename becoming a second club.
 *   - `pairs`    -- an inner self-join on player_id requiring a row for
 *                   BOTH target organisations. `club_organization_relations`
 *                   is never consulted, so Fitzroy to Brisbane Lions is a
 *                   genuine crossover and Footscray to Western Bulldogs
 *                   is not a crossover at all.
 *
 * (The evidence pack's probe failed because it named a CTE `both`, which
 * is a reserved word. Nothing here is called `both`.)
 */
function crossoverScope(orgA: number, orgB: number) {
  return sql`
    WITH crossover_players AS (
      -- Stage 5 performance: the players who can possibly appear at all.
      -- pairs below already requires an org_rep row for BOTH target
      -- organisations, which requires a player_clubs row in a club of
      -- each, so scoping the stints to these players removes no row the
      -- query could have returned -- including from the intervening
      -- organisations subquery, which is correlated to one of them.
      -- Without it the whole 16,710-row player_clubs table was
      -- re-aggregated and then rescanned once per crossover player.
      SELECT pc.player_id
        FROM player_clubs pc
        JOIN clubs c ON c.id = pc.club_id
       WHERE c.organization_id IN (${orgA}, ${orgB})
       GROUP BY pc.player_id
      HAVING count(DISTINCT c.organization_id) = 2
    ),
    stints AS (
      SELECT pc.player_id,
             c.organization_id AS org_id,
             pc.games,
             pc.goals,
             fm.id AS first_match_id, fm.match_date AS first_match_date,
             lm.id AS last_match_id, lm.match_date AS last_match_date
        FROM player_clubs pc
        JOIN crossover_players xp ON xp.player_id = pc.player_id
        JOIN clubs c ON c.id = pc.club_id
        LEFT JOIN matches fm ON fm.id = pc.first_match_id
        LEFT JOIN matches lm ON lm.id = pc.last_match_id
    ),
    org_totals AS (
      SELECT player_id, org_id,
             sum(games)::int AS games,
             sum(goals)::int AS goals
        FROM stints
       GROUP BY player_id, org_id
    ),
    org_first AS (
      SELECT DISTINCT ON (player_id, org_id)
             player_id, org_id, first_match_id, first_match_date
        FROM stints
       WHERE first_match_id IS NOT NULL
       ORDER BY player_id, org_id, first_match_date NULLS LAST, first_match_id
    ),
    org_last AS (
      SELECT DISTINCT ON (player_id, org_id)
             player_id, org_id, last_match_id, last_match_date
        FROM stints
       WHERE last_match_id IS NOT NULL
       ORDER BY player_id, org_id, last_match_date DESC NULLS LAST, last_match_id DESC
    ),
    org_rep AS (
      SELECT t.player_id, t.org_id, t.games, t.goals,
             f.first_match_id, f.first_match_date,
             l.last_match_id, l.last_match_date
        FROM org_totals t
        LEFT JOIN org_first f ON f.player_id = t.player_id AND f.org_id = t.org_id
        LEFT JOIN org_last  l ON l.player_id = t.player_id AND l.org_id = t.org_id
    ),
    pairs AS (
      SELECT a.player_id,
             a.games AS a_games, a.goals AS a_goals,
             a.first_match_id AS a_first_match_id, a.first_match_date AS a_first_match_date,
             a.last_match_id  AS a_last_match_id,  a.last_match_date  AS a_last_match_date,
             b.games AS b_games, b.goals AS b_goals,
             b.first_match_id AS b_first_match_id, b.first_match_date AS b_first_match_date,
             b.last_match_id  AS b_last_match_id,  b.last_match_date  AS b_last_match_date,
             CASE
               WHEN a.first_match_date IS NULL OR b.first_match_date IS NULL THEN 'unknown'
               WHEN (a.first_match_date, a.first_match_id) < (b.first_match_date, b.first_match_id) THEN 'a-to-b'
               WHEN (b.first_match_date, b.first_match_id) < (a.first_match_date, a.first_match_id) THEN 'b-to-a'
               ELSE 'unknown'
             END AS direction,
             -- The EARLIER debut opens the intervening interval; the
             -- LATER one closes it and IS the crossover completion.
             LEAST(a.first_match_date, b.first_match_date) AS earlier_date,
             CASE WHEN (a.first_match_date, a.first_match_id) < (b.first_match_date, b.first_match_id)
                  THEN a.first_match_id ELSE b.first_match_id END AS earlier_match_id,
             GREATEST(a.first_match_date, b.first_match_date) AS later_date,
             CASE WHEN (a.first_match_date, a.first_match_id) < (b.first_match_date, b.first_match_id)
                  THEN b.first_match_id ELSE a.first_match_id END AS later_match_id
        FROM org_rep a
        JOIN org_rep b ON b.player_id = a.player_id AND b.org_id = ${orgB}
       WHERE a.org_id = ${orgA}
    )
    SELECT p.player_id AS "playerId",
           pl.display_name AS "displayName",
           pl.sort_name AS "sortName",
           pl.slug,
           p.a_games AS "aGames", p.a_goals AS "aGoals",
           p.a_first_match_id AS "aFirstMatchId", p.a_first_match_date AS "aFirstMatchDate",
           p.a_last_match_id  AS "aLastMatchId",  p.a_last_match_date  AS "aLastMatchDate",
           p.b_games AS "bGames", p.b_goals AS "bGoals",
           p.b_first_match_id AS "bFirstMatchId", p.b_first_match_date AS "bFirstMatchDate",
           p.b_last_match_id  AS "bLastMatchId",  p.b_last_match_date  AS "bLastMatchDate",
           (p.a_games + p.b_games) AS "combinedGames",
           (p.a_goals + p.b_goals) AS "combinedGoals",
           pcs.games AS "careerGames",
           pcs.goals AS "careerGoals",
           p.direction,
           p.later_date AS "completionDate",
           p.later_match_id AS "completionMatchId",
           (
             SELECT jsonb_agg(
                      jsonb_build_object('organizationId', x."organizationId",
                                         'name', x.name,
                                         'slug', x.slug)
                      ORDER BY x.first_match_date, x.first_match_id)
               FROM (
                 SELECT o.id AS "organizationId", o.name, o.slug,
                        r.first_match_date, r.first_match_id
                   FROM org_rep r
                   JOIN club_organizations o ON o.id = r.org_id
                  WHERE r.player_id = p.player_id
                    AND r.org_id NOT IN (${orgA}, ${orgB})
                    AND r.first_match_date IS NOT NULL
                    AND p.earlier_date IS NOT NULL
                    AND p.later_date IS NOT NULL
                    AND (r.first_match_date, r.first_match_id) > (p.earlier_date, p.earlier_match_id)
                    AND (r.first_match_date, r.first_match_id) < (p.later_date, p.later_match_id)
               ) x
           ) AS "interveningOrganizations"
      FROM pairs p
      JOIN players pl ON pl.id = p.player_id
      LEFT JOIN player_career_stats pcs ON pcs.player_id = p.player_id
  `;
}

function toCrossoverPlayer(row: CrossoverRow): CrossoverPlayer {
  return {
    playerId: row.playerId,
    displayName: row.displayName,
    sortName: row.sortName,
    slug: row.slug,
    a: {
      games: row.aGames, goals: row.aGoals,
      firstMatchId: row.aFirstMatchId, firstMatchDate: row.aFirstMatchDate,
      lastMatchId: row.aLastMatchId, lastMatchDate: row.aLastMatchDate,
    },
    b: {
      games: row.bGames, goals: row.bGoals,
      firstMatchId: row.bFirstMatchId, firstMatchDate: row.bFirstMatchDate,
      lastMatchId: row.bLastMatchId, lastMatchDate: row.bLastMatchDate,
    },
    combinedGames: row.combinedGames,
    combinedGoals: row.combinedGoals,
    careerGames: row.careerGames,
    careerGoals: row.careerGoals,
    direction: row.direction,
    completionDate: row.completionDate,
    completionMatchId: row.completionMatchId,
    interveningOrganizations: row.interveningOrganizations ?? [],
  };
}

/**
 * Every player who represented both selected organisations, sorted by
 * combined games for those two organisations, then sort name, then
 * player id -- so the list is stable and a derived-data rebuild cannot
 * reshuffle it.
 */
export async function getCrossoverPlayers(orgA: number, orgB: number): Promise<CrossoverPlayer[]> {
  assertDistinct(orgA, orgB);
  const rows = await sql<CrossoverRow[]>`
    SELECT * FROM (${crossoverScope(orgA, orgB)}) c
     ORDER BY c."combinedGames" DESC, c."sortName", c."playerId"
  `;
  return rows.map(toCrossoverPlayer);
}

export type CrossoverSummary = {
  players: number;
  /**
   * Earliest and latest COMPLETION -- the day each player had appeared
   * for both organisations. Arrays, because a completion date can be
   * shared and dropping a tied player would be a silent edit of the
   * record.
   */
  firstToRepresentBoth: CrossoverPlayer[];
  mostRecentToRepresentBoth: CrossoverPlayer[];
};

/**
 * Head and tail of the crossover history by completion date. A player
 * whose completion date is unknown is counted in `players` but cannot
 * hold either record, because an unknown date is not an early one.
 */
export async function getCrossoverSummary(orgA: number, orgB: number): Promise<CrossoverSummary> {
  assertDistinct(orgA, orgB);
  const rows = await sql<CrossoverRow[]>`
    SELECT * FROM (${crossoverScope(orgA, orgB)}) c
     ORDER BY c."completionDate" NULLS LAST, c."completionMatchId", c."playerId"
  `;
  const players = rows.map(toCrossoverPlayer);
  const dated = players.filter((p) => p.completionDate !== null);
  const tiedWith = (at: CrossoverPlayer) =>
    dated.filter((p) => (p.completionDate as Date).getTime() === (at.completionDate as Date).getTime());

  return {
    players: players.length,
    firstToRepresentBoth: dated.length === 0 ? [] : tiedWith(dated[0]),
    mostRecentToRepresentBoth: dated.length === 0 ? [] : tiedWith(dated[dated.length - 1]),
  };
}

// --- H2H player leaders ---

/**
 * Dense-rank cut for every H2H leaderboard. Ties at the cut are all
 * retained, so a board may return more than ten rows.
 */
export const H2H_LEADER_RANK_LIMIT = 10;

/**
 * One organisation's share of a player's H2H record. `goals` is NULL when
 * the player has no meeting in which goals were recorded at all -- a
 * historical gap is never reported as nought. `goalsRecordedGames` is the
 * honest denominator behind `goals`.
 */
export type H2HLeaderRepresentation = {
  games: number;
  goals: number | null;
  goalsRecordedGames: number;
};

/**
 * A player on an H2H leaderboard. A player who represented BOTH selected
 * organisations in this rivalry -- Charlie Cameron has appeared for
 * Adelaide and for Brisbane Lions in Adelaide vs Brisbane Lions matches --
 * is ONE row with two organisation breakdowns, never two ambiguous rows.
 */
export type H2HPlayerLeader = {
  /** Dense rank, 1-based, ties sharing a rank. */
  rank: number;
  playerId: number;
  displayName: string;
  sortName: string;
  slug: string;
  games: number;
  goals: number | null;
  goalsRecordedGames: number;
  a: H2HLeaderRepresentation;
  b: H2HLeaderRepresentation;
};

/** One holder of a single-match H2H record, with the meeting it was set in. */
export type H2HStatRecordHolder = {
  playerId: number;
  displayName: string;
  sortName: string;
  slug: string;
  value: number;
  matchId: number;
  season: number;
  matchDate: Date | null;
  /** The identity the player actually represented on the day. */
  clubId: number;
  clubName: string;
  clubSlug: string;
  organizationId: number;
};

/**
 * A single-match statistical record over the rivalry. `value` is null and
 * `holders` empty when the statistic was never recorded in ANY meeting of
 * the pair -- which is a coverage statement, not a record of nought.
 */
export type H2HStatRecord = {
  stat: 'goals' | 'disposals';
  /** Player-match rows in the pair in which the statistic is recorded. */
  recordedRows: number;
  value: number | null;
  holders: H2HStatRecordHolder[];
};

export type H2HPlayerLeaders = {
  games: H2HPlayerLeader[];
  goals: H2HPlayerLeader[];
  singleMatchGoals: H2HStatRecord;
  singleMatchDisposals: H2HStatRecord;
};

type H2HLeaderRow = {
  rank: number;
  playerId: number;
  displayName: string;
  sortName: string;
  slug: string;
  games: number;
  goals: number | null;
  goalsRecordedGames: number;
  aGames: number;
  aGoals: number | null;
  aGoalsRecordedGames: number;
  bGames: number;
  bGoals: number | null;
  bGoalsRecordedGames: number;
};

function toLeader(row: H2HLeaderRow): H2HPlayerLeader {
  return {
    rank: row.rank,
    playerId: row.playerId,
    displayName: row.displayName,
    sortName: row.sortName,
    slug: row.slug,
    games: row.games,
    goals: row.goalsRecordedGames > 0 ? row.goals : null,
    goalsRecordedGames: row.goalsRecordedGames,
    a: {
      games: row.aGames,
      goals: row.aGoalsRecordedGames > 0 ? row.aGoals : null,
      goalsRecordedGames: row.aGoalsRecordedGames,
    },
    b: {
      games: row.bGames,
      goals: row.bGoalsRecordedGames > 0 ? row.bGoals : null,
      goalsRecordedGames: row.bGoalsRecordedGames,
    },
  };
}

/**
 * Per-player H2H aggregate over the COMPLETE scoped meeting population --
 * finals included, no historical cutoff. Appearances are counted from
 * `player_match_stats` rows (a row is an appearance whether or not any
 * statistic was recorded) and attributed through the historical
 * `player_match_stats.club_id` to `clubs.organization_id`, so a Footscray
 * appearance lands on Western Bulldogs without becoming a second row.
 */
function h2hPlayerTotals(orgA: number, orgB: number) {
  return sql`
    WITH meetings AS (${h2hScope(orgA, orgB)}),
    appearances AS (
      SELECT pms.player_id,
             pms.goals,
             (c.organization_id = ${orgA}) AS is_a
        FROM player_match_stats pms
        JOIN meetings mt ON mt.id = pms.match_id
        JOIN clubs c ON c.id = pms.club_id
       WHERE c.organization_id IN (${orgA}, ${orgB})
    )
    SELECT ap.player_id,
           count(*)::int AS games,
           sum(ap.goals)::int AS goals,
           count(ap.goals)::int AS goals_recorded_games,
           count(*) FILTER (WHERE ap.is_a)::int AS a_games,
           sum(ap.goals) FILTER (WHERE ap.is_a)::int AS a_goals,
           count(ap.goals) FILTER (WHERE ap.is_a)::int AS a_goals_recorded_games,
           count(*) FILTER (WHERE NOT ap.is_a)::int AS b_games,
           sum(ap.goals) FILTER (WHERE NOT ap.is_a)::int AS b_goals,
           count(ap.goals) FILTER (WHERE NOT ap.is_a)::int AS b_goals_recorded_games
      FROM appearances ap
     GROUP BY ap.player_id
  `;
}

const H2H_LEADER_COLUMNS = sql`
  t.player_id AS "playerId",
  p.display_name AS "displayName", p.sort_name AS "sortName", p.slug,
  t.games, t.goals, t.goals_recorded_games AS "goalsRecordedGames",
  t.a_games AS "aGames", t.a_goals AS "aGoals",
  t.a_goals_recorded_games AS "aGoalsRecordedGames",
  t.b_games AS "bGames", t.b_goals AS "bGoals",
  t.b_goals_recorded_games AS "bGoalsRecordedGames"
`;

/**
 * A single-match record over the rivalry. Only rows where the statistic
 * is actually recorded are considered: NULL is "not recorded", never
 * nought, so a meeting with no disposal data can neither hold nor dilute
 * a disposals record. Every tied holder is returned, ordered by meeting
 * date then match id then player, so the list is stable.
 */
async function h2hStatRecord(
  orgA: number,
  orgB: number,
  stat: 'goals' | 'disposals',
): Promise<H2HStatRecord> {
  const column = stat === 'goals' ? sql`pms.goals` : sql`pms.disposals`;
  const rows = await sql<(H2HStatRecordHolder & { recordedRows: number })[]>`
    WITH meetings AS (${h2hScope(orgA, orgB)}),
    recorded AS (
      SELECT pms.player_id, ${column} AS value,
             mt.id AS match_id, mt.season, mt.match_date,
             c.id AS club_id, c.name AS club_name, c.slug AS club_slug,
             c.organization_id
        FROM player_match_stats pms
        JOIN meetings mt ON mt.id = pms.match_id
        JOIN clubs c ON c.id = pms.club_id
       WHERE c.organization_id IN (${orgA}, ${orgB})
         AND ${column} IS NOT NULL
    )
    SELECT r.player_id AS "playerId",
           p.display_name AS "displayName", p.sort_name AS "sortName", p.slug,
           r.value, r.match_id AS "matchId", r.season, r.match_date AS "matchDate",
           r.club_id AS "clubId", r.club_name AS "clubName", r.club_slug AS "clubSlug",
           r.organization_id AS "organizationId",
           (SELECT count(*)::int FROM recorded) AS "recordedRows"
      FROM recorded r
      JOIN players p ON p.id = r.player_id
     WHERE r.value = (SELECT max(value) FROM recorded)
     ORDER BY r.match_date, r.match_id, p.sort_name, r.player_id
  `;
  if (rows.length === 0) {
    return { stat, recordedRows: 0, value: null, holders: [] };
  }
  const { recordedRows } = rows[0];
  return {
    stat,
    recordedRows,
    value: rows[0].value,
    holders: rows.map(({ recordedRows: _ignored, ...holder }) => holder),
  };
}

/**
 * The V1 H2H player-record families: most meetings played, most goals
 * kicked, and the single-match goals and disposals records. Per-game
 * averages are deliberately NOT in V1.
 */
export async function getHeadToHeadPlayerLeaders(
  orgA: number,
  orgB: number,
): Promise<H2HPlayerLeaders> {
  assertDistinct(orgA, orgB);
  const [gamesRows, goalsRows, singleMatchGoals, singleMatchDisposals] = await Promise.all([
    sql<H2HLeaderRow[]>`
      WITH totals AS (${h2hPlayerTotals(orgA, orgB)}),
      ranked AS (
        SELECT t.*, dense_rank() OVER (ORDER BY t.games DESC) AS rank FROM totals t
      )
      SELECT t.rank::int AS rank, ${H2H_LEADER_COLUMNS}
        FROM ranked t
        JOIN players p ON p.id = t.player_id
       WHERE t.rank <= ${H2H_LEADER_RANK_LIMIT}
       ORDER BY t.rank, p.sort_name, t.player_id
    `,
    sql<H2HLeaderRow[]>`
      WITH totals AS (${h2hPlayerTotals(orgA, orgB)}),
      scored AS (
        SELECT * FROM totals WHERE goals_recorded_games > 0 AND goals IS NOT NULL
      ),
      ranked AS (
        SELECT s.*, dense_rank() OVER (ORDER BY s.goals DESC) AS rank FROM scored s
      )
      SELECT t.rank::int AS rank, ${H2H_LEADER_COLUMNS}
        FROM ranked t
        JOIN players p ON p.id = t.player_id
       WHERE t.rank <= ${H2H_LEADER_RANK_LIMIT}
       ORDER BY t.rank, p.sort_name, t.player_id
    `,
    h2hStatRecord(orgA, orgB, 'goals'),
    h2hStatRecord(orgA, orgB, 'disposals'),
  ]);

  return {
    games: gamesRows.map(toLeader),
    goals: goalsRows.map(toLeader),
    singleMatchGoals,
    singleMatchDisposals,
  };
}

// --- Runtime metric coverage ---

/**
 * `stat_availability.coverage` as the application must read it, plus the
 * one state the table cannot express: `missing`, meaning there is no
 * coverage row at all for that statistic and season. Missing coverage is
 * never optimistically treated as `complete`.
 */
export type MetricCoverage =
  | 'complete'
  | 'partial'
  | 'pending'
  | 'not_collected'
  | 'not_applicable'
  | 'missing';

/**
 * THE runtime metric-coverage abstraction. Every coverage decision in
 * this module joins through here, and nothing anywhere encodes a year
 * window: when a reload turns 2026 from `pending` into `complete`, the
 * next request presents numeric data with no code change at all.
 *
 * One key or many. The many-key form is the same shape plus a
 * `stat_key` column, so the selected-season team metrics read all
 * twenty-one families through this one abstraction instead of a second
 * coverage model. The seasons/keys cross product is LEFT JOINed, so a
 * season with no `stat_availability` row still yields a row reading
 * `missing`; absent coverage is never optimistically `complete`.
 */
function statCoverage(statKeys: string | string[]) {
  const keys = Array.isArray(statKeys) ? statKeys : [statKeys];
  return sql`
    SELECT s.year AS season,
           k.stat_key,
           COALESCE(sa.coverage::text, 'missing') AS coverage,
           COALESCE(sa.is_recorded, false) AS is_recorded,
           sa.populated_rows,
           sa.total_rows
      FROM seasons s
      CROSS JOIN unnest(${keys}::text[]) AS k(stat_key)
      LEFT JOIN stat_availability sa
        ON sa.stat_key = k.stat_key AND sa.season = s.year
  `;
}

/** Coverage keys this module reads. Never a bare 'brownlow'; that key is gone. */
const BROWNLOW_SEASON_TOTAL = 'brownlow_season_total';
const BROWNLOW_MATCH_VOTES = 'brownlow_match_votes';

/**
 * Only `complete` permits presenting an authoritative season total.
 * `partial` explicitly does NOT: a partly-loaded season would read as a
 * smaller season, which is worse than saying nothing.
 */
export function isAuthoritativeCoverage(coverage: MetricCoverage): boolean {
  return coverage === 'complete';
}

// --- Brownlow: club attribution ---

/**
 * Dense-rank cut for club Brownlow leaderboards. Ties at the cut are all
 * retained, so a board may return more than ten rows.
 */
export const CLUB_BROWNLOW_LEADER_RANK_LIMIT = 10;


/**
 * How a season vote row reached a club.
 *
 *   - `explicit`  -- `brownlow_season_votes.club_id` was populated.
 *   - `primary`   -- `club_id` was NULL and the player played for exactly
 *                    one club that season (`player_season_stats.club_count
 *                    = 1`), so `primary_club_id` is not a guess.
 *   - `unattributed` -- `club_id` was NULL in a multi-club season, or the
 *                    player has no season row at all. The votes are real
 *                    and are NEVER forced onto a club; they are counted
 *                    and disclosed instead.
 */
export type BrownlowAttributionSource = 'explicit' | 'primary' | 'unattributed';

/**
 * THE Brownlow attribution fragment. Every club/organisation Brownlow
 * figure in this module -- all-time history, all-time vote leaders and
 * the selected-season summary -- selects from this and nothing else, so
 * Stage 4's selected-season Brownlow cannot drift from the all-time
 * history it is supposed to be a slice of.
 *
 * `brownlow_season_votes` is authoritative: season totals, winners and
 * eligibility come from here and are NEVER re-derived by summing
 * `player_match_stats.brownlow_votes`.
 *
 * `brownlow_season_votes.club_id` is NULLABLE (in the canonical test
 * database it is null on every one of the 16,120 rows), so it is
 * COALESCEd, never inner-joined. The supplied evidence probe returned
 * zero rows precisely because it inner-joined it.
 */
function brownlowAttribution() {
  return sql`
    SELECT b.season,
           b.player_id,
           b.votes::int AS votes,
           b.vote_rank,
           b.is_winner,
           b.is_ineligible,
           b.three_vote_games,
           b.two_vote_games,
           b.one_vote_games,
           b.polling_games,
           COALESCE(
             b.club_id,
             CASE WHEN pss.club_count = 1 THEN pss.primary_club_id END
           ) AS attributed_club_id,
           CASE
             WHEN b.club_id IS NOT NULL THEN 'explicit'
             WHEN pss.club_count = 1 AND pss.primary_club_id IS NOT NULL THEN 'primary'
             ELSE 'unattributed'
           END AS attribution_source,
           pss.club_count,
           pss.primary_club_id AS season_primary_club_id
      FROM brownlow_season_votes b
      LEFT JOIN player_season_stats pss
        ON pss.player_id = b.player_id AND pss.season = b.season
  `;
}

/**
 * Attribution resolved to the organisation grain, with the season-total
 * coverage state attached. Nothing is filtered here: callers decide what
 * `complete` means for them.
 */
function brownlowOrganizationRows() {
  return sql`
    SELECT a.*,
           c.organization_id,
           cov.coverage AS season_total_coverage,
           -- The organisation an UNATTRIBUTED row is merely associated
           -- with, for disclosure. Its votes are never added to a club.
           po.organization_id AS primary_organization_id
      FROM (${brownlowAttribution()}) a
      LEFT JOIN clubs c ON c.id = a.attributed_club_id
      LEFT JOIN clubs po ON po.id = a.season_primary_club_id
      LEFT JOIN (${statCoverage(BROWNLOW_SEASON_TOTAL)}) cov ON cov.season = a.season
  `;
}

export type ClubBrownlowWinner = {
  season: number;
  playerId: number;
  displayName: string;
  slug: string;
  votes: number;
  isIneligible: boolean;
};

export type ClubBrownlowSeason = {
  season: number;
  votes: number;
  playersWithVotes: number;
  winners: number;
  ineligiblePlayers: number;
  /** Real vote rows in this season that could not be attributed to a club. */
  unattributedRows: number;
  unattributedVotes: number;
};

export type ClubBrownlowLeader = {
  /** Dense rank, 1-based, ties sharing a rank. */
  rank: number;
  playerId: number;
  displayName: string;
  sortName: string;
  slug: string;
  votes: number;
  seasons: number;
  winners: number;
  /** True when at least one of the player's seasons here was ineligible. */
  hasIneligibleSeason: boolean;
};

export type ClubBrownlowHistory = {
  organizationId: number;
  /** Ascending. Only seasons whose brownlow_season_total coverage is complete. */
  seasons: ClubBrownlowSeason[];
  totalVotes: number;
  seasonsCovered: number;
  winners: ClubBrownlowWinner[];
  voteLeaders: ClubBrownlowLeader[];
  /**
   * Multi-club seasons whose votes belong to a player associated with
   * this organisation but which cannot honestly be attributed to it.
   * Disclosed, never added to `totalVotes`.
   */
  unattributed: { rows: number; votes: number };
  /**
   * Seasons in which this organisation has vote rows but whose season-total
   * coverage is not complete, and which are therefore excluded from every
   * figure above.
   */
  excludedSeasons: { season: number; coverage: MetricCoverage }[];
};

/**
 * All-time club Brownlow history at the organisation grain.
 *
 * Only seasons whose runtime `brownlow_season_total` coverage is
 * `complete` contribute. Winners come from `is_winner` alone -- never
 * from vote rank, never from "most votes" -- and ineligibility is
 * preserved rather than filtered away.
 */
export async function getClubBrownlowHistory(
  organizationId: number,
): Promise<ClubBrownlowHistory> {
  /**
   * THE attribution fragment, scoped to the only rows this organisation
   * can appear in: those attributed to it, and the unattributed rows
   * merely associated with it through the season primary club. Every
   * statement below already requires one of those two predicates, so
   * this is a filter push-down and not a change of meaning.
   *
   * Stage 5 performance: without it each statement re-attributed and
   * re-aggregated all 16,120 vote rows, which put the warm median for a
   * long-history organisation on the 250 ms ceiling.
   */
  const scoped = sql`
    SELECT r.* FROM (${brownlowOrganizationRows()}) r
     WHERE r.organization_id = ${organizationId}
        OR r.primary_organization_id = ${organizationId}
  `;

  const [
    seasons, winners, voteLeaders, [totals], excludedSeasons, unattributedBySeason,
  ] = await Promise.all([
    sql<ClubBrownlowSeason[]>`
      WITH attributed AS (${scoped})
      SELECT r.season,
             sum(r.votes)::int AS votes,
             count(*) FILTER (WHERE r.votes > 0)::int AS "playersWithVotes",
             count(*) FILTER (WHERE r.is_winner)::int AS winners,
             count(*) FILTER (WHERE r.is_ineligible)::int AS "ineligiblePlayers",
             0::int AS "unattributedRows",
             0::int AS "unattributedVotes"
        FROM attributed r
       WHERE r.organization_id = ${organizationId}
         AND r.season_total_coverage = 'complete'
       GROUP BY r.season
       ORDER BY r.season
    `,
    sql<ClubBrownlowWinner[]>`
      WITH attributed AS (${scoped})
      SELECT r.season, r.player_id AS "playerId",
             p.display_name AS "displayName", p.slug,
             r.votes, r.is_ineligible AS "isIneligible"
        FROM attributed r
        JOIN players p ON p.id = r.player_id
       WHERE r.organization_id = ${organizationId}
         AND r.season_total_coverage = 'complete'
         AND r.is_winner
       ORDER BY r.season, p.sort_name
    `,
    sql<ClubBrownlowLeader[]>`
      WITH attributed AS (${scoped}),
      per_player AS (
        SELECT r.player_id,
               sum(r.votes)::int AS votes,
               count(*)::int AS seasons,
               count(*) FILTER (WHERE r.is_winner)::int AS winners,
               bool_or(r.is_ineligible) AS has_ineligible_season
          FROM attributed r
         WHERE r.organization_id = ${organizationId}
           AND r.season_total_coverage = 'complete'
         GROUP BY r.player_id
        HAVING sum(r.votes) > 0
      ),
      ranked AS (
        SELECT pp.*, dense_rank() OVER (ORDER BY pp.votes DESC) AS rank FROM per_player pp
      )
      SELECT t.rank::int AS rank, t.player_id AS "playerId",
             p.display_name AS "displayName", p.sort_name AS "sortName", p.slug,
             t.votes, t.seasons, t.winners,
             t.has_ineligible_season AS "hasIneligibleSeason"
        FROM ranked t
        JOIN players p ON p.id = t.player_id
       WHERE t.rank <= ${CLUB_BROWNLOW_LEADER_RANK_LIMIT}
       ORDER BY t.rank, p.sort_name, t.player_id
    `,
    sql<{ totalVotes: number; seasonsCovered: number;
          unattributedRows: number; unattributedVotes: number }[]>`
      WITH attributed AS (${scoped})
      SELECT COALESCE(sum(r.votes) FILTER (
               WHERE r.organization_id = ${organizationId}
                 AND r.season_total_coverage = 'complete'), 0)::int AS "totalVotes",
             count(DISTINCT r.season) FILTER (
               WHERE r.organization_id = ${organizationId}
                 AND r.season_total_coverage = 'complete')::int AS "seasonsCovered",
             count(*) FILTER (
               WHERE r.attribution_source = 'unattributed'
                 AND r.primary_organization_id = ${organizationId}
                 AND r.season_total_coverage = 'complete')::int AS "unattributedRows",
             COALESCE(sum(r.votes) FILTER (
               WHERE r.attribution_source = 'unattributed'
                 AND r.primary_organization_id = ${organizationId}
                 AND r.season_total_coverage = 'complete'), 0)::int AS "unattributedVotes"
        FROM attributed r
    `,
    sql<{ season: number; coverage: MetricCoverage }[]>`
      WITH attributed AS (${scoped})
      SELECT DISTINCT r.season, r.season_total_coverage AS coverage
        FROM attributed r
       WHERE r.organization_id = ${organizationId}
         AND r.season_total_coverage <> 'complete'
       ORDER BY r.season
    `,
    // Independent of the five above -- it was a serial seventh round
    // trip, and is now issued with them.
    sql<{ season: number; rowCount: number; votes: number }[]>`
      WITH attributed AS (${scoped})
      SELECT r.season, count(*)::int AS "rowCount", sum(r.votes)::int AS votes
        FROM attributed r
       WHERE r.attribution_source = 'unattributed'
         AND r.primary_organization_id = ${organizationId}
         AND r.season_total_coverage = 'complete'
       GROUP BY r.season
    `,
  ]);

  const unattributedIndex = new Map(unattributedBySeason.map((r) => [r.season, r]));

  return {
    organizationId,
    seasons: seasons.map((s) => {
      const u = unattributedIndex.get(s.season);
      return { ...s, unattributedRows: u?.rowCount ?? 0, unattributedVotes: u?.votes ?? 0 };
    }),
    totalVotes: totals.totalVotes,
    seasonsCovered: totals.seasonsCovered,
    winners,
    voteLeaders,
    unattributed: { rows: totals.unattributedRows, votes: totals.unattributedVotes },
    excludedSeasons,
  };
}

export type ClubSeasonBrownlowPlayer = {
  rank: number;
  playerId: number;
  displayName: string;
  sortName: string;
  slug: string;
  votes: number;
  isWinner: boolean;
  isIneligible: boolean;
  attributionSource: BrownlowAttributionSource;
};

export type ClubSeasonBrownlowSummary = {
  organizationId: number;
  season: number;
  coverage: MetricCoverage;
  /** True only for `complete`. When false every numeric field is null/empty. */
  isAuthoritative: boolean;
  totalVotes: number | null;
  playersWithVotes: number | null;
  leaders: ClubSeasonBrownlowPlayer[];
  winners: ClubSeasonBrownlowPlayer[];
  unattributedRows: number;
  unattributedVotes: number;
};

/**
 * The selected-season club Brownlow primitive Stage 4 builds on. It
 * shares `brownlowAttribution()` with the all-time history, so the two
 * can never disagree about whose votes belong to which club.
 *
 * The coverage state is returned whatever it is, and the numeric fields
 * are null unless the state is `complete`, so the caller can distinguish
 * complete / partial / pending / not_collected / not_applicable /
 * missing without recomputing any of the semantics.
 */
export async function getClubSeasonBrownlowSummary(
  organizationId: number,
  season: number,
): Promise<ClubSeasonBrownlowSummary> {
  const [[coverageRow], [totals], players] = await Promise.all([
    sql<{ coverage: MetricCoverage }[]>`
      SELECT cov.coverage
        FROM (${statCoverage(BROWNLOW_SEASON_TOTAL)}) cov
       WHERE cov.season = ${season}
    `,
    sql<{ totalVotes: number; playersWithVotes: number;
          unattributedRows: number; unattributedVotes: number }[]>`
      WITH attributed AS (${brownlowOrganizationRows()})
      SELECT COALESCE(sum(r.votes) FILTER (
               WHERE r.organization_id = ${organizationId}), 0)::int AS "totalVotes",
             count(*) FILTER (
               WHERE r.organization_id = ${organizationId} AND r.votes > 0)::int
               AS "playersWithVotes",
             count(*) FILTER (
               WHERE r.attribution_source = 'unattributed'
                 AND r.primary_organization_id = ${organizationId})::int AS "unattributedRows",
             COALESCE(sum(r.votes) FILTER (
               WHERE r.attribution_source = 'unattributed'
                 AND r.primary_organization_id = ${organizationId}), 0)::int
               AS "unattributedVotes"
        FROM attributed r
       WHERE r.season = ${season}
    `,
    sql<ClubSeasonBrownlowPlayer[]>`
      WITH attributed AS (${brownlowOrganizationRows()}),
      scored AS (
        SELECT r.* FROM attributed r
         WHERE r.season = ${season}
           AND r.organization_id = ${organizationId}
           AND r.votes > 0
      ),
      ranked AS (
        SELECT s.*, dense_rank() OVER (ORDER BY s.votes DESC) AS rank FROM scored s
      )
      SELECT t.rank::int AS rank, t.player_id AS "playerId",
             p.display_name AS "displayName", p.sort_name AS "sortName", p.slug,
             t.votes, t.is_winner AS "isWinner", t.is_ineligible AS "isIneligible",
             t.attribution_source AS "attributionSource"
        FROM ranked t
        JOIN players p ON p.id = t.player_id
       ORDER BY t.rank, p.sort_name, t.player_id
    `,
  ]);

  const coverage: MetricCoverage = coverageRow?.coverage ?? 'missing';
  const authoritative = isAuthoritativeCoverage(coverage);

  return {
    organizationId,
    season,
    coverage,
    isAuthoritative: authoritative,
    totalVotes: authoritative ? totals.totalVotes : null,
    playersWithVotes: authoritative ? totals.playersWithVotes : null,
    // The rank cut trims the leaderboard, never the winners: a medallist
    // is read from `is_winner` over the whole club-season, so an
    // ineligible or otherwise unusual winner cannot fall off the board.
    leaders: authoritative
      ? players.filter((p) => p.rank <= CLUB_BROWNLOW_LEADER_RANK_LIMIT)
      : [],
    winners: authoritative ? players.filter((p) => p.isWinner) : [],
    unattributedRows: totals.unattributedRows,
    unattributedVotes: totals.unattributedVotes,
  };
}

// --- H2H Brownlow ---

/**
 * A fully polled home-and-away match distributes exactly 3 + 2 + 1 = 6
 * Brownlow votes. This is the canonical completeness rule -- it is what
 * migration 016 and the repeatable `import_legacy_afl.py` coverage
 * derivation both use to decide `brownlow_match_votes` per season -- and
 * it is deliberately NOT weakened to "some votes present".
 */
const FULLY_POLLED_MATCH_VOTES = 6;

export type H2HBrownlowPlayer = {
  playerId: number;
  displayName: string;
  sortName: string;
  slug: string;
  votes: number;
  threeVoteGames: number;
  twoVoteGames: number;
  oneVoteGames: number;
  pollingGames: number;
  /** Votes polled while representing organisation A / B, at the match. */
  aVotes: number;
  bVotes: number;
};

export type H2HBrownlow = {
  /** Home-and-away meetings only. Finals are never polled. */
  eligibleMeetings: number;
  /** Eligible meetings whose season coverage allows the question to be asked. */
  evaluableMeetings: number;
  /** Eligible meetings with the complete published 3-2-1 allocation recorded. */
  coveredMeetings: number;
  /** Eligible meetings with some votes recorded but not the full allocation. */
  partiallyPolledMeetings: number;
  /** `complete` only when coveredMeetings === eligibleMeetings. */
  coverage: 'complete' | 'partial';
  totalVotes: number;
  players: H2HBrownlowPlayer[];
};

/**
 * Match-level H2H Brownlow votes and their coverage.
 *
 * This is the ONLY feature in the module that reads
 * `player_match_stats.brownlow_votes`, and it is match-scoped reporting
 * only: season totals, season winners and career totals come from
 * `brownlow_season_votes` and are never derived here.
 *
 * The eligible population is home-and-away meetings only -- finals are
 * never polled, so they contribute neither votes nor a denominator.
 * Votes are reported from FULLY covered meetings alone, so the reported
 * total is exactly the total of the X in "Recorded H2H Brownlow votes
 * from X of Y eligible meetings"; a meeting with no data contributes no
 * votes and no zeros.
 */
export async function getHeadToHeadBrownlow(
  orgA: number,
  orgB: number,
): Promise<H2HBrownlow> {
  assertDistinct(orgA, orgB);

  /** Eligible meetings, each with its season coverage and recorded vote total. */
  const polled = sql`
    SELECT mt.id, mt.season,
           cov.coverage AS match_votes_coverage,
           COALESCE((
             SELECT sum(pms.brownlow_votes)
               FROM player_match_stats pms
              WHERE pms.match_id = mt.id
           ), 0)::int AS recorded_votes
      FROM (${h2hScope(orgA, orgB, 'home-and-away')}) mt
      LEFT JOIN (${statCoverage(BROWNLOW_MATCH_VOTES)}) cov ON cov.season = mt.season
  `;

  const [[counts], players] = await Promise.all([
    sql<{ eligibleMeetings: number; evaluableMeetings: number;
          coveredMeetings: number; partiallyPolledMeetings: number }[]>`
      WITH eligible AS (${polled})
      SELECT count(*)::int AS "eligibleMeetings",
             count(*) FILTER (
               WHERE e.match_votes_coverage IN ('complete', 'partial'))::int
               AS "evaluableMeetings",
             count(*) FILTER (
               WHERE e.match_votes_coverage IN ('complete', 'partial')
                 AND e.recorded_votes = ${FULLY_POLLED_MATCH_VOTES})::int
               AS "coveredMeetings",
             count(*) FILTER (
               WHERE e.recorded_votes > 0
                 AND e.recorded_votes <> ${FULLY_POLLED_MATCH_VOTES})::int
               AS "partiallyPolledMeetings"
        FROM eligible e
    `,
    sql<H2HBrownlowPlayer[]>`
      WITH eligible AS (${polled}),
      covered AS (
        SELECT e.id FROM eligible e
         WHERE e.match_votes_coverage IN ('complete', 'partial')
           AND e.recorded_votes = ${FULLY_POLLED_MATCH_VOTES}
      )
      SELECT pms.player_id AS "playerId",
             p.display_name AS "displayName", p.sort_name AS "sortName", p.slug,
             sum(pms.brownlow_votes)::int AS votes,
             count(*) FILTER (WHERE pms.brownlow_votes = 3)::int AS "threeVoteGames",
             count(*) FILTER (WHERE pms.brownlow_votes = 2)::int AS "twoVoteGames",
             count(*) FILTER (WHERE pms.brownlow_votes = 1)::int AS "oneVoteGames",
             count(*) FILTER (WHERE pms.brownlow_votes > 0)::int AS "pollingGames",
             COALESCE(sum(pms.brownlow_votes) FILTER (
               WHERE c.organization_id = ${orgA}), 0)::int AS "aVotes",
             COALESCE(sum(pms.brownlow_votes) FILTER (
               WHERE c.organization_id = ${orgB}), 0)::int AS "bVotes"
        FROM player_match_stats pms
        JOIN covered ON covered.id = pms.match_id
        JOIN players p ON p.id = pms.player_id
        JOIN clubs c ON c.id = pms.club_id
       WHERE pms.brownlow_votes IS NOT NULL
         AND c.organization_id IN (${orgA}, ${orgB})
       GROUP BY pms.player_id, p.display_name, p.sort_name, p.slug
      HAVING sum(pms.brownlow_votes) > 0
       ORDER BY votes DESC, p.sort_name, pms.player_id
    `,
  ]);

  return {
    eligibleMeetings: counts.eligibleMeetings,
    evaluableMeetings: counts.evaluableMeetings,
    coveredMeetings: counts.coveredMeetings,
    partiallyPolledMeetings: counts.partiallyPolledMeetings,
    coverage: counts.coveredMeetings === counts.eligibleMeetings ? 'complete' : 'partial',
    totalVotes: players.reduce((sum, p) => sum + p.votes, 0),
    players,
  };
}

// --- Selected season: canonical season discovery ---

/**
 * `seasons.status`. There are exactly two canonical states and the
 * application never infers a third from a year.
 */
export type SeasonStatus = 'in_progress' | 'complete';

/**
 * A canonical season as the compare surface needs it. Everything here is
 * read from the `seasons` row: nothing is computed from the calendar,
 * and there is no supported-year list anywhere in this module.
 */
export type ComparisonSeason = {
  season: number;
  competition: string;
  league: string;
  status: SeasonStatus;
  /** `seasons.is_complete`, which may lag `status`; both are surfaced. */
  isComplete: boolean;
  /** `status <> 'complete'` -- the flag a provisional badge renders from. */
  isProvisional: boolean;
  /** How far canonical data runs. Null until ingestion sets it. */
  dataThroughDate: Date | null;
  completedAt: Date | null;
  firstMatchDate: Date | null;
  lastMatchDate: Date | null;
  matchCount: number | null;
  clubCount: number | null;
};

/**
 * The season columns, aliased for the wire. `status` is cast to text so
 * the enum arrives as a plain string.
 */
const SEASON_COLUMNS = sql`
  s.year::int AS season, s.competition, s.league,
  s.status::text AS status,
  COALESCE(s.is_complete, false) AS "isComplete",
  (s.status <> 'complete') AS "isProvisional",
  s.data_through_date AS "dataThroughDate",
  s.completed_at AS "completedAt",
  s.first_match_date AS "firstMatchDate",
  s.last_match_date AS "lastMatchDate",
  s.match_count AS "matchCount",
  s.club_count AS "clubCount"
`;

/**
 * Every canonical season, newest first. This is the ONLY source of valid
 * seasons for the compare surface: a season exists because `seasons` has
 * a row, never because application code names it. A future season
 * becomes selectable the moment ingestion inserts its row.
 *
 * No competition or league predicate is applied, matching the existing
 * `statCoverage()` fragment and the rest of `src/db/queries`: `seasons`
 * is the AFL/VFL season ledger, and AFLW lives outside it.
 */
export async function getComparisonSeasons(): Promise<ComparisonSeason[]> {
  return sql<ComparisonSeason[]>`
    SELECT ${SEASON_COLUMNS} FROM seasons s ORDER BY s.year DESC
  `;
}

/**
 * The conceptual default: the maximum canonical season. Discovered, not
 * named. Null only if `seasons` is empty.
 */
export async function getMaximumComparisonSeason(): Promise<ComparisonSeason | null> {
  const [row] = await sql<ComparisonSeason[]>`
    SELECT ${SEASON_COLUMNS} FROM seasons s ORDER BY s.year DESC LIMIT 1
  `;
  return row ?? null;
}

/** Metadata for one selected season, or null when the season is not canonical. */
export async function getComparisonSeason(season: number): Promise<ComparisonSeason | null> {
  const [row] = await sql<ComparisonSeason[]>`
    SELECT ${SEASON_COLUMNS} FROM seasons s WHERE s.year = ${season}
  `;
  return row ?? null;
}

/**
 * Organisations with canonical participation in a season, at the
 * organisation grain the comparison aggregates on. Participation is
 * evidence -- a `club_seasons` row or a played match -- never a club
 * lifespan, so a season whose data has not been ingested yet honestly
 * returns nobody instead of the whole competition.
 */
export async function getSeasonParticipants(season: number): Promise<ComparisonOrganization[]> {
  return sql<ComparisonOrganization[]>`
    SELECT DISTINCT o.id, o.name, o.slug,
           o.first_season AS "firstSeason", o.last_season AS "lastSeason",
           o.is_active AS "isActive"
      FROM club_organizations o
      JOIN clubs c ON c.organization_id = o.id
     WHERE EXISTS (SELECT 1 FROM club_seasons cs
                    WHERE cs.club_id = c.id AND cs.season = ${season})
        OR EXISTS (SELECT 1 FROM matches m
                    WHERE m.season = ${season}
                      AND c.id IN (m.home_club_id, m.away_club_id))
     ORDER BY o.name
  `;
}

// --- Selected season: identity resolution ---

/**
 * The organisation's identity-at-season, plus whether it participated at
 * all. An organisation that did not play gets `participated: false` and
 * a null record everywhere downstream: no other season and no other
 * identity is ever substituted.
 */
export type ClubSeasonIdentity = {
  organizationId: number;
  organizationName: string;
  organizationSlug: string;
  season: number;
  /** `afldb_identity_for_season`. Null when the organisation did not exist. */
  clubId: number | null;
  clubName: string | null;
  clubSlug: string | null;
  participated: boolean;
  /** Canonical matches played by the organisation in the season, finals included. */
  matchesPlayed: number;
  /** `club_seasons` rows for the organisation in the season (normally 0 or 1). */
  ladderRows: number;
};

/**
 * Identity-at-season through the canonical
 * `afldb_identity_for_season(organization_id, season)` function. The
 * lineage rules stay in the database: nothing here knows that Kangaroos
 * sits inside North Melbourne's span or that Footscray became the
 * Western Bulldogs.
 *
 * The function resolves from club lifespans, so it can name an identity
 * for a season that has no data yet. Participation is therefore decided
 * separately, from canonical evidence.
 */
export async function getSeasonIdentity(
  organizationId: number,
  season: number,
): Promise<ClubSeasonIdentity | null> {
  const [row] = await sql<{
    organizationId: number; organizationName: string; organizationSlug: string;
    clubId: number | null; clubName: string | null; clubSlug: string | null;
    matchesPlayed: number; ladderRows: number;
  }[]>`
    SELECT o.id AS "organizationId", o.name AS "organizationName", o.slug AS "organizationSlug",
           c.id AS "clubId", c.name AS "clubName", c.slug AS "clubSlug",
           (SELECT count(*) FROM matches m
              JOIN clubs mc ON mc.id IN (m.home_club_id, m.away_club_id)
             WHERE m.season = ${season} AND mc.organization_id = o.id)::int AS "matchesPlayed",
           (SELECT count(*) FROM club_seasons cs
              JOIN clubs sc ON sc.id = cs.club_id
             WHERE cs.season = ${season} AND sc.organization_id = o.id)::int AS "ladderRows"
      FROM club_organizations o
      LEFT JOIN clubs c ON c.id = afldb_identity_for_season(o.id, ${season}::smallint)
     WHERE o.id = ${organizationId}
  `;
  if (!row) return null;
  return {
    ...row,
    season,
    participated: row.matchesPlayed > 0 || row.ladderRows > 0,
  };
}

// --- Selected season: home-and-away record ---

/**
 * The selected identity's `club_seasons` row. This is HOME-AND-AWAY
 * data: `played` excludes the finals series, which is carried separately
 * as `finalsPlayed`, and it is deliberately NOT the denominator the team
 * metric averages use.
 */
export type ClubSeasonRecord = {
  organizationId: number;
  season: number;
  clubId: number;
  clubName: string;
  clubSlug: string;
  played: number;
  wins: number;
  draws: number;
  losses: number;
  premiershipPoints: number | null;
  pointsFor: number;
  pointsAgainst: number;
  /** Canonical 100 x pointsFor / pointsAgainst. Null when the denominator is zero. */
  percentage: number | null;
  ladderRank: number | null;
  finalsPlayed: number | null;
  isPremier: boolean;
  woodenSpoon: boolean;
  /** 100 x (wins + 0.5 x draws) / played. Null when nothing was played. */
  winPercentage: number | null;
  averagePointsFor: number | null;
  averagePointsAgainst: number | null;
};

/**
 * The selected-season home-and-away record.
 *
 * Scoped by `clubs.organization_id`, exactly as the H2H layer is, so a
 * rename inside one organisation resolves without a TypeScript mapping.
 * Canonical data holds at most one `club_seasons` row per organisation
 * and season; the ordering makes the choice deterministic if that ever
 * stops being true.
 *
 * Null when the organisation has no row for that season -- never a
 * neighbouring season, never another identity, never a zeroed row.
 */
export async function getClubSeasonRecord(
  organizationId: number,
  season: number,
): Promise<ClubSeasonRecord | null> {
  const [row] = await sql<{
    clubId: number; clubName: string; clubSlug: string;
    played: number; wins: number; draws: number; losses: number;
    premiershipPoints: number | null; pointsFor: number; pointsAgainst: number;
    percentage: number | null; ladderRank: number | null; finalsPlayed: number | null;
    isPremier: boolean; woodenSpoon: boolean;
  }[]>`
    SELECT cs.club_id AS "clubId", c.name AS "clubName", c.slug AS "clubSlug",
           cs.played::int AS played, cs.wins::int AS wins,
           cs.draws::int AS draws, cs.losses::int AS losses,
           cs.premiership_points::int AS "premiershipPoints",
           cs.points_for::int AS "pointsFor", cs.points_against::int AS "pointsAgainst",
           cs.percentage::float8 AS percentage,
           cs.ladder_rank::int AS "ladderRank",
           cs.finals_played::int AS "finalsPlayed",
           cs.is_premier AS "isPremier", cs.wooden_spoon AS "woodenSpoon"
      FROM club_seasons cs
      JOIN clubs c ON c.id = cs.club_id
     WHERE cs.season = ${season} AND c.organization_id = ${organizationId}
     ORDER BY cs.played DESC, cs.club_id
     LIMIT 1
  `;
  if (!row) return null;
  const played = row.played;
  return {
    organizationId,
    season,
    ...row,
    winPercentage: winPercentage(row.wins, row.draws, played),
    averagePointsFor: played > 0 ? row.pointsFor / played : null,
    averagePointsAgainst: played > 0 ? row.pointsAgainst / played : null,
  };
}

// --- Selected season: team metrics ---

/**
 * The approved team stat families. This registry is STATIC on purpose
 * and carries three things only: the stat key coverage is recorded
 * under, the `player_match_stats` column, and a display label.
 *
 * It carries no season, no year range and no availability: availability
 * is read at request time from `stat_availability` through
 * `statCoverage()`. `marks_i50` coverage maps to
 * `player_match_stats.marks_inside_50`, and `inside50s` to `inside_50s`;
 * the two names differ in the canonical schema and neither is renamed
 * here.
 */
export type TeamMetricDefinition = {
  key: string;
  statKey: string;
  column: string;
  label: string;
};

export const TEAM_METRICS: TeamMetricDefinition[] = [
  { key: 'goals', statKey: 'goals', column: 'goals', label: 'Goals' },
  { key: 'behinds', statKey: 'behinds', column: 'behinds', label: 'Behinds' },
  { key: 'kicks', statKey: 'kicks', column: 'kicks', label: 'Kicks' },
  { key: 'handballs', statKey: 'handballs', column: 'handballs', label: 'Handballs' },
  { key: 'disposals', statKey: 'disposals', column: 'disposals', label: 'Disposals' },
  { key: 'marks', statKey: 'marks', column: 'marks', label: 'Marks' },
  { key: 'tackles', statKey: 'tackles', column: 'tackles', label: 'Tackles' },
  { key: 'hitouts', statKey: 'hitouts', column: 'hitouts', label: 'Hit-outs' },
  { key: 'rebounds', statKey: 'rebounds', column: 'rebounds', label: 'Rebound 50s' },
  { key: 'inside50s', statKey: 'inside50s', column: 'inside_50s', label: 'Inside 50s' },
  { key: 'clearances', statKey: 'clearances', column: 'clearances', label: 'Clearances' },
  { key: 'clangers', statKey: 'clangers', column: 'clangers', label: 'Clangers' },
  { key: 'frees_for', statKey: 'frees_for', column: 'frees_for', label: 'Frees for' },
  { key: 'frees_against', statKey: 'frees_against', column: 'frees_against', label: 'Frees against' },
  { key: 'contested', statKey: 'contested', column: 'contested', label: 'Contested possessions' },
  { key: 'uncontested', statKey: 'uncontested', column: 'uncontested', label: 'Uncontested possessions' },
  { key: 'contested_marks', statKey: 'contested_marks', column: 'contested_marks', label: 'Contested marks' },
  { key: 'marks_i50', statKey: 'marks_i50', column: 'marks_inside_50', label: 'Marks inside 50' },
  { key: 'one_percenters', statKey: 'one_percenters', column: 'one_percenters', label: 'One percenters' },
  { key: 'bounces', statKey: 'bounces', column: 'bounces', label: 'Bounces' },
  { key: 'goal_assists', statKey: 'goal_assists', column: 'goal_assists', label: 'Goal assists' },
];

/** One team stat family for one club-season, with its coverage state and denominators. */
export type ClubSeasonTeamMetric = {
  key: string;
  statKey: string;
  label: string;
  /** Runtime `stat_availability` state for this statistic and season. */
  coverage: MetricCoverage;
  /**
   * True only when coverage permits a number AND at least one team-match
   * is eligible. When false, `average` and `total` are null: an
   * uncollected or unplayed statistic is never rendered as zero.
   */
  isAvailable: boolean;
  /** Coverage is `partial`: the average is over recorded matches only. */
  isPartial: boolean;
  isPending: boolean;
  isNotApplicable: boolean;
  /** Average of eligible team-match totals. Never an average of player rows. */
  average: number | null;
  /** Sum over eligible team-matches. Null whenever `average` is null. */
  total: number | null;
  /** Team-matches whose player rows are all non-NULL for this statistic. */
  eligibleMatches: number;
  /** Every canonical team-match in the season, finals included. */
  totalTeamMatches: number;
  /**
   * The metric is presentable but its eligible denominator is short of
   * the team-match total. Preserved for UI disclosure even when coverage
   * is `complete`, because a complete season can still be missing a
   * match's player rows. False for an unavailable metric, where the
   * empty denominator is the unavailability, not a discrepancy.
   */
  hasDenominatorDiscrepancy: boolean;
};

export type ClubSeasonTeamMetrics = {
  organizationId: number;
  season: number;
  participated: boolean;
  /** Canonical matches for the organisation in the season, finals included. */
  totalTeamMatches: number;
  metrics: ClubSeasonTeamMetric[];
};

const metricNullsAlias = (key: string) => `${key}__nulls`;
const metricSumAlias = (key: string) => `${key}__sum`;
const metricEligibleAlias = (key: string) => `${key}__eligible`;
const metricAverageAlias = (key: string) => `${key}__average`;
const metricTotalAlias = (key: string) => `${key}__total`;

/**
 * Per team-match, for every metric: how many player rows are NULL, and
 * the team total. The NULL count is what makes eligibility decidable --
 * `sum()` alone cannot tell "nobody recorded it" from "everyone recorded
 * zero".
 */
function teamMetricPerMatchColumns() {
  return TEAM_METRICS.reduce(
    (acc, m) => sql`${acc},
           count(*) FILTER (WHERE p.${sql(m.column)} IS NULL)::int AS ${sql(metricNullsAlias(m.key))},
           sum(p.${sql(m.column)})::float8 AS ${sql(metricSumAlias(m.key))}`,
    sql``,
  );
}

/** Average and sum of ELIGIBLE team-match totals, plus the eligible denominator. */
function teamMetricAggregateColumns() {
  return TEAM_METRICS.reduce(
    (acc, m) => sql`${acc},
           count(*) FILTER (WHERE pm.${sql(metricNullsAlias(m.key))} = 0)::int
             AS ${sql(metricEligibleAlias(m.key))},
           (avg(pm.${sql(metricSumAlias(m.key))})
             FILTER (WHERE pm.${sql(metricNullsAlias(m.key))} = 0))::float8
             AS ${sql(metricAverageAlias(m.key))},
           (sum(pm.${sql(metricSumAlias(m.key))})
             FILTER (WHERE pm.${sql(metricNullsAlias(m.key))} = 0))::float8
             AS ${sql(metricTotalAlias(m.key))}`,
    sql``,
  );
}

/**
 * Selected-season team statistics at the contracted grain:
 *
 *   organisation -> selected-season identity -> match/club -> sum player
 *   stat values -> average eligible team-match totals
 *
 * Player rows are NEVER averaged directly. The match population is every
 * canonical match the organisation played in the season, finals
 * included, which is why the denominator is reported separately from the
 * home-and-away record.
 *
 * A team-match is eligible for a metric only when player rows exist for
 * it AND every present row has a non-NULL value. A missing row and a
 * recorded zero are therefore never conflated, and an ineligible
 * team-match contributes neither a value nor a zero.
 *
 * Availability comes from `statCoverage()` at request time. Nothing here
 * branches on the season.
 */
export async function getClubSeasonTeamMetrics(
  organizationId: number,
  season: number,
): Promise<ClubSeasonTeamMetrics> {
  const [[totals], coverageRows] = await Promise.all([
    sql<Record<string, number | null>[]>`
      WITH team_matches AS (
        SELECT m.id AS match_id, c.id AS club_id
          FROM matches m
          JOIN clubs c ON c.id IN (m.home_club_id, m.away_club_id)
         WHERE m.season = ${season} AND c.organization_id = ${organizationId}
      ),
      per_match AS (
        SELECT tm.match_id
               ${teamMetricPerMatchColumns()}
          FROM team_matches tm
          JOIN player_match_stats p
            ON p.match_id = tm.match_id AND p.club_id = tm.club_id
         GROUP BY tm.match_id
      )
      SELECT (SELECT count(*) FROM team_matches)::int AS "totalTeamMatches"
             ${teamMetricAggregateColumns()}
        FROM per_match pm
    `,
    sql<{ statKey: string; coverage: MetricCoverage }[]>`
      SELECT cov.stat_key AS "statKey", cov.coverage
        FROM (${statCoverage(TEAM_METRICS.map((m) => m.statKey))}) cov
       WHERE cov.season = ${season}
    `,
  ]);

  const coverageByKey = new Map(coverageRows.map((r) => [r.statKey, r.coverage]));
  const totalTeamMatches = Number(totals?.totalTeamMatches ?? 0);

  const metrics = TEAM_METRICS.map((m): ClubSeasonTeamMetric => {
    // No coverage row at all for this statistic and season -- including a
    // season with no `seasons` row -- fails safely as unavailable.
    const coverage: MetricCoverage = coverageByKey.get(m.statKey) ?? 'missing';
    const eligibleMatches = Number(totals?.[metricEligibleAlias(m.key)] ?? 0);
    const presentable = coverage === 'complete' || coverage === 'partial';
    const isAvailable = presentable && eligibleMatches > 0;
    const average = totals?.[metricAverageAlias(m.key)];
    const total = totals?.[metricTotalAlias(m.key)];
    return {
      key: m.key,
      statKey: m.statKey,
      label: m.label,
      coverage,
      isAvailable,
      isPartial: coverage === 'partial',
      isPending: coverage === 'pending',
      isNotApplicable: coverage === 'not_applicable',
      average: isAvailable && average !== null && average !== undefined ? Number(average) : null,
      total: isAvailable && total !== null && total !== undefined ? Number(total) : null,
      eligibleMatches,
      totalTeamMatches,
      hasDenominatorDiscrepancy: isAvailable && eligibleMatches !== totalTeamMatches,
    };
  });

  return {
    organizationId,
    season,
    participated: totalTeamMatches > 0,
    totalTeamMatches,
    metrics,
  };
}

// --- Selected season: player leaders ---

/**
 * Dense-rank cut for selected-season leaderboards. Every tie at the cut
 * is retained, so a board may return more than five rows -- in a modern
 * season the games board routinely does.
 */
export const CLUB_SEASON_LEADER_RANK_LIMIT = 5;

export type ClubSeasonLeader = {
  rank: number;
  playerId: number;
  displayName: string;
  sortName: string;
  slug: string;
  value: number;
  /**
   * Matches in which the statistic was actually recorded, where the
   * canonical table carries one. Null for boards that have no such
   * denominator (games, goals).
   */
  recordedGames: number | null;
};

export type ClubSeasonPlayerLeaders = {
  organizationId: number;
  season: number;
  participated: boolean;
  games: ClubSeasonLeader[];
  goals: ClubSeasonLeader[];
  disposals: ClubSeasonLeader[];
  /** Runtime coverage for the goals board. */
  goalsCoverage: MetricCoverage;
  goalsAvailable: boolean;
  /** Runtime coverage for the disposals board. */
  disposalsCoverage: MetricCoverage;
  disposalsAvailable: boolean;
};

/**
 * One dense-ranked leaderboard over `player_club_season_stats`, summed
 * across every identity of the organisation active in the season, so a
 * mid-season rename could not split a player's total.
 *
 * Only players with a recorded, positive value appear: a NULL total is
 * not a zero, and a zero is not a leader.
 */
async function clubSeasonLeaderBoard(
  organizationId: number,
  season: number,
  valueColumn: string,
  recordedColumn: string | null,
): Promise<ClubSeasonLeader[]> {
  return sql<ClubSeasonLeader[]>`
    WITH totals AS (
      SELECT pcs.player_id,
             sum(pcs.games)::int AS games,
             sum(pcs.goals)::int AS goals,
             sum(pcs.disposals)::int AS disposals,
             sum(pcs.disposals_recorded_games)::int AS disposals_recorded_games
        FROM player_club_season_stats pcs
        JOIN clubs c ON c.id = pcs.club_id
       WHERE pcs.season = ${season} AND c.organization_id = ${organizationId}
       GROUP BY pcs.player_id
    ),
    scored AS (
      SELECT t.* FROM totals t
       WHERE t.${sql(valueColumn)} IS NOT NULL AND t.${sql(valueColumn)} > 0
    ),
    ranked AS (
      SELECT s.*, dense_rank() OVER (ORDER BY s.${sql(valueColumn)} DESC) AS rank
        FROM scored s
    )
    SELECT r.rank::int AS rank, r.player_id AS "playerId",
           p.display_name AS "displayName", p.sort_name AS "sortName", p.slug,
           r.${sql(valueColumn)}::int AS value,
           ${recordedColumn === null ? sql`NULL::int` : sql`r.${sql(recordedColumn)}::int`}
             AS "recordedGames"
      FROM ranked r
      JOIN players p ON p.id = r.player_id
     WHERE r.rank <= ${CLUB_SEASON_LEADER_RANK_LIMIT}
     ORDER BY r.rank, p.sort_name, r.player_id
  `;
}

/**
 * Selected-season player leaders for games, goals and disposals.
 *
 * Games and goals cover all season matches. Disposals are shown only
 * when runtime coverage permits, and always with their recorded-game
 * denominator, because a partly recorded season's totals are not
 * comparable with a fully recorded one's.
 *
 * If the organisation did not participate, every board is empty. No
 * other season and no other identity is ever borrowed.
 */
export async function getClubSeasonPlayerLeaders(
  organizationId: number,
  season: number,
): Promise<ClubSeasonPlayerLeaders> {
  const coverageRows = await sql<{ statKey: string; coverage: MetricCoverage }[]>`
    SELECT cov.stat_key AS "statKey", cov.coverage
      FROM (${statCoverage(['goals', 'disposals'])}) cov
     WHERE cov.season = ${season}
  `;
  const coverageByKey = new Map(coverageRows.map((r) => [r.statKey, r.coverage]));
  const goalsCoverage: MetricCoverage = coverageByKey.get('goals') ?? 'missing';
  const disposalsCoverage: MetricCoverage = coverageByKey.get('disposals') ?? 'missing';
  const goalsAvailable = goalsCoverage === 'complete' || goalsCoverage === 'partial';
  const disposalsAvailable = disposalsCoverage === 'complete' || disposalsCoverage === 'partial';

  const [games, goals, disposals] = await Promise.all([
    clubSeasonLeaderBoard(organizationId, season, 'games', null),
    goalsAvailable
      ? clubSeasonLeaderBoard(organizationId, season, 'goals', null)
      : Promise.resolve([] as ClubSeasonLeader[]),
    disposalsAvailable
      ? clubSeasonLeaderBoard(organizationId, season, 'disposals', 'disposals_recorded_games')
      : Promise.resolve([] as ClubSeasonLeader[]),
  ]);

  return {
    organizationId,
    season,
    participated: games.length > 0,
    games,
    goals,
    disposals,
    goalsCoverage,
    goalsAvailable,
    disposalsCoverage,
    disposalsAvailable,
  };
}

// --- Selected season: whole comparison side ---

/**
 * Everything the compare surface needs about ONE organisation in ONE
 * season. Composed from the focused queries above plus the Stage 3
 * Brownlow primitive, so no semantics are duplicated here.
 */
export type ClubSeasonComparison = {
  season: number;
  /** Canonical season metadata, or null when the season is not canonical. */
  seasonMeta: ComparisonSeason | null;
  identity: ClubSeasonIdentity | null;
  /** True only when canonical evidence shows the organisation played. */
  participated: boolean;
  record: ClubSeasonRecord | null;
  teamMetrics: ClubSeasonTeamMetrics;
  leaders: ClubSeasonPlayerLeaders;
  brownlow: ClubSeasonBrownlowSummary;
};

/**
 * The complete selected-season path for one organisation. Season state,
 * identity, record, metric coverage and Brownlow state all come from
 * canonical rows read at request time: a season turning from
 * `in_progress` to `complete`, or Brownlow coverage from `pending` to
 * `complete`, changes the answer with no release.
 */
export async function getClubSeasonComparison(
  organizationId: number,
  season: number,
): Promise<ClubSeasonComparison> {
  const [seasonMeta, identity, record, teamMetrics, leaders, brownlow] = await Promise.all([
    getComparisonSeason(season),
    getSeasonIdentity(organizationId, season),
    getClubSeasonRecord(organizationId, season),
    getClubSeasonTeamMetrics(organizationId, season),
    getClubSeasonPlayerLeaders(organizationId, season),
    getClubSeasonBrownlowSummary(organizationId, season),
  ]);

  return {
    season,
    seasonMeta,
    identity,
    participated: identity?.participated ?? false,
    record,
    teamMetrics,
    leaders,
    brownlow,
  };
}

// =====================================================================
// Stage 6 -- Extended rivalry analytics
// =====================================================================

// --- H2H by decade ---

/**
 * One decade of a rivalry. Decades are DISCOVERED from the canonical
 * meeting population -- `season - mod(season, 10)` -- never enumerated
 * from a list and never bounded by a "current era". A decade in which
 * the pair never met simply has no row; it is never rendered as a zero
 * row, which would invent a meeting-less decade for every pair whose
 * organisations did not co-exist.
 */
export type H2HDecade = {
  /** The decade's first season: 1990 for the 1990s. */
  decade: number;
  meetings: number;
  aWins: number;
  bWins: number;
  draws: number;
  /** Half-draw formula, `100 * (wins + 0.5 * draws) / meetings`. */
  aWinPercentage: number | null;
  bWinPercentage: number | null;
  /**
   * Points are summed over meetings with a recorded score only, and are
   * null when the decade has none: an unscored meeting is not nil-all.
   * `scoredMeetings` is the honest denominator behind all four totals.
   */
  scoredMeetings: number;
  aPointsFor: number | null;
  aPointsAgainst: number | null;
  bPointsFor: number | null;
  bPointsAgainst: number | null;
};

/**
 * The rivalry by decade, over the Stage 1 pair scope and nothing else.
 * `aPointsAgainst` is `bPointsFor` by construction and is returned
 * anyway, because a UI reading one organisation's row should not have to
 * reach into the other's to render "for and against".
 *
 * Ordering is ascending by decade, so the result reads as a timeline.
 */
export async function getHeadToHeadByDecade(orgA: number, orgB: number): Promise<H2HDecade[]> {
  assertDistinct(orgA, orgB);
  const rows = await sql<{
    decade: number; meetings: number; aWins: number; bWins: number; draws: number;
    scoredMeetings: number; aPointsFor: number | null; bPointsFor: number | null;
  }[]>`
    WITH meetings AS (${h2hScope(orgA, orgB)})
    SELECT (season - mod(season, 10))::int AS decade,
           count(*)::int AS meetings,
           count(*) FILTER (WHERE outcome = 'a-win')::int AS "aWins",
           count(*) FILTER (WHERE outcome = 'b-win')::int AS "bWins",
           count(*) FILTER (WHERE outcome = 'draw')::int AS draws,
           count(*) FILTER (WHERE a_score IS NOT NULL AND b_score IS NOT NULL)::int
             AS "scoredMeetings",
           sum(a_score)::int AS "aPointsFor",
           sum(b_score)::int AS "bPointsFor"
      FROM meetings
     GROUP BY 1
     ORDER BY 1
  `;

  return rows.map((row) => ({
    decade: row.decade,
    meetings: row.meetings,
    aWins: row.aWins,
    bWins: row.bWins,
    draws: row.draws,
    aWinPercentage: winPercentage(row.aWins, row.draws, row.meetings),
    bWinPercentage: winPercentage(row.bWins, row.draws, row.meetings),
    scoredMeetings: row.scoredMeetings,
    aPointsFor: row.aPointsFor,
    aPointsAgainst: row.bPointsFor,
    bPointsFor: row.bPointsFor,
    bPointsAgainst: row.aPointsFor,
  }));
}

// --- Period-score rivalry records ---

/**
 * `match_period_scores` semantics, VERIFIED against the canonical schema
 * and data rather than assumed (migration 003:98, migration 076:100-103):
 *
 *   - `points` is the CUMULATIVE score at the end of the period, "as
 *     published". No row in `afldb_test` decreases from one period to
 *     the next, which is what cumulative means.
 *   - Periods 1-4 are quarters. The CHECK allows 1-8, and the historical
 *     importer deliberately imports no extra-time period, so a match
 *     that went to extra time carries period 4 = END OF REGULATION.
 *   - Three matches in `afldb_test` prove exactly that: 10795 (1994 QF),
 *     13203 (2007 SF) and 15194 (2017 EF) have a period-4 total below
 *     their canonical final score.
 *
 * Period 4 is therefore NEVER read as the final score here. Quarter
 * time, half time and three-quarter time come from periods 1, 2 and 3;
 * full time comes from the canonical `matches` score and
 * `matches.winner_club_id`, through the Stage 1 scope's `a_score`,
 * `b_score` and `outcome`.
 *
 * There is no `stat_availability` key for period scores -- the runtime
 * coverage table carries the player statistic families and the Brownlow
 * only -- so completeness cannot be read through `statCoverage()`, and a
 * coverage column is NOT invented in the schema for it. The V1 contract
 * is decided from canonical rows alone: see `getHeadToHeadPeriodRecords`.
 */
export type H2HTurnaroundSegment =
  | 'quarter-time-to-half-time'
  | 'half-time-to-three-quarter-time'
  | 'three-quarter-time-to-full-time';

export type H2HPeriodRecordKind =
  | 'biggest-quarter-time-lead-a'
  | 'biggest-quarter-time-lead-b'
  | 'biggest-half-time-lead-a'
  | 'biggest-half-time-lead-b'
  | 'biggest-three-quarter-time-lead-a'
  | 'biggest-three-quarter-time-lead-b'
  | 'biggest-comeback-from-quarter-time-a'
  | 'biggest-comeback-from-quarter-time-b'
  | 'biggest-comeback-from-half-time-a'
  | 'biggest-comeback-from-half-time-b'
  | 'biggest-comeback-from-three-quarter-time-a'
  | 'biggest-comeback-from-three-quarter-time-b'
  | 'largest-turnaround-a'
  | 'largest-turnaround-b';

const PERIOD_RECORD_KINDS: H2HPeriodRecordKind[] = [
  'biggest-quarter-time-lead-a', 'biggest-quarter-time-lead-b',
  'biggest-half-time-lead-a', 'biggest-half-time-lead-b',
  'biggest-three-quarter-time-lead-a', 'biggest-three-quarter-time-lead-b',
  'biggest-comeback-from-quarter-time-a', 'biggest-comeback-from-quarter-time-b',
  'biggest-comeback-from-half-time-a', 'biggest-comeback-from-half-time-b',
  'biggest-comeback-from-three-quarter-time-a', 'biggest-comeback-from-three-quarter-time-b',
  'largest-turnaround-a', 'largest-turnaround-b',
];

/**
 * A period record-holding meeting: the full meeting (so a route can link
 * it without a second query), the value it holds, the three cumulative
 * break scores for both organisations, and -- for a turnaround only --
 * the segment the swing happened in.
 */
export type H2HPeriodRecordEntry = H2HMeeting & {
  value: number;
  segment: H2HTurnaroundSegment | null;
  aQuarterTime: number;
  aHalfTime: number;
  aThreeQuarterTime: number;
  bQuarterTime: number;
  bHalfTime: number;
  bThreeQuarterTime: number;
};

/** `complete` only when EVERY meeting is usable; `none` when none is. */
export type H2HPeriodCoverageState = 'complete' | 'partial' | 'none';

/**
 * Pair-level period-score coverage, so a caller can always state
 * "Period-score data available for X of Y rivalry meetings" -- even
 * while every measured pair in `afldb_test` happens to be complete.
 * Present completeness is evidence, never a contract.
 *
 * `meetingsWithPeriodRows` is the weak "has any period row" test;
 * `usableMeetings` is the one the records actually run on.
 */
export type H2HPeriodCoverage = {
  /** Every meeting in the Stage 1 pair scope. */
  meetings: number;
  /** Meetings carrying at least one `match_period_scores` row. */
  meetingsWithPeriodRows: number;
  /** Meetings satisfying the full usability contract. */
  usableMeetings: number;
  /** `meetings - usableMeetings`: missing or incomplete. */
  incompleteMeetings: number;
  state: H2HPeriodCoverageState;
};

export type H2HPeriodRecords = {
  coverage: H2HPeriodCoverage;
  records: Record<H2HPeriodRecordKind, H2HPeriodRecordEntry[]>;
};

type PeriodRecordRow = H2HPeriodRecordEntry & { kind: H2HPeriodRecordKind };

/**
 * The three cumulative break totals per meeting, per organisation, from
 * canonical `match_period_scores`. NULL for any break either
 * organisation has no recorded `points` at -- which is precisely what
 * makes incompleteness decidable rather than silently zero.
 *
 * The pair's two organisations are distinct (`assertDistinct`), and a
 * period row's club is always one of the match's two participants, so
 * each `FILTER` selects at most one row and `max()` is a picker, not an
 * aggregate over rivals.
 */
function h2hPeriodBreaks(orgA: number, orgB: number) {
  return sql`
    SELECT mt.id,
           max(ps.points) FILTER (WHERE c.organization_id = ${orgA} AND ps.period = 1)::int AS a1,
           max(ps.points) FILTER (WHERE c.organization_id = ${orgA} AND ps.period = 2)::int AS a2,
           max(ps.points) FILTER (WHERE c.organization_id = ${orgA} AND ps.period = 3)::int AS a3,
           max(ps.points) FILTER (WHERE c.organization_id = ${orgB} AND ps.period = 1)::int AS b1,
           max(ps.points) FILTER (WHERE c.organization_id = ${orgB} AND ps.period = 2)::int AS b2,
           max(ps.points) FILTER (WHERE c.organization_id = ${orgB} AND ps.period = 3)::int AS b3
      FROM meetings mt
      JOIN match_period_scores ps ON ps.match_id = mt.id
      JOIN clubs c ON c.id = ps.club_id
     WHERE ps.period BETWEEN 1 AND 3
       AND ps.points IS NOT NULL
       AND c.organization_id IN (${orgA}, ${orgB})
     GROUP BY mt.id
  `;
}

/**
 * THE usability predicate, applied identically by the coverage count and
 * by the records, so the denominator a caller renders is exactly the
 * population the records were drawn from.
 */
const PERIOD_USABLE_PREDICATE = sql`
  b.a1 IS NOT NULL AND b.a2 IS NOT NULL AND b.a3 IS NOT NULL
  AND b.b1 IS NOT NULL AND b.b2 IS NOT NULL AND b.b3 IS NOT NULL
  AND mt.a_score IS NOT NULL AND mt.b_score IS NOT NULL
`;

/**
 * Period-score rivalry records over the Stage 1 pair scope.
 *
 * THE USABILITY CONTRACT. A meeting is usable only when, from canonical
 * rows alone:
 *
 *   1. both organisations have a non-NULL cumulative `points` at period
 *      1, period 2 AND period 3 -- the three breaks every record below
 *      is defined at; and
 *   2. the meeting has canonical final scores for both organisations,
 *      which is where full time comes from.
 *
 * A meeting satisfying only part of that is INCOMPLETE and contributes
 * nothing: a missing period row is never read as nought, so a half-
 * populated match can neither hold nor dilute a record. Period 4 is
 * deliberately not required, because nothing here reads it.
 *
 * RECORD DEFINITIONS, each from the named organisation's perspective and
 * each strictly positive, so a level break is neither a "lead" nor a
 * "comeback":
 *
 *   - biggest lead at a break: max(own cumulative - other cumulative) at
 *     period 1 / 2 / 3 over usable meetings where that is > 0.
 *   - biggest comeback from a break: the organisation TRAILED at that
 *     break (other - own > 0) AND won the match on the canonical result.
 *     A drawn match is never a comeback win. Ranked by largest deficit
 *     overcome.
 *   - largest turnaround between consecutive breaks: with margin
 *     `M(t) = own - other` at t in {QT, HT, 3QT, FT}, the largest value
 *     of `M(t+1) - M(t)` over the three consecutive pairs QT->HT,
 *     HT->3QT and 3QT->FT, over all usable meetings, where it is > 0. FT
 *     is the canonical final score, never period 4. The winning entry
 *     names its `segment`. No subjective label is applied.
 *
 * Every tied witness is returned, ordered by meeting date, season then
 * match id, exactly as the Stage 1 records are.
 */
export async function getHeadToHeadPeriodRecords(
  orgA: number,
  orgB: number,
): Promise<H2HPeriodRecords> {
  assertDistinct(orgA, orgB);

  const [[counts], rows] = await Promise.all([
    sql<{ meetings: number; meetingsWithPeriodRows: number; usableMeetings: number }[]>`
      WITH meetings AS (${h2hScope(orgA, orgB)}),
      breaks AS (${h2hPeriodBreaks(orgA, orgB)})
      SELECT (SELECT count(*) FROM meetings)::int AS "meetings",
             (SELECT count(*) FROM meetings mt
               WHERE EXISTS (SELECT 1 FROM match_period_scores ps
                              WHERE ps.match_id = mt.id))::int AS "meetingsWithPeriodRows",
             (SELECT count(*) FROM meetings mt
                JOIN breaks b ON b.id = mt.id
               WHERE ${PERIOD_USABLE_PREDICATE})::int AS "usableMeetings"
    `,
    sql<PeriodRecordRow[]>`
      WITH meetings AS (${h2hScope(orgA, orgB)}),
      breaks AS (${h2hPeriodBreaks(orgA, orgB)}),
      usable AS (
        SELECT mt.*, b.a1, b.a2, b.a3, b.b1, b.b2, b.b3
          FROM meetings mt
          JOIN breaks b ON b.id = mt.id
         WHERE ${PERIOD_USABLE_PREDICATE}
      ),
      swings AS (
        SELECT id, 'quarter-time-to-half-time'::text AS segment,
               ((a2 - b2) - (a1 - b1))::int AS a_swing,
               ((b2 - a2) - (b1 - a1))::int AS b_swing
          FROM usable
        UNION ALL
        SELECT id, 'half-time-to-three-quarter-time',
               ((a3 - b3) - (a2 - b2))::int, ((b3 - a3) - (b2 - a2))::int
          FROM usable
        UNION ALL
        SELECT id, 'three-quarter-time-to-full-time',
               ((a_score - b_score) - (a3 - b3))::int,
               ((b_score - a_score) - (b3 - a3))::int
          FROM usable
      ),
      picks AS (
        SELECT 'biggest-quarter-time-lead-a'::text AS kind, id,
               (a1 - b1)::int AS value, NULL::text AS segment
          FROM usable WHERE a1 > b1
           AND a1 - b1 = (SELECT max(a1 - b1) FROM usable WHERE a1 > b1)
        UNION ALL
        SELECT 'biggest-quarter-time-lead-b', id, (b1 - a1)::int, NULL
          FROM usable WHERE b1 > a1
           AND b1 - a1 = (SELECT max(b1 - a1) FROM usable WHERE b1 > a1)
        UNION ALL
        SELECT 'biggest-half-time-lead-a', id, (a2 - b2)::int, NULL
          FROM usable WHERE a2 > b2
           AND a2 - b2 = (SELECT max(a2 - b2) FROM usable WHERE a2 > b2)
        UNION ALL
        SELECT 'biggest-half-time-lead-b', id, (b2 - a2)::int, NULL
          FROM usable WHERE b2 > a2
           AND b2 - a2 = (SELECT max(b2 - a2) FROM usable WHERE b2 > a2)
        UNION ALL
        SELECT 'biggest-three-quarter-time-lead-a', id, (a3 - b3)::int, NULL
          FROM usable WHERE a3 > b3
           AND a3 - b3 = (SELECT max(a3 - b3) FROM usable WHERE a3 > b3)
        UNION ALL
        SELECT 'biggest-three-quarter-time-lead-b', id, (b3 - a3)::int, NULL
          FROM usable WHERE b3 > a3
           AND b3 - a3 = (SELECT max(b3 - a3) FROM usable WHERE b3 > a3)
        UNION ALL
        SELECT 'biggest-comeback-from-quarter-time-a', id, (b1 - a1)::int, NULL
          FROM usable WHERE outcome = 'a-win' AND b1 > a1
           AND b1 - a1 = (SELECT max(b1 - a1) FROM usable WHERE outcome = 'a-win' AND b1 > a1)
        UNION ALL
        SELECT 'biggest-comeback-from-quarter-time-b', id, (a1 - b1)::int, NULL
          FROM usable WHERE outcome = 'b-win' AND a1 > b1
           AND a1 - b1 = (SELECT max(a1 - b1) FROM usable WHERE outcome = 'b-win' AND a1 > b1)
        UNION ALL
        SELECT 'biggest-comeback-from-half-time-a', id, (b2 - a2)::int, NULL
          FROM usable WHERE outcome = 'a-win' AND b2 > a2
           AND b2 - a2 = (SELECT max(b2 - a2) FROM usable WHERE outcome = 'a-win' AND b2 > a2)
        UNION ALL
        SELECT 'biggest-comeback-from-half-time-b', id, (a2 - b2)::int, NULL
          FROM usable WHERE outcome = 'b-win' AND a2 > b2
           AND a2 - b2 = (SELECT max(a2 - b2) FROM usable WHERE outcome = 'b-win' AND a2 > b2)
        UNION ALL
        SELECT 'biggest-comeback-from-three-quarter-time-a', id, (b3 - a3)::int, NULL
          FROM usable WHERE outcome = 'a-win' AND b3 > a3
           AND b3 - a3 = (SELECT max(b3 - a3) FROM usable WHERE outcome = 'a-win' AND b3 > a3)
        UNION ALL
        SELECT 'biggest-comeback-from-three-quarter-time-b', id, (a3 - b3)::int, NULL
          FROM usable WHERE outcome = 'b-win' AND a3 > b3
           AND a3 - b3 = (SELECT max(a3 - b3) FROM usable WHERE outcome = 'b-win' AND a3 > b3)
        UNION ALL
        SELECT 'largest-turnaround-a', id, a_swing, segment
          FROM swings WHERE a_swing > 0
           AND a_swing = (SELECT max(a_swing) FROM swings WHERE a_swing > 0)
        UNION ALL
        SELECT 'largest-turnaround-b', id, b_swing, segment
          FROM swings WHERE b_swing > 0
           AND b_swing = (SELECT max(b_swing) FROM swings WHERE b_swing > 0)
      )
      SELECT p.kind, p.value, p.segment, ${MEETING_COLUMNS},
             m.a1 AS "aQuarterTime", m.a2 AS "aHalfTime", m.a3 AS "aThreeQuarterTime",
             m.b1 AS "bQuarterTime", m.b2 AS "bHalfTime", m.b3 AS "bThreeQuarterTime"
        FROM picks p
        JOIN usable m ON m.id = p.id
       ORDER BY p.kind, m.match_date, m.season, m.id, p.segment
    `,
  ]);

  const meetings = Number(counts?.meetings ?? 0);
  const usableMeetings = Number(counts?.usableMeetings ?? 0);
  const state: H2HPeriodCoverageState =
    usableMeetings === 0
      ? 'none'
      : usableMeetings === meetings
        ? 'complete'
        : 'partial';

  const records = Object.fromEntries(
    PERIOD_RECORD_KINDS.map((kind) => [kind, [] as H2HPeriodRecordEntry[]]),
  ) as Record<H2HPeriodRecordKind, H2HPeriodRecordEntry[]>;
  for (const row of rows) {
    const { kind, ...entry } = row;
    records[kind].push(entry);
  }

  return {
    coverage: {
      meetings,
      meetingsWithPeriodRows: Number(counts?.meetingsWithPeriodRows ?? 0),
      usableMeetings,
      incompleteMeetings: meetings - usableMeetings,
      state,
    },
    records,
  };
}

// --- H2H player averages ---

/**
 * A player qualifies for a metric's average board only with at least
 * this many H2H games in which THAT metric was actually recorded. The
 * threshold is metric-specific by construction: twelve rivalry games
 * with four recorded disposal rows is not a disposals average.
 */
export const H2H_AVERAGE_MINIMUM_RECORDED_GAMES = 5;

/** Dense-rank cut for every average board. Ties at the cut are retained. */
export const H2H_AVERAGE_RANK_LIMIT = 10;

/**
 * The average boards are a SUBSET of the existing `TEAM_METRICS`
 * registry -- the same static rows, filtered, never a second registry
 * and never a year-based one. `behinds`, `frees_for` and `frees_against`
 * are the three families the approved V1.7 average list omits.
 */
const H2H_AVERAGE_METRIC_KEYS = new Set([
  'goals', 'disposals', 'kicks', 'handballs', 'marks', 'tackles', 'hitouts',
  'rebounds', 'inside50s', 'clearances', 'clangers', 'contested', 'uncontested',
  'contested_marks', 'marks_i50', 'one_percenters', 'bounces', 'goal_assists',
]);

export const H2H_AVERAGE_METRICS: TeamMetricDefinition[] =
  TEAM_METRICS.filter((m) => H2H_AVERAGE_METRIC_KEYS.has(m.key));

/**
 * One organisation's share of a player's board row. Null total and
 * average when the player recorded the metric for that organisation in
 * no meeting at all -- a player who only ever faced the rivalry from one
 * side has nothing on the other, which is not a nought average.
 */
export type H2HAverageContribution = {
  recordedGames: number;
  total: number | null;
  average: number | null;
};

export type H2HAverageLeader = {
  /** Dense rank, 1-based, ties sharing a rank. */
  rank: number;
  playerId: number;
  displayName: string;
  sortName: string;
  slug: string;
  /** THE denominator: H2H games in which this metric was recorded. */
  recordedGames: number;
  total: number;
  average: number;
  a: H2HAverageContribution;
  b: H2HAverageContribution;
};

export type H2HAverageBoard = {
  key: string;
  statKey: string;
  label: string;
  /**
   * Rivalry seasons whose runtime `stat_availability` coverage is
   * `complete` or `partial`, and the count that is not. Both are
   * discovered at request time from the rivalry's own seasons; no year
   * appears anywhere in this module.
   */
  rivalrySeasons: number;
  coveredSeasons: number;
  uncoveredSeasons: number;
  /** Per-coverage-state season counts, for UI disclosure. */
  seasonsByCoverage: Record<MetricCoverage, number>;
  /** At least one rivalry season permits the metric to be presented. */
  isAvailable: boolean;
  /**
   * The metric is presentable but does not cover the whole rivalry, so a
   * UI must not imply era-wide comparability.
   */
  hasCoverageGap: boolean;
  minimumRecordedGames: number;
  leaders: H2HAverageLeader[];
};

export type H2HPlayerAverages = {
  meetings: number;
  /** Distinct seasons the pair met in. */
  rivalrySeasons: number;
  minimumRecordedGames: number;
  rankLimit: number;
  boards: H2HAverageBoard[];
};

type H2HAverageRow = {
  metricKey: string;
  rank: number;
  playerId: number;
  displayName: string;
  sortName: string;
  slug: string;
  recordedGames: number;
  total: number;
  average: number;
  aRecordedGames: number;
  aTotal: number | null;
  bRecordedGames: number;
  bTotal: number | null;
};

const averageRecordedAlias = (key: string) => `${key}__recorded`;
const averageTotalAlias = (key: string) => `${key}__total`;
const averageARecordedAlias = (key: string) => `${key}__a_recorded`;
const averageATotalAlias = (key: string) => `${key}__a_total`;

/**
 * Four aggregates per metric over the rivalry's player rows, in ONE
 * grouped pass: recorded games, total, and organisation A's share of
 * each. `count(column)` counts non-NULL values only, which is exactly
 * the metric-specific recorded-game denominator; `sum()` likewise
 * ignores NULLs, so a missing row never enters as a nought.
 *
 * Organisation B's share is not aggregated: it is the remainder, and
 * computing it here would double the aggregate count for nothing.
 */
function h2hAverageAggregateColumns() {
  return H2H_AVERAGE_METRICS.reduce(
    (acc, m) => sql`${acc},
           count(ap.${sql(m.column)})::int AS ${sql(averageRecordedAlias(m.key))},
           sum(ap.${sql(m.column)})::float8 AS ${sql(averageTotalAlias(m.key))},
           count(ap.${sql(m.column)}) FILTER (WHERE ap.is_a)::int
             AS ${sql(averageARecordedAlias(m.key))},
           sum(ap.${sql(m.column)}) FILTER (WHERE ap.is_a)::float8
             AS ${sql(averageATotalAlias(m.key))}`,
    sql``,
  );
}

/**
 * The eighteen already-aggregated metric columns turned back into rows,
 * one per player and metric.
 *
 * Deliberately in THIS order: unpivoting the player rows first and
 * grouping afterwards multiplies the rivalry's player-match population
 * by eighteen before it is reduced, which measured 230 ms median on
 * Carlton/Collingwood against a 250 ms ceiling. Aggregating first and
 * unpivoting ~1/8 as many rows afterwards is the same result with the
 * headroom back.
 */
function h2hAverageMetricValues() {
  return H2H_AVERAGE_METRICS.reduce(
    (acc, m, i) => sql`${acc}${i === 0 ? sql`` : sql`,`}
      (${m.key}::text,
       pt.${sql(averageRecordedAlias(m.key))},
       pt.${sql(averageTotalAlias(m.key))},
       pt.${sql(averageARecordedAlias(m.key))},
       pt.${sql(averageATotalAlias(m.key))})`,
    sql``,
  );
}

/**
 * Coverage-aware H2H player average leaderboards.
 *
 * Availability is decided ENTIRELY by runtime `stat_availability`
 * through the shared `statCoverage()` abstraction, evaluated over the
 * rivalry's own seasons. Nothing here encodes a collection start year:
 * when a reload turns a season's `goal_assists` from `not_collected`
 * into `complete`, the next request presents the board with no code
 * change.
 *
 * Aggregation reads ONLY non-NULL recorded values, and reports
 * `recordedGames` -- the number of H2H games in which the metric was
 * recorded for that player -- as the average's denominator. A missing
 * player-match value is never a zero, and the denominator is never total
 * rivalry appearances.
 *
 * Eligibility is `recordedGames >= H2H_AVERAGE_MINIMUM_RECORDED_GAMES`,
 * applied per metric. Ranking is dense on the average descending, cut at
 * rank ten with every tie at the cut retained, then ordered by sort name
 * and player id so the list is stable.
 */
export async function getHeadToHeadPlayerAverages(
  orgA: number,
  orgB: number,
): Promise<H2HPlayerAverages> {
  assertDistinct(orgA, orgB);
  const statKeys = H2H_AVERAGE_METRICS.map((m) => m.statKey);

  const [[population], coverageRows, leaderRows] = await Promise.all([
    sql<{ meetings: number; rivalrySeasons: number }[]>`
      WITH meetings AS (${h2hScope(orgA, orgB)})
      SELECT count(*)::int AS "meetings",
             count(DISTINCT season)::int AS "rivalrySeasons"
        FROM meetings
    `,
    sql<{ statKey: string; coverage: MetricCoverage; seasons: number }[]>`
      WITH meetings AS (${h2hScope(orgA, orgB)}),
      rivalry_seasons AS (SELECT DISTINCT season FROM meetings)
      SELECT cov.stat_key AS "statKey", cov.coverage, count(*)::int AS seasons
        FROM (${statCoverage(statKeys)}) cov
        JOIN rivalry_seasons rs ON rs.season = cov.season
       GROUP BY cov.stat_key, cov.coverage
    `,
    sql<H2HAverageRow[]>`
      WITH meetings AS (${h2hScope(orgA, orgB)}),
      appearances AS (
        SELECT pms.*, (c.organization_id = ${orgA}) AS is_a
          FROM player_match_stats pms
          JOIN meetings mt ON mt.id = pms.match_id
          JOIN clubs c ON c.id = pms.club_id
         WHERE c.organization_id IN (${orgA}, ${orgB})
      ),
      player_totals AS (
        SELECT ap.player_id
               ${h2hAverageAggregateColumns()}
          FROM appearances ap
         GROUP BY ap.player_id
      ),
      totals AS (
        SELECT pt.player_id, v.metric_key,
               v.recorded_games,
               v.total,
               (v.total / v.recorded_games) AS average,
               v.a_recorded_games,
               v.a_total,
               (v.recorded_games - v.a_recorded_games) AS b_recorded_games,
               (v.total - COALESCE(v.a_total, 0)) AS b_total
          FROM player_totals pt
          CROSS JOIN LATERAL (VALUES ${h2hAverageMetricValues()})
            AS v(metric_key, recorded_games, total, a_recorded_games, a_total)
         WHERE v.recorded_games >= ${H2H_AVERAGE_MINIMUM_RECORDED_GAMES}
      ),
      ranked AS (
        SELECT t.*,
               dense_rank() OVER (PARTITION BY t.metric_key ORDER BY t.average DESC) AS rank
          FROM totals t
      )
      SELECT r.metric_key AS "metricKey", r.rank::int AS rank, r.player_id AS "playerId",
             p.display_name AS "displayName", p.sort_name AS "sortName", p.slug,
             r.recorded_games AS "recordedGames", r.total, r.average,
             r.a_recorded_games AS "aRecordedGames", r.a_total AS "aTotal",
             r.b_recorded_games AS "bRecordedGames", r.b_total AS "bTotal"
        FROM ranked r
        JOIN players p ON p.id = r.player_id
       WHERE r.rank <= ${H2H_AVERAGE_RANK_LIMIT}
       ORDER BY r.metric_key, r.rank, p.sort_name, r.player_id
    `,
  ]);

  const leadersByKey = new Map<string, H2HAverageLeader[]>();
  for (const row of leaderRows) {
    const leaders = leadersByKey.get(row.metricKey) ?? [];
    leaders.push({
      rank: row.rank,
      playerId: row.playerId,
      displayName: row.displayName,
      sortName: row.sortName,
      slug: row.slug,
      recordedGames: row.recordedGames,
      total: Number(row.total),
      average: Number(row.average),
      a: {
        recordedGames: row.aRecordedGames,
        total: row.aRecordedGames > 0 ? Number(row.aTotal) : null,
        average: row.aRecordedGames > 0 ? Number(row.aTotal) / row.aRecordedGames : null,
      },
      b: {
        recordedGames: row.bRecordedGames,
        total: row.bRecordedGames > 0 ? Number(row.bTotal) : null,
        average: row.bRecordedGames > 0 ? Number(row.bTotal) / row.bRecordedGames : null,
      },
    });
    leadersByKey.set(row.metricKey, leaders);
  }

  const coverageByKey = new Map<string, Map<MetricCoverage, number>>();
  for (const row of coverageRows) {
    const states = coverageByKey.get(row.statKey) ?? new Map<MetricCoverage, number>();
    states.set(row.coverage, row.seasons);
    coverageByKey.set(row.statKey, states);
  }

  const meetings = Number(population?.meetings ?? 0);
  const rivalrySeasons = Number(population?.rivalrySeasons ?? 0);

  const boards = H2H_AVERAGE_METRICS.map((m): H2HAverageBoard => {
    const states = coverageByKey.get(m.statKey) ?? new Map<MetricCoverage, number>();
    const seasonsByCoverage: Record<MetricCoverage, number> = {
      complete: states.get('complete') ?? 0,
      partial: states.get('partial') ?? 0,
      pending: states.get('pending') ?? 0,
      not_collected: states.get('not_collected') ?? 0,
      not_applicable: states.get('not_applicable') ?? 0,
      missing: states.get('missing') ?? 0,
    };
    const coveredSeasons = seasonsByCoverage.complete + seasonsByCoverage.partial;
    const isAvailable = coveredSeasons > 0;
    return {
      key: m.key,
      statKey: m.statKey,
      label: m.label,
      rivalrySeasons,
      coveredSeasons,
      uncoveredSeasons: rivalrySeasons - coveredSeasons,
      seasonsByCoverage,
      isAvailable,
      hasCoverageGap: isAvailable && coveredSeasons < rivalrySeasons,
      minimumRecordedGames: H2H_AVERAGE_MINIMUM_RECORDED_GAMES,
      // An unavailable metric presents no board at all: runtime coverage
      // decides availability, and rows behind it are not shown anyway.
      leaders: isAvailable ? (leadersByKey.get(m.key) ?? []) : [],
    };
  });

  return {
    meetings,
    rivalrySeasons,
    minimumRecordedGames: H2H_AVERAGE_MINIMUM_RECORDED_GAMES,
    rankLimit: H2H_AVERAGE_RANK_LIMIT,
    boards,
  };
}

import 'server-only';

import postgres from 'postgres';

import { recordDataEdit, type DataEditTableName } from '@/db/queries/audit-log';
import { sql } from '@/db/client';
import {
  recomputeClubSeasons,
  recomputePlayerDerivedStats,
  recomputeSeasonBrownlowStatus,
  recomputeSeasonMetadata,
  matchBusyRefusal,
} from '@/db/queries/player-derived';
import {
  applyManualIdentityRecordSync,
  planManualIdentityRecordSync,
  syncManualIdentityNameRecord,
} from '@/db/queries/player-identity';
import {
  EDITABLE_ENTITIES,
  type EditEntity,
  type FieldValue,
  validateFieldValue,
} from '@/lib/edit/spec';

/**
 * The manual data editor's read and write paths (migration 057).
 *
 * Reads run on the public client — everything editable is app-readable.
 * The statistical UPDATE runs as afldb_import on a short-lived
 * connection, the promoteSubmission pattern, so afldb_auth keeps zero
 * write access to the statistical tables. The required data_edits audit
 * row is written inside the same import-role transaction (migration
 * 066, AFLDB-ISSUE-027): if the audit insert fails, the edit rolls
 * back with it, so an edit can never exist without its audit row.
 *
 * AFLDB-ISSUE-160 D-5: `draft_picks` is no longer editable here. It kept a
 * spec entry, a natural key and an apply branch, but the key it produced for
 * an admin-created row was garbage and was never replayed, and a second draft
 * writer with different semantics is exactly what one authoritative mutation
 * contract cannot have. `src/db/queries/admin-draft.ts` owns draft selections
 * now; `EDITABLE_ENTITIES.draft_picks` stays as the field spec it validates
 * with.
 */

export type EditableRow = {
  entity: string;
  rowId: number;
  /** Human header: player name, or "Home v Away · date". */
  title: string;
  /** Current values for every field in the spec, stringified for forms. */
  values: Record<string, string>;
};

export async function getEditableRow(
  entityKey: string,
  rowId: number,
): Promise<EditableRow | null> {
  const entity = EDITABLE_ENTITIES[entityKey];
  if (!entity || !Number.isInteger(rowId) || rowId <= 0) return null;

  if (entity.key === 'players') {
    const [row] = await sql<Record<string, unknown>[]>`
      SELECT display_name, given_name, surname,
             to_char(dob, 'YYYY-MM-DD') AS dob,
             dob_confidence::text AS dob_confidence,
             birth_year, birth_year_min, birth_year_max,
             birth_year_confidence::text AS birth_year_confidence,
             height_cm, weight_kg, notes
        FROM players WHERE id = ${rowId}
    `;
    if (!row) return null;
    return {
      entity: entity.key,
      rowId,
      title: String(row.display_name),
      values: stringify(entity, row),
    };
  }

  // AFLDB-ISSUE-160 D-5: draft selections are read and edited in /admin/draft,
  // which is the one draft mutation contract. EDITABLE_ENTITIES.draft_picks
  // stays as the field SPEC that surface validates with; this generic editor
  // is no longer a second, weaker writer for it.
  if (entity.key === 'draft_picks') return null;

  const [row] = await sql<Record<string, unknown>[]>`
    SELECT m.attendance, m.home_goals, m.home_behinds, m.away_goals, m.away_behinds,
           m.home_score, m.away_score,
           m.match_time, m.match_event, m.notes,
           hc.name AS home_name, ac.name AS away_name,
           to_char(m.match_date, 'YYYY-MM-DD') AS match_date,
           m.season, m.round_code
      FROM matches m
      JOIN clubs hc ON hc.id = m.home_club_id
      JOIN clubs ac ON ac.id = m.away_club_id
     WHERE m.id = ${rowId}
  `;
  if (!row) return null;
  return {
    entity: entity.key,
    rowId,
    title: `${row.home_name} v ${row.away_name} · ${row.season} ${row.round_code} · ${row.match_date}`
      + ` · ${row.home_score}–${row.away_score}`,
    values: stringify(entity, row),
  };
}

function stringify(entity: EditEntity, row: Record<string, unknown>): Record<string, string> {
  const out: Record<string, string> = {};
  for (const key of Object.keys(entity.fields)) {
    const v = row[key];
    out[key] = v === null || v === undefined ? '' : String(v);
  }
  return out;
}

export type SaveEditResult =
  | {
      ok: true;
      changed: Record<string, { from: FieldValue; to: FieldValue }>;
    }
  | { ok: false; error: string };

/**
 * Save one field group. Validates against the spec, applies the
 * entity-specific coupled recomputes, and writes the audit row.
 */
async function getEntityNaturalKey(tx: Tx, entityKey: string, rowId: number): Promise<string | null> {
  if (entityKey === 'matches') {
    const [row] = await tx<{ match_key: string }[]>`SELECT match_key FROM matches WHERE id = ${rowId}`;
    if (!row) throw new Error('Match not found');
    return row.match_key;
  }
  if (entityKey === 'players') {
    // Identity is profile-URL path through external_identities (afltables).
    // A player can hold two accepted paths (a renumbered profile pair, ISSUE-136/137), so the
    // choice must be a function of the data and not of the physical row order: two edits of
    // one field group made at different times would otherwise be keyed under different paths,
    // and the players replay refuses equal-authority overrides that disagree (AFLDB-ISSUE-292).
    // The replay resolves a key only through `afltables_profile_url` rows, so those rank first;
    // the smallest path breaks the tie.
    const [row] = await tx<{ external_id: string }[]>`
      SELECT e.external_id
        FROM external_identities e
        JOIN sources s ON s.id = e.source_id
       WHERE e.player_id = ${rowId}
         AND s.key = 'afltables'
         AND e.status IN ('unique', 'resolved')
       ORDER BY (e.match_method = 'afltables_profile_url') DESC NULLS LAST, e.external_id
       LIMIT 1
    `;
    if (!row) return null; // Not source-owned or lacks stable identity
    return `afltables:${row.external_id}`;
  }
  // 'draft_picks' is deliberately absent (AFLDB-ISSUE-160 D-5 / DEF-1). For an
  // admin-created row every component of that key was SQL NULL, so the
  // expression produced the literal string 'null|null|<year>|null' -- one key
  // shared by every admin pick of that year and field group, which the UNIQUE
  // (entity_type, entity_key, field_group) then made the SECOND edit silently
  // overwrite, and which replay_admin_overrides could never match. Draft
  // identity now lives in src/db/queries/admin-draft.ts, where a manual row is
  // keyed by its own minted token.
  throw new Error(`Unknown entity key for natural key: ${entityKey}`);
}

export async function saveEdit(input: {
  entityKey: string;
  rowId: number;
  groupKey: string;
  /** Raw form values keyed by field key. */
  raw: Record<string, string>;
  adminUserId: number;
  note?: string | null;
}): Promise<SaveEditResult> {
  const entity = EDITABLE_ENTITIES[input.entityKey];
  const group = entity?.groups[input.groupKey];
  if (!entity || !group) return { ok: false, error: 'Unknown entity or field group.' };
  if (input.entityKey === 'draft_picks') {
    return { ok: false, error: 'Draft selections are edited in /admin/draft.' };
  }
  if (!Number.isInteger(input.rowId) || input.rowId <= 0) {
    return { ok: false, error: 'Bad row id.' };
  }

  // Validate every field in the group.
  const values: Record<string, FieldValue> = {};
  for (const fieldKey of group.fields) {
    const field = entity.fields[fieldKey];
    const result = validateFieldValue(field, input.raw[fieldKey] ?? '');
    if (!result.ok) return { ok: false, error: result.error };
    values[fieldKey] = result.value;
  }

  // Cross-field rules the spec cannot express per-field.
  if (input.entityKey === 'players' && input.groupKey === 'birth_year') {
    const lo = values.birth_year_min;
    const hi = values.birth_year_max;
    if (typeof lo === 'number' && typeof hi === 'number' && lo > hi) {
      return { ok: false, error: 'Earliest birth year cannot exceed latest.' };
    }
  }

  const importUrl = process.env.AFLDB_IMPORT_DATABASE_URL;
  if (!importUrl) return { ok: false, error: 'AFLDB_IMPORT_DATABASE_URL is not configured.' };

  const importSql = postgres(importUrl, { max: 1, onnotice: () => {} });
  let old: Record<string, FieldValue>;
  try {
    const applied = await importSql.begin(async (tx) => {
      // AFLDB-ISSUE-261: the score edit recomputes player-derived rows and so can
      // wait on, or deadlock with, a settle. Bound every lock wait of this
      // transaction (not its total run time) so a loser rolls back and releases its
      // locks. Set before the first contended statement, `readCurrent`'s FOR UPDATE.
      if (input.entityKey === 'matches' && input.groupKey === 'score') {
        await tx`SET LOCAL lock_timeout = '5s'`;
      }
      const before = await readCurrent(tx, entity, group.fields, input.rowId);
      if (!before) return null;

      const naturalKey = await getEntityNaturalKey(tx, input.entityKey, input.rowId);

      if (input.entityKey === 'players') {
        // AFLDB-ISSUE-277 (D-277-1). A player with no AFL Tables identity has no override
        // key, so nothing below this block would make a dob, birth-year, height, weight or
        // notes correction durable: the players replay re-creates them from the creation
        // record and would put the old value back. Plan the creation-record sync FIRST,
        // read-only, so a save that would leave that record unreplayable is refused before
        // the canonical row is touched.
        const recordPlan = naturalKey === null
          ? await planManualIdentityRecordSync(tx, {
            playerId: input.rowId, groupKey: input.groupKey, before, after: values,
          })
          : null;
        if (recordPlan?.kind === 'refused') throw new EditRefusal(recordPlan.error);

        await applyPlayerEdit(tx, input.rowId, input.groupKey, values);
        if (recordPlan?.kind === 'write') {
          await applyManualIdentityRecordSync(tx, recordPlan, {
            playerId: input.rowId, adminUserId: input.adminUserId, note: input.note,
          });
        }
        if (input.groupKey === 'name') {
          // AFLDB-ISSUE-224 §21.3.2 (A1). An admin-created player also carries a
          // durable CREATION RECORD keyed by their manual token, and nothing else
          // re-types its name fields. Left alone it contradicts this correction for
          // ever -- and for a manual player with no AFL Tables identity yet,
          // getEntityNaturalKey returns null below, so it would be the only durable
          // record of the name and would still hold the OLD one. Same transaction,
          // its own audit row; a player with no such record is a no-op.
          await syncManualIdentityNameRecord(tx, {
            playerId: input.rowId,
            before,
            after: values,
            adminUserId: input.adminUserId,
            note: input.note,
          });
        }
      } else {
        await applyMatchEdit(tx, input.rowId, input.groupKey, values);
      }

      if (naturalKey !== null) {
        const [existing] = await tx<{ override_values: Record<string, any> }[]>`
          SELECT override_values FROM data_overrides
           WHERE entity_type = ${input.entityKey} AND entity_key = ${naturalKey} AND field_group = ${input.groupKey}
        `;

        const overrides: Record<string, any> = existing ? { ...existing.override_values } : {};
        for (const field of group.fields) {
          if (values[field] !== before[field]) {
            overrides[field] = values[field];
          }
        }

        // Upsert the active override so importers can replay it
        if (Object.keys(overrides).length > 0) {
          await tx`
            INSERT INTO data_overrides (entity_type, entity_key, field_group, override_values, admin_user_id, is_active, updated_at)
            VALUES (${input.entityKey}, ${naturalKey}, ${input.groupKey}, ${tx.json(overrides)}, ${input.adminUserId}, true, now())
            ON CONFLICT (entity_type, entity_key, field_group) DO UPDATE SET
              override_values = EXCLUDED.override_values,
              admin_user_id = EXCLUDED.admin_user_id,
              is_active = true,
              updated_at = now()
          `;
        }
      }

      // Required audit, same transaction: a failed insert rolls the
      // edit back (AFLDB-ISSUE-027).
      await recordDataEdit(tx, {
        tableName: entity.table as DataEditTableName,
        rowId: input.rowId,
        fieldGroup: input.groupKey,
        oldValues: before,
        newValues: values,
        adminUserId: input.adminUserId,
        note: input.note,
      });
      return before;
    }) as Record<string, FieldValue> | null;
    if (applied === null) return { ok: false, error: 'No row with that id.' };
    old = applied;
  } catch (error) {
    // 55P03 / 40P01: the whole transaction rolled back (AFLDB-ISSUE-261). Mapped only
    // where the bound above is set (matches/score); other edits keep the generic message.
    if (input.entityKey === 'matches' && input.groupKey === 'score') {
      const busy = matchBusyRefusal(error);
      if (busy) return { ok: false, error: busy };
    }
    // A refusal this module decided inside the transaction (AFLDB-ISSUE-277): its own message, not the generic wrapper.
    if (error instanceof EditRefusal) return { ok: false, error: error.message };
    const message = error instanceof Error ? error.message : String(error);
    return { ok: false, error: `The edit could not be applied: ${message}` };
  } finally {
    await importSql.end({ timeout: 5 });
  }

  const changed: Record<string, { from: FieldValue; to: FieldValue }> = {};
  for (const key of group.fields) {
    if (old[key] !== values[key]) changed[key] = { from: old[key], to: values[key] };
  }

  return { ok: true, changed };
}

type Tx = postgres.TransactionSql;

/**
 * A save refused by a precondition this module checks inside the transaction
 * (AFLDB-ISSUE-277's replay-compatibility guard). Thrown so the transaction rolls
 * back, and mapped back to a plain `{ ok: false }` with its own message instead of
 * the generic "could not be applied" wrapper.
 */
class EditRefusal extends Error {}

async function readCurrent(
  tx: Tx,
  entity: EditEntity,
  fields: string[],
  rowId: number,
): Promise<Record<string, FieldValue> | null> {
  // Column identifiers come from the spec alone. dob is read as text so
  // the audit snapshot and the change comparison use the same shape the
  // form submits.
  const cols = fields
    .map((f) => (entity.fields[f].kind === 'date'
      ? `to_char(${f}, 'YYYY-MM-DD') AS ${f}`
      : entity.fields[f].kind === 'enum' ? `${f}::text AS ${f}` : f))
    .join(', ');
  const [row] = await tx.unsafe(
    `SELECT ${cols} FROM ${entity.table} WHERE id = $1 FOR UPDATE`,
    [rowId],
  ) as unknown as Record<string, FieldValue>[];
  return row ?? null;
}

async function applyPlayerEdit(
  tx: Tx,
  rowId: number,
  groupKey: string,
  v: Record<string, FieldValue>,
): Promise<void> {
  switch (groupKey) {
    case 'name':
      // Nothing in the database maintains the search and sort forms —
      // they are recomputed here or they silently go stale (the slug is
      // deliberately untouched: player URLs are id-authoritative).
      await tx`
        UPDATE players
           SET display_name = ${v.display_name},
               given_name = ${v.given_name},
               surname = ${v.surname},
               search_name = afldb_normalise_name(${v.display_name}::text),
               sort_name = CASE
                 WHEN ${v.surname}::text IS NULL THEN ${v.display_name}
                 WHEN ${v.given_name}::text IS NULL THEN ${v.surname}
                 ELSE ${v.surname} || ', ' || ${v.given_name}
               END
         WHERE id = ${rowId}
      `;
      return;
    case 'dob':
      await tx`
        UPDATE players
           SET dob = ${v.dob}::date,
               dob_confidence = ${v.dob === null ? 'unknown' : v.dob_confidence}::value_confidence
         WHERE id = ${rowId}
      `;
      return;
    case 'birth_year':
      await tx`
        UPDATE players
           SET birth_year = ${v.birth_year},
               birth_year_min = ${v.birth_year_min},
               birth_year_max = ${v.birth_year_max},
               birth_year_confidence = ${v.birth_year_confidence}::value_confidence
         WHERE id = ${rowId}
      `;
      return;
    case 'height_cm':
      await tx`UPDATE players SET height_cm = ${v.height_cm} WHERE id = ${rowId}`;
      return;
    case 'weight_kg':
      await tx`UPDATE players SET weight_kg = ${v.weight_kg} WHERE id = ${rowId}`;
      return;
    case 'notes':
      await tx`UPDATE players SET notes = ${v.notes} WHERE id = ${rowId}`;
      return;
    default:
      throw new Error(`unhandled players group ${groupKey}`);
  }
}

async function applyMatchEdit(
  tx: Tx,
  rowId: number,
  groupKey: string,
  v: Record<string, FieldValue>,
): Promise<void> {
  switch (groupKey) {
    case 'attendance':
      // Migration 020's contract: the figure and its status agree in
      // both directions, and a genuine zero must cite a source.
      await tx`
        UPDATE matches
           SET attendance = ${v.attendance},
               attendance_status = ${v.attendance === null ? 'not_collected' : 'complete'}::coverage_status,
               attendance_source_id = CASE
                 WHEN ${v.attendance}::int IS NULL THEN NULL
                 ELSE (SELECT id FROM sources WHERE key = 'manual_admin_edit')
               END
         WHERE id = ${rowId}
      `;
      return;
    case 'score': {
      // Everything the CHECK constraints couple, derived in one
      // statement: scores from components, then result, winner and
      // margin from the scores. The admin never types the derived half.
      const hg = v.home_goals as number;
      const hb = v.home_behinds as number;
      const ag = v.away_goals as number;
      const ab = v.away_behinds as number;
      const home = hg * 6 + hb;
      const away = ag * 6 + ab;
      const result = home > away ? 'home_win' : home < away ? 'away_win' : 'draw';
      const [match] = await tx<{
        season: number;
        homeClubId: number;
        awayClubId: number;
      }[]>`
        SELECT season, home_club_id AS "homeClubId", away_club_id AS "awayClubId"
          FROM matches
         WHERE id = ${rowId}
      `;
      if (!match) throw new Error('No match with that id.');

      const playerRows = await tx<{ playerId: number }[]>`
        SELECT DISTINCT player_id AS "playerId"
          FROM player_match_stats
         WHERE match_id = ${rowId}
      `;
      const affectedIds = playerRows.map((row) => row.playerId);

      await tx`
        UPDATE matches
           SET home_goals = ${hg}, home_behinds = ${hb}, home_score = ${home},
               away_goals = ${ag}, away_behinds = ${ab}, away_score = ${away},
               result = ${result}::match_result,
               winner_club_id = CASE ${result}
                 WHEN 'home_win' THEN home_club_id
                 WHEN 'away_win' THEN away_club_id
                 ELSE NULL END,
               margin = ${Math.abs(home - away)}
         WHERE id = ${rowId}
      `;

      // Period rows are cumulative. A sparse Q1/Q2/Q3 set does not identify
      // the final period, so regulation time is period 4 unless explicit
      // extra-time rows (5+) already establish a later final period.
      const [periodRow] = await tx<{ period: number }[]>`
        SELECT GREATEST(COALESCE(max(period), 4), 4)::int AS period
          FROM match_period_scores
         WHERE match_id = ${rowId}
      `;
      const finalPeriod = periodRow?.period ?? 4;
      for (const score of [
        { clubId: match.homeClubId, goals: hg, behinds: hb, points: home },
        { clubId: match.awayClubId, goals: ag, behinds: ab, points: away },
      ]) {
        await tx`
          INSERT INTO match_period_scores (match_id, club_id, period, goals, behinds, points)
          VALUES (${rowId}, ${score.clubId}, ${finalPeriod}, ${score.goals}, ${score.behinds}, ${score.points})
          ON CONFLICT (match_id, club_id, period) DO UPDATE SET
            goals = EXCLUDED.goals,
            behinds = EXCLUDED.behinds,
            points = EXCLUDED.points
        `;
      }

      await recomputeSeasonMetadata(tx, match.season);
      await recomputeClubSeasons(tx, match.season);
      await recomputePlayerDerivedStats(tx, affectedIds, match.season);
      await recomputeSeasonBrownlowStatus(tx, match.season);
      return;
    }
    case 'match_time':
      await tx`UPDATE matches SET match_time = ${v.match_time} WHERE id = ${rowId}`;
      return;
    case 'match_event':
      await tx`UPDATE matches SET match_event = ${v.match_event} WHERE id = ${rowId}`;
      return;
    case 'notes':
      await tx`UPDATE matches SET notes = ${v.notes} WHERE id = ${rowId}`;
      return;
    default:
      throw new Error(`unhandled matches group ${groupKey}`);
  }
}

import 'server-only';

import { sql } from '@/db/client';
import { allOf, containsPattern, rangeConditions } from '@/db/queries/filters';
import type { FilterValues } from '@/search/table-filters';

export type DraftPickRow = {
  id: number;
  draftYear: number;
  draftType: string;
  draftKind: string | null;
  pickNumber: number | null;
  playerId: number | null;
  playerSlug: string | null;
  playerDisplayName: string | null;
  playerNameRaw: string;
  linkStatus: string;
  clubSlug: string | null;
  clubName: string | null;
  clubNameRaw: string | null;
  originClub: string | null;
  draftAge: number | null;
  /** Career games of the linked player; null when the pick is unlinked. */
  careerGames: number | null;
};

/**
 * Draft columns the index may be filtered on.
 *
 * `games` is the drafted player's career total, which exists only for a
 * selection that was linked to a player. A range on it therefore excludes
 * unlinked rows rather than treating them as zero games — the filter help
 * text says so, because a quarter of legacy rows are unlinked.
 */
export const DRAFT_FILTER_COLUMNS: Record<string, string> = {
  pick: 'dp.pick_number',
  age: 'dp.draft_age',
  games: 'pcs.games',
};

export const DRAFT_SORTS: Record<string, string> = {
  year: 'dp.draft_year',
  pick: 'dp.pick_number',
  player: 'COALESCE(p.sort_name, dp.player_name_raw)',
  type: 'dp.draft_type',
  age: 'dp.draft_age',
  games: 'pcs.games',
};

export function isDraftSort(s: string | undefined): s is keyof typeof DRAFT_SORTS {
  return s !== undefined && Object.hasOwn(DRAFT_SORTS, s);
}

export function isDraftSortDir(d: string | undefined): d is 'asc' | 'desc' {
  return d === 'asc' || d === 'desc';
}

export type DraftPickFilters = {
  year?: number;
  clubSlug?: string;
  origin?: string;
  draftType?: string;
  q?: string;
  ranges?: FilterValues;
  sort?: string;
  dir?: string;
  page: number;
  pageSize: number;
};

/**
 * Draft and recruitment history, 1981 onward.
 *
 * Roughly a quarter of legacy rows have no linked player (see
 * draft_picks_link_ck / draft_persons_backlog_ck in migration 019); those
 * rows are still returned, with playerId null and the raw source name in
 * playerNameRaw, rather than filtered out.
 */
export async function listDraftPicks(
  filters: DraftPickFilters,
): Promise<{ rows: DraftPickRow[]; total: number }> {
  const conditions = filters.ranges
    ? rangeConditions(filters.ranges, DRAFT_FILTER_COLUMNS)
    : [];

  if (filters.year !== undefined) {
    conditions.push(sql`dp.draft_year = ${filters.year}`);
  }
  if (filters.clubSlug) {
    conditions.push(sql`c.slug = ${filters.clubSlug}`);
  }
  if (filters.origin) {
    conditions.push(sql`dp.original_club_raw ILIKE ${containsPattern(filters.origin)}`);
  }
  if (filters.draftType) {
    conditions.push(sql`dp.draft_type = ${filters.draftType}`);
  }
  if (filters.q) {
    const like = containsPattern(filters.q);
    conditions.push(sql`(dp.player_name_raw ILIKE ${like} OR p.display_name ILIKE ${like})`);
  }

  const where = allOf(conditions);
  const offset = (filters.page - 1) * filters.pageSize;

  let orderBy = sql`dp.draft_year DESC, dp.pick_number NULLS LAST`;
  if (isDraftSort(filters.sort) && isDraftSortDir(filters.dir)) {
    const sortCol = DRAFT_SORTS[filters.sort];
    const sqlDir = filters.dir === 'asc' ? sql`ASC` : sql`DESC`;
    orderBy = sql`${sql.unsafe(sortCol)} ${sqlDir} NULLS LAST, dp.draft_year DESC, dp.pick_number NULLS LAST`;
  }

  const rows = await sql<(DraftPickRow & { total: string })[]>`
    SELECT dp.id, dp.draft_year AS "draftYear", dp.draft_type AS "draftType",
           dp.draft_kind AS "draftKind", dp.pick_number AS "pickNumber",
           dp.player_id AS "playerId", p.slug AS "playerSlug",
           p.display_name AS "playerDisplayName", dp.player_name_raw AS "playerNameRaw",
           dp.link_status_value::text AS "linkStatus",
           c.slug AS "clubSlug", c.name AS "clubName", dp.club_name_raw AS "clubNameRaw",
           dp.original_club_raw AS "originClub",
           dp.draft_age AS "draftAge",
           pcs.games AS "careerGames",
           count(*) OVER () AS total
      FROM draft_picks dp
      LEFT JOIN players p ON p.id = dp.player_id
      LEFT JOIN player_career_stats pcs ON pcs.player_id = dp.player_id
      LEFT JOIN clubs c ON c.id = dp.club_id
     WHERE ${where}
     ORDER BY ${orderBy}
     LIMIT ${filters.pageSize} OFFSET ${offset}
  `;

  return {
    rows: rows.map(({ total: _total, ...rest }) => rest),
    total: rows.length > 0 ? Number(rows[0].total) : 0,
  };
}

export async function getDraftYears(): Promise<number[]> {
  const rows = await sql<{ year: number }[]>`
    SELECT DISTINCT draft_year AS year FROM draft_picks ORDER BY year DESC
  `;
  return rows.map((r) => r.year);
}

export async function getDraftTypes(): Promise<string[]> {
  const rows = await sql<{ type: string }[]>`
    SELECT DISTINCT draft_type AS type FROM draft_picks ORDER BY type
  `;
  return rows.map((r) => r.type);
}

export type PlayerDraftHistoryRow = {
  id: number;
  draftYear: number;
  draftType: string;
  draftKind: string | null;
  pickNumber: number | null;
  clubName: string | null;
  clubSlug: string | null;
  originClub: string | null;
  heightCm: number | null;
  weightKg: number | null;
  draftAge: number | null;
  detail: string | null;
  pickNote: string | null;
};

/**
 * All draft selections recorded for one player (see changeLog.md).
 */
export async function getPlayerDraftHistory(playerId: number): Promise<PlayerDraftHistoryRow[]> {
  return sql<PlayerDraftHistoryRow[]>`
    SELECT dp.id, dp.draft_year AS "draftYear", dp.draft_type AS "draftType",
           dp.draft_kind AS "draftKind", dp.pick_number AS "pickNumber",
           c.name AS "clubName", c.slug AS "clubSlug",
           dp.original_club_raw AS "originClub",
           dp.height_cm AS "heightCm", dp.weight_kg AS "weightKg",
           dp.draft_age AS "draftAge", dp.detail, dp.pick_note AS "pickNote"
      FROM draft_picks dp
      LEFT JOIN clubs c ON c.id = dp.club_id
     WHERE dp.player_id = ${playerId}
     ORDER BY dp.draft_year DESC, dp.pick_number ASC NULLS LAST
  `;
}

import 'server-only';

import { sql } from '@/db/client';
import {
  MATCH_FIELDS,
  MATCH_SORTS,
  type MatchSearchQuery,
} from '@/search/match-spec';

export type MatchSearchResultRow = {
  id: number;
  season: number;
  roundType: string;
  roundNumber: number | null;
  matchDate: Date;
  homeName: string;
  homeSlug: string;
  awayName: string;
  awaySlug: string;
  homeGoals: number | null;
  homeBehinds: number | null;
  homeScore: number;
  awayGoals: number | null;
  awayBehinds: number | null;
  awayScore: number;
  lowScore: number;
  highScore: number;
  totalScore: number;
  result: 'home_win' | 'away_win' | 'draw';
  margin: number;
  venueName: string;
};

/**
 * One row as the `totals LEFT JOIN page` shape below actually returns it.
 *
 * Every match column is nullable here because a page beyond the last result
 * produces exactly one row carrying the total and nothing else. The filter
 * further down relies on that; typing the columns non-null made the very
 * check that keeps the empty row out of the results look impossible.
 */
type RawMatchSearchRow =
  { [K in keyof MatchSearchResultRow]: MatchSearchResultRow[K] | null }
  & { total: number };

/**
 * Execute a validated Match Search specification.
 *
 * The filtered result, page and total are produced by one SQL statement. That
 * gives the count and rows one MVCC snapshot even while an import is running,
 * and the totals CTE preserves the true count when a hand-edited page number
 * is beyond the last result page.
 */
export async function runMatchSearch(
  query: MatchSearchQuery,
): Promise<{ rows: MatchSearchResultRow[]; total: number }> {
  const conditions: ReturnType<typeof sql>[] = [];

  for (const filter of query.filters) {
    const definition = MATCH_FIELDS[filter.field];
    if (!definition) continue;
    const column = sql.unsafe(definition.column);

    if (filter.min !== undefined) {
      conditions.push(sql`${column} >= ${filter.min}`);
    }
    if (filter.max !== undefined) {
      conditions.push(sql`${column} <= ${filter.max}`);
    }
  }

  if (query.clubSlugs.length > 0) {
    conditions.push(sql`
      (h.slug = ANY(${query.clubSlugs}) OR a.slug = ANY(${query.clubSlugs}))
    `);
  }

  if (query.outcome === 'draw') {
    conditions.push(sql`m.result = 'draw'`);
  } else if (query.outcome === 'decided') {
    conditions.push(sql`m.result <> 'draw'`);
  }

  if (query.matchType === 'finals') {
    // The finals series, so is_finals_series: a wildcard final is is_final = true
    // but is not a finals-series match (AFLDB-ISSUE-129 §8.4).
    conditions.push(sql`m.is_finals_series`);
  } else if (query.matchType === 'home_and_away') {
    conditions.push(sql`NOT m.is_final`);
  } else if (query.matchType === 'wildcard_final') {
    conditions.push(sql`m.round_type = 'wildcard_final'`);
  }

  const where = conditions.length
    ? conditions.reduce((combined, condition) => sql`${combined} AND ${condition}`)
    : sql`TRUE`;
  const orderBy = sql.unsafe(
    MATCH_SORTS[query.sort]?.sql ?? MATCH_SORTS.date_desc.sql,
  );
  const offset = (query.page - 1) * query.pageSize;

  const rawRows = await sql<RawMatchSearchRow[]>`
    WITH filtered AS MATERIALIZED (
      SELECT m.id, m.season, m.round_type AS "roundType",
             m.round_number AS "roundNumber", m.match_date AS "matchDate",
             h.name AS "homeName", h.slug AS "homeSlug",
             a.name AS "awayName", a.slug AS "awaySlug",
             m.home_goals AS "homeGoals", m.home_behinds AS "homeBehinds",
             m.home_score AS "homeScore",
             m.away_goals AS "awayGoals", m.away_behinds AS "awayBehinds",
             m.away_score AS "awayScore",
             LEAST(m.home_score, m.away_score) AS "lowScore",
             GREATEST(m.home_score, m.away_score) AS "highScore",
             (m.home_score + m.away_score) AS "totalScore",
             m.result::text, m.margin,
             COALESCE(v.canonical_name, m.venue_raw) AS "venueName"
        FROM matches m
        JOIN clubs h ON h.id = m.home_club_id
        JOIN clubs a ON a.id = m.away_club_id
        LEFT JOIN venues v ON v.id = m.venue_id
       WHERE ${where}
    ),
    page AS (
      SELECT * FROM filtered
       ORDER BY ${orderBy}
       LIMIT ${query.pageSize} OFFSET ${offset}
    ),
    totals AS (
      SELECT count(*)::int AS total FROM filtered
    )
    SELECT page.*, totals.total
      FROM totals
      LEFT JOIN page ON TRUE
     ORDER BY ${orderBy}
  `;

  const total = rawRows[0]?.total ?? 0;
  const rows = rawRows
    .filter((row): row is MatchSearchResultRow & { total: number } => row.id !== null)
    .map(({ total: _total, ...row }) => row);

  return { rows, total };
}

import 'server-only';

import { sql } from '@/db/client';
import { afterSirenRequiresMatchLink, type NlQueryPlan } from '@/search/nl/plan';
import type {
  NlAfterSirenEventRow, NlAfterSirenExclusions, NlAfterSirenPlayerRow, NlAnswerPayload,
} from '@/search/nl/answer-types';

type SqlFragment = ReturnType<typeof sql>;

/**
 * The after_siren grain: AFLDB's curated, cited list of kicks after the
 * siren (`after_siren_kicks`, migration 089).
 *
 * This is NOT a second derivation of db/queries/after-siren.ts, and nor is
 * it a parameterised copy of it. `getAfterSirenRecords` is the Records
 * board, whose five-CTE first/last-attempt/first/last-goal shape answers a
 * different question. What this compiler SHARES with it verbatim, and must
 * not re-decide:
 *
 *  - the trusted-link rule (`player_id IS NOT NULL`, and -- because
 *    `after_siren_kicks_link_ck` already binds them -- `link_status_value
 *    IN ('unique','resolved')` stated explicitly anyway);
 *  - `COALESCE(cl.name, a.club_name_raw)` / `COALESCE(op.name,
 *    a.opponent_name_raw)` club naming, and the slug-null-when-unresolved
 *    convention;
 *  - `LEFT JOIN matches m ON m.id = a.match_id` as the ONLY route to a
 *    canonical match property.
 *
 * Ownership is encoded structurally rather than by convention:
 *
 *  - The base relation is `after_siren_kicks a`, alone. Every dimension,
 *    the season, both raw club names, the competition, the
 *    `premiership_season` flag and the citation come from it and from
 *    nothing else.
 *  - `matches` is joined LEFT and used ONLY to project `match_date` and
 *    `round_type`. When afterSirenRequiresMatchLink(plan) is true -- and
 *    only then -- `a.match_id IS NOT NULL` is emitted too, promoting the
 *    join to an effective inner join and excluding unlinked rows.
 *  - `a.premiership_season` is emitted as a filter ONLY alongside a match
 *    type. It is never emitted merely to make a match link likely: D10 is
 *    explicit that `match_id` must not be required because an event is
 *    premiership-season, and the converse discipline applies here.
 *  - **`round_raw` is never read as a filter, by any code path here.** It
 *    is projected for display and nothing else. The witness is Kerry Good,
 *    1980, `round_raw = 'GF'`, North Melbourne v Collingwood -- an ESCORT
 *    CHAMPIONSHIPS match with `premiership_season = false`. Any round- or
 *    finals-shaped filter reading `round_raw` returns that row as a Grand
 *    Final. Finals scope goes through `matches.round_type` /
 *    `matches.is_finals_series` instead.
 *  - All SQL is parameterised. Every enum value reaching SQL is bound and
 *    is one of the closed union members on NlAfterSiren, never text from
 *    the question.
 *
 * `shot_detail`, `supergoal_scoring`, the verbatim source scores, the link
 * provenance and the source notes are neither selected nor rendered.
 */

function foldAnd(clauses: SqlFragment[]): SqlFragment {
  if (clauses.length === 0) return sql`TRUE`;
  return clauses.reduce((acc, clause) => sql`${acc} AND ${clause}`);
}

/**
 * The question's own filters: the three independent typed dimensions, the
 * subject player, the club lineages and the season range. Deliberately
 * EXCLUDES the ownership requirements (match link, trusted player link),
 * which are added separately so the excluded rows can be counted against
 * the same set the reader asked about.
 */
function baseClauses(plan: NlQueryPlan): SqlFragment[] {
  const clauses: SqlFragment[] = [];

  // The lifecycle filter (migration 102, AFLDB-ISSUE-167 §7), emitted
  // UNCONDITIONALLY and FIRST so that it is the one clause no question shape
  // can omit. It belongs here rather than in ownershipClauses precisely
  // because `exclusions()` is built from the base clauses alone: the caveat
  // line ("N of these rows have no player link") is counted over the
  // question's own filters, so a filter applied only to the answer would
  // leave a retracted row being quoted at the reader in the caveat it had
  // just been removed from in the result.
  clauses.push(sql`a.status = 'active'`);

  const siren = plan.afterSiren;

  // Three INDEPENDENT dimensions, ANDed and never merged: what the kick
  // registered, what it did to the result, and the match result from the
  // kicker's side. "A goal after the siren" is kickScored alone; "a goal
  // after the siren TO WIN" is kickScored AND kickEffect, and the two are
  // different populations.
  if (siren?.kickScored) clauses.push(sql`a.kick_scored = ${siren.kickScored}`);
  if (siren?.kickEffect) clauses.push(sql`a.kick_effect = ${siren.kickEffect}`);
  if (siren?.kickerResult) clauses.push(sql`a.kicker_result = ${siren.kickerResult}`);

  if (plan.player) clauses.push(sql`a.player_id = ${plan.player.id}`);

  // Club scope folds the whole organization_id lineage, exactly as the
  // club page and coach-record.ts do. The measured witness is Bill Wood,
  // Footscray, 1946: one of the four goals after the siren against the
  // RICHMOND organization, and a raw club_id comparison would drop it.
  // Nothing of Fitzroy's ever reaches Brisbane Lions -- a merger is a
  // different organisation.
  if (plan.scope.clubFor) {
    clauses.push(sql`a.club_id IN (SELECT id FROM clubs WHERE organization_id = ${plan.scope.clubFor.organizationId})`);
  }
  if (plan.scope.clubAgainst) {
    clauses.push(sql`a.opponent_club_id IN (SELECT id FROM clubs WHERE organization_id = ${plan.scope.clubAgainst.organizationId})`);
  }

  if (plan.scope.seasonMin !== undefined) clauses.push(sql`a.season >= ${plan.scope.seasonMin}`);
  if (plan.scope.seasonMax !== undefined) clauses.push(sql`a.season <= ${plan.scope.seasonMax}`);
  return clauses;
}

/**
 * The D10 ownership requirements, on top of the question's own filters.
 * `matches` is the only source of a match type, so any match type -- home
 * and away included -- also requires the link.
 */
function ownershipClauses(plan: NlQueryPlan): SqlFragment[] {
  const clauses: SqlFragment[] = [];
  if (afterSirenRequiresMatchLink(plan)) clauses.push(sql`a.match_id IS NOT NULL`);
  const matchType = plan.scope.matchType;
  if (matchType !== undefined) {
    // Belt and braces: after_siren_kicks_match_ck already implies this for
    // any row carrying a match id, and stating it makes the query
    // self-evidently right rather than right by inference.
    clauses.push(sql`a.premiership_season`);
    clauses.push(matchType === 'finals'
      ? sql`m.is_finals_series`
      : sql`m.round_type = ${matchType}`);
  }
  return clauses;
}

/** The trusted-link rule. A player-subject answer counts nothing else. */
const TRUSTED_LINK = sql`a.player_id IS NOT NULL AND a.link_status_value IN ('unique', 'resolved')`;

const FROM_EVENTS = sql`
  FROM after_siren_kicks a
  LEFT JOIN clubs cl ON cl.id = a.club_id
  LEFT JOIN clubs op ON op.id = a.opponent_club_id
  LEFT JOIN matches m ON m.id = a.match_id
`;

const EVENT_SELECT = sql`
  a.id AS "eventId", a.season, a.round_raw AS "roundRaw", a.competition,
  a.premiership_season AS "premiershipSeason",
  a.player_id AS "playerId", p.slug AS "playerSlug", a.player_name_raw AS "playerName",
  COALESCE(cl.name, a.club_name_raw) AS "clubName", cl.slug AS "clubSlug",
  COALESCE(op.name, a.opponent_name_raw) AS "opponentName", op.slug AS "opponentSlug",
  a.kick_scored AS "kickScored", a.kick_effect AS "kickEffect",
  a.kicker_result AS "kickerResult", a.siren,
  a.match_id AS "matchId", m.match_date AS "matchDate", m.round_type AS "roundType",
  a.cited, NULL::float8 AS value
`;

/**
 * What the ownership rules left out of THIS answer, counted over the
 * question's own filters rather than over the whole table -- computed at
 * answer time so the caveat can never be a stale hard-coded number.
 */
async function exclusions(plan: NlQueryPlan): Promise<NlAfterSirenExclusions> {
  const base = foldAnd(baseClauses(plan));
  const [row] = await sql<{ no_player_link: string; no_match_link: string }[]>`
    SELECT count(*) FILTER (WHERE a.player_id IS NULL) AS no_player_link,
           count(*) FILTER (WHERE a.match_id IS NULL)  AS no_match_link
      FROM after_siren_kicks a
     WHERE ${base}
  `;
  return {
    noPlayerLink: Number(row?.no_player_link ?? 0),
    noMatchLink: Number(row?.no_match_link ?? 0),
  };
}

export async function answerAfterSiren(plan: NlQueryPlan, limit: number): Promise<NlAnswerPayload> {
  const where = foldAnd([...baseClauses(plan), ...ownershipClauses(plan)]);
  const excluded = await exclusions(plan);

  if (plan.afterSiren?.subject === 'player') return answerPlayers(plan, where, limit, excluded);
  if (plan.afterSiren?.occurrence) return answerOccurrence(plan, where, excluded);
  if (plan.agg.kind === 'count') return answerEventCount(where);
  return answerEventList(where, limit, excluded);
}

/** "How many kicks after the siren" -- the size of the qualifying set. */
async function answerEventCount(where: SqlFragment): Promise<NlAnswerPayload> {
  const [row] = await sql<{ value: string }[]>`
    SELECT count(*) AS value
      ${FROM_EVENTS}
     WHERE ${where}
  `;
  return { kind: 'count', value: Number(row?.value ?? 0) };
}

/**
 * The qualifying events themselves, ordered the way
 * getPlayerAfterSirenEvents already orders a player's own list, so the
 * same question asked two ways cannot come back in two different orders.
 */
async function answerEventList(
  where: SqlFragment,
  limit: number,
  excluded: NlAfterSirenExclusions,
): Promise<NlAnswerPayload> {
  const rows = await sql<(NlAfterSirenEventRow & { total: string })[]>`
    SELECT ${EVENT_SELECT}, count(*) OVER () AS total
      ${FROM_EVENTS}
      LEFT JOIN players p ON p.id = a.player_id
     WHERE ${where}
     ORDER BY a.season DESC, a.id DESC
     LIMIT ${limit}
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = rows.map(({ total: _total, ...rest }) => rest);
  return { kind: 'after_siren_event', lead: clean[0] ?? null, rows: clean, total, excluded };
}

/**
 * "The first" / "the most recent" -- ordered by the CANONICAL match date
 * and nothing else. `round_raw` is free text ('GF', 'round 1', 'round 3'
 * all occur) and gives no within-season order, so a row with no match link
 * cannot be placed in a chronology at all and is excluded (D10 limit 1).
 * The caveat says how many were left out.
 */
async function answerOccurrence(
  plan: NlQueryPlan,
  where: SqlFragment,
  excluded: NlAfterSirenExclusions,
): Promise<NlAnswerPayload> {
  const ascending = plan.afterSiren?.occurrence === 'first';
  const direction = ascending ? sql.unsafe('ASC') : sql.unsafe('DESC');
  const rows = await sql<NlAfterSirenEventRow[]>`
    SELECT ${EVENT_SELECT}
      ${FROM_EVENTS}
      LEFT JOIN players p ON p.id = a.player_id
     WHERE ${where}
     ORDER BY m.match_date ${direction}, a.id ${direction}
     LIMIT 1
  `;
  return {
    kind: 'after_siren_event',
    lead: rows[0] ?? null,
    rows,
    total: rows.length,
    excluded,
  };
}

/**
 * The kicker leaderboard. Every superlative in this family is a TIE --
 * the measured maxima are 2 kicks, 2 goals and 2 winning kicks -- so this
 * uses the same `rank()` with no PARTITION BY every other grain uses and
 * returns every row at the lead rank. An answer that names one player
 * would be wrong by construction.
 */
async function answerPlayers(
  plan: NlQueryPlan,
  where: SqlFragment,
  limit: number,
  excluded: NlAfterSirenExclusions,
): Promise<NlAnswerPayload> {
  const totals = sql`
    SELECT a.player_id AS "playerId", p.slug, p.display_name AS "displayName",
           count(*)::int AS value,
           min(a.season)::int AS "firstSeason",
           max(a.season)::int AS "lastSeason",
           string_agg(DISTINCT COALESCE(cl.name, a.club_name_raw), ', ') AS "clubNames"
      ${FROM_EVENTS}
      JOIN players p ON p.id = a.player_id
     WHERE ${where} AND ${TRUSTED_LINK}
     GROUP BY a.player_id, p.slug, p.display_name
  `;

  if (plan.agg.kind === 'count') {
    const [row] = await sql<{ value: string }[]>`
      WITH t AS (${totals})
      SELECT count(*) AS value FROM t
    `;
    return { kind: 'count', value: Number(row?.value ?? 0) };
  }

  // A threshold lists every qualifier; it never ranks one. The measured
  // ceiling is 2, so "3 or more goals after the siren" comes back EMPTY --
  // an honest answer to a well-formed question, not a decline.
  if (plan.agg.kind === 'list') {
    const having = plan.metricCondition
      ? compareExpr(sql`t.value`, plan.metricCondition.op, plan.metricCondition.value)
      : sql`TRUE`;
    const rows = await sql<(NlAfterSirenPlayerRow & { total: string })[]>`
      WITH t AS (${totals})
      SELECT t.*, count(*) OVER () AS total
        FROM t
       WHERE ${having}
       ORDER BY t.value DESC, t."displayName"
       LIMIT ${limit}
    `;
    const total = rows[0] ? Number(rows[0].total) : 0;
    const clean = rows.map(({ total: _total, ...rest }) => rest);
    return { kind: 'after_siren_player', lead: clean[0] ?? null, rows: clean, total, excluded };
  }

  const n = plan.agg.kind === 'top_n' ? plan.agg.n : 1;
  const rows = await sql<(NlAfterSirenPlayerRow & { total: string; rnk: number })[]>`
    WITH t AS (${totals}),
    ranked AS (
      SELECT t.*, rank() OVER (ORDER BY t.value DESC)::int AS rnk FROM t
    )
    SELECT r.*, count(*) OVER () AS total
      FROM ranked r
     WHERE r.rnk <= ${n}
     ORDER BY r.value DESC, r."displayName"
     LIMIT ${limit}
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = rows.map(({ total: _total, rnk: _rnk, ...rest }) => rest);
  return { kind: 'after_siren_player', lead: clean[0] ?? null, rows: clean, total, excluded };
}

/** A closed switch, the same discipline coach-record.ts applies: no operator reaches SQL as text. */
function compareExpr(value: SqlFragment, op: string, bound: number): SqlFragment {
  switch (op) {
    case 'gte': return sql`${value} >= ${bound}`;
    case 'gt': return sql`${value} > ${bound}`;
    case 'lte': return sql`${value} <= ${bound}`;
    case 'lt': return sql`${value} < ${bound}`;
    case 'eq': return sql`${value} = ${bound}`;
    default: throw new Error(`after_siren comparison "${op}" is not recognised.`);
  }
}

import 'server-only';

import { sql } from '@/db/client';
import { type NlAggregation, type NlClubSeasonCondition, type NlQueryPlan } from '@/search/nl/plan';
import type { NlAnswerPayload, NlClubSeasonRow } from '@/search/nl/answer-types';

type SqlFragment = ReturnType<typeof sql>;

/**
 * percentage is numeric(9,4) in Postgres, and postgres.js hands a numeric
 * back as text (arbitrary precision, same reason bigint does) unless cast
 * -- ::float8 keeps this a real JS number the same way ::int already does
 * for the bigint sums elsewhere in db/queries/nl. wins/losses/draws are
 * plain smallint and need no cast.
 */
function metricValueExpr(metric: string): SqlFragment {
  switch (metric) {
    case 'wins': return sql`cs.wins`;
    case 'losses': return sql`cs.losses`;
    case 'draws': return sql`cs.draws`;
    case 'percentage': return sql`cs.percentage::float8`;
    default: throw new Error(`club_season metric "${metric}" is not recognised.`);
  }
}

/** Each condition reads one already-computed club_seasons column. "Made/missed finals" reads finals_played, which is NULL for a genuinely unrecorded season -- NULL satisfies neither > 0 nor = 0, the same "never treat absent as zero" rule the rest of this codebase applies. */
function conditionSql(cond: NlClubSeasonCondition): SqlFragment {
  switch (cond.kind) {
    case 'premier': return sql`cs.is_premier`;
    case 'wooden_spoon': return sql`cs.wooden_spoon`;
    case 'made_finals': return sql`cs.finals_played > 0`;
    case 'missed_finals': return sql`cs.finals_played = 0`;
  }
}

function scopeClauses(plan: NlQueryPlan): SqlFragment[] {
  const clauses: SqlFragment[] = [];
  if (plan.scope.clubFor) {
    clauses.push(sql`cs.club_id IN (SELECT id FROM clubs WHERE organization_id = ${plan.scope.clubFor.organizationId})`);
  }
  if (plan.scope.seasonMin !== undefined) clauses.push(sql`cs.season >= ${plan.scope.seasonMin}`);
  if (plan.scope.seasonMax !== undefined) clauses.push(sql`cs.season <= ${plan.scope.seasonMax}`);
  for (const cond of plan.clubSeasonConditions) clauses.push(conditionSql(cond));
  return clauses;
}

function foldAnd(clauses: SqlFragment[]): SqlFragment {
  if (clauses.length === 0) return sql`TRUE`;
  return clauses.reduce((acc, clause) => sql`${acc} AND ${clause}`);
}

function rankCutoff(agg: NlAggregation): number {
  return agg.kind === 'top_n' ? agg.n : 1;
}

const ROW_SELECT = sql`
  c.id AS "clubId", c.slug AS "clubSlug", c.name AS "clubName",
  cs.season, cs.played, cs.wins, cs.draws, cs.losses,
  cs.ladder_rank AS "ladderRank"
`;

/**
 * Answers a club_season plan: a plain list when there is no ranking
 * metric ("teams that won the wooden spoon"), or a ranked, tie-aware
 * answer when there is ("fewest wins by a premier") -- the same
 * list-vs-ranked split player-career.ts's answerPlayerCareer already
 * uses for the same reason (a conditions-only question has no metric to
 * rank by at all).
 */
export async function answerClubSeason(plan: NlQueryPlan, limit: number): Promise<NlAnswerPayload> {
  const where = foldAnd(scopeClauses(plan));
  if (!plan.metric) return answerList(where, limit);
  return answerRanked(plan, where, limit);
}

async function answerList(where: SqlFragment, limit: number): Promise<NlAnswerPayload> {
  const rows = await sql<(NlClubSeasonRow & { total: string })[]>`
    SELECT ${ROW_SELECT}, NULL::float8 AS value, count(*) OVER () AS total
      FROM club_seasons cs JOIN clubs c ON c.id = cs.club_id
     WHERE ${where}
     ORDER BY cs.season DESC, c.name
     LIMIT ${limit}
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = rows.map(({ total: _t, ...rest }) => rest);
  return { kind: 'club_season', lead: clean[0] ?? null, rows: clean, total };
}

async function answerRanked(plan: NlQueryPlan, where: SqlFragment, limit: number): Promise<NlAnswerPayload> {
  const value = metricValueExpr(plan.metric!);
  const direction = plan.agg.kind === 'min' ? sql.unsafe('ASC') : sql.unsafe('DESC');
  const n = rankCutoff(plan.agg);

  const rows = await sql<(NlClubSeasonRow & { total: string; rnk: number })[]>`
    WITH ranked AS (
      SELECT ${ROW_SELECT}, ${value} AS value,
             rank() OVER (ORDER BY ${value} ${direction})::int AS rnk
        FROM club_seasons cs JOIN clubs c ON c.id = cs.club_id
       WHERE ${where} AND ${value} IS NOT NULL
    )
    SELECT r.*, count(*) OVER () AS total
      FROM ranked r
     WHERE r.rnk <= ${n}
     ORDER BY r.value ${direction}, r.season DESC
     LIMIT ${limit}
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = rows.map(({ total: _t, rnk: _r, ...rest }) => rest);
  return { kind: 'club_season', lead: clean[0] ?? null, rows: clean, total };
}

import 'server-only';

import { sql } from '@/db/client';
import { coachSlug } from '@/lib/slugs';
import { type NlAggregation, type NlQueryPlan } from '@/search/nl/plan';
import type { NlAnswerPayload, NlCoachRecordRow } from '@/search/nl/answer-types';

type SqlFragment = ReturnType<typeof sql>;

/**
 * The coach_record grain: a coaching record derived from the canonical
 * per-match assignment, `match_coaches` JOIN `matches`.
 *
 * This is a PARAMETERISED GENERALISATION of db/queries/coaches.ts, not a
 * second derivation: the aggregate expressions below are the ones
 * getClubCoachRecords and getCoachRecordsByWinPct already use, with bound
 * parameters for the coach, the club organization, the season range, the
 * ranked metric, its threshold and the limit. `coaches.source_games_coached`
 * is evidence only (migration 087) and is read nowhere here.
 *
 * Two details are load-bearing and were taken from those functions rather
 * than re-decided:
 *
 *  - Draws are `m.winner_club_id IS NULL`, valid because the FROM clause
 *    starts at `match_coaches` and every join is INNER. (The board queries
 *    that start FROM `coaches` need the extra `m.id IS NOT NULL` guard,
 *    because there a coach with no matches has a NULL winner too.)
 *  - Win percentage is `(W + D/2) / G * 100`, the site convention, never a
 *    plain `W / G`. George Angus is 41 W / 2 D / 60 g = 70.00, where W/G
 *    would print 68.33.
 *
 * Club scope folds the whole `organization_id` lineage, exactly as the
 * club page does: a coach of Footscray counts on Western Bulldogs, and
 * nothing of Fitzroy's ever reaches Brisbane Lions, because a merger is a
 * different organisation.
 */

/**
 * The metric's value, read off the aggregate CTE. Every key is looked up
 * here rather than spliced, the same discipline NL_CAREER_COLUMNS applies:
 * a metric name reaching SQL as text from a question is exactly what this
 * closed switch exists to prevent.
 */
function metricValueExpr(metric: string): SqlFragment {
  switch (metric) {
    case 'games': return sql`t.games::float8`;
    case 'wins': return sql`t.wins::float8`;
    case 'draws': return sql`t.draws::float8`;
    case 'losses': return sql`t.losses::float8`;
    case 'finals': return sql`t.finals::float8`;
    case 'grand_finals': return sql`t."grandFinals"::float8`;
    case 'premierships': return sql`t.premierships::float8`;
    case 'seasons': return sql`t.seasons::float8`;
    case 'organizations': return sql`t.organizations::float8`;
    case 'win_pct': return sql`t."winPctValue"`;
    default: throw new Error(`coach_record metric "${metric}" is not recognised.`);
  }
}

function compareExpr(value: SqlFragment, op: string, bound: number): SqlFragment {
  switch (op) {
    case 'gte': return sql`${value} >= ${bound}`;
    case 'gt': return sql`${value} > ${bound}`;
    case 'lte': return sql`${value} <= ${bound}`;
    case 'lt': return sql`${value} < ${bound}`;
    case 'eq': return sql`${value} = ${bound}`;
    default: throw new Error(`coach_record comparison "${op}" is not recognised.`);
  }
}

function foldAnd(clauses: SqlFragment[]): SqlFragment {
  if (clauses.length === 0) return sql`TRUE`;
  return clauses.reduce((acc, clause) => sql`${acc} AND ${clause}`);
}

/**
 * Match-level scope. `match_coaches.club_id` is the RAW historical club
 * identity, so folding the lineage is this compiler's job and is never
 * assumed by the caller -- NlClubRef.organizationId is already the
 * lineage-level id, so no extra lookup is needed.
 */
function scopeClauses(plan: NlQueryPlan): SqlFragment[] {
  const clauses: SqlFragment[] = [];
  if (plan.coach) clauses.push(sql`mc.coach_id = ${plan.coach.id}`);
  if (plan.scope.clubFor) {
    clauses.push(sql`mc.club_id IN (SELECT id FROM clubs WHERE organization_id = ${plan.scope.clubFor.organizationId})`);
  }
  if (plan.scope.seasonMin !== undefined) clauses.push(sql`m.season >= ${plan.scope.seasonMin}`);
  if (plan.scope.seasonMax !== undefined) clauses.push(sql`m.season <= ${plan.scope.seasonMax}`);
  return clauses;
}

function totals(where: SqlFragment): SqlFragment {
  return sql`
    SELECT c.id AS "coachId", c.display_name AS "displayName",
           (c.player_id IS NULL) AS "coachOnly",
           c.player_id AS "playerId", p.slug AS "playerSlug",
           min(m.season)::int AS "firstSeason",
           max(m.season)::int AS "lastSeason",
           count(DISTINCT m.season)::int AS seasons,
           count(DISTINCT cl.organization_id)::int AS organizations,
           count(*)::int AS games,
           count(*) FILTER (WHERE m.winner_club_id = mc.club_id)::int AS wins,
           count(*) FILTER (WHERE m.winner_club_id IS NULL)::int AS draws,
           count(*) FILTER (
             WHERE m.winner_club_id IS NOT NULL AND m.winner_club_id <> mc.club_id
           )::int AS losses,
           count(*) FILTER (WHERE m.is_finals_series)::int AS finals,
           count(*) FILTER (WHERE m.round_type = 'grand_final')::int AS "grandFinals",
           count(*) FILTER (
             WHERE m.round_type = 'grand_final' AND m.winner_club_id = mc.club_id
           )::int AS premierships,
           round((
             (count(*) FILTER (WHERE m.winner_club_id = mc.club_id)
               + count(*) FILTER (WHERE m.winner_club_id IS NULL) * 0.5)
             * 100.0 / count(*)
           )::numeric, 2) AS "winPct",
           (
             (count(*) FILTER (WHERE m.winner_club_id = mc.club_id)
               + count(*) FILTER (WHERE m.winner_club_id IS NULL) * 0.5)
             * 100.0 / count(*)
           )::float8 AS "winPctValue"
      FROM match_coaches mc
      JOIN matches m ON m.id = mc.match_id
      JOIN coaches c ON c.id = mc.coach_id
      JOIN clubs cl ON cl.id = mc.club_id
      LEFT JOIN players p ON p.id = c.player_id
     WHERE ${where}
     GROUP BY c.id, c.display_name, c.player_id, p.slug
  `;
}

const ROW_SELECT = sql`
  t."coachId", t."displayName", t."coachOnly", t."playerId", t."playerSlug",
  t."firstSeason", t."lastSeason", t.seasons, t.organizations,
  t.games, t.wins, t.draws, t.losses, t.finals, t."grandFinals", t.premierships,
  t."winPct"
`;

type RawRow = Omit<NlCoachRecordRow, 'slug'> & { total: string };

/** `coaches` stores no slug, so the URL-readable form is derived the same way every coach route derives it. */
function withSlug(rows: RawRow[]): NlCoachRecordRow[] {
  return rows.map(({ total: _total, ...rest }) => ({ ...rest, slug: coachSlug(rest.displayName) }));
}

function rankCutoff(agg: NlAggregation): number {
  return agg.kind === 'top_n' ? agg.n : 1;
}

/**
 * The qualifying filters applied AFTER aggregation: the win-percentage
 * games qualifier, and the plan's own metric threshold. Both are bound
 * parameters against a metric looked up in the closed switch above.
 */
function havingClauses(plan: NlQueryPlan): SqlFragment[] {
  const clauses: SqlFragment[] = [];
  if (plan.coachQualifier) clauses.push(sql`t.games >= ${plan.coachQualifier.minGames}`);
  if (plan.metricCondition && plan.metric) {
    clauses.push(compareExpr(metricValueExpr(plan.metric), plan.metricCondition.op, plan.metricCondition.value));
  }
  return clauses;
}

export async function answerCoachRecord(plan: NlQueryPlan, limit: number): Promise<NlAnswerPayload> {
  const where = foldAnd(scopeClauses(plan));
  const having = foldAnd(havingClauses(plan));

  if (plan.agg.kind === 'count') return answerCount(where, having);
  if (plan.agg.kind === 'list' || plan.metric === null) return answerList(plan, where, having, limit);
  return answerRanked(plan, where, having, limit);
}

/** "How many coaches has Richmond had" -- the qualifying set's size, not a row list. */
async function answerCount(where: SqlFragment, having: SqlFragment): Promise<NlAnswerPayload> {
  const [row] = await sql<{ value: string }[]>`
    WITH t AS (${totals(where)})
    SELECT count(*) AS value FROM t WHERE ${having}
  `;
  return { kind: 'count', value: Number(row?.value ?? 0) };
}

/**
 * The unranked qualifying set. Ordered most-recently-in-charge first,
 * exactly as getClubCoachRecords orders the club page's own table, so the
 * same question asked two ways cannot come back in two different orders.
 */
async function answerList(
  plan: NlQueryPlan,
  where: SqlFragment,
  having: SqlFragment,
  limit: number,
): Promise<NlAnswerPayload> {
  const value = plan.metric ? metricValueExpr(plan.metric) : sql`NULL::float8`;
  const rows = await sql<RawRow[]>`
    WITH t AS (${totals(where)})
    SELECT ${ROW_SELECT}, ${value} AS value, count(*) OVER () AS total
      FROM t
     WHERE ${having}
     ORDER BY t."lastSeason" DESC, t."firstSeason" DESC, t."displayName"
     LIMIT ${limit}
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = withSlug(rows);
  return { kind: 'coach_record', lead: clean[0] ?? null, rows: clean, total };
}

/**
 * A ranked answer, with every row tied at the lead rank returned -- the
 * same `rank()` with no PARTITION BY every other grain uses, so a shared
 * coaching record is named as shared rather than silently reduced to
 * whichever holder sorted first.
 */
async function answerRanked(
  plan: NlQueryPlan,
  where: SqlFragment,
  having: SqlFragment,
  limit: number,
): Promise<NlAnswerPayload> {
  const value = metricValueExpr(plan.metric!);
  const direction = plan.agg.kind === 'min' ? sql.unsafe('ASC') : sql.unsafe('DESC');
  const n = rankCutoff(plan.agg);

  const rows = await sql<(RawRow & { rnk: number })[]>`
    WITH t AS (${totals(where)}),
    ranked AS (
      SELECT ${ROW_SELECT}, ${value} AS value,
             rank() OVER (ORDER BY ${value} ${direction})::int AS rnk
        FROM t
       WHERE ${having} AND ${value} IS NOT NULL
    )
    SELECT r.*, count(*) OVER () AS total
      FROM ranked r
     WHERE r.rnk <= ${n}
     ORDER BY r.value ${direction}, r."displayName"
     LIMIT ${limit}
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = withSlug(rows.map(({ rnk: _rnk, ...rest }) => rest));
  return { kind: 'coach_record', lead: clean[0] ?? null, rows: clean, total };
}

import 'server-only';

import { sql } from '@/db/client';
import { type NlAggregation, type NlQueryPlan } from '@/search/nl/plan';
import type { NlAnswerPayload, NlFamilyRow } from '@/search/nl/answer-types';

type SqlFragment = ReturnType<typeof sql>;

/**
 * The `family` grain (AFLDB-ISSUE-153 Stage 6, decision D6): a sibling
 * family, grouped by `player_relationships.family_key`.
 *
 * This is a PARAMETERISED GENERALISATION of getFamilyRecords
 * (db/queries/family-records.ts), not a second derivation -- the same
 * sibling-only population, the same id-keyed member union, the same
 * COALESCE(family_name, family_key) fallback -- with two additions the
 * page board does not need: a HAVING floor that excludes the 46 size-1
 * families (a family of one is not a family, §4.6), and a bound ranked
 * metric/threshold instead of the page's fixed combined_games DESC order.
 *
 * `family_members` unions both relationship sides and keeps only the
 * LINKED one, so an unmatched relative -- a name in player_relationships
 * with no player_id -- can never surface as a member (the D6 fail-closed
 * rule). Identity is the player id throughout, never the display name:
 * `ablett-0004` holds two distinct ids (4700, 4701) both named "Gary
 * Ablett", and the UNION keys on person_a/b_player_id, never on a name.
 */
const FAMILIES_CTE = sql`
  WITH family_names AS (
    SELECT family_key,
           max(family_name) FILTER (WHERE family_name IS NOT NULL) AS family_name
      FROM player_relationships
     WHERE relationship = 'sibling' AND family_key IS NOT NULL
     GROUP BY family_key
  ),
  family_members AS (
    SELECT family_key, person_a_player_id AS player_id
      FROM player_relationships
     WHERE relationship = 'sibling' AND family_key IS NOT NULL AND person_a_player_id IS NOT NULL
     UNION
    SELECT family_key, person_b_player_id AS player_id
      FROM player_relationships
     WHERE relationship = 'sibling' AND family_key IS NOT NULL AND person_b_player_id IS NOT NULL
  ),
  member_stats AS (
    SELECT fm.family_key, fm.player_id, p.display_name, p.slug,
           COALESCE(pcs.games, 0)::int AS games
      FROM family_members fm
      JOIN players p ON p.id = fm.player_id
      LEFT JOIN player_career_stats pcs ON pcs.player_id = fm.player_id
  ),
  t AS (
    SELECT ms.family_key AS "familyKey",
           COALESCE(fn.family_name, ms.family_key) AS "familyName",
           count(*)::int AS "linkedMembers",
           sum(ms.games)::int AS "combinedGames",
           jsonb_agg(
             jsonb_build_object(
               'playerId', ms.player_id, 'name', ms.display_name,
               'slug', ms.slug, 'games', ms.games
             ) ORDER BY ms.games DESC, ms.display_name
           ) AS members
      FROM member_stats ms
      LEFT JOIN family_names fn ON fn.family_key = ms.family_key
     GROUP BY ms.family_key, fn.family_name
    HAVING count(*) >= 2
  )
`;

function metricValueExpr(metric: string): SqlFragment {
  switch (metric) {
    case 'combined_games': return sql`t."combinedGames"::float8`;
    case 'linked_members': return sql`t."linkedMembers"::float8`;
    default: throw new Error(`family metric "${metric}" is not recognised.`);
  }
}

function compareExpr(value: SqlFragment, op: string, bound: number): SqlFragment {
  switch (op) {
    case 'gte': return sql`${value} >= ${bound}`;
    case 'gt': return sql`${value} > ${bound}`;
    case 'lte': return sql`${value} <= ${bound}`;
    case 'lt': return sql`${value} < ${bound}`;
    case 'eq': return sql`${value} = ${bound}`;
    default: throw new Error(`family comparison "${op}" is not recognised.`);
  }
}

function rankCutoff(agg: NlAggregation): number {
  return agg.kind === 'top_n' ? agg.n : 1;
}

const ROW_SELECT = sql`t."familyKey", t."familyName", t."linkedMembers", t."combinedGames", t.members`;

type RawRow = NlFamilyRow & { total: string; rnk?: number };

function clean(rows: RawRow[]): NlFamilyRow[] {
  return rows.map(({ total: _total, rnk: _rnk, ...rest }) => rest);
}

export async function answerFamily(plan: NlQueryPlan, limit: number): Promise<NlAnswerPayload> {
  if (plan.metricCondition && plan.metric) {
    return answerList(plan, limit);
  }
  return answerRanked(plan, limit);
}

/** C5: "families with three AFL players" -- the qualifying set, never a rank-one leader. */
async function answerList(plan: NlQueryPlan, limit: number): Promise<NlAnswerPayload> {
  const value = metricValueExpr(plan.metric!);
  const having = compareExpr(value, plan.metricCondition!.op, plan.metricCondition!.value);
  const rows = await sql<RawRow[]>`
    ${FAMILIES_CTE}
    SELECT ${ROW_SELECT}, ${value} AS value, count(*) OVER () AS total
      FROM t
     WHERE ${having}
     ORDER BY t."combinedGames" DESC, t."familyName"
     LIMIT ${limit}
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const rowsClean = clean(rows);
  return { kind: 'family', lead: rowsClean[0] ?? null, rows: rowsClean, total };
}

/**
 * C1: "biggest football family" (combined_games) or "which family has the
 * most AFL players" (linked_members) -- a ranked leader, with every family
 * tied at the lead value returned (rank() with no PARTITION BY, the same
 * tie machinery every other grain uses).
 */
async function answerRanked(plan: NlQueryPlan, limit: number): Promise<NlAnswerPayload> {
  const value = metricValueExpr(plan.metric!);
  const direction = plan.agg.kind === 'min' ? sql.unsafe('ASC') : sql.unsafe('DESC');
  const n = rankCutoff(plan.agg);

  const rows = await sql<RawRow[]>`
    ${FAMILIES_CTE},
    ranked AS (
      SELECT ${ROW_SELECT}, ${value} AS value,
             rank() OVER (ORDER BY ${value} ${direction})::int AS rnk
        FROM t
    )
    SELECT r.*, count(*) OVER () AS total
      FROM ranked r
     WHERE r.rnk <= ${n}
     ORDER BY r.value ${direction}, r."familyName"
     LIMIT ${limit}
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const rowsClean = clean(rows);
  return { kind: 'family', lead: rowsClean[0] ?? null, rows: rowsClean, total };
}

import 'server-only';

import { sql } from '@/db/client';
import { compileAxis } from '@/db/queries/grid-solver';
import { GRID_STATS, isGridStatKey } from '@/search/grid-solver-spec';
import {
  careerPredicatesOwnClubFor,
  NL_AWARDS,
  NL_CAREER_COLUMNS,
  NL_METRICS,
  type NlAggregation,
  type NlBoundary,
  type NlCareerCondition,
  type NlCompareOp,
  type NlQueryPlan,
} from '@/search/nl/plan';
import type { NlAnswerPayload, NlPlayerCareerRow } from '@/search/nl/answer-types';

type SqlFragment = ReturnType<typeof sql>;

const COMPARE_SQL: Record<NlCompareOp, string> = {
  gte: '>=', lte: '<=', gt: '>', lt: '<', eq: '=',
};

/** Career appearances for one organization across all historical club identities. */
function clubAppearanceCount(organizationId: number): SqlFragment {
  return sql`(SELECT count(DISTINCT pms.match_id)::int
                FROM player_match_stats pms
                JOIN clubs pcl ON pcl.id = pms.club_id
               WHERE pms.player_id = p.id AND pcl.organization_id = ${organizationId})`;
}

/**
 * The value expression for a player_career metric: a plain
 * player_career_stats column for the 8 precomputed stats
 * (always/era_limited in GRID_STATS' grain tagging), a live SUM over
 * player_match_stats for the 13 that have no precomputed total -- the
 * same grain-aware shape grid-solver.ts's careerStatValueExpr already
 * proves out for the grid catalogue -- or a count of linked
 * award_winners rows for an award_count metric (NL_AWARDS).
 */
function metricValueExpr(plan: NlQueryPlan): SqlFragment {
  const metric = plan.metric!;
  const periodSplit = plan.periodSplit;
  const def = NL_METRICS.player_career[metric];
  // Fail closed (AFLDB-ISSUE-256): validatePlan should already have refused
  // either case, but an entry whose statKey is not a GRID_STATS key would
  // otherwise reach GRID_STATS[...].grain as a TypeError, or sql.unsafe as
  // a column that does not exist.
  if (!def) throw new Error(`player_career metric "${metric}" is not recognised.`);
  if (def.kind === 'column' && def.statKey !== undefined && !isGridStatKey(def.statKey)) {
    throw new Error(`player_career metric "${metric}" has no stored statistic.`);
  }
  if (def.kind === 'award_count') {
    // count(*) is bigint in Postgres regardless of how small the count
    // is, and postgres.js hands a bigint back as text -- ::int keeps
    // this a number the same way NlPlayerCareerRow.value promises.
    const slug = NL_AWARDS[def.awardKey].slug;
    // `status = 'active'` (AFLDB-ISSUE-165 §4.3): an award count is a
    // football fact, and a voided winner row is an administrator saying the
    // record should never have existed. The same predicate the public awards
    // pages and the Grid Solver use, so the three never disagree about how
    // many times one player won one award.
    return sql`(SELECT count(*)::int FROM award_winners w
                  JOIN awards a ON a.id = w.award_id
                 WHERE a.slug = ${slug} AND w.player_id = p.id
                   AND w.status = 'active'
                   AND w.link_status_value IN ('unique', 'resolved'))`;
  }
  if (periodSplit && periodSplit !== 'FULL_MATCH') {
    let periodCondition = sql`period = 1`;
    if (periodSplit === 'Q2') periodCondition = sql`period = 2`;
    else if (periodSplit === 'Q3') periodCondition = sql`period = 3`;
    else if (periodSplit === 'Q4') periodCondition = sql`period = 4`;
    else if (periodSplit === 'H1') periodCondition = sql`period IN (1, 2)`;
    else if (periodSplit === 'H2') periodCondition = sql`period IN (3, 4)`;

    if (def.kind === 'column' && def.column === 'games') {
      return sql`(SELECT count(DISTINCT match_id)::int FROM player_match_period_stats WHERE player_id = p.id AND ${periodCondition})`;
    }
    const col = def.statKey ? sql.unsafe(def.statKey) : (def.kind === 'column' ? sql.unsafe(def.column) : sql.unsafe('0'));
    return sql`(SELECT sum(${col})::int FROM player_match_period_stats WHERE player_id = p.id AND ${periodCondition})`;
  }
  if (plan.scope.clubFor) {
    const organizationId = plan.scope.clubFor.organizationId;
    if (metric === 'games') {
      return clubAppearanceCount(organizationId);
    }
    if (def.statKey) {
      return sql`(SELECT sum(pms.${sql.unsafe(def.statKey)})::int
                    FROM player_match_stats pms
                    JOIN clubs pcl ON pcl.id = pms.club_id
                   WHERE pms.player_id = p.id AND pcl.organization_id = ${organizationId})`;
    }
  }
  if (def.statKey && GRID_STATS[def.statKey].grain === 'live_only') {
    // sum() over a smallint column is bigint too, same reason.
    return sql`(SELECT sum(${sql.unsafe(def.statKey)})::int FROM player_match_stats WHERE player_id = p.id)`;
  }
  return def.kind === 'column' ? sql`${sql.unsafe(def.column)}` : sql`0`;
}

/** A single career condition compiled to a bound predicate -- the only path a condition's threshold reaches SQL. */
function conditionSql(cond: NlCareerCondition, plan: NlQueryPlan): SqlFragment {
  const op = sql.unsafe(COMPARE_SQL[cond.op]);
  if (cond.kind === 'column') {
    if (cond.column === 'games' && plan.scope.clubFor) {
      return sql`${clubAppearanceCount(plan.scope.clubFor.organizationId)} ${op} ${cond.value}`;
    }
    const column = sql.unsafe(NL_CAREER_COLUMNS[cond.column]);
    return sql`${column} ${op} ${cond.value}`;
  }
  const slug = NL_AWARDS[cond.awardKey].slug;
  return sql`(SELECT count(*) FROM award_winners w
                JOIN awards a ON a.id = w.award_id
               WHERE a.slug = ${slug} AND w.player_id = p.id
                 AND w.status = 'active'
                 AND w.link_status_value IN ('unique', 'resolved')) ${op} ${cond.value}`;
}

/**
 * "Debuted in a grand final" / "last game was a final". Debut reads
 * career_game_no = 1, the same shape debut_club (grid-solver.ts) already
 * proves out. Last game reads match_date = c.last_match_date rather than
 * career_game_no = c.games: career_game_no is nullable (not every source
 * row carries it), where last_match_date -- a plain min/max over
 * match_date -- always does.
 */
function boundarySql(boundary: NlBoundary): SqlFragment {
  const finalCondition = boundary.where === 'grand_final'
    ? sql`m.round_type = 'grand_final'`
    : sql`m.is_finals_series`;
  if (boundary.event === 'debut') {
    return sql`EXISTS (SELECT 1 FROM player_match_stats pms
                          JOIN matches m ON m.id = pms.match_id
                         WHERE pms.player_id = p.id AND pms.career_game_no = 1 AND ${finalCondition})`;
  }
  return sql`EXISTS (SELECT 1 FROM player_match_stats pms
                        JOIN matches m ON m.id = pms.match_id
                       WHERE pms.player_id = p.id AND m.match_date = c.last_match_date AND ${finalCondition})`;
}

/**
 * AFLDB-ISSUE-201: "since"/"before"/"in" YEAR beside a boundary names when
 * the player's TRUE debut/last game happened, not a window to search
 * matches in before picking one. c.debut_season/c.final_season are
 * precomputed, single-valued facts about that real boundary (the same
 * columns careerRowSelect already projects and debuted_between already
 * filters in grid-solver.ts), so ANDing a range onto one of them can only
 * additionally require the already-fixed true boundary to fall in range --
 * it cannot change which game the boundary is, unlike a range applied to
 * player_match_stats/matches rows before the boundary is chosen.
 */
function boundarySeasonWhere(boundary: NlBoundary, scope: NlQueryPlan['scope']): SqlFragment[] {
  const seasonColumn = boundary.event === 'debut' ? sql`c.debut_season` : sql`c.final_season`;
  const clauses: SqlFragment[] = [];
  if (scope.seasonMin !== undefined) clauses.push(sql`${seasonColumn} >= ${scope.seasonMin}`);
  if (scope.seasonMax !== undefined) clauses.push(sql`${seasonColumn} <= ${scope.seasonMax}`);
  return clauses;
}

function conditionsWhere(plan: NlQueryPlan): SqlFragment[] {
  const clauses: SqlFragment[] = plan.careerConditions.map((condition) => conditionSql(condition, plan));
  if (plan.boundary) {
    clauses.push(boundarySql(plan.boundary));
    clauses.push(...boundarySeasonWhere(plan.boundary, plan.scope));
  }
  // A single named player ("Nick Dal Santo most games", "Dusty's debut
  // was a grand final"). Pre-existing gap, not new: player_career had no
  // player filter at all before CAREER_ONLY_METRICS started routing
  // named-player questions here (games/premierships/wins/losses/draws/
  // brownlow_medals/clubs_played have no player_game equivalent), but the
  // boundary and all_australian_selections branches could already reach
  // this grain with a player named, and would have silently ranked
  // everyone instead of answering about the one player asked about. Found
  // by executing "Nick Dal Santo most games" end to end against real
  // data, not just checking the plan shape -- it returned Scott
  // Pendlebury's 440 games, the outright leader, rather than Dal Santo's
  // own 322.
  if (plan.player) clauses.push(sql`p.id = ${plan.player.id}`);
  // An ambiguous surname ("Ablett most goals") -- ranks across every
  // plausible candidate instead of declining. See NlMatchScope.playerIdIn.
  if (plan.scope.playerIdIn) clauses.push(sql`p.id = ANY(${plan.scope.playerIdIn})`);
  // The generic club filter, emitted unless a predicate already carries the
  // club as a builder parameter (first_kick_goal_for_club scopes the FEAT to
  // the club, which implies playing for it -- repeating it here would state
  // the same fact twice). Keyed on ownership rather than on "no predicates
  // at all": under the old count-based guard a plan mixing a club with a
  // club-blind predicate reached SQL with no club constraint whatsoever.
  // validatePlan now refuses that combination, and this is the second half
  // of the same invariant (AFLDB-ISSUE-110 finding B).
  if (plan.scope.clubFor && !careerPredicatesOwnClubFor(plan.careerPredicates)) {
    clauses.push(sql`EXISTS (
      SELECT 1 FROM player_match_stats pms
      JOIN clubs pcl ON pcl.id = pms.club_id
      WHERE pms.player_id = p.id AND pcl.organization_id = ${plan.scope.clubFor.organizationId}
    )`);
  }
  return clauses;
}

function foldAnd(clauses: SqlFragment[]): SqlFragment {
  if (clauses.length === 0) return sql`TRUE`;
  return clauses.reduce((acc, clause) => sql`${acc} AND ${clause}`);
}

/**
 * The `games` field is rendered directly under a visible Games heading.
 * A club-scoped career row therefore carries appearances for that
 * organization lineage; an unscoped row retains the whole-career total.
 */
function projectedGames(plan: NlQueryPlan): SqlFragment {
  return plan.scope.clubFor
    ? clubAppearanceCount(plan.scope.clubFor.organizationId)
    : sql`c.games`;
}

function careerRowSelect(games: SqlFragment): SqlFragment {
  return sql`
    p.id AS "playerId", p.slug, p.display_name AS "displayName",
    ${games} AS games, c.debut_season AS "debutSeason", c.final_season AS "finalSeason",
    (SELECT string_agg(DISTINCT cl.short_name, ', ' ORDER BY cl.short_name)
       FROM player_clubs pc JOIN clubs cl ON cl.id = pc.club_id
      WHERE pc.player_id = p.id) AS "clubNames"
  `;
}

/**
 * Answers a player_career plan: a plain list when there is no ranking
 * metric ("300 games, no premiership"), or a ranked, tie-aware answer
 * when there is ("most brownlow votes without winning one") -- the same
 * rank()-with-ties-included-past-the-cutoff shape records.ts's
 * getCareerRecord uses, generalised to any allowlisted metric and any
 * number of extra conditions.
 *
 * Career predicates (GridAxisState entries) are compiled through the grid
 * solver's own 107-builder catalogue (compileAxis) rather than recompiling
 * any of it. Each compiled predicate is a bare boolean fragment over the
 * same `p`/`c` aliases this file's queries already use, so predicates AND
 * plain conditions AND the named-player pin all fold into one WHERE --
 * the earlier split path through solvePredicates dropped everything
 * except the predicates ("did Dustin Martin kick a goal with his first
 * kick" listed every holder instead of answering about him).
 */
export async function answerPlayerCareer(
  plan: NlQueryPlan,
  limit: number,
): Promise<NlAnswerPayload> {
  const clauses = conditionsWhere(plan);
  for (const axis of plan.careerPredicates) clauses.push(compileAxis(axis));
  const extraWhere = foldAnd(clauses);

  if (!plan.metric) {
    return answerList(plan, extraWhere, limit);
  }

  return answerRanked(plan, extraWhere, limit);
}

async function answerList(
  plan: NlQueryPlan,
  extraWhere: SqlFragment,
  limit: number,
): Promise<NlAnswerPayload> {
  const games = projectedGames(plan);
  const rows = await sql<(NlPlayerCareerRow & { total: string })[]>`
    SELECT ${careerRowSelect(games)}, NULL::int AS value, count(*) OVER () AS total
      FROM players p JOIN player_career_stats c ON c.player_id = p.id
     WHERE ${extraWhere}
     ORDER BY ${games} DESC, p.sort_name
     LIMIT ${limit}
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = rows.map(({ total: _t, ...rest }) => rest);
  return { kind: 'player_career', lead: clean[0] ?? null, rows: clean, total };
}

async function answerRanked(
  plan: NlQueryPlan,
  extraWhere: SqlFragment,
  limit: number,
): Promise<NlAnswerPayload> {
  const value = metricValueExpr(plan);
  const games = projectedGames(plan);
  const direction = plan.agg.kind === 'min' ? sql.unsafe('ASC') : sql.unsafe('DESC');
  const n = rankCutoff(plan.agg);

  const rows = await sql<(NlPlayerCareerRow & { total: string; rnk: number })[]>`
    WITH ranked AS (
      SELECT ${careerRowSelect(games)}, ${value} AS value,
             rank() OVER (ORDER BY ${value} ${direction})::int AS rnk
        FROM players p JOIN player_career_stats c ON c.player_id = p.id
       WHERE ${extraWhere} AND ${value} IS NOT NULL
    )
    SELECT r.*, count(*) OVER () AS total
      FROM ranked r
     WHERE r.rnk <= ${n}
     ORDER BY r.value ${direction}, r."displayName"
     LIMIT ${limit}
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = rows.map(({ total: _t, rnk: _r, ...rest }) => rest);
  return { kind: 'player_career', lead: clean[0] ?? null, rows: clean, total };
}

function rankCutoff(agg: NlAggregation): number {
  return agg.kind === 'top_n' ? agg.n : 1;
}

import 'server-only';

import { sql } from '@/db/client';
import { NL_METRICS, type NlAggregation, type NlCompareOp, type NlMatchScope, type NlMatchType, type NlQueryPlan } from '@/search/nl/plan';
import type { NlAnswerPayload, NlPlayerGameRow } from '@/search/nl/answer-types';

type SqlFragment = ReturnType<typeof sql>;

/** Closed op -> SQL map, the same allowlist-then-bind discipline player-career.ts's COMPARE_SQL follows; the value is always a bound parameter. */
const COMPARE_SQL: Record<NlCompareOp, string> = {
  gte: '>=', lte: '<=', gt: '>', lt: '<', eq: '=',
};

/** player_game NL_METRICS entries are all 'column' kind with the bare player_match_stats column name (goals, disposals, brownlow_votes, ...) as `.column` -- there is no grain branching here, unlike player_career: every one of the 21 GRID_STATS is a real column on player_match_stats. */
function metricColumn(metric: string): string {
  const def = NL_METRICS.player_game[metric];
  if (def.kind !== 'column') throw new Error(`player_game metric "${metric}" has no column.`);
  return def.column;
}

/**
 * 'finals' is a synthetic "any final" reading with no matching round_type
 * value; every other NlMatchType (including 'home_and_away') is a literal
 * enum member, bound and cast the same way search.ts's own round_type
 * lookup already does.
 */
function matchTypeSql(matchType: NlMatchType | undefined): SqlFragment {
  if (!matchType) return sql`TRUE`;
  if (matchType === 'finals') return sql`m.is_finals_series`;
  return sql`m.round_type = ${matchType}::round_type`;
}

/** WHERE clauses shared by both modes -- club/opponent/venue/season/match-type scope, plus an optional player filter (mode 'single' always has one; mode 'sum' may or may not). */
function scopeClauses(scope: NlMatchScope, playerId: number | undefined, debutGame = false): SqlFragment[] {
  const clauses: SqlFragment[] = [];
  if (playerId) clauses.push(sql`s.player_id = ${playerId}`);
  if (debutGame) clauses.push(sql`s.career_game_no = 1`);
  // An ambiguous surname ranking across every plausible candidate rather
  // than declining -- see NlMatchScope.playerIdIn. validatePlan keeps
  // this and `playerId` mutually exclusive, so only one of the two ever
  // fires for a given plan.
  if (scope.playerIdIn) clauses.push(sql`s.player_id = ANY(${scope.playerIdIn})`);
  if (scope.clubFor) {
    clauses.push(sql`s.club_id IN (SELECT id FROM clubs WHERE organization_id = ${scope.clubFor.organizationId})`);
  }
  if (scope.clubAgainst) {
    // The other side of the match from the player's own club, the same
    // CASE getPlayerMatches (players.ts) and getMatchRecord (records.ts)
    // already use to find an opponent without a stored opponent column.
    clauses.push(sql`
      (CASE WHEN m.home_club_id = s.club_id THEN m.away_club_id ELSE m.home_club_id END)
        IN (SELECT id FROM clubs WHERE organization_id = ${scope.clubAgainst.organizationId})
    `);
  }
  if (scope.matchup) {
    clauses.push(sql`
      (
        (m.home_club_id IN (SELECT id FROM clubs WHERE organization_id = ${scope.matchup.clubA.organizationId})
         AND m.away_club_id IN (SELECT id FROM clubs WHERE organization_id = ${scope.matchup.clubB.organizationId}))
        OR
        (m.home_club_id IN (SELECT id FROM clubs WHERE organization_id = ${scope.matchup.clubB.organizationId})
         AND m.away_club_id IN (SELECT id FROM clubs WHERE organization_id = ${scope.matchup.clubA.organizationId}))
      )
    `);
  }
  if (scope.venue) clauses.push(sql`m.venue_id = ${scope.venue.id}`);
  if (scope.seasonMin !== undefined) clauses.push(sql`m.season >= ${scope.seasonMin}`);
  if (scope.seasonMax !== undefined) clauses.push(sql`m.season <= ${scope.seasonMax}`);
  if (scope.roundNumber !== undefined) clauses.push(sql`m.round_number = ${scope.roundNumber}`);
  clauses.push(matchTypeSql(scope.matchType));
  return clauses;
}

function foldAnd(clauses: SqlFragment[]): SqlFragment {
  if (clauses.length === 0) return sql`TRUE`;
  return clauses.reduce((acc, clause) => sql`${acc} AND ${clause}`);
}

function rankCutoff(agg: NlAggregation): number {
  return agg.kind === 'top_n' ? agg.n : 1;
}

/**
 * How deep the rank filter reaches. A metric-condition list wants EVERY
 * qualifying row (the threshold is the filter; collapsing a list to rank
 * one was the ISSUE-110 silent-threshold defect), so the cutoff opens to
 * the display limit's own cap instead of 1.
 */
function rankDepth(plan: NlQueryPlan): number {
  return plan.metricCondition ? 2147483647 : rankCutoff(plan.agg);
}

/**
 * Answers a player_game plan. Mode 'single' ranks individual match
 * performances (ties included, the same rank()-with-ties discipline as
 * every other grain here) -- "dusty's highest disposal game", "most goals
 * in a grand final at the MCG since 1980". Mode 'sum' ranks each player's
 * scoped career total instead -- "most goals against Carlton" -- since a
 * cumulative total across many games has no single match to point at.
 */
export async function answerPlayerGame(plan: NlQueryPlan, limit: number): Promise<NlAnswerPayload> {
  return plan.mode === 'sum' ? answerSum(plan, limit) : answerSingle(plan, limit);
}

async function answerSingle(plan: NlQueryPlan, limit: number): Promise<NlAnswerPayload> {
  const value = sql`${sql.unsafe(`s.${metricColumn(plan.metric!)}`)}`;
  const direction = plan.agg.kind === 'min' ? sql.unsafe('ASC') : sql.unsafe('DESC');
  const n = rankDepth(plan);
  const clauses: SqlFragment[] = [...scopeClauses(plan.scope, plan.player?.id, plan.debutGame), sql`${value} IS NOT NULL`];
  // Mode 'single': the threshold qualifies each individual performance.
  // Applied inside the ranked CTE, before any ranking work, alongside the
  // IS NOT NULL above -- a NULL statistic is "not recorded" and never
  // qualifies, even against lte/lt/eq 0.
  if (plan.metricCondition) {
    clauses.push(sql`${value} ${sql.unsafe(COMPARE_SQL[plan.metricCondition.op])} ${plan.metricCondition.value}`);
  }
  const where = foldAnd(clauses);

  let statsTarget = sql`player_match_stats s`;
  if (plan.periodSplit && plan.periodSplit !== 'FULL_MATCH') {
    let periodCondition = sql`period = 1`;
    if (plan.periodSplit === 'Q2') periodCondition = sql`period = 2`;
    else if (plan.periodSplit === 'Q3') periodCondition = sql`period = 3`;
    else if (plan.periodSplit === 'Q4') periodCondition = sql`period = 4`;
    else if (plan.periodSplit === 'H1') periodCondition = sql`period IN (1, 2)`;
    else if (plan.periodSplit === 'H2') periodCondition = sql`period IN (3, 4)`;
    const col = sql.unsafe(metricColumn(plan.metric!));
    statsTarget = sql`(SELECT player_id, match_id, club_id, sum(${col})::int AS ${col} FROM player_match_period_stats WHERE ${periodCondition} GROUP BY player_id, match_id, club_id) s`;
  }

  const rows = await sql<(NlPlayerGameRow & { total: string; rnk: number })[]>`
    WITH ranked AS (
      SELECT p.id AS "playerId", p.slug AS "playerSlug", p.display_name AS "playerName",
             ${value} AS value,
             m.id AS "matchId", m.season, m.round_type AS "roundType", m.round_number AS "roundNumber",
             m.match_date AS "matchDate",
             cl.name AS "clubName", opp.name AS "opponentName",
             COALESCE(v.canonical_name, m.venue_raw) AS "venueName",
             m.home_score AS "homeScore", m.away_score AS "awayScore",
             NULL::int AS games,
             rank() OVER (ORDER BY ${value} ${direction})::int AS rnk
        FROM ${statsTarget}
        JOIN players p ON p.id = s.player_id
        JOIN matches m ON m.id = s.match_id
        JOIN clubs cl ON cl.id = s.club_id
        JOIN clubs opp ON opp.id = CASE WHEN m.home_club_id = s.club_id THEN m.away_club_id ELSE m.home_club_id END
        LEFT JOIN venues v ON v.id = m.venue_id
       WHERE ${where}
    )
    SELECT r.*, count(*) OVER () AS total
      FROM ranked r
     WHERE r.rnk <= ${n}
     ORDER BY r.value ${direction}, r."matchDate", r."matchId", r."playerId"
     LIMIT ${limit}
  `;
  return toPayload(rows);
}

async function answerSum(plan: NlQueryPlan, limit: number): Promise<NlAnswerPayload> {
  const statColumn = sql.unsafe(metricColumn(plan.metric!));
  const direction = plan.agg.kind === 'min' ? sql.unsafe('ASC') : sql.unsafe('DESC');
  const n = rankDepth(plan);
  const where = foldAnd(scopeClauses(plan.scope, plan.player?.id, plan.debutGame));
  // Mode 'sum': the threshold qualifies the player's aggregate across the
  // fully scoped match set, so it is a HAVING predicate AFTER aggregation.
  // A player with no non-NULL row in scope forms no group and can never
  // qualify -- NULL stays "not recorded", not zero.
  const having = plan.metricCondition
    ? sql`HAVING sum(${statColumn}) ${sql.unsafe(COMPARE_SQL[plan.metricCondition.op])} ${plan.metricCondition.value}`
    : sql``;

  let statsTarget = sql`player_match_stats s`;
  if (plan.periodSplit && plan.periodSplit !== 'FULL_MATCH') {
    let periodCondition = sql`period = 1`;
    if (plan.periodSplit === 'Q2') periodCondition = sql`period = 2`;
    else if (plan.periodSplit === 'Q3') periodCondition = sql`period = 3`;
    else if (plan.periodSplit === 'Q4') periodCondition = sql`period = 4`;
    else if (plan.periodSplit === 'H1') periodCondition = sql`period IN (1, 2)`;
    else if (plan.periodSplit === 'H2') periodCondition = sql`period IN (3, 4)`;
    statsTarget = sql`(SELECT player_id, match_id, club_id, ${statColumn} FROM player_match_period_stats WHERE ${periodCondition}) s`;
  }

  const rows = await sql<(NlPlayerGameRow & { total: string; rnk: number })[]>`
    WITH totals AS (
      SELECT s.player_id, sum(${statColumn})::int AS value, count(DISTINCT s.match_id)::int AS games
        FROM ${statsTarget}
        JOIN matches m ON m.id = s.match_id
       WHERE ${where} AND ${statColumn} IS NOT NULL
       GROUP BY s.player_id
       ${having}
    ),
    ranked AS (
      SELECT t.player_id, t.value, t.games,
             rank() OVER (ORDER BY t.value ${direction})::int AS rnk
        FROM totals t
    )
    SELECT p.id AS "playerId", p.slug AS "playerSlug", p.display_name AS "playerName",
           r.value, r.games,
           NULL::int AS "matchId", NULL::int AS season,
           NULL::text AS "roundType", NULL::int AS "roundNumber", NULL::date AS "matchDate",
           NULL::text AS "clubName", NULL::text AS "opponentName", NULL::text AS "venueName",
           NULL::int AS "homeScore", NULL::int AS "awayScore",
           r.rnk, count(*) OVER () AS total
      FROM ranked r
      JOIN players p ON p.id = r.player_id
     WHERE r.rnk <= ${n}
     ORDER BY r.value ${direction}, p.sort_name, p.id
     LIMIT ${limit}
  `;
  return toPayload(rows);
}

function toPayload(rows: (NlPlayerGameRow & { total: string; rnk: number })[]): NlAnswerPayload {
  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = rows.map(({ total: _t, rnk: _r, ...rest }) => rest);
  return { kind: 'player_game', lead: clean[0] ?? null, rows: clean, total };
}

import 'server-only';

import { sql } from '@/db/client';
import { GRID_STATS } from '@/search/grid-solver-spec';
import { NL_METRICS, type NlAggregation, type NlCompareOp, type NlQueryPlan } from '@/search/nl/plan';
import type { NlAnswerPayload, NlPlayerSeasonRow } from '@/search/nl/answer-types';

type SqlFragment = ReturnType<typeof sql>;

/**
 * The value expression for a player_season metric, grain-aware like
 * player-career.ts's metricValueExpr: player_season_stats precomputes a
 * real column for the 8 'always'/'era_limited' stats plus games/wins/
 * brownlow_votes, but the 13 'live_only' stats (migration 007 never
 * precomputed a season total for them) have no such column at all -- a
 * plain `sql.unsafe('s.clangers')` would reference a column that does not
 * exist. Those fall back to a correlated SUM over player_match_stats for
 * the same player and season, the same shape seasonStatAtLeast in
 * grid-solver.ts already proves out for the grid catalogue.
 */
function metricValueExpr(metric: string): SqlFragment {
  const def = NL_METRICS.player_season[metric];
  if (def.kind !== 'column') throw new Error(`player_season metric "${metric}" has no column.`);
  if (def.statKey && GRID_STATS[def.statKey].grain === 'live_only') {
    // sum() over a smallint column is bigint in Postgres, and postgres.js
    // hands a bigint back as text -- ::int keeps this a real number, the
    // same fix player-career.ts's metricValueExpr already needed.
    return sql`(SELECT sum(${sql.unsafe(def.statKey)})::int FROM player_match_stats pms
                  JOIN matches m2 ON m2.id = pms.match_id
                 WHERE pms.player_id = s.player_id AND m2.season = s.season)`;
  }
  return sql`${sql.unsafe(`s.${def.column}`)}`;
}

function rankCutoff(agg: NlAggregation): number {
  return agg.kind === 'top_n' ? agg.n : 1;
}

/** Closed op -> SQL map; same allowlist-then-bind discipline as player-career.ts's COMPARE_SQL. */
const COMPARE_SQL: Record<NlCompareOp, string> = {
  gte: '>=', lte: '<=', gt: '>', lt: '<', eq: '=',
};

/**
 * A metric-condition list returns every qualifying season row, so the
 * rank filter opens up instead of collapsing the list to one leader --
 * the ISSUE-110 silent-threshold defect.
 */
function rankDepth(plan: NlQueryPlan): number {
  return plan.metricCondition ? 2147483647 : rankCutoff(plan.agg);
}

function isLiveOnlyMetric(metric: string): boolean {
  const def = NL_METRICS.player_season[metric];
  return def.kind === 'column' && def.statKey !== undefined && GRID_STATS[def.statKey].grain === 'live_only';
}

/**
 * Answers a player_season plan: player_season_stats is true player+season
 * grain (migration 015) -- a season total belongs to the player, not to
 * one club, so a mid-season transfer is never split into two smaller
 * totals. A club scope ("goals by a Richmond player in 2017") therefore
 * narrows WHICH players are eligible via the club-grained sibling table
 * (player_club_season_stats: did they play at least one game for that
 * club that season) without changing which total they are ranked on.
 */
export async function answerPlayerSeason(plan: NlQueryPlan, limit: number): Promise<NlAnswerPayload> {
  const value = metricValueExpr(plan.metric!);
  const liveOnly = isLiveOnlyMetric(plan.metric!);
  const direction = plan.agg.kind === 'min' ? sql.unsafe('ASC') : sql.unsafe('DESC');
  const n = rankDepth(plan);

  const clauses: SqlFragment[] = [];
  if (plan.player) clauses.push(sql`s.player_id = ${plan.player.id}`);
  // An ambiguous surname ranking across every plausible candidate rather
  // than declining -- see NlMatchScope.playerIdIn. validatePlan keeps
  // this and `plan.player` mutually exclusive.
  if (plan.scope.playerIdIn) clauses.push(sql`s.player_id = ANY(${plan.scope.playerIdIn})`);
  if (plan.scope.seasonMin !== undefined) clauses.push(sql`s.season >= ${plan.scope.seasonMin}`);
  if (plan.scope.seasonMax !== undefined) clauses.push(sql`s.season <= ${plan.scope.seasonMax}`);
  if (plan.scope.clubFor) {
    clauses.push(sql`s.player_id IN (
      SELECT pcs.player_id FROM player_club_season_stats pcs
       WHERE pcs.season = s.season
         AND pcs.club_id IN (SELECT id FROM clubs WHERE organization_id = ${plan.scope.clubFor.organizationId})
    )`);
  }
  clauses.push(liveOnly ? sql`mt.value IS NOT NULL` : sql`${value} IS NOT NULL`);
  // The season threshold compares the player's SEASON AGGREGATE -- for a
  // precomputed column that is the stored season total, for a live_only
  // metric it is metric_totals' summed value, both already
  // post-aggregation. NULL stays excluded by the IS NOT NULL above, so
  // "not recorded" can never qualify as zero.
  if (plan.metricCondition) {
    const op = sql.unsafe(COMPARE_SQL[plan.metricCondition.op]);
    clauses.push(sql`${liveOnly ? sql`mt.value` : value} ${op} ${plan.metricCondition.value}`);
  }
  const where = clauses.reduce((acc, clause) => sql`${acc} AND ${clause}`, sql`TRUE`);

  if (liveOnly) {
    const def = NL_METRICS.player_season[plan.metric!];
    if (def.kind !== 'column' || def.statKey === undefined) {
      throw new Error(`player_season metric "${plan.metric}" has no live stat key.`);
    }
    const totalClauses: SqlFragment[] = [];
    if (plan.player) totalClauses.push(sql`pms.player_id = ${plan.player.id}`);
    if (plan.scope.playerIdIn) totalClauses.push(sql`pms.player_id = ANY(${plan.scope.playerIdIn})`);
    if (plan.scope.seasonMin !== undefined) totalClauses.push(sql`m.season >= ${plan.scope.seasonMin}`);
    if (plan.scope.seasonMax !== undefined) totalClauses.push(sql`m.season <= ${plan.scope.seasonMax}`);
    const totalsWhere = totalClauses.reduce((acc, clause) => sql`${acc} AND ${clause}`, sql`TRUE`);

    const liveRows = await sql<(NlPlayerSeasonRow & { total: string; rnk: number })[]>`
      WITH metric_totals AS (
        SELECT pms.player_id, m.season, sum(${sql.unsafe(def.statKey)})::int AS value
          FROM player_match_stats pms
          JOIN matches m ON m.id = pms.match_id
         WHERE ${totalsWhere}
         GROUP BY pms.player_id, m.season
        HAVING sum(${sql.unsafe(def.statKey)}) IS NOT NULL
      ), ranked AS (
        SELECT p.id AS "playerId", p.slug, p.display_name AS "displayName",
               mt.value, s.season, s.games,
               cl.name AS "clubName", cl.slug AS "clubSlug",
               rank() OVER (ORDER BY mt.value ${direction})::int AS rnk
          FROM metric_totals mt
          JOIN player_season_stats s ON s.player_id = mt.player_id AND s.season = mt.season
          JOIN players p ON p.id = s.player_id
          LEFT JOIN clubs cl ON cl.id = s.primary_club_id
         WHERE ${where}
      )
      SELECT r.*, count(*) OVER () AS total
        FROM ranked r
       WHERE r.rnk <= ${n}
       ORDER BY r.value ${direction}, r.season, r."displayName", r."playerId"
       LIMIT ${limit}
    `;
    const liveTotal = liveRows[0] ? Number(liveRows[0].total) : 0;
    const liveClean = liveRows.map(({ total: _t, rnk: _r, ...rest }) => rest);
    return { kind: 'player_season', lead: liveClean[0] ?? null, rows: liveClean, total: liveTotal };
  }

  const rows = await sql<(NlPlayerSeasonRow & { total: string; rnk: number })[]>`
    WITH ranked AS (
      SELECT p.id AS "playerId", p.slug, p.display_name AS "displayName",
             ${value} AS value, s.season, s.games,
             cl.name AS "clubName", cl.slug AS "clubSlug",
             rank() OVER (ORDER BY ${value} ${direction})::int AS rnk
        FROM player_season_stats s
        JOIN players p ON p.id = s.player_id
        LEFT JOIN clubs cl ON cl.id = s.primary_club_id
       WHERE ${where}
    )
    SELECT r.*, count(*) OVER () AS total
      FROM ranked r
     WHERE r.rnk <= ${n}
     ORDER BY r.value ${direction}, r.season, r."displayName", r."playerId"
     LIMIT ${limit}
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = rows.map(({ total: _t, rnk: _r, ...rest }) => rest);
  return { kind: 'player_season', lead: clean[0] ?? null, rows: clean, total };
}

import 'server-only';

import { sql } from '@/db/client';
import { type NlAggregation, type NlMatchScope, type NlMatchType, type NlQueryPlan } from '@/search/nl/plan';
import type { NlAnswerPayload, NlTeamAggregateRow, NlTeamMatchRow } from '@/search/nl/answer-types';

type SqlFragment = ReturnType<typeof sql>;

/**
 * Every match, twice -- once from each club's own perspective. `matches`
 * stores home/away, not for/against, so this CTE is what turns "Richmond
 * v Carlton, Richmond home, 90-70" into two rows: Richmond's (score_for
 * 90, score_against 70, won) and Carlton's (score_for 70, score_against
 * 90, lost) -- the same reframing getPlayerMatches (players.ts) and
 * getMatchRecord (records.ts) already do with a CASE expression, done
 * once here as a real row set so every metric can filter/rank over it
 * uniformly instead of repeating the CASE per metric.
 */
const SIDES = sql`
  SELECT m.id AS match_id, m.season, m.round_type, m.round_number, m.is_finals_series,
         m.match_date, m.venue_id, m.attendance, m.winner_club_id,
         m.winner_club_id AS final_winner_club_id,
         m.home_club_id AS club_id, m.away_club_id AS opponent_id,
         m.home_score AS score_for, m.away_score AS score_against,
         hq.points AS q3_score_for, aq.points AS q3_score_against
    FROM matches m
    LEFT JOIN match_period_scores hq ON hq.match_id = m.id AND hq.club_id = m.home_club_id AND hq.period = 3
    LEFT JOIN match_period_scores aq ON aq.match_id = m.id AND aq.club_id = m.away_club_id AND aq.period = 3
  UNION ALL
  SELECT m.id, m.season, m.round_type, m.round_number, m.is_finals_series,
         m.match_date, m.venue_id, m.attendance, m.winner_club_id,
         m.winner_club_id,
         m.away_club_id, m.home_club_id,
         m.away_score, m.home_score,
         aq.points, hq.points
    FROM matches m
    LEFT JOIN match_period_scores hq ON hq.match_id = m.id AND hq.club_id = m.home_club_id AND hq.period = 3
    LEFT JOIN match_period_scores aq ON aq.match_id = m.id AND aq.club_id = m.away_club_id AND aq.period = 3
`;

/**
 * The value a metric ranks on. win_margin/loss_margin are NULL (excluded
 * from ranking, the same NULL-means-not-eligible discipline every other
 * grain here uses) for a side that didn't actually win/lose that game --
 * "biggest win" must never rank a loss by how close it was, and a drawn
 * Grand Final (winner_club_id IS NULL) counts as neither, the same
 * exclusion grid-solver.ts's grand_finals_lost_min already applies.
 */
function metricValueExpr(metric: string): SqlFragment {
  switch (metric) {
    case 'win_margin':
      return sql`CASE WHEN t.winner_club_id = t.club_id THEN (t.score_for - t.score_against) END`;
    case 'loss_margin':
      return sql`CASE WHEN t.winner_club_id IS NOT NULL AND t.winner_club_id <> t.club_id
                       THEN (t.score_against - t.score_for) END`;
    case 'team_score':
      return sql`t.score_for`;
    case 'opponent_score':
      return sql`t.score_against`;
    case 'total_score':
      return sql`(t.score_for + t.score_against)`;
    case 'attendance':
      return sql`t.attendance`;
    case 'q3_deficit_overcome':
      return sql`CASE WHEN t.winner_club_id = t.club_id AND t.q3_score_against IS NOT NULL THEN (t.q3_score_against - t.q3_score_for) END`;
    default:
      throw new Error(`team_match metric "${metric}" is not recognised.`);
  }
}

/** 'finals' is a synthetic "any final" reading; every other NlMatchType is a literal round_type enum member, the same bound-and-cast pattern player-game.ts's matchTypeSql and search.ts's own round_type lookup already use. */
function matchTypeSql(matchType: NlMatchType | undefined): SqlFragment {
  if (!matchType) return sql`TRUE`;
  if (matchType === 'finals') return sql`t.is_finals_series`;
  return sql`t.round_type = ${matchType}::round_type`;
}

function scopeClauses(scope: NlMatchScope): SqlFragment[] {
  const clauses: SqlFragment[] = [];
  if (scope.clubFor) {
    clauses.push(sql`t.club_id IN (SELECT id FROM clubs WHERE organization_id = ${scope.clubFor.organizationId})`);
  }
  if (scope.clubAgainst) {
    clauses.push(sql`t.opponent_id IN (SELECT id FROM clubs WHERE organization_id = ${scope.clubAgainst.organizationId})`);
  }
  if (scope.matchup) {
    clauses.push(sql`
      (
        (t.club_id IN (SELECT id FROM clubs WHERE organization_id = ${scope.matchup.clubA.organizationId})
         AND t.opponent_id IN (SELECT id FROM clubs WHERE organization_id = ${scope.matchup.clubB.organizationId}))
        OR
        (t.club_id IN (SELECT id FROM clubs WHERE organization_id = ${scope.matchup.clubB.organizationId})
         AND t.opponent_id IN (SELECT id FROM clubs WHERE organization_id = ${scope.matchup.clubA.organizationId}))
      )
    `);
  }
  if (scope.venue) clauses.push(sql`t.venue_id = ${scope.venue.id}`);
  if (scope.seasonMin !== undefined) clauses.push(sql`t.season >= ${scope.seasonMin}`);
  if (scope.seasonMax !== undefined) clauses.push(sql`t.season <= ${scope.seasonMax}`);
  if (scope.roundNumber !== undefined) clauses.push(sql`t.round_number = ${scope.roundNumber}`);
  clauses.push(matchTypeSql(scope.matchType));
  return clauses;
}

function foldAnd(clauses: SqlFragment[]): SqlFragment {
  if (clauses.length === 0) return sql`TRUE`;
  return clauses.reduce((acc, clause) => sql`${acc} AND ${clause}`);
}

function rankCutoff(agg: NlAggregation): number {
  return agg.kind === 'top_n' ? agg.n : 1;
}

/**
 * Answers a team_match plan: "Richmond's biggest loss", "biggest win at
 * the MCG", "highest score in a Grand Final". Ties included past the
 * rank cutoff, the same discipline every other grain here applies.
 */
export async function answerTeamMatch(plan: NlQueryPlan, limit: number): Promise<NlAnswerPayload> {
  if (plan.havingClause) return answerTeamAggregate(plan, limit);

  const value = metricValueExpr(plan.metric!);
  const direction = plan.agg.kind === 'min' ? sql.unsafe('ASC') : sql.unsafe('DESC');
  const n = rankCutoff(plan.agg);
  // attendance/total_score are identical for both SIDES rows of a match,
  // so with no clubFor/clubAgainst scope to justify a per-side row, both
  // rows would tie and rank() would return the same match twice
  // (AFLDB-ISSUE-192). Restrict to the home-perspective row so the match
  // is ranked once; side-scoped and side-dependent (margin/team score)
  // queries are unaffected. scope.matchup is deliberately excluded here:
  // it's a physical-match filter (either club can be on either side), not
  // a directional perspective -- validatePlan rejects matchup combined
  // with clubFor/clubAgainst (plan.ts), so it never masks a genuine side
  // scope, and a matchup-scoped symmetric metric must still canonicalise
  // to one row per match (AFLDB-ISSUE-194).
  const isSymmetricMetric = plan.metric === 'attendance' || plan.metric === 'total_score';
  const hasSideScope = Boolean(plan.scope.clubFor || plan.scope.clubAgainst);
  const where = foldAnd([
    ...scopeClauses(plan.scope),
    plan.resultFilter === 'won' ? sql`t.final_winner_club_id = t.club_id` : sql`TRUE`,
    plan.metric ? sql`${value} IS NOT NULL` : sql`TRUE`,
    isSymmetricMetric && !hasSideScope ? sql`t.club_id = m.home_club_id` : sql`TRUE`,
  ]);

  let periodCte = sql``;
  const sidesRef = plan.scoreCheckpoint ? sql.unsafe('checkpoint_sides')
    : plan.periodSplit && plan.periodSplit !== 'FULL_MATCH' ? sql.unsafe('period_sides')
    : sql.unsafe('sides');

  if (plan.periodSplit && plan.periodSplit !== 'FULL_MATCH') {
    const split = plan.periodSplit;
    const forPoints = split === 'Q1' ? sql`pc.q1`
      : split === 'Q2' ? sql`CASE WHEN pc.q1 IS NOT NULL AND pc.q2 IS NOT NULL THEN pc.q2 - pc.q1 END`
      : split === 'Q3' ? sql`CASE WHEN pc.q2 IS NOT NULL AND pc.q3 IS NOT NULL THEN pc.q3 - pc.q2 END`
      : split === 'Q4' ? sql`CASE WHEN pc.q3 IS NOT NULL AND pc.q4 IS NOT NULL THEN pc.q4 - pc.q3 END`
      : split === 'H1' ? sql`pc.q2`
      : sql`CASE WHEN pc.q2 IS NOT NULL THEN s.score_for - pc.q2 END`;
    const againstPoints = split === 'Q1' ? sql`po.q1`
      : split === 'Q2' ? sql`CASE WHEN po.q1 IS NOT NULL AND po.q2 IS NOT NULL THEN po.q2 - po.q1 END`
      : split === 'Q3' ? sql`CASE WHEN po.q2 IS NOT NULL AND po.q3 IS NOT NULL THEN po.q3 - po.q2 END`
      : split === 'Q4' ? sql`CASE WHEN po.q3 IS NOT NULL AND po.q4 IS NOT NULL THEN po.q4 - po.q3 END`
      : split === 'H1' ? sql`po.q2`
      : sql`CASE WHEN po.q2 IS NOT NULL THEN s.score_against - po.q2 END`;

    periodCte = sql`,
      period_club AS (
        SELECT match_id, club_id,
               max(points) FILTER (WHERE period = 1) AS q1,
               max(points) FILTER (WHERE period = 2) AS q2,
               max(points) FILTER (WHERE period = 3) AS q3,
               max(points) FILTER (WHERE period = 4) AS q4
          FROM match_period_scores
         WHERE period BETWEEN 1 AND 4
         GROUP BY match_id, club_id
      ),
      period_sides AS (
        SELECT s.match_id, s.season, s.round_type, s.round_number, s.is_finals_series,
               s.match_date, s.venue_id, s.attendance, s.final_winner_club_id,
               CASE WHEN ${forPoints} > ${againstPoints} THEN s.club_id
                    WHEN ${forPoints} < ${againstPoints} THEN s.opponent_id
                    ELSE NULL END AS winner_club_id,
               s.club_id, s.opponent_id,
               ${forPoints} AS score_for, ${againstPoints} AS score_against,
               s.q3_score_for, s.q3_score_against
          FROM sides s
          LEFT JOIN period_club pc ON pc.match_id = s.match_id AND pc.club_id = s.club_id
          LEFT JOIN period_club po ON po.match_id = s.match_id AND po.club_id = s.opponent_id
      )`;
  }

  if (plan.scoreCheckpoint) {
    const checkpoint = plan.scoreCheckpoint;
    const forPoints = checkpoint === 'QT' ? sql`pc.q1`
      : checkpoint === 'HT' ? sql`pc.q2`
      : sql`pc.q3`;
    const againstPoints = checkpoint === 'QT' ? sql`po.q1`
      : checkpoint === 'HT' ? sql`po.q2`
      : sql`po.q3`;
    periodCte = sql`,
      checkpoint_club AS (
        SELECT match_id, club_id,
               max(points) FILTER (WHERE period = 1) AS q1,
               max(points) FILTER (WHERE period = 2) AS q2,
               max(points) FILTER (WHERE period = 3) AS q3
          FROM match_period_scores
         WHERE period BETWEEN 1 AND 3
         GROUP BY match_id, club_id
      ),
      checkpoint_sides AS (
        SELECT s.match_id, s.season, s.round_type, s.round_number, s.is_finals_series,
               s.match_date, s.venue_id, s.attendance, s.final_winner_club_id,
               CASE WHEN ${forPoints} > ${againstPoints} THEN s.club_id
                    WHEN ${forPoints} < ${againstPoints} THEN s.opponent_id
                    ELSE NULL END AS winner_club_id,
               s.club_id, s.opponent_id,
               ${forPoints} AS score_for, ${againstPoints} AS score_against,
               s.q3_score_for, s.q3_score_against
          FROM sides s
          LEFT JOIN checkpoint_club pc ON pc.match_id = s.match_id AND pc.club_id = s.club_id
          LEFT JOIN checkpoint_club po ON po.match_id = s.match_id AND po.club_id = s.opponent_id
      )`;
  }

  const rows = await sql<(NlTeamMatchRow & { total: string; rnk: number })[]>`
    WITH sides AS (${SIDES})${periodCte},
    ranked AS (
      SELECT t.match_id AS "matchId", t.season, t.round_type AS "roundType", t.round_number AS "roundNumber",
             t.match_date AS "matchDate",
             cl.name AS "clubName", cl.slug AS "clubSlug",
             opp.name AS "opponentName", opp.slug AS "opponentSlug",
             ${value} AS value,
             t.score_for AS "clubScore", t.score_against AS "opponentScore",
             COALESCE(v.canonical_name, m.venue_raw) AS "venueName",
             rank() OVER (ORDER BY ${value} ${direction})::int AS rnk
        FROM ${sidesRef} t
        JOIN matches m ON m.id = t.match_id
        JOIN clubs cl ON cl.id = t.club_id
        JOIN clubs opp ON opp.id = t.opponent_id
        LEFT JOIN venues v ON v.id = t.venue_id
       WHERE ${where}
    )
    SELECT r.*, count(*) OVER () AS total
      FROM ranked r
     WHERE r.rnk <= ${n}
     ORDER BY r.value ${direction}, r."matchDate"
     LIMIT ${limit}
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = rows.map(({ total: _t, rnk: _r, ...rest }) => rest);
  return { kind: 'team_match', lead: clean[0] ?? null, rows: clean, total };
}

const COMPARE_SQL = {
  gte: '>=', lte: '<=', gt: '>', lt: '<', eq: '=',
} as const;

/**
 * A HAVING question is organization-grained output, not a match ranking.
 * Result and margin predicates are applied to individual matches first;
 * only then are the surviving rows counted and thresholded per club.
 */
async function answerTeamAggregate(plan: NlQueryPlan, limit: number): Promise<NlAnswerPayload> {
  const having = plan.havingClause!;
  const clauses = scopeClauses(plan.scope);
  // 'games' is deliberately un-predicated: every match already inside
  // the scope counts, so no result clause is added. Written as an
  // exhaustive if/else rather than a trailing `else` for draws, which
  // would silently have swallowed any metric added later.
  if (having.metric === 'wins') clauses.push(sql`t.winner_club_id = t.club_id`);
  else if (having.metric === 'losses') clauses.push(sql`t.winner_club_id IS NOT NULL AND t.winner_club_id <> t.club_id`);
  else if (having.metric === 'draws') clauses.push(sql`t.winner_club_id IS NULL`);

  if (plan.matchFilter) {
    const filterValue = metricValueExpr(plan.matchFilter.metric);
    const filterOp = sql.unsafe(COMPARE_SQL[plan.matchFilter.op]);
    clauses.push(sql`${filterValue} ${filterOp} ${plan.matchFilter.value}`);
  }

  const where = foldAnd(clauses);
  const havingOp = sql.unsafe(COMPARE_SQL[having.op]);
  const rows = await sql<(NlTeamAggregateRow & { total: string })[]>`
    WITH sides AS (${SIDES}),
    grouped AS (
      SELECT cl.organization_id, count(*)::int AS value
        FROM sides t
        JOIN clubs cl ON cl.id = t.club_id
       WHERE ${where}
       GROUP BY cl.organization_id
      HAVING count(*) ${havingOp} ${having.value}
    )
    SELECT o.id AS "organizationId", o.name AS "clubName", o.slug AS "clubSlug",
           g.value, count(*) OVER () AS total
      FROM grouped g
      JOIN club_organizations o ON o.id = g.organization_id
     ORDER BY g.value DESC, o.name
     LIMIT ${limit}
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = rows.map(({ total: _total, ...row }) => row);
  return { kind: 'team_aggregate', rows: clean, total };
}

export async function answerTeamAggregateDrilldown(
  plan: NlQueryPlan,
  clubSlug: string,
): Promise<{ rows: NlTeamMatchRow[]; total: number }> {
  const having = plan.havingClause!;
  const clauses = scopeClauses(plan.scope);
  // 'games' is deliberately un-predicated: every match already inside
  // the scope counts, so no result clause is added. Written as an
  // exhaustive if/else rather than a trailing `else` for draws, which
  // would silently have swallowed any metric added later.
  if (having.metric === 'wins') clauses.push(sql`t.winner_club_id = t.club_id`);
  else if (having.metric === 'losses') clauses.push(sql`t.winner_club_id IS NOT NULL AND t.winner_club_id <> t.club_id`);
  else if (having.metric === 'draws') clauses.push(sql`t.winner_club_id IS NULL`);

  if (plan.matchFilter) {
    const filterValue = metricValueExpr(plan.matchFilter.metric);
    const filterOp = sql.unsafe(COMPARE_SQL[plan.matchFilter.op]);
    clauses.push(sql`${filterValue} ${filterOp} ${plan.matchFilter.value}`);
  }

  // Drill-down constraint
  clauses.push(sql`t.club_id IN (
    SELECT id FROM clubs WHERE organization_id = (
      SELECT organization_id FROM clubs WHERE slug = ${clubSlug} LIMIT 1
    )
  )`);

  const where = foldAnd(clauses);
  const rows = await sql<(NlTeamMatchRow & { total: string })[]>`
    WITH sides AS (${SIDES})
    SELECT t.match_id AS "matchId", t.season, t.round_type AS "roundType", t.round_number AS "roundNumber",
           t.match_date AS "matchDate",
           cl.name AS "clubName", cl.slug AS "clubSlug",
           opp.name AS "opponentName", opp.slug AS "opponentSlug",
           0 AS value,
           t.score_for AS "clubScore", t.score_against AS "opponentScore",
           COALESCE(v.canonical_name, m.venue_raw) AS "venueName",
           count(*) OVER () AS total
      FROM sides t
      JOIN matches m ON m.id = t.match_id
      JOIN clubs cl ON cl.id = t.club_id
      JOIN clubs opp ON opp.id = t.opponent_id
      LEFT JOIN venues v ON v.id = t.venue_id
     WHERE ${where}
     ORDER BY t.match_date DESC, t.match_id DESC
  `;
  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = rows.map(({ total: _total, ...row }) => row);
  return { rows: clean, total };
}

import 'server-only';

import { sql } from '@/db/client';
import { type NlAggregation, type NlMatchScope, type NlMatchType, type NlQueryPlan } from '@/search/nl/plan';
import type { NlAnswerPayload, NlTeamStreakRow } from '@/search/nl/answer-types';

type SqlFragment = ReturnType<typeof sql>;

const SIDES = sql`
  SELECT m.id AS match_id, m.season, m.round_type, m.round_number, m.is_finals_series,
         m.match_date, m.venue_id, m.winner_club_id,
         m.home_club_id AS club_id, m.away_club_id AS opponent_id
    FROM matches m
  UNION ALL
  SELECT m.id, m.season, m.round_type, m.round_number, m.is_finals_series,
         m.match_date, m.venue_id, m.winner_club_id,
         m.away_club_id, m.home_club_id
    FROM matches m
`;

function matchTypeSql(matchType: NlMatchType | undefined): SqlFragment {
  if (!matchType) return sql`TRUE`;
  if (matchType === 'finals') return sql`t.is_finals_series`;
  return sql`t.round_type = ${matchType}::round_type`;
}

function scopeClauses(scope: NlMatchScope): SqlFragment[] {
  const clauses: SqlFragment[] = [];
  if (scope.clubFor) {
    clauses.push(sql`t.club_id IN (SELECT id FROM clubs WHERE organization_id = ${scope.clubFor.organizationId})`);
  }
  if (scope.clubAgainst) {
    clauses.push(sql`t.opponent_id IN (SELECT id FROM clubs WHERE organization_id = ${scope.clubAgainst.organizationId})`);
  }
  if (scope.venue) clauses.push(sql`t.venue_id = ${scope.venue.id}`);
  if (scope.seasonMin !== undefined) clauses.push(sql`t.season >= ${scope.seasonMin}`);
  if (scope.seasonMax !== undefined) clauses.push(sql`t.season <= ${scope.seasonMax}`);
  if (scope.roundNumber !== undefined) clauses.push(sql`t.round_number = ${scope.roundNumber}`);
  clauses.push(matchTypeSql(scope.matchType));
  return clauses;
}

function foldAnd(clauses: SqlFragment[]): SqlFragment {
  if (clauses.length === 0) return sql`TRUE`;
  return clauses.reduce((acc, clause) => sql`${acc} AND ${clause}`);
}

function rankCutoff(agg: NlAggregation): number {
  return agg.kind === 'top_n' ? agg.n : 1;
}

export async function answerTeamStreak(plan: NlQueryPlan, limit: number): Promise<NlAnswerPayload> {
  const n = rankCutoff(plan.agg);
  const direction = plan.agg.kind === 'min' ? sql.unsafe('ASC') : sql.unsafe('DESC');
  const where = foldAnd(scopeClauses(plan.scope));

  // streak target logic
  let targetSql: SqlFragment;
  if (plan.streakDefinition?.kind === 'win') targetSql = sql`t.winner_club_id = t.club_id`;
  else if (plan.streakDefinition?.kind === 'loss') targetSql = sql`t.winner_club_id IS NOT NULL AND t.winner_club_id <> t.club_id`;
  else if (plan.streakDefinition?.kind === 'unbeaten') targetSql = sql`t.winner_club_id = t.club_id OR t.winner_club_id IS NULL`;
  else throw new Error('Unknown streak type');

  const rows = await sql<(NlTeamStreakRow & { total: string; rnk: number })[]>`
    WITH sides AS (${SIDES}),
    filtered AS (
      SELECT t.*, cl.organization_id, (${targetSql}) AS is_target
        FROM sides t
        JOIN clubs cl ON cl.id = t.club_id
       WHERE ${where}
    ),
    islands AS (
      SELECT f.*,
             ROW_NUMBER() OVER (PARTITION BY f.organization_id ORDER BY f.match_date, f.match_id) -
             ROW_NUMBER() OVER (PARTITION BY f.organization_id, f.is_target ORDER BY f.match_date, f.match_id) AS grp
        FROM filtered f
    ),
    grouped AS (
      SELECT organization_id,
             COUNT(*) AS streak_length,
             MIN(match_date) AS start_date,
             MAX(match_date) AS end_date
        FROM islands
       WHERE is_target = TRUE
       GROUP BY organization_id, grp
    ),
    ranked AS (
      SELECT g.organization_id AS "clubId",
             o.name AS "clubName", o.slug AS "clubSlug",
             g.streak_length::int AS "streakLength",
             g.start_date AS "startDate", g.end_date AS "endDate",
             rank() OVER (ORDER BY g.streak_length ${direction})::int AS rnk
        FROM grouped g
        JOIN club_organizations o ON o.id = g.organization_id
    )
    SELECT r.*, count(*) OVER () AS total
      FROM ranked r
     WHERE r.rnk <= ${n}
     ORDER BY r."streakLength" ${direction}, r."startDate"
     LIMIT ${limit}
  `;

  // Attach opponent context if scoped
  if (plan.scope.clubAgainst) {
    const oppName = plan.scope.clubAgainst.name;
    const oppSlug = plan.scope.clubAgainst.slug;
    for (const row of rows) {
      row.opponentName = oppName;
      row.opponentSlug = oppSlug;
    }
  }

  const total = rows[0] ? Number(rows[0].total) : 0;
  const clean = rows.map(({ total: _t, rnk: _r, ...rest }) => rest);
  return { kind: 'team_streak', lead: clean[0] ?? null, rows: clean, total };
}

import { randomUUID } from 'node:crypto';

import 'server-only';

import { cache } from 'react';
import postgres from 'postgres';

import { sql } from '@/db/client';
import { recordDataEdit } from '@/db/queries/audit-log';
import { allOf, containsPattern, rangeConditions } from '@/db/queries/filters';
import { EDITABLE_ENTITIES, validateFieldValue } from '@/lib/edit/spec';
import type { FilterValues } from '@/search/table-filters';

export type PlayerListRow = {
  id: number;
  slug: string;
  displayName: string;
  debutSeason: number | null;
  finalSeason: number | null;
  games: number;
  goals: number;
  finals: number;
  premierships: number;
  brownlowVotes: number;
  clubsPlayed: number;
  clubNames: string | null;
};

export const PLAYER_SORTS: Record<string, string> = {
  games: 'c.games',
  goals: 'c.goals',
  name: 'p.sort_name',
  debut: 'c.debut_season',
  final_game: 'c.final_season',
  brownlow_votes: 'c.brownlow_votes',
  finals: 'c.finals',
  premierships: 'c.premierships',
};

export type PlayerSort = keyof typeof PLAYER_SORTS;

export function isPlayerSort(value: string | undefined): value is PlayerSort {
  return value !== undefined && Object.hasOwn(PLAYER_SORTS, value);
}

export type PlayerSortDir = 'asc' | 'desc';

export function isPlayerSortDir(value: string | undefined): value is PlayerSortDir {
  return value === 'asc' || value === 'desc';
}

/**
 * Career columns the player index may be filtered on.
 *
 * The allowlist that `rangeConditions` resolves against: a filter key with
 * no entry here produces no SQL. Era-limited statistics are deliberately
 * absent for the reason `advanced-spec.ts` gives — filtering on disposals
 * would quietly exclude everyone who played before they were recorded.
 */
export const PLAYER_FILTER_COLUMNS: Record<string, string> = {
  games: 'c.games',
  goals: 'c.goals',
  finals: 'c.finals',
  premierships: 'c.premierships',
  brownlow_votes: 'c.brownlow_votes',
  brownlow_medals: 'c.brownlow_medals',
  clubs: 'c.clubs_played',
  seasons: 'c.seasons_played',
  wins: 'c.wins',
  debut: 'c.debut_season',
  final: 'c.final_season',
};

export type PlayerListFilters = {
  club?: string;
  season?: number;
  name?: string;
  ranges?: FilterValues;
};

/**
 * Paged player index.
 *
 * Club names are aggregated in the same query rather than fetched per
 * player, so a 50-row page costs one round trip, not 51.
 */
export async function listPlayers(options: PlayerListFilters & {
  sort: PlayerSort;
  dir?: PlayerSortDir;
  limit: number;
  offset: number;
}): Promise<{ rows: PlayerListRow[]; total: number }> {
  const { sort, dir = 'desc', limit, offset, club, season, name, ranges } = options;

  // Base column for the sort
  const sortCol = PLAYER_SORTS[sort];
  const sqlDir = dir === 'asc' ? sql`ASC` : sql`DESC`;

  // Custom orderBy construction to handle ties and specific requirements
  let orderBy;
  if (sort === 'name') {
    orderBy = sql`${sql.unsafe(sortCol)} ${sqlDir}`;
  } else if (sort === 'debut' || sort === 'final_game') {
    const nulls = dir === 'asc' ? sql`NULLS LAST` : sql`NULLS LAST`;
    orderBy = sql`${sql.unsafe(sortCol)} ${sqlDir} ${nulls}, p.sort_name ASC`;
  } else if (sort === 'premierships') {
    orderBy = sql`${sql.unsafe(sortCol)} ${sqlDir}, c.games ${sqlDir}, p.sort_name ASC`;
  } else {
    orderBy = sql`${sql.unsafe(sortCol)} ${sqlDir}, p.sort_name ASC`;
  }

  const conditions = ranges ? rangeConditions(ranges, PLAYER_FILTER_COLUMNS) : [];
  if (name) conditions.push(sql`p.display_name ILIKE ${containsPattern(name)}`);
  if (club) {
    conditions.push(sql`
      EXISTS (SELECT 1 FROM player_clubs pc
                JOIN clubs cl ON cl.id = pc.club_id
               WHERE pc.player_id = p.id AND cl.slug = ${club})
    `);
  }
  if (season !== undefined) {
    conditions.push(sql`
      EXISTS (SELECT 1 FROM player_season_stats ps
               WHERE ps.player_id = p.id AND ps.season = ${season})
    `);
  }
  const where = allOf(conditions);

  const rows = await sql<(PlayerListRow & { total: string })[]>`
    SELECT p.id,
           p.slug,
           p.display_name       AS "displayName",
           c.debut_season       AS "debutSeason",
           c.final_season       AS "finalSeason",
           COALESCE(c.games, 0) AS games,
           COALESCE(c.goals, 0) AS goals,
           COALESCE(c.finals, 0) AS finals,
           COALESCE(c.premierships, 0) AS premierships,
           COALESCE(c.brownlow_votes, 0) AS "brownlowVotes",
           COALESCE(c.clubs_played, 0) AS "clubsPlayed",
           (SELECT string_agg(DISTINCT cl.short_name, ', ' ORDER BY cl.short_name)
              FROM player_clubs pc JOIN clubs cl ON cl.id = pc.club_id
             WHERE pc.player_id = p.id) AS "clubNames",
           count(*) OVER ()     AS total
      FROM players p
      LEFT JOIN player_career_stats c ON c.player_id = p.id
     WHERE ${where}
     ORDER BY ${orderBy}
     LIMIT ${limit} OFFSET ${offset}
  `;

  if (rows.length > 0) {
    return {
      rows: rows.map(({ total: _total, ...rest }) => rest),
      total: Number(rows[0].total),
    };
  }

  // An offset past the end returns no rows, and a window count carried on
  // those rows would report the collection as empty. Count separately so
  // "13,361 players" stays true on a page that happens to be past the last
  // one, and so the caller can redirect to a page that exists.
  const [counted] = await sql<{ total: string }[]>`
    SELECT count(*) AS total
      FROM players p
      LEFT JOIN player_career_stats c ON c.player_id = p.id
     WHERE ${where}
  `;
  return { rows: [], total: Number(counted.total) };
}

