          const fetchImpl = (async () => { starts.push(clock.t); return jsonResponse({ ok: true }); }) as unknown as FetchLike;
          for (let i = 0; i < 3; i += 1) await requestAflApi(fetchImpl, plan, { rateLimiter: limiter, sleep });
