    }

    const seasonFeed = {
      matches: [
        { providerId: 'CD_M1', status: 'CONCLUDED', utcStartTime: '2026-03-05T04:40:00Z', home: { team: { providerId: 'CD_T10' } } },
        { providerId: 'CD_M2', status: 'POSTGAME', utcStartTime: '2026-09-19T05:00:00Z' },
      ],
