    it('flattens nested objects and arrays to dot-path leaves, arrays transparent (no index)', () => {
      expect(flattenObservedColumns({ a: { b: 1, c: [{ d: 2 }, { d: 3 }] }, e: null })).toEqual(['a.b', 'a.c.d', 'e']);
