      listing: parseAflApiCompSeasons(withFuture(FUTURE_2027, 40)), registered, source,
    });
    expect(proposal.listing.complete).toBe(false);
    expect(proposal.verdict).toBe('refused');
    expect(proposal.proposals).toEqual([]);
    expect(proposal.findings.map((f) => f.kind)).toEqual(['listing_incomplete']);
  });

  it('reports a registered season missing from the listing, and an unregistered gap inside the registered range', () => {
    const withGap = new Map<number, RegisteredAflApiSeason>(registered);
    withGap.delete(2024);
    withGap.set(2011, { compSeasonId: 1, providerId: 'CD_S2011014' });
    const proposal = proposeAflApiSeasons({ listing: parseAflApiCompSeasons(rawText()), registered: withGap, source });
    expect(proposal.verdict).toBe('refused');
    expect(proposal.findings.map((f) => [f.kind, f.year])).toEqual([
      ['registered_absent_from_listing', 2011],
      ['unregistered_within_registered_range', 2012],
      ['unregistered_within_registered_range', 2013],
      ['unregistered_within_registered_range', 2014],
      ['unregistered_within_registered_range', 2015],
      ['unregistered_within_registered_range', 2016],
      ['unregistered_within_registered_range', 2017],
      ['unregistered_within_registered_range', 2018],
      ['unregistered_within_registered_range', 2019],
      ['unregistered_within_registered_range', 2020],
      ['unregistered_within_registered_range', 2021],
      ['unregistered_within_registered_range', 2024],
    ]);
  });

  it('is deterministic: the same input serialises to the same bytes, with no clock in it', () => {
    const once = serialiseAflApiSeasonDiscoveryProposal(
      proposeAflApiSeasons({ listing: parseAflApiCompSeasons(withFuture(FUTURE_2027)), registered, source }),
    );
    const twice = serialiseAflApiSeasonDiscoveryProposal(
      proposeAflApiSeasons({ listing: parseAflApiCompSeasons(withFuture(FUTURE_2027)), registered, source }),
    );
    expect(twice).toBe(once);
    expect(once.endsWith('}\n')).toBe(true);
    expect(once).not.toMatch(/generated|_at"|timestamp/i);
  });

  it('throws on a malformed envelope rather than reading half of it', () => {
    expect(() => parseAflApiCompSeasons('{"meta":{}}')).toThrow(/no 'compSeasons' array/);
    expect(() => parseAflApiCompSeasons('{"compSeasons":[{"id":"85","providerId":"x","name":"y"}]}')).toThrow(/integer id/);
  });

  describe('the CLI', () => {
    let dir: string | null = null;
    afterEach(() => {
      if (dir !== null) rmSync(dir, { recursive: true, force: true });
      dir = null;
    });
    const noFetch: FetchLike = async () => { throw new Error('network must not be touched'); };

    it('parses exactly one source and requires --output (and --save-raw with --fetch)', () => {
      expect(parseDiscoverAflApiSeasonsArgs(['--input', 'a.json', '--output', 'p.json']))
        .toEqual({ source: 'input', input: 'a.json', output: 'p.json' });
      expect(parseDiscoverAflApiSeasonsArgs(['--fetch', '--save-raw', 'r.json', '--output', 'p.json']))
        .toEqual({ source: 'fetch', saveRaw: 'r.json', output: 'p.json' });
      expect(() => parseDiscoverAflApiSeasonsArgs(['--input', 'a.json'])).toThrow(/--output/);
      expect(() => parseDiscoverAflApiSeasonsArgs(['--output', 'p.json'])).toThrow(/Exactly one/);
      expect(() => parseDiscoverAflApiSeasonsArgs(['--fetch', '--input', 'a', '--output', 'p'])).toThrow(/Exactly one/);
      expect(() => parseDiscoverAflApiSeasonsArgs(['--fetch', '--output', 'p.json'])).toThrow(/--save-raw/);
      expect(() => parseDiscoverAflApiSeasonsArgs(['--input', 'a', '--output', 'p', '--apply'])).toThrow(/Unknown/);
    });

    it('--input writes the proposal and a summary, touches no network and no reference data', async () => {
      dir = mkdtempSync(join(tmpdir(), 'afldb-issue233-'));
      const output = join(dir, 'proposal.json');
      const identitiesBefore = readFileSync(join(projectRoot, 'data', 'reference', 'afl-api-identities.json'));
      const lines: string[] = [];
      const proposal = await runDiscoverAflApiSeasons(
        ['--input', RAW_PATH, '--output', output],
        { log: (line) => lines.push(line), fetchImpl: noFetch },
      );
      expect(proposal.verdict).toBe('no_change');
      expect(proposal.input).toEqual(source);
      expect(readFileSync(output, 'utf8')).toBe(serialiseAflApiSeasonDiscoveryProposal(proposal));
      expect(lines.join('\n')).toContain('verdict: NO_CHANGE. Nothing was written to data/reference/.');
      expect(readFileSync(join(projectRoot, 'data', 'reference', 'afl-api-identities.json'))).toEqual(identitiesBefore);
      // Never overwrites a reviewed proposal.
      await expect(runDiscoverAflApiSeasons(['--input', RAW_PATH, '--output', output], { log: () => {} }))
        .rejects.toThrow(/already exists/);
    });

    it('--fetch refuses before any request when the ingestion switch is off', async () => {
      dir = mkdtempSync(join(tmpdir(), 'afldb-issue233-'));
      await expect(runDiscoverAflApiSeasons(
        ['--fetch', '--save-raw', join(dir, 'raw.json'), '--output', join(dir, 'p.json')],
        {
          log: () => {}, fetchImpl: noFetch,
          ingestionControls: { ...ENABLED_INGESTION_CONTROLS, currentSeasonEnabled: false },
        },
      )).rejects.toThrow(/ingestion is disabled/);
      expect(existsSync(join(dir, 'raw.json'))).toBe(false);
    });

    it('AFLDB-ISSUE-300: --fetch reports an unreadable control database as a read failure, not a disabled switch', async () => {
      dir = mkdtempSync(join(tmpdir(), 'afldb-issue300-'));
      const refusal = runDiscoverAflApiSeasons(
        ['--fetch', '--save-raw', join(dir, 'raw.json'), '--output', join(dir, 'p.json')],
        { log: () => {}, fetchImpl: noFetch, ingestionControls: await readAflApiIngestionControls({}) },
      );
      await expect(refusal).rejects.toThrow(/ingestion refused: the ingestion switches could not be read: DATABASE_URL is not set/);
      await expect(refusal).rejects.not.toThrow(/A super admin must enable it/);
      expect(existsSync(join(dir, 'raw.json'))).toBe(false);
      expect(existsSync(join(dir, 'p.json'))).toBe(false);
    });

    it('--fetch retains the raw bytes verbatim and binds the proposal to their sha256', async () => {
      dir = mkdtempSync(join(tmpdir(), 'afldb-issue233-'));
      const body = rawText();
      const fetchImpl: FetchLike = async (url) => {
        expect(String(url)).toBe('https://aflapi.afl.com.au/afl/v2/competitions/1/compseasons?pageSize=100');
        return new Response(body, { status: 200, headers: { 'content-type': 'application/json' } });
      };
      const rawPath = join(dir, 'seasons', '00-compseasons.raw.json');
      const proposal = await runDiscoverAflApiSeasons(
        ['--fetch', '--save-raw', rawPath, '--output', join(dir, 'p.json')],
        { log: () => {}, fetchImpl, ingestionControls: ENABLED_INGESTION_CONTROLS },
      );
      expect(readFileSync(rawPath, 'utf8')).toBe(body);
      // the ASCII fixture's bytes, exactly: same bytes, same sha256 as the retained fixture
      expect(readFileSync(rawPath)).toEqual(readFileSync(RAW_PATH));
      expect(proposal.input.sha256).toBe(RAW_SHA256);
      expect(proposal.verdict).toBe('no_change');
    });

    it('--fetch retains the HTTP entity bytes, not a decode/re-encode of them (BOM, CRLF, invalid UTF-8)', async () => {
      const fetchBytes = async (entity: Buffer) => {
        dir = mkdtempSync(join(tmpdir(), 'afldb-issue233-'));
        const fetchImpl: FetchLike = async () => new Response(new Uint8Array(entity),
          { status: 200, headers: { 'content-type': 'application/json' } });
        const rawPath = join(dir, 'raw.json');
        const output = join(dir, 'p.json');
        const run = runDiscoverAflApiSeasons(['--fetch', '--save-raw', rawPath, '--output', output],
          { log: () => {}, fetchImpl, ingestionControls: ENABLED_INGESTION_CONTROLS });
        return { run, rawPath, output };
      };
      const fixture = readFileSync(RAW_PATH);
      // A UTF-8 BOM and a trailing CRLF: text() drops the BOM, so a decode/re-encode differs.
      const withBom = Buffer.concat([Buffer.from([0xef, 0xbb, 0xbf]), fixture, Buffer.from('\r\n')]);
      const bom = await fetchBytes(withBom);
      const proposal = await bom.run;
      expect(readFileSync(bom.rawPath).equals(withBom)).toBe(true);
      expect(proposal.input.sha256).toBe(createHash('sha256').update(withBom).digest('hex'));
      expect(proposal.input.sha256).not.toBe(RAW_SHA256);
      expect(proposal.verdict).toBe('no_change'); // parsed only after retention, from the same bytes
      rmSync(dir!, { recursive: true, force: true });

      // An invalid UTF-8 byte: retained verbatim, then refused rather than silently replaced.
      const invalid = Buffer.concat([fixture.subarray(0, 20), Buffer.from([0xff]), fixture.subarray(20)]);
      const bad = await fetchBytes(invalid);
      await expect(bad.run).rejects.toThrow(/not valid UTF-8; it was retained as received/);
      expect(readFileSync(bad.rawPath).equals(invalid)).toBe(true);
      expect(existsSync(bad.output)).toBe(false);
    });
  });
});

/**
 * AFLDB-ISSUE-228 S6 — the read-only settle planner.
 *
 * Covers the complete bundle -> settle records -> match identity ->
 * match/player resolution -> plan path (`afl-api-settle-plan.ts`), plus the
 * match identity context builder it depends on (`afl-api-match-identity.ts`).
 * DB-free: uses the real tracked registry/identities and the same
 * hand-trimmed `tests/fixtures/afl_api/match/*` fixtures
 * `tests/afl-api-match.test.ts` already proves (Hawthorn 122 d Brisbane
 * Lions 131, CD_M20260142801, 2026 Preliminary Final, local match date/time
 * `2026-09-19T17:15:00`), routed through a fake postgres.js tagged-template
 * handle exactly as `tests/afl-api-match.test.ts`'s resolver suites do.
 *
 * No database, Git, network or deployment command is executed by this file
 * or by anything it imports (CLAUDE.md §9).
 */
import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import type postgres from 'postgres';

import {
  buildAflApiMatchBundle,
  buildAflApiSettleRecords,
  parseAflApiIdentities,
  type AflApiMatchBundle,
  type AflApiSettleRecord,
} from '@/lib/acquisition/afl-api-bundle';
import {
  buildAflApiMatchIdentity,
  resolveAflApiMatchClubs,
  resolveAflApiSourceId,
  AflApiMatchIdentityError,
} from '@/lib/acquisition/afl-api-match-identity';
import {
  planAflApiMatchUnit,
  AflApiSettlePlanError,
} from '@/lib/acquisition/afl-api-settle-plan';
import { resolveAflApiPlayer } from '@/lib/acquisition/afl-api-player-resolver';
import { NO_MATCH_REKEY_SCOPE } from '@/lib/acquisition/match-rekey';
import { parseSourceFamilyRegistry } from '@/lib/acquisition/source-families';

const projectRoot = join(__dirname, '..');
const registry = parseSourceFamilyRegistry(
  JSON.parse(readFileSync(join(projectRoot, 'data', 'reference', 'source-families.json'), 'utf8')),
);
const identities = parseAflApiIdentities(
  JSON.parse(readFileSync(join(projectRoot, 'data', 'reference', 'afl-api-identities.json'), 'utf8')),
);
const fixturesDir = join(projectRoot, 'tests', 'fixtures', 'afl_api');
const readFixture = (relPath: string): any => JSON.parse(readFileSync(join(fixturesDir, relPath), 'utf8'));

const SOURCE_ID = 42;
const HOME_CLUB_ID = 10; // Hawthorn
const AWAY_CLUB_ID = 20; // Brisbane Lions
const EXPECTED_MATCH_KEY = '2026|PF|2026-09-19|Hawthorn|Brisbane Lions';

function loadBundleAndRecords(mutate?: {
  fixture?: (raw: any) => void;
  roster?: (raw: any) => void;
  stats?: (raw: RawStatsFeed) => void;
}): { bundle: AflApiMatchBundle; records: readonly AflApiSettleRecord[] } {
  const fixture = readFixture('match/01-fixture-result.json');
  const roster = readFixture('match/03-match-roster.raw.json');
  const stats = readFixture('match/02-player-stats.raw.json');
  // §11.1 default bundle: the shared trimmed roster fixture deliberately
  // omits `match.venueLocalStartTime` (proven absent by
  // tests/afl-api-match.test.ts's D3a coverage), which otherwise leaves
  // every scenario here pre-empted by unproved_match_date before it reaches
  // the match/player/ownership code path it exists to exercise. Inject the
  // already-measured value (agrees with this fixture's own
  // `utcStartTime`/`venue.timezone`, per the module doc comment) so only the
  // scenarios that explicitly remove match-date evidence (below) see it
  // unproved.
  roster.match.venueLocalStartTime = '2026-09-19T17:15:00';
  mutate?.fixture?.(fixture);
  mutate?.roster?.(roster);
  mutate?.stats?.(stats);
  const bundle = buildAflApiMatchBundle(fixture, roster, stats, registry, identities);
  const records = buildAflApiSettleRecords(bundle, fixture, roster, stats, registry);
  return { bundle, records };
}

type Responder = (text: string) => unknown[];

/**
 * The same routing-by-substring fake postgres.js handle
 * `tests/afl-api-match.test.ts` uses, extended to interleave the
 * interpolated VALUES (JSON-stringified) into the routed text, so a
 * responder can branch on which provider id a given call named — this
 * suite plans two players per unit and needs to answer them differently,
 * unlike the single-identity resolver suites upstream.
 */
function fakeSql(respond: Responder): { sql: postgres.Sql; seen: string[] } {
  const seen: string[] = [];
  const sql = ((strings: TemplateStringsArray, ...values: unknown[]) => {
    const text = strings
      .reduce((acc, part, i) => acc + part + (i < values.length ? JSON.stringify(values[i]) : ''), '')
      .replace(/\s+/g, ' ')
      .trim();
    seen.push(text);
    return Promise.resolve(respond(text));
  }) as unknown as postgres.Sql;
  return { sql, seen };
}

/** Routes the queries a fully-resolved-club, no-existing-match-row planning
 * pass issues: clubs (always), then whatever `matchRespond` answers for the
 * match resolver's own queries, then whatever `playerRespond` answers for
 * each player lookup. */
function planningSql(options: {
  matchRespond?: Responder;
  ownerRespond?: Responder;
  playerRespond?: Responder;
}): { sql: postgres.Sql; seen: string[] } {
  return fakeSql((text) => {
    if (text.includes('FROM clubs')) {
      return [
        { legacyClubHist: 'Hawthorn', id: HOME_CLUB_ID, name: 'Hawthorn' },
        { legacyClubHist: 'Brisbane Lions', id: AWAY_CLUB_ID, name: 'Brisbane Lions' },
      ];
    }
    if (text.includes('FROM matches m')) return options.ownerRespond?.(text) ?? [];
    if (text.includes('FROM external_identities')) return options.playerRespond?.(text) ?? [];
    return options.matchRespond?.(text) ?? [];
  });
}

