  describe('--freeze-plan and --unfreeze-recovery files', () => {
    it('writes the manifest and three SQL files once, never a second token', () => {
      const opts = baseOpts({ freezePlan: true, database: 'afldb_prod', freezeDir: join(dir, 'freeze') });
