    wrong.afApiRows = wrong.afApiRows.map((r) => (r.externalId === 'CD_I1001' ? { ...r, playerId: 9002 } : r));
    await expect(verifyBijectionStage(statefulTx(wrong).tx, 'afldb_test')).rejects.toThrow(
