/** The four proven convergence pairs — both ordinals of each. */
const CONVERGENCE_URLS = [
  `${BASE}/players/adam_houlihan/1`, `${BASE}/players/adam_houlihan/2`,
  `${BASE}/players/andrew_hill/1`, `${BASE}/players/andrew_hill/2`,
