      const [sourceRecordAfter] = await sql<{ versionSeq: number }[]>`
        SELECT current_version_seq AS "versionSeq" FROM staging.source_records
         WHERE source_id = ${aflApiSourceId} AND family = 'brownlow_match_votes'
