    );
    expect(block).toContain('"named_medals"');
    expect(source).toContain('"named_medals": "draftguru"');
  });

  it('dispatches import_named_medals, reading both tracked manifests', () => {
    expect(source).toContain('elif key == "named_medals":');
    expect(source).toContain('import_named_medals(pg, rep, batch, clubs, sources,');
    expect(source).toContain('definitions = load_named_medals_definitions()');
    expect(source).toContain('winners = load_named_medals()');
    expect(source).toContain('validate_named_medals_family(winners, definitions)');
  });

  it('does not force the legacy awards group as a named_medals prerequisite, but a full awards refresh still reloads it', () => {
    const block = source.slice(
      source.indexOf('GROUP_REQUIRES = {'),
      source.indexOf('GROUP_REQUIRES = {') + 300,
    );
    expect(block).not.toMatch(/^\s*"named_medals":/m);
    expect(block).toContain(
      '"awards": {"all_australian", "under_22", "rising_star", "club_bf", "named_medals"}',
    );
  });

  it('reloads the 24 definitions on slug (scoped to those slugs) and the winners on (source_id, source_record_id)', () => {
    const body = source.slice(
      source.indexOf('def import_named_medals('),
      source.indexOf('# Group: AFLPA 22 Under 22'),
    );
    expect(body).toContain('pg, "awards", ["slug"]');
    expect(body).toContain('scope_column="slug", scope_values=[d.slug for d in definitions]');
    expect(body).toContain('pg, "award_winners", ["source_id", "source_record_id"]');
    expect(body).toContain('scope_column="award_id", scope_values=named_medal_award_ids');
    expect(body).toContain('scopes=[("source_id", sorted(source_ids.values()), False)]');
    expect(body).toContain('target_table="award_winners"');
  });

  it('takes the 17 named-medal awards out of the legacy awards group\'s winner scope, definitions untouched', () => {
    const legacyAwardsLoader = source.slice(
      source.indexOf('def import_awards('),
      source.indexOf('# Group: All-Australian'),
    );
    // The shared definition build and its slug-scoped reload are untouched —
    // the named-medal (and bf-*) entries still flow through
    // build_definitions(), so the legacy group keeps its remaining job of
    // creating the all-australian / rising-star / coleman definitions.
    expect(legacyAwardsLoader).toMatch(
      /reload_keyed\([\s\S]*?"awards", \["slug"\][\s\S]*?scope_column="slug", scope_values=\[UNDER_22_SLUG\], scope_exclude=True/,
    );
    // The winner reload now also excludes the named-medal awards, by slug.
    expect(legacyAwardsLoader).toContain(
      'award_ids[slug] for slug in NAMED_MEDAL_SLUGS if slug in award_ids',
    );
    expect(legacyAwardsLoader).toMatch(
      /reload_keyed\([\s\S]*?"award_winners", \["source_id", "source_record_id"\][\s\S]*?scope_column="award_id", scope_values=other_group_awards, scope_exclude=True/,
    );
  });
});

/**
 * Fable NL code review (final acceptance pass, 2026-09-17) corpus
 * correction: tools/nl/fix-stale-finals-without-premiership-tie.ts.
 *
 * DB-free: builds a small synthetic 12,000-row corpus in memory (real rows
 * would be the external ~/nl-stress-corpus-v5.csv, which this repository
 * does not carry) with the exact 3-row `verified_finals_without_premiership`
 * equivalence group the final V5 rerun reported failing, then proves the
 * invariants the script's own header promises: it rewrites exactly those
 * three rows' expected_answer_primary/expected_tie_count to the audited
 * two-way tie, preserves expected_answer_value=24 and every other column,
 * refuses on any before-state/count/question-identity mismatch, and never
 * touches anything else.
 */
import { describe, expect, it } from 'vitest';

import { toCsv } from '@/lib/csv';

import { parseCsv } from '../tools/nl/corpus';
import {
  AUDITED_QUESTIONS, assertAuditedTiePreState, assertOutputPathIsSafe, correctCorpus,
  normaliseQuestion, TARGET_EQUIVALENCE_GROUP,
} from '../tools/nl/fix-stale-finals-without-premiership-tie';

// ------------------------------------------------------------------ fixture

const HEADER = [
  'id', 'category', 'difficulty', 'verification_level', 'equivalence_group', 'question', 'notes',
  'expected_status', 'expected_grain', 'expected_metric', 'expected_aggregation',
  'expected_predicates_json', 'expected_answer_primary', 'expected_answer_value',
  'expected_tie_count', 'expected_min_confidence',
] as const;

type Row = Record<(typeof HEADER)[number], string>;

const TARGET_IDS = [11001, 11002, 11003] as const;

function baseRow(id: number): Row {
  return {
    id: String(id),
    category: 'filler',
    difficulty: '1',
    verification_level: 'SEMANTIC',
    equivalence_group: '',
    question: `Filler question ${id}`,
    notes: '',
    expected_status: 'success',
    expected_grain: 'player_game',
    expected_metric: '',
    expected_aggregation: '',
    expected_predicates_json: '',
    expected_answer_primary: '',
    expected_answer_value: '',
    expected_tie_count: '',
    expected_min_confidence: '',
  };
}

/** The exact audited pre-state for each target row. */
function tieRow(id: number, question: string): Row {
  return {
    ...baseRow(id),
    category: 'career_record',
    verification_level: 'VERIFIED_RESULT',
    equivalence_group: TARGET_EQUIVALENCE_GROUP,
    question,
    notes: 'Nick Dal Santo holds the record',
    expected_grain: 'player_career',
    expected_metric: 'finals',
    expected_aggregation: 'max',
    expected_predicates_json: '[{"column":"premierships","op":"eq","value":0}]',
    expected_answer_primary: 'Nick Dal Santo',
    expected_answer_value: '24',
    expected_tie_count: '1',
    expected_min_confidence: '0.9',
  };
}

function buildRows(mutate?: (rows: Map<number, Row>) => void): Row[] {
  const rows = new Map<number, Row>();
  for (let id = 1; id <= 12000; id++) rows.set(id, baseRow(id));

  // Real-corpus shape: mixed case and a trailing "?" on the interrogative.
  rows.set(TARGET_IDS[0], tieRow(TARGET_IDS[0], 'Most finals without a premiership'));
  rows.set(TARGET_IDS[1], tieRow(TARGET_IDS[1], 'most career finals without a premiership'));
  rows.set(TARGET_IDS[2], tieRow(TARGET_IDS[2], 'Who played the most finals without a premiership?'));

  mutate?.(rows);
  return [...rows.entries()].sort(([a], [b]) => a - b).map(([, row]) => row);
}

function buildCsv(rows: Row[] = buildRows()): string {
  return toCsv(HEADER, rows);
}

function parseBack(csvText: string): Row[] {
  const parsed = parseCsv(csvText);
  const header = parsed[0];
  return parsed.slice(1).map((cells) => {
    const record = {} as Row;
    header.forEach((name, index) => { (record as Record<string, string>)[name] = cells[index] ?? ''; });
    return record;
  });
}

// --------------------------------------------------------------------- tests

describe('finals-without-premiership tie correctCorpus', () => {
  it('rewrites exactly the 3 audited rows to the two-way tie and preserves the verified value', () => {
    const { outputCsvText, summary } = correctCorpus(buildCsv());

    expect(summary.inputRows).toBe(12000);
    expect(summary.outputRows).toBe(12000);
    expect(summary.targetRowsExpected).toBe(3);
    expect(summary.targetRowsModified).toBe(3);
    expect(summary.nonTargetRowsModified).toBe(0);
    expect(summary.targetIds).toEqual([...TARGET_IDS]);

    const outputRows = parseBack(outputCsvText);
    const byId = new Map(outputRows.map((row) => [Number(row.id), row]));

    for (const id of TARGET_IDS) {
      const row = byId.get(id)!;
      expect(row.expected_answer_primary).toBe('Dane Rampe|Nick Dal Santo');
      expect(row.expected_tie_count).toBe('2');

      // Preserved: the verified value and everything that is not the tie.
      expect(row.expected_answer_value).toBe('24');
      expect(row.expected_status).toBe('success');
      expect(row.verification_level).toBe('VERIFIED_RESULT');
      expect(row.equivalence_group).toBe(TARGET_EQUIVALENCE_GROUP);
      expect(row.expected_grain).toBe('player_career');
      expect(row.expected_metric).toBe('finals');
      expect(row.expected_predicates_json).toBe('[{"column":"premierships","op":"eq","value":0}]');
      expect(row.expected_min_confidence).toBe('0.9');
      expect(row.notes).toBe('Nick Dal Santo holds the record');
    }
  });

  it('leaves every non-target row byte-identical', () => {
    const inputRows = buildRows();
    const { outputCsvText } = correctCorpus(buildCsv(inputRows));
    const outputRows = parseBack(outputCsvText);
    expect(outputRows).toHaveLength(12000);
    const targets = new Set<number>(TARGET_IDS);
    for (let index = 0; index < inputRows.length; index++) {
      if (targets.has(Number(inputRows[index].id))) continue;
      expect(outputRows[index]).toEqual(inputRows[index]);
    }
  });

  it('question identity ignores case, surrounding whitespace and a trailing "?" only', () => {
    expect(normaliseQuestion('  Who played the most finals without a premiership?  '))
      .toBe('who played the most finals without a premiership');
    expect(normaliseQuestion('most   finals without a premiership')).toBe('most finals without a premiership');
    expect(AUDITED_QUESTIONS.map(normaliseQuestion)).toEqual(AUDITED_QUESTIONS);
  });

  // ---- refusals ----------------------------------------------------------

  it('refuses when the group does not hold exactly three rows', () => {
    const fewer = buildRows((rows) => { rows.get(TARGET_IDS[2])!.equivalence_group = ''; });
    expect(() => correctCorpus(buildCsv(fewer))).toThrow(/Expected exactly 3 rows in equivalence group/);

    const more = buildRows((rows) => {
      rows.set(5, { ...tieRow(5, 'most finals without a premiership') });
    });
    expect(() => correctCorpus(buildCsv(more))).toThrow(/Expected exactly 3 rows in equivalence group/);
  });

  it('refuses a group row whose question is not one of the audited three', () => {
    const rows = buildRows((rows) => {
      rows.get(TARGET_IDS[1])!.question = 'most grand finals without a premiership';
    });
    expect(() => correctCorpus(buildCsv(rows))).toThrow(/not one of this correction's audited questions/);
  });

  it('refuses when an audited question is duplicated inside the group (and another missing)', () => {
    const rows = buildRows((rows) => {
      rows.get(TARGET_IDS[1])!.question = 'most finals without a premiership';
    });
    expect(() => correctCorpus(buildCsv(rows))).toThrow(/not present exactly once in the group/);
  });

  it('refuses a target whose before-state is not the audited answer/value/tie', () => {
    const wrongPrimary = buildRows((rows) => { rows.get(TARGET_IDS[0])!.expected_answer_primary = 'Dane Rampe'; });
    expect(() => correctCorpus(buildCsv(wrongPrimary))).toThrow(/expects expected_answer_primary="Nick Dal Santo"/);

    const wrongValue = buildRows((rows) => { rows.get(TARGET_IDS[0])!.expected_answer_value = '25'; });
    expect(() => correctCorpus(buildCsv(wrongValue))).toThrow(/expects expected_answer_value=24/);

    const wrongTie = buildRows((rows) => { rows.get(TARGET_IDS[0])!.expected_tie_count = '2'; });
    expect(() => correctCorpus(buildCsv(wrongTie))).toThrow(/expects expected_tie_count=1/);

    const wrongStatus = buildRows((rows) => { rows.get(TARGET_IDS[0])!.expected_status = 'decline'; });
    expect(() => correctCorpus(buildCsv(wrongStatus))).toThrow(/expects expected_status="success"/);
  });

  it('refuses on structural corpus problems', () => {
    const wrongCount = buildRows();
    wrongCount.pop();
    expect(() => correctCorpus(buildCsv(wrongCount))).toThrow(/Expected exactly 12000 data rows/);

    const duplicate = buildRows();
    duplicate[10] = { ...duplicate[10], id: '5' };
    expect(() => correctCorpus(buildCsv(duplicate))).toThrow(/duplicate id/);

    const missingColumn = toCsv<Record<string, string>>(
      HEADER.filter((name) => name !== 'expected_tie_count'),
      buildRows().map(({ expected_tie_count: _t, ...rest }) => rest),
    );
    expect(() => correctCorpus(missingColumn)).toThrow(/missing required column "expected_tie_count"/);

    expect(() => correctCorpus('')).toThrow(/empty/);
  });

  it('assertAuditedTiePreState accepts the audited shape and rejects a blank tie count', () => {
    expect(() => assertAuditedTiePreState(tieRow(1, 'most finals without a premiership'))).not.toThrow();
    const blank = { ...tieRow(1, 'most finals without a premiership'), expected_tie_count: '' };
    expect(() => assertAuditedTiePreState(blank)).toThrow(/expects expected_tie_count=1/);
  });

  it('refuses to overwrite the input file unless deliberately allowed', () => {
    expect(() => assertOutputPathIsSafe('/tmp/a.csv', '/tmp/a.csv', false)).toThrow(/--allow-overwrite-input/);
    expect(() => assertOutputPathIsSafe('/tmp/a.csv', '/tmp/a.csv', true)).not.toThrow();
    expect(() => assertOutputPathIsSafe('/tmp/a.csv', '/tmp/b.csv', false)).not.toThrow();
  });
});

import { describe, expect, it } from 'vitest';

import { GRID_STATS, isGridStatKey } from '@/search/grid-solver-spec';
import {
  afterSirenRequiresMatchLink,
  decodePlanToken,
  describePlan,
  encodePlanToken,
  isNlMetric,
  NL_CAREER_COLUMNS,
  NL_LIMITS,
  NL_METRICS,
  validatePlan,
  type NlCareerColumn,
  type NlGrain,
  type NlQueryPlan,
} from '@/search/nl/plan';

function basePlan(overrides: Partial<NlQueryPlan> = {}): NlQueryPlan {
  return {
    v: 1,
    grain: 'player_career',
    metric: 'games',
    agg: { kind: 'max' },
    scope: {},
    careerConditions: [],
    careerPredicates: [],
    clubSeasonConditions: [],
    tiePolicy: 'all',
    limit: 25,
    ...overrides,
  };
}

describe('validatePlan', () => {
  it('accepts a well-formed plan unchanged (aside from clamping)', () => {
    const result = validatePlan(basePlan());
    expect('error' in result).toBe(false);
  });

  it('rejects an unknown grain', () => {
    const result = validatePlan({ ...basePlan(), grain: 'nonsense' as never });
    expect(result).toHaveProperty('error');
  });

  it('rejects a metric not in the grain\'s allowlist', () => {
    const result = validatePlan(basePlan({ metric: 'win_margin' })); // team_match metric, wrong grain
    expect(result).toHaveProperty('error');
  });

  it('requires mode on a player_game plan, and forbids it elsewhere', () => {
    const noMode = validatePlan(basePlan({ grain: 'player_game', metric: 'goals' }));
    expect(noMode).toHaveProperty('error');

    const wrongGrainMode = validatePlan(basePlan({ mode: 'single' }));
    expect(wrongGrainMode).toHaveProperty('error');

    const ok = validatePlan(basePlan({ grain: 'player_game', metric: 'goals', mode: 'single' }));
    expect('error' in ok).toBe(false);
  });

  describe('metric conditions (AFLDB-ISSUE-110)', () => {
    it.each([
      ['player_game single', { grain: 'player_game', metric: 'goals', mode: 'single' }],
      ['player_game sum', { grain: 'player_game', metric: 'disposals', mode: 'sum' }],
      ['player_season', { grain: 'player_season', metric: 'goals' }],
    ] as const)('accepts a %s list qualified by a metric condition', (_label, shape) => {
      for (const op of ['gte', 'lte', 'gt', 'lt', 'eq'] as const) {
        const result = validatePlan(basePlan({
          ...shape, agg: { kind: 'list' }, limit: 100, metricCondition: { op, value: 5 },
        }));
        expect('error' in result, `${_label} ${op}`).toBe(false);
      }
    });

    it('rejects a metric condition on a grain whose compiler cannot consume it', () => {
      expect(validatePlan(basePlan({
        metricCondition: { op: 'gte', value: 5 }, agg: { kind: 'list' }, metric: null,
        careerConditions: [{ kind: 'column', column: 'games', op: 'gte', value: 1 }],
      }))).toHaveProperty('error');
      expect(validatePlan(basePlan({
        grain: 'team_match', metric: 'win_margin',
        metricCondition: { op: 'gte', value: 5 },
      }))).toHaveProperty('error');
    });

    it('rejects a malformed comparator or value', () => {
      expect(validatePlan(basePlan({
        grain: 'player_game', metric: 'goals', mode: 'single', agg: { kind: 'list' },
        metricCondition: { op: 'between' as never, value: 5 },
      }))).toHaveProperty('error');
      expect(validatePlan(basePlan({
        grain: 'player_game', metric: 'goals', mode: 'single', agg: { kind: 'list' },
        metricCondition: { op: 'gte', value: Number.NaN },
      }))).toHaveProperty('error');
      expect(validatePlan(basePlan({
        grain: 'player_game', metric: 'goals', mode: 'single', agg: { kind: 'list' },
        metricCondition: { op: 'gte', value: -1 },
      }))).toHaveProperty('error');
    });

    it('rejects a ranked aggregation alongside a metric condition', () => {
      expect(validatePlan(basePlan({
        grain: 'player_game', metric: 'goals', mode: 'single', agg: { kind: 'max' },
        metricCondition: { op: 'gte', value: 5 },
      }))).toHaveProperty('error');
    });

    it('still requires mode on a player_game metric-condition plan', () => {
      expect(validatePlan(basePlan({
        grain: 'player_game', metric: 'goals', agg: { kind: 'list' },
        metricCondition: { op: 'gte', value: 5 },
      }))).toHaveProperty('error');
    });

    it('fails a player game/season list with no threshold closed instead of collapsing it to a leader', () => {
      expect(validatePlan(basePlan({ grain: 'player_game', metric: 'goals', mode: 'single', agg: { kind: 'list' } })))
        .toEqual({ error: 'Listing player results needs a qualifying threshold.' });
      expect(validatePlan(basePlan({ grain: 'player_season', metric: 'goals', agg: { kind: 'list' } })))
        .toEqual({ error: 'Listing player results needs a qualifying threshold.' });
    });

    it('rejects a metric condition smuggled into a head-to-head plan', () => {
      expect(validatePlan(basePlan({
        grain: 'head_to_head', metric: null, agg: { kind: 'count' },
        headToHead: { kind: 'record' },
        scope: {
          matchup: {
            clubA: { organizationId: 1, slug: 'a', name: 'A' },
            clubB: { organizationId: 2, slug: 'b', name: 'B' },
          },
        },
        metricCondition: { op: 'gte', value: 1 },
      }))).toHaveProperty('error');
    });

    it('describes the applied threshold in the plan trace', () => {
      const plan = validatePlan(basePlan({
        grain: 'player_game', metric: 'disposals', mode: 'sum', agg: { kind: 'list' }, limit: 100,
        metricCondition: { op: 'lte', value: 25 },
      }));
      if ('error' in plan) throw new Error(plan.error);
      expect(describePlan(plan)).toContain('Condition: disposals at most 25.');
    });
  });

  describe('career-grain scope backstop (AFLDB-ISSUE-110 revision)', () => {
    const SCOPE_ERROR = 'A career question cannot be scoped to a venue, opponent, match type, or round.';
    const SEASON_ERROR = 'A career question cannot be restricted to a season range.';
    const carlton = { organizationId: 2, slug: 'carlton', name: 'Carlton' };

    it('rejects a career-condition plan carrying opponent scope its compiler cannot consume', () => {
      // The exact scope-discarding shape: "players with more than 100
      // games against Carlton" used to validate and answer whole-career
      // games with the opponent silently ignored.
      expect(validatePlan(basePlan({
        metric: null, agg: { kind: 'list' },
        careerConditions: [{ kind: 'column', column: 'games', op: 'gt', value: 100 }],
        scope: { clubAgainst: carlton },
      }))).toEqual({ error: SCOPE_ERROR });
    });

    it('rejects venue, match-type, and round scope on any career plan', () => {
      expect(validatePlan(basePlan({ scope: { venue: { id: 1, slug: 'mcg', name: 'MCG' } } })))
        .toEqual({ error: SCOPE_ERROR });
      expect(validatePlan(basePlan({ scope: { matchType: 'finals' } })))
        .toEqual({ error: SCOPE_ERROR });
      expect(validatePlan(basePlan({ scope: { roundNumber: 5 } })))
        .toEqual({ error: SCOPE_ERROR });
    });

    it('rejects season bounds on every non-predicate career execution path', () => {
      expect(validatePlan(basePlan({
        metric: null, agg: { kind: 'list' },
        careerConditions: [{ kind: 'column', column: 'goals', op: 'gt', value: 500 }],
        scope: { seasonMin: 2000 },
      }))).toEqual({ error: SEASON_ERROR });
      expect(validatePlan(basePlan({
        metric: 'goals', agg: { kind: 'max' },
        scope: { seasonMin: 2000 },
      }))).toEqual({ error: SEASON_ERROR });
      expect(validatePlan(basePlan({
        metric: 'goals', agg: { kind: 'max' },
        scope: { seasonMax: 1999 },
      }))).toEqual({ error: SEASON_ERROR });
      expect(validatePlan(basePlan({
        metric: 'goals', agg: { kind: 'max' },
        scope: { seasonMin: 2000, seasonMax: 2000 },
      }))).toEqual({ error: SEASON_ERROR });
    });

    it('still accepts unscoped all-time, condition-list, and clubFor career shapes', () => {
      expect('error' in validatePlan(basePlan({
        metric: 'goals', agg: { kind: 'max' }, scope: {},
      }))).toBe(false);
      expect('error' in validatePlan(basePlan({
        metric: null, agg: { kind: 'list' },
        careerConditions: [{ kind: 'column', column: 'goals', op: 'gt', value: 500 }],
      }))).toBe(false);
      expect('error' in validatePlan(basePlan({
        metric: 'games', agg: { kind: 'max' },
        scope: { clubFor: carlton },
      }))).toBe(false);
    });

    // AFLDB-ISSUE-110 findings A and B: a career predicate exempted a plan
    // from both backstops by existing, but a builder consumes only its own
    // parameters. Ownership is per builder, and a field nothing owns fails
    // closed -- it is never folded into a guessed played_for_club reading.
    describe('career predicate field ownership', () => {
      const CLUB_ERROR = 'This kind of career question cannot be limited to one club.';
      const listPlan = { metric: null, agg: { kind: 'list' } } as const;

      it('rejects a season range no predicate consumes', () => {
        expect(validatePlan(basePlan({
          ...listPlan,
          careerPredicates: [{ builder: 'grand_finals_played_min', params: { times: '3' } }],
          scope: { seasonMin: 2000 },
        }))).toEqual({ error: SEASON_ERROR });
        expect(validatePlan(basePlan({
          ...listPlan,
          careerPredicates: [{ builder: 'premierships_min', params: { times: '2' } }],
          scope: { seasonMin: 1990, seasonMax: 1999 },
        }))).toEqual({ error: SEASON_ERROR });
      });

      it('accepts a season range a predicate takes as a builder parameter', () => {
        expect('error' in validatePlan(basePlan({
          ...listPlan,
          careerPredicates: [{ builder: 'debuted_between', params: { from: '1990', to: '1999' } }],
          scope: { seasonMin: 1990, seasonMax: 1999 },
        }))).toBe(false);
        expect('error' in validatePlan(basePlan({
          ...listPlan,
          careerPredicates: [{ builder: 'first_kick_goal_between', params: { from: '1940', to: '1949' } }],
          scope: { seasonMin: 1940, seasonMax: 1949 },
        }))).toBe(false);
      });

      it('rejects a club no predicate consumes, with or without a season range', () => {
        expect(validatePlan(basePlan({
          ...listPlan,
          careerPredicates: [{ builder: 'debuted_between', params: { from: '2000', to: '2100' } }],
          scope: { clubFor: carlton, seasonMin: 2000 },
        }))).toEqual({ error: CLUB_ERROR });
        expect(validatePlan(basePlan({
          ...listPlan,
          careerPredicates: [{ builder: 'grand_finals_played_min', params: { times: '3' } }],
          scope: { clubFor: carlton },
        }))).toEqual({ error: CLUB_ERROR });
      });

      it('accepts a club a predicate takes as a builder parameter', () => {
        expect('error' in validatePlan(basePlan({
          ...listPlan,
          careerPredicates: [
            { builder: 'first_kick_goal_for_club', params: { club: '2' } },
            { builder: 'first_kick_goal_between', params: { from: '1940', to: '1949' } },
          ],
          scope: { clubFor: carlton, seasonMin: 1940, seasonMax: 1949 },
        }))).toBe(false);
      });

      it('leaves the predicate-free club and predicate-only shapes exactly as they were', () => {
        // No predicates: the compiler's own clubFor filter and club-scoped
        // totals own the club, so the supported-metric gate still decides.
        expect('error' in validatePlan(basePlan({
          metric: 'games', agg: { kind: 'max' }, scope: { clubFor: carlton },
        }))).toBe(false);
        expect(validatePlan(basePlan({
          metric: 'premierships', agg: { kind: 'max' }, scope: { clubFor: carlton },
        }))).toEqual({ error: 'This career statistic cannot currently be totalled for one club.' });
        // A predicate with no season range and no club is untouched.
        expect('error' in validatePlan(basePlan({
          ...listPlan,
          careerPredicates: [{ builder: 'grand_finals_played_min', params: { times: '3' } }],
        }))).toBe(false);
      });
    });

    // AFLDB-ISSUE-259: the compiler club-scopes a `games` condition and no
    // other, so a club-scoped career plan -- ranked or not -- is answerable
    // only when every condition is a games condition. The ranked branch
    // previously never looked at conditions and mixed a club-scoped ranking
    // with a whole-career filter.
    describe('club-scoped career conditions (AFLDB-ISSUE-259)', () => {
      const CLUB_STAT_ERROR = 'This career statistic cannot currently be totalled for one club.';
      const premierships0 = { kind: 'column', column: 'premierships', op: 'eq', value: 0 } as const;
      const brownlow2 = { kind: 'column', column: 'brownlow_medals', op: 'gte', value: 2 } as const;
      const games200 = { kind: 'column', column: 'games', op: 'gte', value: 200 } as const;
      const aa1 = { kind: 'award_count', awardKey: 'all_australian', op: 'gte', value: 1 } as const;
      const unranked = { metric: null, agg: { kind: 'list' } } as const;
      const ranked = { metric: 'games', agg: { kind: 'max' } } as const;

      it('refuses a ranked club-scoped plan carrying a non-games column condition', () => {
        expect(validatePlan(basePlan({
          ...ranked, scope: { clubFor: carlton }, careerConditions: [premierships0],
        }))).toEqual({ error: CLUB_STAT_ERROR });
        expect(validatePlan(basePlan({
          ...ranked, scope: { clubFor: carlton }, careerConditions: [brownlow2],
        }))).toEqual({ error: CLUB_STAT_ERROR });
        // A club-scopable stat metric is refused the same way.
        expect(validatePlan(basePlan({
          metric: 'goals', agg: { kind: 'top_n', n: 5 }, scope: { clubFor: carlton }, careerConditions: [premierships0],
        }))).toEqual({ error: CLUB_STAT_ERROR });
      });

      it('refuses a ranked club-scoped plan carrying an award condition', () => {
        expect(validatePlan(basePlan({
          ...ranked, scope: { clubFor: carlton }, careerConditions: [aa1],
        }))).toEqual({ error: CLUB_STAT_ERROR });
      });

      it('refuses a ranked club-scoped plan when a games condition is mixed with another', () => {
        expect(validatePlan(basePlan({
          ...ranked, scope: { clubFor: carlton }, careerConditions: [games200, premierships0],
        }))).toEqual({ error: CLUB_STAT_ERROR });
      });

      it('refuses the unranked form identically', () => {
        expect(validatePlan(basePlan({
          ...unranked, scope: { clubFor: carlton }, careerConditions: [premierships0],
        }))).toEqual({ error: CLUB_STAT_ERROR });
        expect(validatePlan(basePlan({
          ...unranked, scope: { clubFor: carlton }, careerConditions: [aa1],
        }))).toEqual({ error: CLUB_STAT_ERROR });
        expect(validatePlan(basePlan({
          ...unranked, scope: { clubFor: carlton }, careerConditions: [games200, premierships0],
        }))).toEqual({ error: CLUB_STAT_ERROR });
      });

      it('keeps club-scoped plans whose conditions are all on games', () => {
        expect('error' in validatePlan(basePlan({
          ...ranked, scope: { clubFor: carlton }, careerConditions: [games200],
        }))).toBe(false);
        expect('error' in validatePlan(basePlan({
          metric: 'goals', agg: { kind: 'max' }, scope: { clubFor: carlton }, careerConditions: [games200],
        }))).toBe(false);
        expect('error' in validatePlan(basePlan({
          ...unranked, scope: { clubFor: carlton }, careerConditions: [games200],
        }))).toBe(false);
        // No condition at all on a club-scoped ranking is unchanged.
        expect('error' in validatePlan(basePlan({
          ...ranked, scope: { clubFor: carlton },
        }))).toBe(false);
      });

      it('keeps whole-career plans with any condition valid when no club is set', () => {
        expect('error' in validatePlan(basePlan({ ...ranked, careerConditions: [premierships0] }))).toBe(false);
        expect('error' in validatePlan(basePlan({ ...ranked, careerConditions: [brownlow2, aa1] }))).toBe(false);
        expect('error' in validatePlan(basePlan({ ...unranked, careerConditions: [games200, premierships0] }))).toBe(false);
      });
    });
  });

  describe('season-grain scope backstop (AFLDB-ISSUE-110 final review)', () => {
    // answerPlayerSeason consumes player/playerIdIn/season-range/clubFor/
    // metricCondition and nothing else in match scope: a player_season
    // plan carrying any of these four would validate and then silently
    // answer the whole-season question with the scope discarded.
    const SCOPE_ERROR = 'A season total cannot be scoped to a venue, opponent, match type, or round.';
    const carlton = { organizationId: 2, slug: 'carlton', name: 'Carlton' };
    const seasonThreshold = (scope: NlQueryPlan['scope']) => basePlan({
      grain: 'player_season', metric: 'disposals', agg: { kind: 'list' },
      metricCondition: { op: 'gt', value: 20 },
      scope,
    });

    it('rejects opponent scope on a season threshold list its executor cannot consume', () => {
      // The exact HIGH-finding shape: "players with more than 20
      // disposals in a season against Carlton" must not become
      // whole-season disposals against every opponent.
      expect(validatePlan(seasonThreshold({ clubAgainst: carlton }))).toEqual({ error: SCOPE_ERROR });
    });

    it('rejects venue, match-type, and round scope on a season threshold list', () => {
      expect(validatePlan(seasonThreshold({ venue: { id: 30, slug: 'mcg', name: 'MCG' } })))
        .toEqual({ error: SCOPE_ERROR });
      expect(validatePlan(seasonThreshold({ matchType: 'grand_final' }))).toEqual({ error: SCOPE_ERROR });
      expect(validatePlan(seasonThreshold({ roundNumber: 5 }))).toEqual({ error: SCOPE_ERROR });
    });

    it('rejects the same scope on a ranked season leaderboard, not just threshold lists', () => {
      expect(validatePlan(basePlan({
        grain: 'player_season', metric: 'goals', agg: { kind: 'max' },
        scope: { matchType: 'finals' },
      }))).toEqual({ error: SCOPE_ERROR });
      expect(validatePlan(basePlan({
        grain: 'player_season', metric: 'goals', agg: { kind: 'max' },
        scope: { clubAgainst: carlton },
      }))).toEqual({ error: SCOPE_ERROR });
    });

    it('still accepts the season shapes the executor genuinely consumes', () => {
      expect('error' in validatePlan(seasonThreshold({}))).toBe(false);
      expect('error' in validatePlan(seasonThreshold({ seasonMin: 1989, seasonMax: 1989 }))).toBe(false);
      expect('error' in validatePlan(seasonThreshold({ clubFor: carlton }))).toBe(false);
      expect('error' in validatePlan(basePlan({
        grain: 'player_season', metric: 'goals', agg: { kind: 'max' },
        scope: { clubFor: carlton, seasonMin: 2017, seasonMax: 2017 },
      }))).toBe(false);
    });
  });

  describe('player-season tie policy (AFLDB-ISSUE-110)', () => {
    it('keeps the executor-supported all-ties policy valid', () => {
      expect(validatePlan(basePlan({
        grain: 'player_season', metric: 'goals', agg: { kind: 'max' }, tiePolicy: 'all',
      }))).not.toHaveProperty('error');
    });

    it('rejects first-tie selection until the player-season executor supports it', () => {
      expect(validatePlan(basePlan({
        grain: 'player_season', metric: 'goals', agg: { kind: 'max' }, tiePolicy: 'first',
      }))).toEqual({ error: 'Player-season questions do not support first-tie selection.' });
    });
  });

  it('rejects career conditions on a non-career grain', () => {
    const result = validatePlan(basePlan({
      grain: 'player_game', metric: 'goals', mode: 'single',
      careerConditions: [{ kind: 'column', column: 'games', op: 'gte', value: 100 }],
    }));
    expect(result).toHaveProperty('error');
  });

  it('caps the number of career conditions and predicates', () => {
    const tooMany = validatePlan(basePlan({
      careerConditions: Array.from({ length: NL_LIMITS.maxCareerConditions + 1 }, () => (
        { kind: 'column' as const, column: 'games' as const, op: 'gte' as const, value: 1 }
      )),
    }));
    expect(tooMany).toHaveProperty('error');
  });

  it('rejects an unknown career column, award key or grid builder', () => {
    expect(validatePlan(basePlan({
      careerConditions: [{ kind: 'column', column: 'not_a_column' as never, op: 'eq', value: 0 }],
    }))).toHaveProperty('error');

    expect(validatePlan(basePlan({
      careerConditions: [{ kind: 'award_count', awardKey: 'not_an_award' as never, op: 'gte', value: 1 }],
    }))).toHaveProperty('error');

    expect(validatePlan(basePlan({
      careerPredicates: [{ builder: 'not_a_real_builder', params: {} }],
    }))).toHaveProperty('error');
  });

  it('accepts a real award condition and a real grid predicate', () => {
    const award = validatePlan(basePlan({
      metric: 'all_australian_selections',
      careerConditions: [{ kind: 'award_count', awardKey: 'all_australian', op: 'gte', value: 5 }],
    }));
    expect('error' in award).toBe(false);

    const predicate = validatePlan(basePlan({
      careerPredicates: [{ builder: 'premierships_min', params: { times: '3' } }],
    }));
    expect('error' in predicate).toBe(false);
  });

  it('rejects a boundary on a non-career grain, and an unknown boundary shape', () => {
    expect(validatePlan(basePlan({
      grain: 'player_game', metric: 'goals', mode: 'single',
      boundary: { event: 'debut', where: 'grand_final' },
    }))).toHaveProperty('error');

    expect(validatePlan(basePlan({
      boundary: { event: 'nonsense' as never, where: 'grand_final' },
    }))).toHaveProperty('error');
  });

  // AFLDB-ISSUE-201: the season range names when the boundary event itself
  // happened, not a career-aggregation window -- raw.boundary must exempt
  // the plan from the generic player_career season-range rejection
  // (plan.ts:2239-2244) the same way an owning careerPredicates builder
  // (e.g. debuted_between) already does. Uses metric: null / agg: list,
  // the real shape parseNlQuestion produces for these questions (see
  // tests/nl-parser.test.ts "AFLDB-ISSUE-201: boundary plus a season
  // range").
  describe('AFLDB-ISSUE-201: a boundary owns its own season range', () => {
    const boundaryListPlan = { metric: null, agg: { kind: 'list' as const } };

    it.each([
      ['exact year', { seasonMin: 1897, seasonMax: 1897 }],
      ['since', { seasonMin: 2000 }],
      ['before', { seasonMax: 1949 }],
    ] as const)('accepts a debut/grand_final boundary with a season range (%s)', (_label, scope) => {
      const result = validatePlan(basePlan({
        ...boundaryListPlan,
        boundary: { event: 'debut', where: 'grand_final' },
        scope,
      }));
      expect('error' in result).toBe(false);
    });

    it('accepts last_game with a season range', () => {
      const result = validatePlan(basePlan({
        ...boundaryListPlan,
        boundary: { event: 'last_game', where: 'grand_final' },
        scope: { seasonMin: 2000 },
      }));
      expect('error' in result).toBe(false);
    });

    it('accepts the plain "final" boundary target with a season range', () => {
      const result = validatePlan(basePlan({
        ...boundaryListPlan,
        boundary: { event: 'debut', where: 'final' },
        scope: { seasonMin: 2000 },
      }));
      expect('error' in result).toBe(false);
    });

    // The exception is boundary-only: no career predicate gained a new
    // season-owning path, and a plan with neither a boundary nor an
    // owning predicate must still refuse exactly as before.
    it('does not broaden the exemption to a boundary-free plan', () => {
      const result = validatePlan(basePlan({ ...boundaryListPlan, scope: { seasonMin: 2000 } }));
      expect(result).toEqual({ error: 'A career question cannot be restricted to a season range.' });
    });
  });

  it('rejects a malformed entity reference', () => {
    expect(validatePlan(basePlan({
      scope: { clubFor: { organizationId: 0, slug: 'x', name: 'X' } },
    }))).toHaveProperty('error');

    expect(validatePlan(basePlan({
      scope: { venue: { id: -1, slug: 'x', name: 'X' } },
    }))).toHaveProperty('error');
  });

  it('rejects an unknown match type', () => {
    expect(validatePlan(basePlan({ scope: { matchType: 'nonsense' as never } }))).toHaveProperty('error');
  });

  it('rejects an out-of-range or backwards season', () => {
    expect(validatePlan(basePlan({ scope: { seasonMin: 1800 } }))).toHaveProperty('error');
    expect(validatePlan(basePlan({ scope: { seasonMax: 2200 } }))).toHaveProperty('error');
    expect(validatePlan(basePlan({ scope: { seasonMin: 2000, seasonMax: 1990 } }))).toHaveProperty('error');
  });

  it('declines an era-limited metric whose coverage starts after the requested range', () => {
    const result = validatePlan(basePlan({
      grain: 'player_game', metric: 'tackles', mode: 'single',
      scope: { seasonMin: 1950, seasonMax: 1960 },
    }));
    expect(result).toHaveProperty('error');
    if ('error' in result) expect(result.error).toMatch(/1987/);
  });

  it('allows an era-limited metric when the range overlaps its coverage', () => {
    const result = validatePlan(basePlan({
      grain: 'player_game', metric: 'tackles', mode: 'single',
      scope: { seasonMin: 1980, seasonMax: 1990 },
    }));
    expect('error' in result).toBe(false);
  });

  it('clamps top_n to the configured maximum rather than rejecting it', () => {
    const result = validatePlan(basePlan({ agg: { kind: 'top_n', n: 999 } }));
    expect('error' in result).toBe(false);
    if (!('error' in result)) expect(result.agg).toEqual({ kind: 'top_n', n: NL_LIMITS.maxTopN });
  });

  it('rejects a non-positive top_n', () => {
    expect(validatePlan(basePlan({ agg: { kind: 'top_n', n: 0 } }))).toHaveProperty('error');
  });

  it('clamps limit to the tied-rows cap for max/min, and the list cap for top_n/list', () => {
    const maxPlan = validatePlan(basePlan({ agg: { kind: 'max' }, limit: 9999 }));
    if (!('error' in maxPlan)) expect(maxPlan.limit).toBe(NL_LIMITS.maxTiedRows);

    const listPlan = validatePlan(basePlan({ agg: { kind: 'list' }, limit: 9999 }));
    if (!('error' in listPlan)) expect(listPlan.limit).toBe(NL_LIMITS.maxListRows);
  });

  it('accepts only executable grouped team-result shapes', () => {
    const grouped = basePlan({
      grain: 'team_match', metric: null, agg: { kind: 'list' },
      havingClause: { metric: 'losses', op: 'gte', value: 5 },
      matchFilter: { metric: 'loss_margin', op: 'gt', value: 100 },
    });
    expect(validatePlan(grouped)).not.toHaveProperty('error');
    expect(validatePlan({ ...grouped, agg: { kind: 'max' } })).toHaveProperty('error');
    expect(validatePlan({ ...grouped, grain: 'club_season' })).toHaveProperty('error');
    expect(validatePlan({
      ...grouped,
      havingClause: { metric: 'wins', op: 'gte', value: 5 },
    })).toHaveProperty('error');
  });

  it('rejects plan fields on grains whose compilers cannot consume them', () => {
    expect(validatePlan(basePlan({
      grain: 'player_season', metric: 'goals', periodSplit: 'Q1',
    }))).toEqual({ error: 'Quarter-by-quarter player statistics are not currently available to rank.' });
    expect(validatePlan(basePlan({
      streakDefinition: { kind: 'win' },
    }))).toHaveProperty('error');
    expect(validatePlan(basePlan({
      grain: 'player_game', metric: 'goals', mode: 'single', debutGame: true,
    }))).not.toHaveProperty('error');
    expect(validatePlan(basePlan({ debutGame: true }))).toHaveProperty('error');
  });

  it('limits period splits to meaningful team scoring metrics', () => {
    expect(validatePlan(basePlan({
      grain: 'team_match', metric: 'team_score', periodSplit: 'H2',
    }))).not.toHaveProperty('error');
    expect(validatePlan(basePlan({
      grain: 'team_match', metric: 'attendance', periodSplit: 'Q1',
    }))).toHaveProperty('error');
  });

  it('never throws on a wildly malformed plan', () => {
    expect(() => validatePlan({} as NlQueryPlan)).not.toThrow();
  });
});

describe('describePlan', () => {
  it('produces a non-empty, ordered trace including every set field', () => {
    const plan = basePlan({
      grain: 'player_game', mode: 'single', metric: 'disposals',
      agg: { kind: 'top_n', n: 5 },
      player: { id: 1, slug: 'dustin-martin', name: 'Dustin Martin' },
      scope: {
        clubAgainst: { organizationId: 2, slug: 'carlton', name: 'Carlton' },
        venue: { id: 1, slug: 'mcg', name: 'Melbourne Cricket Ground' },
        seasonMin: 1980,
      },
    });
    const lines = describePlan(plan);
    expect(lines.length).toBeGreaterThan(3);
    expect(lines.some((l) => l.includes('Dustin Martin'))).toBe(true);
    expect(lines.some((l) => l.includes('Carlton'))).toBe(true);
    expect(lines.some((l) => l.includes('Melbourne Cricket Ground'))).toBe(true);
    expect(lines.some((l) => l.includes('1980'))).toBe(true);
  });

  it('calls a scoped total a total, not a single-match performance (AFLDB-ISSUE-110)', () => {
    // "most goals for Geelong" elects player_game in SUM mode -- a
    // club-scoped career total. The explain trace is what tells the
    // reader which question was answered, and the flat grain label
    // called it a single-match search while the answer text underneath
    // correctly said "Total across N games in scope".
    const summed = describePlan(basePlan({
      grain: 'player_game', mode: 'sum', metric: 'goals', agg: { kind: 'max' },
      scope: { clubFor: { organizationId: 4, slug: 'geelong', name: 'Geelong' } },
    }));
    expect(summed[0]).toBe('Searched for the highest total goals.');
    expect(summed).toContain('Club: Geelong.');
    expect(summed.join(' ')).not.toContain('single-match');

    const rankedTotals = describePlan(basePlan({
      grain: 'player_game', mode: 'sum', metric: 'goals', agg: { kind: 'top_n', n: 5 },
    }));
    expect(rankedTotals[0]).toBe('Ranked total goals, the top 5.');

    // Single mode is untouched: it really is one performance.
    const single = describePlan(basePlan({
      grain: 'player_game', mode: 'single', metric: 'goals', agg: { kind: 'max' },
    }));
    expect(single[0]).toBe('Searched for the highest single-match goals.');
  });

  it('describes career conditions and predicates in plain words', () => {
    const plan = basePlan({
      metric: null,
      careerConditions: [{ kind: 'column', column: 'premierships', op: 'eq', value: 0 }],
      careerPredicates: [{ builder: 'played_a_grand_final', params: {} }],
    });
    const lines = describePlan(plan);
    expect(lines.some((l) => /premierships.*exactly 0/.test(l))).toBe(true);
    expect(lines.some((l) => l.includes('Played a grand final'))).toBe(true);
  });

  // AFLDB-ISSUE-260: the condition label used to be NL_CAREER_COLUMNS' value,
  // the compiler's SQL marker ("Condition: c.premierships exactly 0.").
  describe('career condition labels (AFLDB-ISSUE-260)', () => {
    const careerLines = (careerConditions: NlQueryPlan['careerConditions'], overrides: Partial<NlQueryPlan> = {}) =>
      describePlan(basePlan({ metric: null, agg: { kind: 'list' }, careerConditions, ...overrides }))
        .filter((line) => line.startsWith('Condition:'));

    it('prints no SQL alias or column identifier for any career condition column', () => {
      for (const [column, marker] of Object.entries(NL_CAREER_COLUMNS)) {
        const [line] = careerLines([{ kind: 'column', column: column as NlCareerColumn, op: 'gte', value: 7 }]);
        expect(line, column).toMatch(/^Condition: [A-Za-z][A-Za-z ]* at least 7\.$/);
        expect(line, column).not.toContain(marker);
        expect(line, column).not.toMatch(/\bc\.|_/);
      }
    });

    it('names each column in reader-facing words, keeping its operator and value', () => {
      expect(careerLines([{ kind: 'column', column: 'premierships', op: 'eq', value: 0 }]))
        .toEqual(['Condition: premierships exactly 0.']);
      expect(careerLines([{ kind: 'column', column: 'games', op: 'gte', value: 300 }]))
        .toEqual(['Condition: games at least 300.']);
      expect(careerLines([{ kind: 'column', column: 'clubs_played', op: 'gte', value: 3 }]))
        .toEqual(['Condition: clubs played at least 3.']);
      expect(careerLines([{ kind: 'column', column: 'brownlow_medals', op: 'gt', value: 1 }]))
        .toEqual(['Condition: Brownlow medals more than 1.']);
      expect(careerLines([{ kind: 'column', column: 'brownlow_votes', op: 'lte', value: 10 }]))
        .toEqual(['Condition: Brownlow votes at most 10.']);
      expect(careerLines([{ kind: 'column', column: 'losses', op: 'lt', value: 5 }]))
        .toEqual(['Condition: losses less than 5.']);
      expect(careerLines([{ kind: 'column', column: 'debut_season', op: 'gte', value: 2000 }]))
        .toEqual(['Condition: debut season at least 2000.']);
    });

    it('keeps one line per condition, in plan order, for a multi-condition plan', () => {
      expect(careerLines([
        { kind: 'column', column: 'premierships', op: 'eq', value: 0 },
        { kind: 'column', column: 'games', op: 'gte', value: 300 },
      ])).toEqual([
        'Condition: premierships exactly 0.',
        'Condition: games at least 300.',
      ]);
    });

    it('labels a ranked plan\'s condition the same way', () => {
      const lines = describePlan(basePlan({
        metric: 'games', agg: { kind: 'max' },
        careerConditions: [{ kind: 'column', column: 'premierships', op: 'eq', value: 0 }],
      }));
      expect(lines).toContain('Condition: premierships exactly 0.');
      expect(lines.join(' ')).not.toMatch(/\bc\./);
    });

    it('still names a club-scoped games condition after the club, and an award by its label', () => {
      expect(careerLines(
        [{ kind: 'column', column: 'games', op: 'gte', value: 200 }],
        { scope: { clubFor: { organizationId: 4, slug: 'collingwood', name: 'Collingwood' } } },
      )).toEqual(['Condition: games for Collingwood at least 200.']);
      expect(careerLines([{ kind: 'award_count', awardKey: 'all_australian', op: 'gte', value: 2 }]))
        .toEqual(['Condition: All-Australian selections at least 2.']);
    });
  });

  it('uses the answer grain in tie prose and describes grouped counts without a fake metric', () => {
    const matchLines = describePlan(basePlan({ grain: 'team_match', metric: 'team_score' }));
    expect(matchLines).toContain('Ties: every match sharing the value is included.');
    expect(matchLines.join(' ')).not.toContain('every player');

    const groupedLines = describePlan(basePlan({
      grain: 'team_match', metric: null, agg: { kind: 'list' },
      havingClause: { metric: 'wins', op: 'gt', value: 3 },
    }));
    expect(groupedLines).toContain('Grouped clubs by wins and kept counts more than 3.');
    expect(groupedLines.some((line) => line.startsWith('Ties:'))).toBe(false);
  });
});

describe('validatePlan: count aggregation gate (AFLDB-ISSUE-190)', () => {
  it('refuses count on grains whose compiler ranks rather than counts', () => {
    expect(validatePlan(basePlan({
      grain: 'player_game', metric: 'goals', mode: 'single', agg: { kind: 'count' },
