    expect(proof).toBeGreaterThan(t21);
    expect(write).toBeGreaterThan(proof);
    expect(fn.slice(fn.indexOf('decideAflApiRevoke('), fn.indexOf('decideAflApiRevoke(') + 300)).toContain('ledgerNetAction');

