    const base = {
      existingRow: { id: 1, status: 'unique', playerId: 42, matchMethod: 'afl_api_stat_vector_bootstrap' },
      chosenPlayerOtherAflApiProviderId: null, chosenPlayerHasStableIdentity: false,
