    // SET takes no bind parameter: any `SET … ${…}` becomes `SET … $1` and always fails.
    expect(source).not.toMatch(/\bSET\s+(LOCAL\s+)?\w+\s*(=|TO)\s*\$\{/i);
    expect(source).not.toContain('SET LOCAL lock_timeout');
