    const i17 = suite.slice(suite.indexOf("describe('AFLDB-ISSUE-235 (I17)"), suite.indexOf("it('I17 (R1/R2 live pin)"));
    expect(i17).toMatch(/^describe\('AFLDB-ISSUE-235 \(I17\)/);
