});

/*
 * AFLDB-ISSUE-096 S1 — the source-family acquisition contract.
 *
 * data/reference/source-families.json declares, per (source key, family), the
 * external key shape, hash exclusions, required/known columns, round vocabulary
 * and independence group; src/lib/acquisition/source-families.ts parses it
 * fail-closed. These tests pin the parts of the contract that a later family
 * issue must not quietly relax: Kali and Squiggle stay ONE match witness,
 * lineups are never promotable, zero is not a weight, and round integers are
 * not comparable across sources. No database.
 */
describe('source families dataset (AFLDB-ISSUE-096 S1)', () => {
  const registry = parseSourceFamilyRegistry(sourceFamiliesRaw);

  const clone = (): any => JSON.parse(JSON.stringify(sourceFamiliesRaw));
  const familyIn = (data: any, sourceKey: string, family: string): any =>
    data.families.find((f: any) => f.source_key === sourceKey && f.family === family);
  const refuses = (mutate: (data: any) => void): void => {
    const data = clone();
    mutate(data);
    expect(() => parseSourceFamilyRegistry(data)).toThrow();
  };
  /** The `refuses` sibling, for a mutation that must still PARSE. */
  const mutated = (mutate: Parameters<typeof refuses>[0]) => {
    const data = clone();
    mutate(data);
    return data;
  };

  it('declares the four 2026 acquisition sources by stable key only', () => {
    expect([...registry.sources.keys()].sort()).toEqual([
      'afl_api', 'afltables', 'kali_afl_stats', 'squiggle_api',
    ]);
    // A database-local sources.id must never appear in a tracked contract as an
    // actual PROPERTY (`"source_id": ...`). This walks real JSON keys only, so it
    // never rejects a differently-named provenance concept whose key merely
    // CONTAINS the substring (e.g. `attendance_source_id`, a real matches column
    // named in explanatory prose) or a prose string that happens to mention it.
    const forbiddenKey = 'source_id';
    const findForbiddenKey = (value: unknown, path: string): string | null => {
      if (Array.isArray(value)) {
        for (const [index, item] of value.entries()) {
          const hit = findForbiddenKey(item, `${path}[${index}]`);
          if (hit) return hit;
        }
        return null;
      }
      if (value !== null && typeof value === 'object') {
        for (const [key, child] of Object.entries(value as Record<string, unknown>)) {
          if (key === forbiddenKey) return `${path}.${key}`;
          const hit = findForbiddenKey(child, `${path}.${key}`);
          if (hit) return hit;
        }
      }
      return null;
    };
    expect(findForbiddenKey(sourceFamiliesRaw, 'registry')).toBeNull();

    // Each declared key must exist where the registration says it does.
    expect(sources.sources.map((s: any) => s.key)).toContain('afltables');
    const migration063 = readFileSync(
      join(root, 'src', 'db', 'migrations', '063_external_current_match_sources.sql'), 'utf8');
    for (const key of ['squiggle_api', 'kali_afl_stats']) {
      expect(registry.sources.get(key)!.registeredBy).toBe('migration');
      expect(migration063).toContain(`('${key}'`);
    }
    // AFLDB-ISSUE-228 S6-A: the AFL API's sources row is registered by
    // migration 077 (idempotently, fail-closed on a pre-existing row with
    // different provenance), not merely a declared reference dataset.
    expect(registry.sources.get('afl_api')!.registeredBy).toBe('migration');
    const migration077 = readFileSync(
      join(root, 'src', 'db', 'migrations', '077_afl_api_lineups.sql'), 'utf8');
    expect(registry.sources.get('afl_api')!.registeredIn).toBe('src/db/migrations/077_afl_api_lineups.sql');
    // Whitespace-insensitive: the INSERT sits inside a `DO $$ / IF NOT FOUND`
    // block, so exact indentation is an implementation detail, not the fact
    // under test (INSERT INTO sources with these columns, in this order,
    // VALUES 'afl_api' first).
    expect(migration077).toMatch(
      /INSERT\s+INTO\s+sources\s*\(\s*key\s*,\s*name\s*,\s*url\s*,\s*kind\s*,\s*description\s*\)\s*VALUES\s*\(\s*'afl_api'/m,
    );
    expect(registry.sources.get('afl_api')!.registrationOwner).toBe('AFLDB-ISSUE-100');
  });

  /*
   * AMENDED 2026-08-28 by probe P1, which ran once the Kali key became
   * available. The registry previously placed Kali /matches in the `squiggle`
   * group as the fail-closed default while P1 was blocked; P1 disproved
   * derivation, so the two are now two witnesses. The /fixture endpoint stays
   * a proven verbatim proxy, so the derived-group rule is pinned there.
   */
  it('counts Squiggle and Kali as TWO match witnesses now that P1 has run', () => {
    const both = ['squiggle_api', 'kali_afl_stats'];
    expect(independenceGroups(registry, 'match', both)).toEqual(['kali', 'squiggle']);
    expect(countIndependentWitnesses(registry, 'match', both)).toBe(2);
    expect(getSourceFamily(registry, 'kali_afl_stats', 'match').independence).toMatchObject({
      derivesFrom: null,
      group: 'kali',
      evidence: 'proven_independent',
    });
    // The proven /fixture proxy is still recorded explicitly rather than
    // omitted: a derived endpoint stays in its upstream's group.
    expect(getSourceFamily(registry, 'kali_afl_stats', 'fixture').independence).toMatchObject({
      derivesFrom: 'squiggle_api',
      group: 'squiggle',
      evidence: 'proven_derived',
    });
    expect(independenceGroups(registry, 'fixture', ['kali_afl_stats'])).toEqual(['squiggle']);
    // A derived source may not invent its own group and become a second witness.
    refuses((data) => { familyIn(data, 'kali_afl_stats', 'fixture').independence.group = 'kali'; });
    refuses((data) => {
      familyIn(data, 'kali_afl_stats', 'fixture').independence.derives_from = null;
    });
  });

  /*
   * P2 ran at the same time and found NO player id on the Kali stat grain,
   * so the player_stats family must stay unprojectable. This pins the gap: if
   * someone later declares a column contract for it, they must also declare an
   * identity, and this test is where that decision surfaces.
   */
  it('keeps the Kali player grain fail-closed after P2', () => {
    const stats = getSourceFamily(registry, 'kali_afl_stats', 'player_stats');
    expect(stats.status).toBe('identity_only');
    expect(stats.externalKey).toBeNull();
    expect(isPromotable(stats)).toBe(false);
    expect(() => assertProjectableColumns(stats, ['matchId', 'playerName', 'teamId']))
      .toThrow(/no column contract/);
    // Name + team is a heuristic, and the notes must keep saying so.
    expect(stats.notes.join(' ').toLowerCase()).toContain('heuristic');
  });

  /*
   * AMENDED 2026-08-28 by AFLDB-ISSUE-099 T4. The registry previously promoted
   * NOTHING, because no family had a proven shape and key. The two AFL Tables
   * families now do, so they carry `reviewed` — which means every proposal is a
   * promotion_candidate for a human, and never an automatic canonical write.
   * Everything the original assertion protected is still protected below.
   */
  it('promotes the AFL Tables and afl_api match-family families, and lineups never at all', () => {
    // AFLDB-ISSUE-228 S6: afl_api's match/match_roster/player_match_stats
    // joined the AFL Tables pair once the settle successor landed.
    // AFLDB-ISSUE-228 S7 (2026-09-20): afl_api/brownlow_match_votes flipped
    // from 'not_yet_declared' to 'reviewed' once the Brownlow settle engine
    // (afl-api-brownlow.ts) landed — brownlow_leaderboard stays
    // 'not_yet_declared' (an artefact-builder input only, isPromotable()
    // is 'reviewed'-only) and is deliberately NOT in this list.
    expect(registry.families.filter(isPromotable).map((f) => `${f.sourceKey}/${f.family}`).sort())
      .toEqual([
        'afl_api/brownlow_match_votes', 'afl_api/match', 'afl_api/match_roster', 'afl_api/player_match_stats',
        'afltables/match', 'afltables/player_match_stats',
      ]);
    // `reviewed` is the only promotable policy there is: nothing is automatic.
    for (const family of registry.families.filter(isPromotable)) {
      expect(family.promotionPolicy).toBe('reviewed');
      expect(family.promotionOwner).toBe(
        family.sourceKey === 'afl_api' ? 'AFLDB-ISSUE-228' : 'AFLDB-ISSUE-099',
      );
    }
    expect(getSourceFamily(registry, 'afl_api', 'lineup').promotionPolicy).toBe('never');
    expect(getSourceFamily(registry, 'squiggle_api', 'match').promotionPolicy).toBe('never');
    expect(getSourceFamily(registry, 'kali_afl_stats', 'match').promotionPolicy).toBe('never');
    // ...nor for a family whose column contract was never proven.
    refuses((data) => {
      familyIn(data, 'kali_afl_stats', 'player_stats').promotion_policy = 'reviewed';
    });
    // ...and a promotable family may not lose the shape that earned it.
    refuses((data) => { familyIn(data, 'afltables', 'match').status = 'identity_only'; });
  });

  /*
   * AFLDB-ISSUE-122 §10 (stage S4). Corroboration disagreement blocks by
   * DEFAULT and only the two AFL Tables families opt out. The declaration is
   * optional precisely so every undeclared family keeps the fail-closed
   * ISSUE-096 behaviour with no edit; an INVALID one must still fail, because
   * a typo'd policy silently reading as permissive is the failure mode this
   * whole file exists to prevent.
   */
  it('declares advisory corroboration for the two AFL Tables families only (§10)', () => {
    expect(DEFAULT_CORROBORATION_POLICY).toBe('blocking');
    const advisory = registry.families
      .filter((f) => f.corroborationPolicy === 'advisory')
      .map((f) => `${f.sourceKey}/${f.family}`).sort();
    expect(advisory).toEqual(['afltables/match', 'afltables/player_match_stats']);
    // Everything else — Squiggle and Kali included — still vetoes.
    for (const family of registry.families) {
      if (advisory.includes(`${family.sourceKey}/${family.family}`)) continue;
      expect(family.corroborationPolicy).toBe('blocking');
    }
    // Omitted reads as blocking, which is what makes the key safe to add.
    const omitted = parseSourceFamilyRegistry(mutated((data) => {
      delete familyIn(data, 'afltables', 'match').corroboration_policy;
    }));
    expect(getSourceFamily(omitted, 'afltables', 'match').corroborationPolicy).toBe('blocking');
    // null is NOT omitted, and neither is a typo or the wrong type.
    refuses((data) => { familyIn(data, 'afltables', 'match').corroboration_policy = null; });
    refuses((data) => { familyIn(data, 'afltables', 'match').corroboration_policy = 'advisary'; });
    refuses((data) => { familyIn(data, 'squiggle_api', 'match').corroboration_policy = true; });
    // The rest of the family contract stays fail-closed on a missing key.
    refuses((data) => { delete familyIn(data, 'afltables', 'match').promotion_policy; });
  });

  /*
   * AFLDB-ISSUE-099 T4 — the two AFL Tables families, declared against the exact
   * payload the T3 emitter produces. The registry and the emitter are ONE
   * contract with two halves, so the column sets are pinned against
   * import_fitzroy_core.py's own constants rather than retyped here: a change to
   * either side that is not made to the other fails this test.
   */
  describe('AFL Tables in-season families (AFLDB-ISSUE-099)', () => {
    const importer = readFileSync(
      join(root, 'tools', 'migration', 'import_fitzroy_core.py'), 'utf8');

    /** The quoted names of a Python tuple constant, in source order. */
    const pythonNames = (constant: string): string[] => {
      // Anchored: MATCH_PAYLOAD_COLUMNS is a substring of the player constant's
      // name, so an unanchored match could read the wrong block.
      const block = new RegExp(`^${constant} = \\(([\\s\\S]*?)\\n\\)`, 'm').exec(importer);
      expect(block, `${constant} not found in the importer`).not.toBeNull();
      return [...block![1].matchAll(/"([^"]+)"/g)].map((m) => m[1]);
    };
    // STAT_MAP is spread into the player payload, so its TARGET names are part of
    // that column set. Reading them here is what keeps the one mapping authority.
    const statTargets = [...new RegExp('STAT_MAP = \\[([\\s\\S]*?)\\n\\]')
      .exec(importer)![1].matchAll(/\("[^"]+",\s*"([^"]+)"\)/g)].map((m) => m[1]);

    const matchFamily = getSourceFamily(registry, 'afltables', 'match');
    const playerFamily = getSourceFamily(registry, 'afltables', 'player_match_stats');

    it('declares both families with a proven shape and key', () => {
      for (const family of [matchFamily, playerFamily]) {
        expect(family.status).toBe('declared');
        expect(family.knownColumnsStatus).toBe('complete');
        expect(family.independence).toMatchObject({
          derivesFrom: null, group: 'afltables', evidence: 'proven_independent',
        });
        expect(family.roundVocabulary).toBe('afltables_2026');
      }
      expect(independenceGroups(registry, 'match', ['afltables', 'squiggle_api', 'kali_afl_stats']))
        .toEqual(['afltables', 'kali', 'squiggle']);
    });

    it('declares exactly the columns the emitter produces', () => {
      expect(matchFamily.knownColumns).toEqual(pythonNames('MATCH_PAYLOAD_COLUMNS'));
      expect(matchFamily.knownColumns).toHaveLength(18);
      expect(playerFamily.knownColumns).toEqual([
        ...pythonNames('PLAYER_MATCH_PAYLOAD_COLUMNS'), ...statTargets,
      ]);
      expect(playerFamily.knownColumns).toHaveLength(34);
      expect(statTargets).toHaveLength(22);
      // Time.on.Ground has no target column, so it is never declared.
      expect(playerFamily.knownColumns).not.toContain('time_on_ground');
      // The emitted payload is therefore projectable, and drift in either
      // direction is a refusal rather than a silent NULL.
      expect(() => assertProjectableColumns(matchFamily, matchFamily.knownColumns!))
        .not.toThrow();
      expect(() => assertProjectableColumns(playerFamily, playerFamily.knownColumns!))
        .not.toThrow();
      expect(() => assertProjectableColumns(
        playerFamily, playerFamily.knownColumns!.filter((c) => c !== 'url')))
        .toThrow(/missing required column\(s\): url/);
      expect(() => assertProjectableColumns(
        matchFamily, [...matchFamily.knownColumns!, 'Substitute']))
        .toThrow(/undeclared column\(s\): Substitute/);
    });

    it('keys the player grain on the profile URL, with ID enrichment-only (P5)', () => {
      expect(playerFamily.externalKey).toEqual(['url', 'match_key']);
      expect(playerFamily.requiredColumns).toContain('url');
      // 82 in-season rows carry no ID, so requiring it would discard real
      // appearances. It rides the payload as a nullable enrichment column.
      expect(playerFamily.requiredColumns).not.toContain('afltables_id');
      expect(playerFamily.knownColumns).toContain('afltables_id');
      expect(playerFamily.notes.join(' ').toLowerCase()).toContain('never be required');
      // A name is never an identity key at any grain.
      for (const name of ['first_name', 'surname', 'player_name']) {
        expect(playerFamily.knownColumns).toContain(name);
        expect(playerFamily.externalKey).not.toContain(name);
        expect(playerFamily.requiredColumns).not.toContain(name);
      }
    });

    it('composes the match key from the columns the resolver reads', () => {
      expect(matchFamily.externalKey).toEqual([
        'season', 'round_code', 'match_date', 'home_team_raw', 'away_team_raw',
      ]);
      // round_number is NULL for a final, so it is known but never required.
      expect(matchFamily.knownColumns).toContain('round_number');
      expect(matchFamily.requiredColumns).not.toContain('round_number');
      for (const nullable of ['attendance', 'match_time', 'period_scores']) {
        expect(matchFamily.knownColumns).toContain(nullable);
        expect(matchFamily.requiredColumns).not.toContain(nullable);
      }
    });

    it('keeps NULL distinct from zero and the payload hash whole', () => {
      for (const family of [matchFamily, playerFamily]) {
        // A recorded 0 attendance, a 0 statistic and a 0 Brownlow vote are all
        // REAL values. Listing any column here would silently null them out.
        expect(family.zeroIsMissingColumns).toEqual([]);
        // Nothing in an AFL Tables payload is fetch noise, so the hash covers
        // the whole observation and stays the change oracle.
        expect(family.hashExclusions).toEqual([]);
        // AFL Tables publishes no upstream mutation timestamp, and fetch time is
        // never substituted for one.
        expect(family.sourceUpdatedAtField).toBeNull();
      }
      // The fail-closed column cross-check applies to these families too.
      refuses((data) => {
        familyIn(data, 'afltables', 'match').zero_is_missing_columns = ['not_a_column'];
      });
      refuses((data) => {
        familyIn(data, 'afltables', 'player_match_stats').external_key = ['not_a_column'];
      });
    });
  });

  it('keeps AFL API zero-as-missing and the fetch date out of the change oracle', () => {
    const roster = getSourceFamily(registry, 'afl_api', 'roster');
    expect(roster.zeroIsMissingColumns).toEqual(['weightInKg']);
    expect(roster.hashExclusions).toEqual(['data_accessed']);
    // data_accessed is AFLDB's own fetch date: excluded from the hash, and never
    // an upstream mutation timestamp.
    expect(roster.sourceUpdatedAtField).toBeNull();
    refuses((data) => {
      familyIn(data, 'afl_api', 'roster').source_updated_at_field = 'data_accessed';
    });
    // utcStartTime is a scheduled start time, so the lineup family declares none.
    const lineup = getSourceFamily(registry, 'afl_api', 'lineup');
    expect(lineup.sourceUpdatedAtField).toBeNull();
    expect(lineup.knownColumns).toContain('utcStartTime');
  });

  it('treats Squiggle `updated` as the one genuine upstream mutation timestamp', () => {
    const squiggle = getSourceFamily(registry, 'squiggle_api', 'match');
    expect(squiggle.sourceUpdatedAtField).toBe('updated');
    // It is content, not volatile response noise: it stays inside the hash.
    expect(squiggle.hashExclusions).toEqual([]);
    const withUpdatedAt = registry.families.filter((f) => f.sourceUpdatedAtField !== null);
    expect(withUpdatedAt.map((f) => `${f.sourceKey}/${f.family}`).sort()).toEqual([
      'kali_afl_stats/fixture', 'kali_afl_stats/match', 'squiggle_api/match',
    ]);
  });

  /*
   * AMENDED 2026-08-28 by AFLDB-ISSUE-099 T4: the AFL Tables player grain was the
   * example here while its shape was unproven. T3 proved it, so the Kali grain —
   * which still has no stable provider player id (P2) — is now the unprojectable
   * one, and the rule itself is unchanged.
   */
  it('refuses to project a family whose shape was never proven', () => {
    const stats = getSourceFamily(registry, 'kali_afl_stats', 'player_stats');
    expect(stats.status).toBe('identity_only');
    expect(stats.requiredColumns).toBeNull();
    expect(stats.externalKey).toBeNull();
    expect(() => assertProjectableColumns(stats, ['matchId', 'playerName']))
      .toThrow(/no column contract/);
    // Every family that is NOT declared must be equally unprojectable.
    for (const family of registry.families.filter((f) => f.status !== 'declared')) {
      expect(() => assertProjectableColumns(family, ['anything'])).toThrow(/no column contract/);
      expect(isPromotable(family)).toBe(false);
    }
  });

  it('accepts both proven lineup shapes and refuses drift in either direction', () => {
    const lineup = getSourceFamily(registry, 'afl_api', 'lineup');
    // P3b enumerated the column P3 could only count: `lateChanges`, present at
    // round 20 and absent from round 25 entirely. The set is now complete at 20.
    const r20 = [...lineup.knownColumns!];
    expect(r20).toHaveLength(20);
    expect(lineup.knownColumnsStatus).toBe('complete');
    expect(r20).toContain('lateChanges');
    expect(() => assertProjectableColumns(lineup, r20)).not.toThrow();

    // `lateChanges` is CONDITIONAL, so the round-25 shape - the same set minus
    // that one column - must project just as cleanly. This is the round-20
    // refusal P3 left behind, closed by measurement rather than by relaxing the
    // gate: both real shapes pass, and nothing else does.
    const r25 = r20.filter((c) => c !== 'lateChanges');
    expect(r25).toHaveLength(19);
    expect(() => assertProjectableColumns(lineup, r25)).not.toThrow();

    // A missing required column is a refusal, not a silent NULL.
    expect(() => assertProjectableColumns(lineup, r20.filter((c) => c !== 'teamStatus')))
      .toThrow(/missing required column\(s\): teamStatus/);

    // Completing the set did NOT weaken the gate: a genuinely undeclared 21st
    // column still fails closed, from either real shape.
    expect(() => assertProjectableColumns(lineup, [...r20, 'someUnenumeratedColumn']))
      .toThrow(/undeclared column\(s\): someUnenumeratedColumn/);
    expect(() => assertProjectableColumns(lineup, [...r25, 'someUnenumeratedColumn']))
      .toThrow(/undeclared column\(s\): someUnenumeratedColumn/);
  });

  it('fails closed on lineup identity and source state, not on optional fields', () => {
    const lineup = getSourceFamily(registry, 'afl_api', 'lineup');
    // Exactly the approved set: the three identity fields plus the two that
    // carry announcement state. P3b measured 0 NULLs across two rounds for
    // several other useful columns, which establishes them as typed and usable
    // but is NOT a provider guarantee that they can never be absent - so they
    // stay optional and a projection refuses only on identity and state.
    expect([...lineup.requiredColumns!].sort()).toEqual(
      ['player.playerId', 'providerId', 'status', 'teamId', 'teamStatus'],
    );
    expect(lineup.externalKey).toEqual(['providerId', 'teamId', 'player.playerId']);

    const r20 = [...lineup.knownColumns!];
    for (const optional of [
      'position', 'teamType', 'round.roundNumber', 'player.playerJumperNumber', 'lateChanges',
    ]) {
      expect(r20).toContain(optional);
      expect(() => assertProjectableColumns(lineup, r20.filter((c) => c !== optional)))
        .not.toThrow();
    }
    for (const required of lineup.requiredColumns!) {
      expect(() => assertProjectableColumns(lineup, r20.filter((c) => c !== required)))
        .toThrow(/missing required column/);
    }
  });

  it('treats the lineup family as staging-only with no captain signal', () => {
    const lineup = getSourceFamily(registry, 'afl_api', 'lineup');
    // Standing decision: lineups never become canonical participation.
    expect(lineup.promotionPolicy).toBe('never');

    // P3b measured player.captain FALSE for 572 of 572 rows across 11 matches
    // and 22 team instances, with 0 TRUE and 0 NA. It carries no captain signal
    // and is not projected in v1. It is deliberately NOT declared
    // zero-is-missing: that list means "this value means absent", and the right
    // treatment here is to project nothing rather than to null a real column.
    expect(lineup.zeroIsMissingColumns).toEqual([]);
    expect(lineup.knownColumns).toContain('player.captain');
    // It stays in known_columns precisely so its disappearance is drift.
    expect(() => assertProjectableColumns(
      lineup, [...lineup.knownColumns!].filter((c) => c !== 'player.captain'),
    )).not.toThrow();

    // No fetch-noise column exists in this payload, and utcStartTime is a
    // scheduled start time, never an upstream mutation timestamp.
    expect(lineup.hashExclusions).toEqual([]);
    expect(lineup.sourceUpdatedAtField).toBeNull();
  });

  it('keeps round integers inside their own vocabulary', () => {
    const afltables = getSourceFamily(registry, 'afltables', 'player_match_stats');
    const squiggle = getSourceFamily(registry, 'squiggle_api', 'match');
    // Opening Round 2026 is round 1 to AFL Tables and round 0 to Squiggle.
    const openingAfltables = roundKey(afltables, 1, null);
    const openingSquiggle = roundKey(squiggle, 0, null);
    expect(roundKeysEqual(openingAfltables, roundKey(afltables, 1, null))).toBe(true);
    expect(roundKeysEqual(openingAfltables, roundKey(afltables, 25, null))).toBe(false);
    expect(() => roundKeysEqual(openingAfltables, openingSquiggle))
      .toThrow(/different vocabularies/);

    // squiggle_2026/kali_2026/afltables_2026 are still anchors-only, so the
    // GENERIC cross-vocabulary translateRound() stays refused for them.
    for (const key of ['squiggle_2026', 'kali_2026', 'afltables_2026']) {
      const vocabulary = registry.roundVocabularies.get(key)!;
      expect(vocabulary.mappingStatus).toBe('anchors_only');
      if (vocabulary.shape !== 'anchors') throw new Error(`${key} should be the anchors shape`);
      expect(vocabulary.anchors.length).toBeGreaterThan(0);
    }
    expect(() => translateRound(registry, openingSquiggle, 'afltables_2026'))
      .toThrow(/anchors_only/);
    expect(translateRound(registry, openingSquiggle, 'squiggle_2026')).toBe(openingSquiggle);
    // A family with no proven round vocabulary cannot produce a round key at all.
    expect(() => roundKey(getSourceFamily(registry, 'afl_api', 'roster'), 1, null))
      .toThrow(/no round vocabulary/);
    // Kali agrees with Squiggle on every jointly observed round, but the
    // vocabularies stay separate declarations, so the integers stay uncomparable.
    expect(() => roundKeysEqual(
      roundKey(getSourceFamily(registry, 'kali_afl_stats', 'match'), 0, null),
      roundKey(squiggle, 0, null),
    )).toThrow(/different vocabularies/);
  });

  /*
   * AFLDB-ISSUE-228 §6.4 — the anchors_only `afl_api_2026` entry ISSUE-100
   * declared (P3/P3b: two proven points, never a mapping) is REPLACED here by
   * a fully explicit, per-season round table for every season with a captured
   * sample (2022-2026). translateAflRound() (afl-api-rounds.ts) is the only
   * consumer; the generic translateRound() above stays refused for these too,
   * since 'declared' is a distinct mappingStatus from 'complete'.
   */
  describe('AFL API explicit round tables (AFLDB-ISSUE-228 §6.4)', () => {
    const capturedYears = [2022, 2023, 2024, 2025, 2026];

    it('declares one table per captured season, each a contiguous 1..N home-and-away run', () => {
      for (const season of capturedYears) {
        const vocab = registry.roundVocabularies.get(`afl_api_${season}`)!;
        expect(vocab.mappingStatus).toBe('declared');
        if (vocab.shape !== 'declared') throw new Error(`afl_api_${season} should be the declared shape`);
        expect(vocab.season).toBe(season);
        const haNumbers = vocab.rounds
          .filter((r) => r.roundType === 'home_and_away')
          .map((r) => r.canonicalRoundNumber)
          .sort((a, b) => a! - b!);
        expect(haNumbers).toEqual(Array.from({ length: haNumbers.length }, (_, i) => i + 1));
        // Every non-home_and_away, non-mixed row carries no round number at all.
        for (const row of vocab.rounds) {
          if (row.roundType === 'home_and_away') continue;
          expect(row.canonicalRoundNumber).toBeNull();
        }
      }
    });

    it('gives 2024-2026 an Opening Round (offset +1) and 2022/2023 none (offset 0)', () => {
      for (const season of [2024, 2025, 2026]) {
        const vocab = registry.roundVocabularies.get(`afl_api_${season}`)!;
        if (vocab.shape !== 'declared') throw new Error('expected declared shape');
        const opening = vocab.rounds.find((r) => r.apiRoundNumber === 0)!;
        expect(opening.apiAbbreviation).toBe('OR');
        expect(opening.canonicalRoundNumber).toBe(1);
      }
      for (const season of [2022, 2023]) {
        const vocab = registry.roundVocabularies.get(`afl_api_${season}`)!;
        if (vocab.shape !== 'declared') throw new Error('expected declared shape');
        expect(vocab.rounds.some((r) => r.apiRoundNumber === 0)).toBe(false);
        const roundOne = vocab.rounds.find((r) => r.apiRoundNumber === 1)!;
        expect(roundOne.canonicalRoundNumber).toBe(1);
      }
    });

    it('gives 2026 alone a standalone Wildcard round and a labelled QE split', () => {
      const vocab2026 = registry.roundVocabularies.get('afl_api_2026')!;
      if (vocab2026.shape !== 'declared') throw new Error('expected declared shape');
      expect(vocab2026.rounds.find((r) => r.apiAbbreviation === 'WF')!.roundType).toBe('wildcard_final');
      const qe = vocab2026.rounds.find((r) => r.apiAbbreviation === 'QE')!;
      expect(qe.roundType).toBe('mixed_finals');
      expect(qe.finalsLabelRules).toEqual([
        { contains: 'Qualifying', roundType: 'qualifying_final' },
        { contains: 'Elimination', roundType: 'elimination_final' },
      ]);
      for (const season of [2022, 2023, 2024, 2025]) {
        const vocab = registry.roundVocabularies.get(`afl_api_${season}`)!;
        if (vocab.shape !== 'declared') throw new Error('expected declared shape');
        expect(vocab.rounds.some((r) => r.roundType === 'wildcard_final')).toBe(false);
        expect(vocab.rounds.find((r) => r.roundType === 'mixed_finals')!.apiAbbreviation).toBe('FW1');
      }
    });

    it('fails closed on a declared table with drift (§19.7g)', () => {
      const mutateRounds = (data: any, fn: (rounds: any[]) => void): void => {
        fn(data.round_vocabularies.afl_api_2026.rounds);
      };
      // Non-contiguous canonical home-and-away numbers.
      refuses((data) => mutateRounds(data, (rounds) => { rounds[1].canonical_round_number = 99; }));
      // Duplicate api_round_number.
      refuses((data) => mutateRounds(data, (rounds) => { rounds[1].api_round_number = rounds[0].api_round_number; }));
      // A mixed_finals row with no finals_label_rules.
      refuses((data) => mutateRounds(data, (rounds) => {
        const qe = rounds.find((r: any) => r.api_abbreviation === 'QE');
        delete qe.finals_label_rules;
      }));
      // A home_and_away row missing its canonical number.
      refuses((data) => mutateRounds(data, (rounds) => { delete rounds[0].canonical_round_number; }));
      // A finals row that smuggles in a canonical number.
      refuses((data) => mutateRounds(data, (rounds) => {
        const gf = rounds.find((r: any) => r.api_abbreviation === 'GF');
        gf.canonical_round_number = 30;
      }));
    });
  });

  describe('co-source groups (AFLDB-ISSUE-228 §7.5, Q1)', () => {
    it('declares afltables and afl_api as one co-source group', () => {
      expect(registry.coSourceGroups).toEqual([['afl_api', 'afltables']]);
      expect(areCoSources(registry, 'afltables', 'afl_api')).toBe(true);
      expect(areCoSources(registry, 'afl_api', 'afltables')).toBe(true);
      expect(areCoSources(registry, 'afltables', 'squiggle_api')).toBe(false);
      // A source is trivially its own co-source.
      expect(areCoSources(registry, 'afltables', 'afltables')).toBe(true);
    });

    it('is optional and empty when omitted, and fails closed on drift', () => {
      const data = clone();
      delete data.co_source_groups;
      const withoutGroups = parseSourceFamilyRegistry(data);
      expect(withoutGroups.coSourceGroups).toEqual([]);

      refuses((d) => { d.co_source_groups = [['afltables']]; }); // needs >= 2 keys
      refuses((d) => { d.co_source_groups = [['afltables', 'not_a_source']]; });
      refuses((d) => { d.co_source_groups = [['afltables', 'afl_api'], ['afl_api', 'kali_afl_stats']]; });
    });
  });

  it('fails closed on registry drift', () => {
    refuses((data) => { data.contract_version = 2; });
    refuses((data) => { data.families.push(familyIn(data, 'squiggle_api', 'match')); });
    refuses((data) => { familyIn(data, 'squiggle_api', 'match').source_key = 'not_a_source'; });
    refuses((data) => { familyIn(data, 'squiggle_api', 'match').round_vocabulary = 'not_declared'; });
    refuses((data) => { familyIn(data, 'squiggle_api', 'match').hash_exclusions = ['not_a_column']; });
    refuses((data) => { familyIn(data, 'squiggle_api', 'match').required_columns = ['not_a_column']; });
    refuses((data) => { familyIn(data, 'squiggle_api', 'match').surprise = true; });
    // An identity_only family may not smuggle in a column contract.
    refuses((data) => {
      familyIn(data, 'kali_afl_stats', 'player_stats').required_columns = ['matchId'];
    });
    // ...and a declared one may not drop it.
    refuses((data) => { familyIn(data, 'afl_api', 'roster').known_columns = null; });
  });
});

import { afterAll, describe, expect, it } from 'vitest';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { spawnSync } from 'node:child_process';

/**
 * AFLDB-ISSUE-112 Rising Star slice (phase 4, §20). DB-free
 * parser/validation coverage for tools/migration/rising_star.py, in the
 * tests/captaincies-source mould: every case writes a small variant file
 * and drives the real Python checker as a subprocess — no database, no
 * import_awards.py run.
 *
 * Like captaincies, Rising Star preserves a stable source_record_id (the
 * manifest source_key, a 24-hex-character digest) and reloads on
 * (source_id, source_record_id); it is not re-minted. `club` / `opponent`
 * are the canonical clubs.name for the era identity and are re-resolved by
 * the loader's season-aware ClubResolver; one row has no club and three
 * have no opponent. `stat_line` is the exact FootyWire statistic object,
 * an integer-valued JSON object whose keys are a subset of STAT_KEYS; the
 * parser rejects malformed or wrongly-shaped JSON rather than coercing it,
 * and never infers a stat_line for the three rows that lack one.
 */
const repositoryRoot = process.cwd();
const checker = resolve(repositoryRoot, 'tools/migration/rising_star.py');
const canonicalCsv = resolve(repositoryRoot, 'data/awards/rising-star.csv');
const importAwards = resolve(repositoryRoot, 'tools/migration/import_awards.py');
const python = process.env.PYTHON ?? (process.platform === 'win32' ? 'python' : 'python3');
const temporaryDirectory = mkdtempSync(join(tmpdir(), 'afldb-rising-star-'));
const canonicalLines = readFileSync(canonicalCsv, 'utf8').trimEnd().split(/\r?\n/);
let variantNumber = 0;

afterAll(() => {
  rmSync(temporaryDirectory, { recursive: true, force: true });
});

type CheckResult = {
  status: number | null;
  payload: Record<string, unknown>;
  stderr: string;
};

function runChecker(csvPath?: string): CheckResult {
  const args = [checker];
  if (csvPath) args.push('--csv', csvPath);
  const result = spawnSync(python, args, {
    cwd: repositoryRoot,
    encoding: 'utf8',
  });
  if (result.error) throw result.error;
  return {
    status: result.status,
    payload: JSON.parse(result.stdout.trim()) as Record<string, unknown>,
    stderr: result.stderr,
  };
}

function writeVariant(lines: string[]): string {
  variantNumber += 1;
  const path = join(temporaryDirectory, `variant-${variantNumber}.csv`);
  writeFileSync(path, `${lines.join('\n')}\n`, 'utf8');
  return path;
}

function expectRejected(lines: string[], errorPattern: RegExp): void {
  const result = runChecker(writeVariant(lines));
  expect(result.status).toBe(1);
  expect(result.stderr).toBe('');
  expect(result.payload.ok).toBe(false);
  expect(result.payload.error).toEqual(expect.stringMatching(errorPattern));
}

// --- Quote-aware CSV cell helpers -----------------------------------------
// The real manifest has commas and double quotes inside the quoted
// stat_line JSON cell, so a plain split(',') would corrupt those rows.

function parseCsvLine(line: string): string[] {
  const cells: string[] = [];
  let i = 0;
  while (i <= line.length) {
    let cell = '';
    if (line[i] === '"') {
      i += 1;
      while (i < line.length) {
        if (line[i] === '"') {
          if (line[i + 1] === '"') {
            cell += '"';
            i += 2;
            continue;
          }
          i += 1;
          break;
        }
        cell += line[i];
        i += 1;
      }
    } else {
      while (i < line.length && line[i] !== ',') {
        cell += line[i];
        i += 1;
      }
    }
    cells.push(cell);
    if (line[i] === ',') {
      i += 1;
      continue;
    }
    break;
  }
  return cells;
}

function quoteCsvCell(value: string): string {
  return /["\n,]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

function stringifyCsvLine(cells: string[]): string {
  return cells.map(quoteCsvCell).join(',');
}

function replaceCell(line: string, index: number, value: string): string {
  const cells = parseCsvLine(line);
  cells[index] = value;
  return stringifyCsvLine(cells);
}

// Column order: source_key,season,round_number,club,opponent,player,
// player_id,link_status,is_winner,is_ineligible,ineligible_reason,votes,
// stat_line,source_citation
const COL = {
  sourceKey: 0, season: 1, roundNumber: 2, club: 3, opponent: 4, player: 5,
  playerId: 6, linkStatus: 7, isWinner: 8, isIneligible: 9,
  ineligibleReason: 10, votes: 11, statLine: 12, sourceCitation: 13,
};

const HEADER =
  'source_key,season,round_number,club,opponent,player,player_id,link_status,'
  + 'is_winner,is_ineligible,ineligible_reason,votes,stat_line,source_citation';

// Minimal, self-contained valid rows for negative tests whose error fires
// during per-row validation — before the 766-row completeness check ever
// runs, so these variants deliberately do not total 766. The source_key is
// a well-formed 24-hex digest; a second row uses a strictly-greater one.
// The stat_line cell carries commas and quotes and must stay CSV-quoted.
const VALID_ROW = stringifyCsvLine([
  '0000000000000000000000aa', '2000', '5', 'Carlton', 'Geelong',
  'Test Player', '1', 'unique', 'false', 'false', '', '',
  '{"goals": 1, "kicks": 10}', 'footywire',
]);
const VALID_ROW_2 = stringifyCsvLine([
  '0000000000000000000000bb', '2001', '6', 'Essendon', 'Hawthorn',
  'Other Player', '2', 'unique', 'false', 'false', '', '',
  '{"goals": 0, "kicks": 8}', 'footywire',
]);

describe('canonical Rising Star source (AFLDB-ISSUE-112 phase 4)', () => {
  it('contains the complete, machine-checkable G0-measured bootstrap', () => {
    const result = runChecker();

    expect(result.status).toBe(0);
    expect(result.stderr).toBe('');
    expect(result.payload).toMatchObject({
      ok: true,
      row_count: 766,
      linked_count: 766,
      unlinked_count: 0,
      season_min: 1993,
      season_max: 2026,
      distinct_seasons: 34,
      winners: 33,
      ineligible: 9,
      stat_line_present: 763,
      null_club: 1,
      null_opponent: 3,
      link_status: { resolved: 87, unique: 679 },
    });
  });

  it('preserves representative source rows verbatim — a winner, an ineligible row, and the null-club / null-opponent rows', () => {
    const csv = canonicalLines.join('\n');
    // The one row with no club (Michael Gardiner, 1997) — still has an
    // opponent and a stat_line.
    expect(csv).toContain(
      '91f274ba89461c84a6b2aeab,1997,19,,St Kilda,Michael Gardiner,1056,resolved,false,false,,,',
    );
    // A row with no opponent and no stat_line (Jake Neade, 2013).
    expect(csv).toContain(
      'eb92521199120b4260861d6f,2013,13,Port Adelaide,,Jake Neade,12151,unique,false,false,,,,footywire',
    );
    // An ineligible row carries its free-text reason and is never a winner.
    expect(csv).toContain(
      '15eaa9831c9699505ff3f6a5,2024,5,West Coast,Richmond,Harley Reid,13111,unique,false,true,'
        + 'Ineligible to win the Rising Star due to suspension.,,',
    );
    // The first row in deterministic (source_key ascending) order.
    expect(csv).toContain(
      '001777a0faa59ba117929aea,1999,4,Melbourne,Hawthorn,Troy Longmuir,543,unique,false,false,,,',
    );
  });

  it('every row is source-granularity footywire provenance, not a page citation', () => {
    for (const line of canonicalLines.slice(1)) {
      const cells = parseCsvLine(line);
      expect(cells[COL.sourceCitation]).toBe('footywire');
    }
  });

  it('carries the source_record_id verbatim as source_key — 24 hex chars, strictly ascending, unique', () => {
    const keys = canonicalLines.slice(1).map((line) => parseCsvLine(line)[COL.sourceKey]);
    expect(keys).toHaveLength(766);
    for (const key of keys) expect(key).toMatch(/^[0-9a-f]{24}$/);
    expect(new Set(keys).size).toBe(766);
    expect(keys).toEqual([...keys].sort());
  });

  it('every stat_line in the canonical file is an integer-valued object keyed within STAT_KEYS', () => {
    const STAT_KEYS = new Set([
      'kicks', 'handballs', 'disposals', 'marks', 'goals', 'behinds',
      'tackles', 'hitouts', 'frees_for', 'frees_against', 'supercoach',
      'afl_fantasy',
    ]);
    let present = 0;
    let empty = 0;
    for (const line of canonicalLines.slice(1)) {
      const cell = parseCsvLine(line)[COL.statLine];
      if (cell === '') {
        empty += 1;
        continue;
      }
      present += 1;
      const parsed = JSON.parse(cell) as Record<string, unknown>;
      expect(typeof parsed).toBe('object');
      for (const [key, value] of Object.entries(parsed)) {
        expect(STAT_KEYS.has(key)).toBe(true);
        expect(Number.isInteger(value)).toBe(true);
      }
    }
    expect(present).toBe(763);
    expect(empty).toBe(3);
  });

  it('rejects a malformed header', () => {
    const lines = [...canonicalLines];
    lines[0] = lines[0].replace('source_key', 'record_key');
    expectRejected(lines, /invalid header/);
  });

  it('rejects a source_key that is not a 24-hex digest', () => {
    const row = replaceCell(VALID_ROW, COL.sourceKey, 'risingstar:2000:R5');
    expectRejected([HEADER, row], /invalid source_key 'risingstar:2000:R5'/);
  });

  it('rejects source_key rows out of deterministic (ascending) order', () => {
    const first = replaceCell(VALID_ROW, COL.sourceKey, '0000000000000000000000bb');
    const second = replaceCell(
      replaceCell(VALID_ROW, COL.sourceKey, '0000000000000000000000aa'),
      COL.player, 'Second Player',
    );
    expectRejected([HEADER, first, second], /out of deterministic order/);
  });

  it('rejects a duplicate source_key', () => {
    const second = replaceCell(VALID_ROW, COL.player, 'Different Player');
    expectRejected([HEADER, VALID_ROW, second], /duplicate source_key/);
  });

  it('rejects a duplicate natural identity (season, player)', () => {
    const second = replaceCell(VALID_ROW, COL.sourceKey, '0000000000000000000000bb');
    expectRejected([HEADER, VALID_ROW, second], /duplicate natural identity/);
  });

  it('rejects a season outside the declared coverage', () => {
    const row = replaceCell(VALID_ROW, COL.season, '1980');
    expectRejected([HEADER, row], /season 1980 is outside the declared range 1993-2026/);
  });

  it('rejects a round_number outside the declared 0-24 range', () => {
    const row = replaceCell(VALID_ROW, COL.roundNumber, '30');
    expectRejected([HEADER, row], /round_number 30 is outside the declared range 0-24/);
  });

  it('rejects an unknown club', () => {
    const row = replaceCell(VALID_ROW, COL.club, 'Tasmania');
    expectRejected([HEADER, row], /unknown club 'Tasmania'/);
  });

  it('rejects an unknown opponent', () => {
    const row = replaceCell(VALID_ROW, COL.opponent, 'Tasmania');
    expectRejected([HEADER, row], /unknown opponent 'Tasmania'/);
  });

  it('rejects an invalid link_status', () => {
    const row = replaceCell(VALID_ROW, COL.linkStatus, 'confirmed');
    expectRejected([HEADER, row], /invalid link_status 'confirmed'/);
  });

  it('rejects link_status unique/resolved without a player_id', () => {
    const row = replaceCell(replaceCell(VALID_ROW, COL.linkStatus, 'unique'), COL.playerId, '');
    expectRejected([HEADER, row], /link_status 'unique' requires player_id/);
  });

  it('rejects an unmatched row that still carries a player_id', () => {
    const row = replaceCell(VALID_ROW, COL.linkStatus, 'unmatched');
    expectRejected([HEADER, row], /link_status 'unmatched' must not carry player_id/);
  });

  it('rejects a source_citation that is not the decided source-granularity value', () => {
    const row = replaceCell(VALID_ROW, COL.sourceCitation, 'wikipedia');
    expectRejected([HEADER, row], /source_citation 'wikipedia' is not an authorised value/);
  });

  it('rejects a missing required field (empty round_number)', () => {
    const row = replaceCell(VALID_ROW, COL.roundNumber, '');
    expectRejected([HEADER, row], /round_number is required/);
  });

  it('rejects a player field with leading or trailing whitespace', () => {
    const row = replaceCell(VALID_ROW, COL.player, ' Test Player');
    expectRejected([HEADER, row], /player has leading or trailing whitespace/);
  });

  it('rejects malformed JSON in stat_line', () => {
    const row = replaceCell(VALID_ROW, COL.statLine, '{"goals": 1, "kicks":}');
    expectRejected([HEADER, row], /stat_line is not valid JSON/);
  });

  it('rejects a stat_line that is not a JSON object', () => {
    const row = replaceCell(VALID_ROW, COL.statLine, '[1, 2, 3]');
    expectRejected([HEADER, row], /stat_line must be a JSON object/);
  });

  it('rejects a stat_line with an unknown key', () => {
    const row = replaceCell(VALID_ROW, COL.statLine, '{"goals": 1, "clangers": 3}');
    expectRejected([HEADER, row], /stat_line has unknown key\(s\) \['clangers'\]/);
  });

  it('rejects a stat_line with a non-integer value', () => {
    const row = replaceCell(VALID_ROW, COL.statLine, '{"goals": 1.5}');
    expectRejected([HEADER, row], /stat_line\['goals'\] must be an integer/);
  });

  it('rejects an ineligible row with no reason', () => {
    const row = replaceCell(VALID_ROW, COL.isIneligible, 'true');
    expectRejected([HEADER, row], /is_ineligible is true but ineligible_reason is empty/);
  });

  it('rejects an ineligible_reason on a row that is not flagged ineligible', () => {
    const row = replaceCell(VALID_ROW, COL.ineligibleReason, 'Suspended.');
    expectRejected([HEADER, row], /ineligible_reason is set but is_ineligible is false/);
  });

  it('rejects a votes value (not expected for Rising Star nominations)', () => {
    const row = replaceCell(VALID_ROW, COL.votes, '4');
    expectRejected([HEADER, row], /votes is not expected for Rising Star nominations/);
  });

  it('rejects a row that is both a winner and ineligible', () => {
    const row = replaceCell(
      replaceCell(VALID_ROW, COL.isWinner, 'true'),
      COL.isIneligible, 'true',
    );
    // ineligible_reason is still empty, so the ineligible-reason rule could
    // also fire; supply a reason so the winner/ineligible conflict is what
    // trips.
    const withReason = replaceCell(row, COL.ineligibleReason, 'Suspended.');
    expectRejected([HEADER, withReason], /cannot be both is_winner and is_ineligible/);
  });

  it('rejects a total row count short of the declared 766', () => {
    // Dropping only the final row keeps every remaining row's ordering
    // valid, so this reaches the completeness check rather than an earlier
    // per-row rule.
    expectRejected(canonicalLines.slice(0, -1), /expected 766 Rising Star rows, got 765/);
  });
});

describe('rising_star group is legacy-SQLite-free (AFLDB-ISSUE-112 phase 4)', () => {
  const source = readFileSync(importAwards, 'utf8');

  it('lists rising_star in LEGACY_FREE_GROUPS', () => {
    const block = source.slice(
      source.indexOf('LEGACY_FREE_GROUPS = {'),
      source.indexOf('LEGACY_FREE_GROUPS = {') + 240,
    );
    expect(block).toContain('"rising_star"');
  });

  it('records the rising_star import_batch against footywire provenance', () => {
    expect(source).toContain('"rising_star": "footywire"');
  });

  it('no longer threads a legacy SQLite handle through import_rising_star', () => {
    expect(source).toContain(
      'def import_rising_star(pg, rep: Reporter, batch, clubs: ClubResolver,',
    );
    expect(source).not.toContain('def import_rising_star(pg, lite');
    expect(source).toContain('import_rising_star(pg, rep, batch, clubs, sources,');
  });

  it('no longer forces the legacy awards group as a rising_star prerequisite', () => {
    const block = source.slice(
      source.indexOf('GROUP_REQUIRES = {'),
      source.indexOf('GROUP_REQUIRES = {') + 220,
    );
    expect(block).not.toContain('"rising_star": {"awards"}');
    // The reverse direction stays: a full awards refresh still reloads it.
    expect(block).toContain('"awards": {"all_australian", "under_22", "rising_star", "club_bf", "named_medals"}');
  });
});

import { afterAll, describe, expect, it } from 'vitest';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { spawnSync } from 'node:child_process';

/**
 * AFLDB-ISSUE-112 closeout (§24). DB-free parser/validation coverage for the
 * Rising Star family's SECOND tracked file,
 * data/awards/rising-star-winners.csv — the 33 `award_winners` rows for the
 * `rising-star` award.
 *
 * These are a different record from the 33 `is_winner` nominations: a
 * different table, a different reload key, and a different provenance
 * (`draftguru`, the legacy award scrape, not FootyWire). They were the LAST
 * winner rows the legacy `awards` group still owned, which is why its
 * `build_winners()` was not the no-op the earlier slices recorded. Excluding
 * them there and loading them here is what makes that reload genuinely match
 * nothing.
 *
 * `validate_family` cross-checks the two files on **player identity**, not
 * name text: the DraftGuru and FootyWire spellings legitimately differ on
 * five of the thirty-three seasons (measured read-only against afldb_dev —
 * player_id and club_id agree on all 33, the raw name on 28).
 */
const repositoryRoot = process.cwd();
const checker = resolve(repositoryRoot, 'tools/migration/rising_star.py');
const canonicalCsv = resolve(repositoryRoot, 'data/awards/rising-star-winners.csv');
const importAwards = resolve(repositoryRoot, 'tools/migration/import_awards.py');
const python = process.env.PYTHON ?? (process.platform === 'win32' ? 'python' : 'python3');
const temporaryDirectory = mkdtempSync(join(tmpdir(), 'afldb-rs-winners-'));
const canonicalLines = readFileSync(canonicalCsv, 'utf8').trimEnd().split(/\r?\n/);
let variantNumber = 0;

afterAll(() => {
  rmSync(temporaryDirectory, { recursive: true, force: true });
});

type CheckResult = {
  status: number | null;
  payload: Record<string, any>;
  stderr: string;
};

function runChecker(winnersPath?: string): CheckResult {
  const args = [checker];
  if (winnersPath) args.push('--winners', winnersPath);
  const result = spawnSync(python, args, { cwd: repositoryRoot, encoding: 'utf8' });
  if (result.error) throw result.error;
  return {
    status: result.status,
    payload: JSON.parse(result.stdout.trim()),
    stderr: result.stderr,
  };
}

function writeVariant(lines: string[]): string {
  variantNumber += 1;
  const path = join(temporaryDirectory, `variant-${variantNumber}.csv`);
  writeFileSync(path, `${lines.join('\n')}\n`, 'utf8');
  return path;
}

function expectRejected(lines: string[], errorPattern: RegExp): void {
  const result = runChecker(writeVariant(lines));
  expect(result.status).toBe(1);
  expect(result.stderr).toBe('');
  expect(result.payload.ok).toBe(false);
  expect(result.payload.error).toEqual(expect.stringMatching(errorPattern));
}

const header = canonicalLines[0].split(',');

function rowIndexForSeason(season: number): number {
  const seasonColumn = header.indexOf('season');
  const index = canonicalLines
    .slice(1)
    .findIndex((line) => line.split(',')[seasonColumn] === String(season));
  expect(index).toBeGreaterThanOrEqual(0);
  return index;
}

function withCell(rowIndex: number, column: string, value: string): string[] {
  const columnIndex = header.indexOf(column);
  expect(columnIndex).toBeGreaterThanOrEqual(0);
  return canonicalLines.map((line, index) => {
    if (index !== rowIndex + 1) return line;
    const cells = line.split(',');
    cells[columnIndex] = value;
    return cells.join(',');
  });
}

describe('rising-star-winners manifest (AFLDB-ISSUE-112 §24)', () => {
  it('parses the canonical manifest and reports the measured shape', () => {
    const result = runChecker();
    expect(result.status).toBe(0);
    expect(result.stderr).toBe('');
    expect(result.payload.ok).toBe(true);
    expect(result.payload.winner_rows).toMatchObject({
      row_count: 33,
      distinct_seasons: 33,
      season_min: 1993,
      season_max: 2025,
      linked_count: 33,
      votes_present: 29,
      distinct_clubs: 16,
    });
  });

  it('is one winner row per decided season, none for the undecided 2026', () => {
    // The nominations file runs to 2026; the award for that season has not
    // been decided, so it has no winner row and must not acquire one.
    expect(canonicalLines.slice(1)).toHaveLength(33);
    expect(canonicalLines.join('\n')).not.toContain('rising-star:2026');
  });

  it('preserves the database source_record_id verbatim, never re-minted', () => {
    expect(canonicalLines[1].split(',')[0]).toBe('rising-star:1993:937');
    expect(canonicalLines.at(-1)!.split(',')[0]).toBe('rising-star:2025:969');
  });

  it('carries draftguru provenance, not the nominations’ footywire', () => {
    // The reload scope is keyed on source_id: getting this wrong would move
    // the ownership boundary (AFLDB-ISSUE-080).
    for (const line of canonicalLines.slice(1)) {
      expect(line.endsWith(',draftguru')).toBe(true);
    }
  });

  // --- refusals ------------------------------------------------------------

  it('refuses a changed header', () => {
    expectRejected(['source_key,season,club,player,player_id,link_status,votes,'
                    + 'source_citation', ...canonicalLines.slice(1)],
                   /invalid winners header/);
  });

  it('refuses a row with too many columns', () => {
    expectRejected([canonicalLines[0], `${canonicalLines[1]},extra`,
                    ...canonicalLines.slice(2)], /too many columns/);
  });

  it('refuses a missing required field', () => {
    expectRejected(withCell(0, 'player', ''), /player is required/);
  });

  it('refuses a source_key of the wrong shape', () => {
    expectRejected(withCell(0, 'source_key', 'rising-star-1993-937'),
                   /invalid source_key/);
  });

  it('refuses a source_key whose embedded season disagrees with the row', () => {
    expectRejected(withCell(0, 'source_key', 'rising-star:1992:937'),
                   /embeds season 1992 but the row's season is 1993/);
  });

  it('refuses a season outside the decided span', () => {
    expectRejected(withCell(rowIndexForSeason(2025), 'source_key',
                            'rising-star:2026:969')
                     .map((line, index) =>
                       index === rowIndexForSeason(2025) + 1
                         ? line.replace(',2025,', ',2026,') : line),
                   /outside the declared decided range/);
  });

  it('refuses an unknown club', () => {
    expectRejected(withCell(0, 'club', 'Brisbane Bears'), /unknown club/);
  });

  it('refuses an invalid link_status', () => {
    expectRejected(withCell(0, 'link_status', 'probably'), /invalid link_status/);
  });

  it('refuses a linked status with no player_id', () => {
    expectRejected(withCell(0, 'player_id', ''), /requires player_id/);
  });

  it('refuses a non-linked status carrying a player_id', () => {
    expectRejected(withCell(0, 'link_status', 'unmatched'),
                   /must not carry player_id/);
  });

  it('refuses an implausible candidate_count', () => {
    expectRejected(withCell(0, 'candidate_count', '42'),
                   /candidate_count 42 is outside/);
  });

  it('refuses a vote tally before the first season one was recorded', () => {
    expectRejected(withCell(rowIndexForSeason(1993), 'votes', '27.00'),
                   /no vote tally is recorded before 1997/);
  });

  it('refuses a missing vote tally after that season', () => {
    expectRejected(withCell(rowIndexForSeason(1997), 'votes', ''),
                   /must carry the winner's vote tally/);
  });

  it('refuses a vote tally that is not of the measured form', () => {
    expectRejected(withCell(rowIndexForSeason(1997), 'votes', '27'),
                   /not of the measured form/);
  });

  it('refuses the nominations’ footywire provenance on a winner row', () => {
    expectRejected(withCell(0, 'source_citation', 'footywire'),
                   /source_citation 'footywire' must be one of/);
  });

  it('refuses a duplicate source_key', () => {
    expectRejected([canonicalLines[0], canonicalLines[1], canonicalLines[1],
                    ...canonicalLines.slice(2)], /duplicate source_key/);
  });

  it('refuses rows out of deterministic order', () => {
    expectRejected([canonicalLines[0], canonicalLines[2], canonicalLines[1],
                    ...canonicalLines.slice(3)], /out of deterministic order/);
  });

  it('refuses a truncated file rather than loading a partial award history', () => {
    expectRejected(canonicalLines.slice(0, -1),
                   /expected 33 Rising Star winner rows, got 32/);
  });

  it('refuses a winner whose identity disagrees with the winning nomination', () => {
    // The cross-file check is the point: two independently curated files
    // asserting different people won the same season is a curation error, not
    // something to resolve silently at load time.
    expectRejected(withCell(0, 'player_id', '99999'),
                   /the winning nomination resolves to player .* but the winner row/);
  });

  it('accepts a spelling difference between the two sources', () => {
    // Five of the 33 seasons legitimately differ in name text between
    // DraftGuru and FootyWire. Identity, not text, is what must agree.
    const result = runChecker(writeVariant(withCell(0, 'player', 'N. Buckley')));
    expect(result.status).toBe(0);
    expect(result.payload.ok).toBe(true);
  });
});

describe('rising_star owns the last winner rows the legacy group held', () => {
  const source = readFileSync(importAwards, 'utf8');

  it('excludes the rising-star award from the legacy winner reload scope', () => {
    expect(source).toContain(
      'award_ids[slug] for slug in (UNDER_22_SLUG, ALL_AUSTRALIAN_SLUG, COLEMAN_SLUG,');
    expect(source).toContain('RISING_STAR_SLUG)');
  });

  it('loads the winners through the preserved reload key and ownership scope', () => {
    expect(source).toContain('load_rising_star_winners');
    expect(source).toContain('validate_rising_star_family(rows, winner_rows)');
    expect(source).toContain('scopes=[("source_id", [winner_source_id], False)],');
  });

  it('keeps the two halves of the family on their own provenance', () => {
    expect(source).toContain('source_id = require_source(sources, "footywire")');
    expect(source).toContain(
      'winner_source_id = require_source(sources, "draftguru")');
  });
});

#!/usr/bin/env node
/**
 * AFLDB-ISSUE-228 S9 — the FULL-SEASON AFL API player-identity evidence emitter.
 *
 * A thin CLI over pieces that already exist and are already validated:
 *
 *   acquired snapshot (manifest re-hash)      afl-api-snapshot.ts        (S6, shared)
 *     -> buildAflApiSettleBundle()            settle-afl-api.ts          (S3/S6-B/S6-C)
 *     -> buildAflApiMatchIdentity()           afl-api-match-identity.ts  (S6, §6.1/§6.2/§11.1)
 *     -> resolveAflApiMatch()                 afl-api-match-resolver.ts  (S6-D1, §6.1)
 *     -> canonical player_match_stats         READ-ONLY, afldb_dev
 *     -> buildAflApiPlayerEvidence()          afl-api-player-evidence.ts (S9, pure)
 *     -> readAflApiForwardIdentities()        replay_afl_api_adjudications.ts (ISSUE-241, §5)
 *     -> report / evidence artefact
 *
 * AFLDB-ISSUE-241: every linked row carries `candidate_player_identity`, the candidate's
 * accepted stable identity, and the artefact declares `player_identity_contract`. The loader
 * resolves the identity on its target; `candidate_player_id` is only a diagnostic hint.
 *
 * NOTHING in this file re-derives a match date, a timezone, a round, a team
 * identity or a statistic: every one of those comes from the emitters above.
 * There is no second Python builder and no second timezone implementation.
 *
 * SAFETY.
 *   - It never writes to any database. The connection is opened with
 *     `default_transaction_read_only=on` as a STARTUP parameter (so a
 *     reconnect cannot silently lose it), and the live session's own
 *     `current_database()` / `transaction_read_only` /
 *     `default_transaction_read_only` are proven before any evidence
 *     statement runs. Any database other than `afldb_dev` is refused.
 *     (The `afldb_test`-native sibling, `emit-afl-api-player-bridge-test.ts`,
 *     reuses this body with its OWN pinned target; neither entry point can
 *     select the other's database.)
 *   - It never accepts a DSN on argv. The DSN comes from
 *     `AFLDB_DEV_DATABASE_URL` only — deliberately not the importer's
 *     elevated write role and not the migration schema owner.
 *   - It never writes under `data/sources/`, and never overwrites an existing
 *     `--out` target whose content differs.
 *   - There is no PROD target, path or environment variable anywhere in this
 *     file, and none can be supplied from the command line.
 *
 * Usage:
 *   npm run emit:afl-api-player-bridge -- --label <snapshot> --validate-only
 *   npm run emit:afl-api-player-bridge -- --label <snapshot> --out <path>
 */
