/**
 * AFLDB-ISSUE-093 §20 — the read-only catalog fingerprint.
 *
 * Extracted from tools/db/prove-reset.ts so that verifying a database's state can never
 * pull in anything that could change it. This module contains SELECTs and pure functions
 * ONLY: no RESET_SQL, no psql, no DDL, no DML, no subprocess. `tools/db/fingerprint-test.ts`
 * (npm run db:test:fingerprint) and the rollback-only reset proof both use it, so the
 * digest a verification prints is the same digest the proof compares.
 *
 * Every query is search_path independent. Catalog identifiers are assembled from
 * pg_namespace.nspname and the object's own name, or from raw OIDs. Nothing uses
 * ::regclass, ::regtype, ::regprocedure, format_type() or pg_get_constraintdef(), because
 * those render schema-qualified or bare depending on search_path — which would make two
 * fingerprints of the same database incomparable for no gain.
 */

import { createHash } from 'node:crypto';

export type Row = Record<string, unknown>;
export type Query = (sql: string) => Promise<Row[]>;

/** PostgreSQL booleans reach us as `true`; tolerate the text forms rather than trust them. */
export function isTrue(value: unknown): boolean {
  return value === true || value === 't' || value === 'true' || value === 1 || value === '1';
}

const USER_SCHEMA = `n.nspname NOT IN ('pg_catalog', 'information_schema')
                     AND n.nspname !~ '^pg_'`;

export const MIGRATION_TABLE_SQL = `
SELECT (to_regclass('afldb_meta.schema_migrations') IS NOT NULL) AS present`;

/** Only ever run when MIGRATION_TABLE_SQL has already said the table exists. */
export const MIGRATION_STATE_SQL = `
SELECT format('%s|%s', count(*), coalesce(max(name), '-')) AS k
FROM afldb_meta.schema_migrations`;

export const HEALTH_SQL = `
SELECT current_database() AS database,
       (SELECT count(*)::int FROM pg_class)     AS relations,
       (SELECT count(*)::int FROM pg_extension) AS extensions`;

/**
 * Each section is an ordered list of one-line object identities. What must be provable is
 * that the SCHEMA is intact — every relation, column, index, constraint, routine, type,
 * sequence definition, extension, extension membership, ACL and owner.
 *
 * Deliberately absent: table contents (a rolled-back DROP restores the heap untouched, and
 * RESET_SQL performs no DML at all, so a content hash would cost minutes and prove less)
 * and sequence last_value (nextval is non-transactional in general; nothing here calls it,
 * and the sequence definition is fingerprinted instead).
 */
export const FINGERPRINT_SECTIONS: { id: string; sql: string }[] = [
  {
    id: 'schemas',
    sql: `SELECT format('%s|%s|%s', n.nspname, pg_get_userbyid(n.nspowner),
                        coalesce(n.nspacl::text, '')) AS k
          FROM pg_namespace n WHERE ${USER_SCHEMA} ORDER BY 1`,
  },
  {
    id: 'relations',
    sql: `SELECT format('%s.%s|%s|%s|%s|%s', n.nspname, c.relname, c.relkind,
                        c.relpersistence, pg_get_userbyid(c.relowner),
                        coalesce(c.relacl::text, '')) AS k
          FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
          WHERE ${USER_SCHEMA} AND c.relkind IN ('r', 'p', 'v', 'm', 'S', 'f')
          ORDER BY 1`,
  },
  {
    id: 'columns',
    sql: `SELECT format('%s.%s|%s|%s|%s|%s|%s|%s|%s|%s', n.nspname, c.relname, a.attnum,
                        a.attname, a.atttypid, a.atttypmod, a.attnotnull, a.atthasdef,
                        a.attidentity, a.attgenerated) AS k
          FROM pg_attribute a
          JOIN pg_class c ON c.oid = a.attrelid
          JOIN pg_namespace n ON n.oid = c.relnamespace
          WHERE ${USER_SCHEMA} AND a.attnum > 0 AND NOT a.attisdropped
            AND c.relkind IN ('r', 'p', 'v', 'm', 'f')
          ORDER BY 1`,
  },
  {
    id: 'indexes',
    sql: `SELECT format('%s.%s|%s|%s|%s|%s', n.nspname, t.relname, i.relname,
                        x.indisunique, x.indisprimary, x.indkey::text) AS k
          FROM pg_index x
          JOIN pg_class i ON i.oid = x.indexrelid
          JOIN pg_class t ON t.oid = x.indrelid
          JOIN pg_namespace n ON n.oid = t.relnamespace
          WHERE ${USER_SCHEMA} ORDER BY 1`,
  },
  {
    id: 'constraints',
    sql: `SELECT format('%s|%s|%s|%s|%s', n.nspname, co.conname, co.contype,
                        coalesce(cl.relname, '-'), coalesce(co.conkey::text, '-')) AS k
          FROM pg_constraint co
          JOIN pg_namespace n ON n.oid = co.connamespace
          LEFT JOIN pg_class cl ON cl.oid = co.conrelid
          WHERE ${USER_SCHEMA} ORDER BY 1`,
  },
  {
    id: 'routines',
    sql: `SELECT format('%s.%s|%s|%s|%s|%s', n.nspname, p.proname, p.proargtypes::text,
                        p.prokind, pg_get_userbyid(p.proowner),
                        coalesce(p.proacl::text, '')) AS k
          FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
          WHERE ${USER_SCHEMA} ORDER BY 1`,
  },
  {
    id: 'types',
    sql: `SELECT format('%s.%s|%s|%s', n.nspname, t.typname, t.typtype,
                        pg_get_userbyid(t.typowner)) AS k
          FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace
          WHERE ${USER_SCHEMA} ORDER BY 1`,
  },
  {
    id: 'enum_values',
    sql: `SELECT format('%s.%s|%s|%s', n.nspname, t.typname, e.enumsortorder, e.enumlabel)
                 AS k
          FROM pg_enum e
          JOIN pg_type t ON t.oid = e.enumtypid
          JOIN pg_namespace n ON n.oid = t.typnamespace
          WHERE ${USER_SCHEMA} ORDER BY 1`,
  },
  {
    id: 'sequences',
    sql: `SELECT format('%s.%s|%s|%s|%s|%s', n.nspname, c.relname, s.seqstart,
                        s.seqincrement, s.seqmin, s.seqmax) AS k
          FROM pg_sequence s
          JOIN pg_class c ON c.oid = s.seqrelid
          JOIN pg_namespace n ON n.oid = c.relnamespace
          WHERE ${USER_SCHEMA} ORDER BY 1`,
  },
  {
    id: 'extensions',
    sql: `SELECT format('%s|%s|%s|%s', e.extname, e.extversion, n.nspname,
                        pg_get_userbyid(e.extowner)) AS k
          FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace ORDER BY 1`,
  },
  {
    id: 'extension_members',
    sql: `SELECT format('%s:%s:%s:%s', d.classid, d.objid, d.objsubid, d.refobjid) AS k
          FROM pg_depend d WHERE d.deptype = 'e' ORDER BY 1`,
  },
  {
    id: 'default_acls',
    sql: `SELECT format('%s|%s|%s|%s', pg_get_userbyid(d.defaclrole),
                        coalesce(n.nspname, '-'), d.defaclobjtype, d.defaclacl::text) AS k
          FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid = d.defaclnamespace
          ORDER BY 1`,
  },
];

export type Sections = Record<string, string[]>;
export type Fingerprint = { overall: string; sections: Record<string, string> };

function sha256(text: string): string {
  return createHash('sha256').update(text, 'utf8').digest('hex');
}

/**
 * A digest per section plus one over the lot, so a mismatch names the object class that
 * moved without printing a single row of data.
 */
export function fingerprintOf(sections: Sections): Fingerprint {
  const perSection: Record<string, string> = {};
  for (const id of Object.keys(sections).sort()) {
    perSection[id] = sha256(`${id}\n${sections[id].join('\n')}`);
  }
  const overall = sha256(
    Object.keys(perSection).sort().map((id) => `${id} ${perSection[id]}`).join('\n'));
  return { overall, sections: perSection };
}

export function describeFingerprintDrift(before: Fingerprint, after: Fingerprint): string[] {
  const ids = [...new Set([...Object.keys(before.sections), ...Object.keys(after.sections)])];
  return ids.filter((id) => before.sections[id] !== after.sections[id]).sort();
}

/** Read every section, in order. The injected `q` must be a read-only query runner. */
export async function collectSections(q: Query): Promise<Sections> {
  const sections: Sections = {};
  for (const section of FINGERPRINT_SECTIONS) {
    const rows = await q(section.sql);
    sections[section.id] = rows.map((r) => String(r.k));
  }
  // Migration bookkeeping is probed in two steps: a single statement referencing
  // afldb_meta.schema_migrations fails at PARSE time when the table is absent, so a CASE
  // guard inside one query would not survive.
  const present = isTrue((await q(MIGRATION_TABLE_SQL))[0]?.present);
  sections.migrations = present
    ? [`present|${String((await q(MIGRATION_STATE_SQL))[0]?.k ?? '?')}`]
    : ['absent'];
  return sections;
}

export default { FINGERPRINT_SECTIONS, collectSections, fingerprintOf };

/**
 * AFLDB-ISSUE-093 §20 — the ROLLBACK-ONLY proof of the rebuild's RESET_SQL.
 *
 *     npm run db:test:prove-reset
 *
 * The rebuild's DATABASE RESET stage is intentionally destructive and has never run against
 * live PostgreSQL. Its first execution must not also be the first real clean rebuild, so
 * this exercises BOTH halves of it non-destructively:
 *
 *   * the exact same `RESET_SQL` constant — imported, never copied;
 *   * the exact same psql execution path — `tools/db/psql.ts`, same binary, same argv,
 *     same ON_ERROR_STOP and --single-transaction handling.
 *
 * A proof that ran the SQL through a different mechanism would prove the semantics and
 * leave the mechanism untested, which is the gap this stage exists to close.
 *
 * WHY IT CANNOT COMMIT — the stream's last statement is always `RAISE EXCEPTION` with the
 * rollback sentinel. It is reached only when every assertion has already passed, so the
 * success path aborts the transaction exactly as any failure path does. Two independent
 * guarantees follow:
 *
 *   1. psql, under ON_ERROR_STOP with --single-transaction, stops at that error and does
 *      not commit the stream;
 *   2. even if a COMMIT were somehow sent, PostgreSQL rolls back an already-aborted
 *      transaction — `COMMIT` on an aborted transaction IS a rollback.
 *
 * There is therefore no code path, and no psql behaviour, that commits the reset. The proof
 * treats a ZERO exit status as a failure for exactly that reason.
 *
 * Read-only observation (identity, sessions, the before/after catalog fingerprints) runs
 * over postgres.js, outside psql and outside any transaction. That is deliberate: those are
 * `SELECT`s against the catalogs, not the reset, and they need no execution-path parity.
 *
 * It needs only AFLDB_TEST_DATABASE_URL (the owner DSN). It does NOT need
 * AFLDB_TEST_IMPORT_DATABASE_URL, so AFLDB-ISSUE-083 does not gate it, and it does NOT
 * touch the fitzRoy acceptance register or any importer, so the accepted-baseline preflight
 * is irrelevant here: no data is loaded and nothing survives the transaction.
 *
 * Everything below the CLI is pure or dependency-injected and is tested with no database
 * (tests/db-test-rebuild.test.ts, "reset proof").
 */

import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import { RESET_SQL, RebuildRefused, assertDsnPinsTarget, assertRebuildTargetName, databaseOf } from './rebuild-test';
import {
  PsqlCredentialRefused, PsqlUnavailable, assertPsqlReachable, psqlConnection, redact, runPsql,
  type PsqlResult,
} from './psql';
import {
  FINGERPRINT_SECTIONS,
  HEALTH_SQL,
  MIGRATION_STATE_SQL,
  MIGRATION_TABLE_SQL,
  collectSections,
  describeFingerprintDrift,
  fingerprintOf,
  isTrue,
  type Fingerprint,
  type Query,
  type Row,
} from './catalog-fingerprint';

// Re-exported so the reset proof stays the single import site for its own test suite.
export {
  FINGERPRINT_SECTIONS, HEALTH_SQL, MIGRATION_STATE_SQL, MIGRATION_TABLE_SQL,
  fingerprintOf, describeFingerprintDrift, isTrue, type Row, type Query,
};

// ---------------------------------------------------------------------------
// Contract constants
// ---------------------------------------------------------------------------

/** The only database this proof will touch. Cross-checked against the server's answer. */
export const PROOF_EXPECTED_DATABASE = 'afldb_test';

/**
 * The role the rebuild resets as. `afldb_test` is created `-O afldb_owner` at host
 * bootstrap (tools/maintenance/00_install_postgres.sh:88) and every schema stage runs as
 * that owner, so proving the reset under any other role would prove the wrong thing.
 */
export const PROOF_EXPECTED_ROLE = 'afldb_owner';

/** Guards against the proof blocking, or being blocked by, anything else. */
export const PROOF_LOCK_TIMEOUT = '5s';
export const PROOF_STATEMENT_TIMEOUT = '300s';
export const PROOF_IDLE_IN_TRANSACTION_TIMEOUT = '60s';

/** Prefix on every line the proof stream emits for the operator and for this module. */
export const PROOF_MARKER = 'AFLDB-PROOF';

/** The deliberate abort. Its presence in stderr is what a SUCCESSFUL proof looks like. */
export const PROOF_ROLLBACK_SENTINEL = 'AFLDB-RESET-PROOF-ROLLBACK';

/**
 * AFLDB-ISSUE-237 prerequisite P-M, point 2 — a throwaway `COMMENT ON DATABASE` value used
 * ONLY to prove the marker mechanism survives `RESET_SQL`. This is NOT the Stage 2 marker
 * payload (D11b); that format is S3's concern and is not implemented while S3 stays gated.
 * The comment lives in the shared catalog `pg_shdescription`, entirely separate from the
 * schemas/relations `RESET_SQL` touches, and is ordinary transactional DDL — so the
 * mandatory abort below restores whatever comment existed before this proof ran, exactly,
 * with no separate restore step, and nothing is left behind even if the process is killed
 * mid-stream (PostgreSQL rolls back an unfinished transaction on connection loss).
 */
export const PROOF_MARKER_COMMENT = 'AFLDB-RESET-PROOF-MARKER (ISSUE-237 P-M point 2 — safe to ignore; this proof always rolls back)';

/** Every marker the stream must have emitted before the sentinel, or the proof failed. */
export const PROOF_REQUIRED_MARKERS = [
  'received', 'trap', 'identity', 'sessions', 'before', 'marker_set', 'census', 'marker_after',
  'extensions',
];

/** The first marker the stream emits. Its ABSENCE means psql never ran the stream at all. */
export const PROOF_DELIVERY_MARKER = 'received';

/**
 * The one backend type that is reported rather than refused. An autovacuum worker is not a
 * connection anyone can "close": it appears and disappears on its own, holds only SHARE
 * UPDATE EXCLUSIVE, and PostgreSQL cancels it automatically when it blocks DDL. Refusing on
 * it would make the proof fail at random on an otherwise idle database, which is the kind
 * of unexplained refusal that gets a safety gate weakened.
 */
export const TOLERATED_BACKEND_TYPES = ['autovacuum worker'];

export class ProofRefused extends Error {}

// ---------------------------------------------------------------------------
// Read-only observation SQL — every query is search_path independent
// ---------------------------------------------------------------------------

/*
 * Catalog identifiers are assembled from pg_namespace.nspname and the object's own name, or
 * from raw OIDs. Nothing uses ::regclass, ::regtype, ::regprocedure, format_type() or
 * pg_get_constraintdef(), because those render schema-qualified or bare depending on
 * search_path — which would make the before/after fingerprints incomparable for no gain.
 */

/**
 * Identity, separating the three things that are easy to conflate:
 *   current_user  — the effective role, what object ownership is checked against;
 *   session_user  — the role the DSN authenticated as, unchanged by SET ROLE;
 *   rolsuper      — looked up for BOTH, because a superuser bypasses the ownership rules
 *                   the real reset depends on and would mask a failure it would hit.
 */
export const IDENTITY_SQL = `
SELECT current_database() AS database,
       current_user       AS role_name,
       session_user       AS session_role_name,
       (SELECT rolsuper FROM pg_roles WHERE rolname = current_user) AS role_is_superuser,
       (SELECT rolsuper FROM pg_roles WHERE rolname = session_user) AS session_is_superuser,
       coalesce(inet_server_addr()::text, 'local-socket') AS server_addr,
       coalesce(inet_server_port()::text, '-')            AS server_port,
       current_setting('server_version') AS server_version`;

/**
 * Every backend on this database that is not us. A non-superuser sees every row's pid,
 * datname and usename; `state` and `application_name` may come back NULL for another
 * role's backend, which is why the refusal counts rows and never depends on those fields.
 */
export const OTHER_SESSIONS_SQL = `
SELECT pid::text                       AS pid,
       coalesce(usename, '?')          AS usename,
       coalesce(application_name, '?') AS application_name,
       coalesce(state, '?')            AS state,
       coalesce(backend_type, '?')     AS backend_type
FROM pg_stat_activity
WHERE datname = current_database() AND pid <> pg_backend_pid()
ORDER BY pid`;

/**
 * The database-level comment, read outside the reset transaction, both before psql runs and
 * again afterwards from a fresh session. Read as free text over postgres.js rather than
 * parsed out of a psql marker line, because an operator-set comment could contain spaces or
 * punctuation the marker line format (`key=value`, whitespace-delimited) cannot carry.
 */
export const DATABASE_COMMENT_SQL = `
SELECT shobj_description(oid, 'pg_database') AS comment
FROM pg_database WHERE datname = current_database()`;


// ---------------------------------------------------------------------------
// The proof stream — one psql transaction that always aborts
// ---------------------------------------------------------------------------

/**
 * Build the SQL sent to psql. `RESET_SQL` is embedded VERBATIM: this function may wrap it,
 * never edit it.
 *
 * The temp tables that snapshot the extensions live in `pg_temp_N`, which RESET_SQL's
 * `!~ '^pg_'` schema guard excludes and whose tables its `nspname = 'public'` table guard
 * never sees — so the snapshot survives the very reset it is used to check, inside the one
 * transaction, which is stricter than comparing across two sessions.
 */
export function buildProofSql(): string {
  return `-- AFLDB-ISSUE-093 §20 rollback-only RESET_SQL proof.
-- psql runs this as ONE transaction (--single-transaction, ON_ERROR_STOP=1).
-- The final statement always raises, so this stream can never be committed.

SET LOCAL lock_timeout = '${PROOF_LOCK_TIMEOUT}';
SET LOCAL statement_timeout = '${PROOF_STATEMENT_TIMEOUT}';
SET LOCAL idle_in_transaction_session_timeout = '${PROOF_IDLE_IN_TRANSACTION_TIMEOUT}';
-- DROP ... IF EXISTS emits a NOTICE per absent object. Suppress those; the proof's own
-- markers are raised as WARNING so they still come through.
SET LOCAL client_min_messages = warning;

-- 0. PROOF OF DELIVERY, and the COMMIT TRAP. Both exist because of the failed first live
--    attempt on 2026-08-27, which exited 0 with no diagnostics: nothing then distinguished
--    "psql never received the stream" from "psql received PART of the stream, reached EOF
--    after the reset, and COMMITTED it".
--
--    The marker proves the stream arrived and began executing.
--
--    The trap makes a commit IMPOSSIBLE from this point on, wherever the stream is cut. A
--    DEFERRABLE INITIALLY DEFERRED unique constraint is checked at COMMIT, not at INSERT,
--    so the duplicate below sits harmlessly inside the transaction and turns any COMMIT
--    into an error — and therefore a rollback. This is a SERVER-side guarantee: it does not
--    depend on psql's flags, on ON_ERROR_STOP, or on the stream reaching its own sentinel.
--    It is armed BEFORE the reset, in a temp table the reset cannot drop.
DO $afldb_proof$ BEGIN
  RAISE WARNING '${PROOF_MARKER} received stream=begins';
END $afldb_proof$;

CREATE TEMP TABLE afldb_proof_commit_trap (id int);
ALTER TABLE afldb_proof_commit_trap
  ADD CONSTRAINT afldb_proof_commit_trap_uq UNIQUE (id) DEFERRABLE INITIALLY DEFERRED;
INSERT INTO afldb_proof_commit_trap VALUES (1), (1);

-- 0b. PROOF THAT WE ARE IN A TRANSACTION BLOCK AT ALL.
--     The trap doubles as the detector. Inside a transaction block the deferred constraint
--     is not checked until COMMIT, so the duplicate INSERT above succeeds and two rows are
--     visible here. In AUTOCOMMIT — psql running without --single-transaction, which is the
--     leading explanation for the 2026-08-27 incident — that INSERT is its own transaction
--     and the deferred check fires at its end, so it fails and this sees fewer than two
--     rows. Either way the stream stops HERE, before the first destructive statement.
DO $afldb_proof$
DECLARE armed int;
BEGIN
  SELECT count(*) INTO armed FROM afldb_proof_commit_trap;
  IF armed <> 2 THEN
    RAISE EXCEPTION '${PROOF_MARKER} trap: the commit trap did not arm (% rows, expected 2). This session is not in a transaction block, so nothing here could be rolled back. Refusing to run the reset', armed;
  END IF;
  RAISE WARNING '${PROOF_MARKER} trap armed=% rows', armed;
END $afldb_proof$;

-- 1. IDENTITY, asserted in the SAME session that will run the reset.
DO $afldb_proof$
DECLARE db text; cu text; su text; cu_super boolean; su_super boolean;
BEGIN
  SELECT current_database(), current_user, session_user INTO db, cu, su;
  SELECT rolsuper INTO cu_super FROM pg_roles WHERE rolname = cu;
  SELECT rolsuper INTO su_super FROM pg_roles WHERE rolname = su;
  IF db <> '${PROOF_EXPECTED_DATABASE}' THEN
    RAISE EXCEPTION '${PROOF_MARKER} identity: connected to %, not ${PROOF_EXPECTED_DATABASE}', db;
  END IF;
  IF cu <> '${PROOF_EXPECTED_ROLE}' THEN
    RAISE EXCEPTION '${PROOF_MARKER} identity: current_user is %, not ${PROOF_EXPECTED_ROLE}', cu;
  END IF;
  IF su <> '${PROOF_EXPECTED_ROLE}' THEN
    RAISE EXCEPTION '${PROOF_MARKER} identity: session_user is %, not ${PROOF_EXPECTED_ROLE}; SET ROLE is not part of the AFLDB credential model', su;
  END IF;
  IF cu_super THEN
    RAISE EXCEPTION '${PROOF_MARKER} identity: current_user % is a SUPERUSER; ${PROOF_EXPECTED_ROLE} is created NOSUPERUSER and the reset must be proven under ownership, not superuser bypass', cu;
  END IF;
  IF su_super THEN
    RAISE EXCEPTION '${PROOF_MARKER} identity: session_user % is a SUPERUSER', su;
  END IF;
  RAISE WARNING '${PROOF_MARKER} identity database=% current_user=% session_user=%', db, cu, su;
END $afldb_proof$;

-- 2. EXCLUSIVE ACCESS, re-checked in this session. The reset takes ACCESS EXCLUSIVE locks
--    on everything it drops, so a concurrent backend would be blocked by it.
DO $afldb_proof$
DECLARE others int;
BEGIN
  SELECT count(*) INTO others FROM pg_stat_activity
   WHERE datname = current_database() AND pid <> pg_backend_pid()
     AND coalesce(backend_type, '') <> 'autovacuum worker';
  IF others > 0 THEN
    RAISE EXCEPTION '${PROOF_MARKER} sessions: % other client session(s) connected to %', others, current_database();
  END IF;
  RAISE WARNING '${PROOF_MARKER} sessions others=0';
END $afldb_proof$;

-- 3. Snapshot the extensions and every object they own, INSIDE this transaction.
CREATE TEMP TABLE afldb_proof_ext AS
  SELECT e.extname, e.extversion, n.nspname AS extschema
    FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace;
CREATE TEMP TABLE afldb_proof_extmem AS
  SELECT d.classid, d.objid, d.objsubid, d.refobjid
    FROM pg_depend d WHERE d.deptype = 'e';

-- 4. Pre-reset counts, cross-checked against what was fingerprinted outside psql.
DO $afldb_proof$
DECLARE sc int; rel int; ext int; mem int;
BEGIN
  SELECT count(*) INTO sc FROM pg_namespace n
   WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname !~ '^pg_';
  SELECT count(*) INTO rel FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
   WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname !~ '^pg_'
     AND c.relkind IN ('r', 'p', 'v', 'm', 'S', 'f');
  SELECT count(*) INTO ext FROM afldb_proof_ext;
  SELECT count(*) INTO mem FROM afldb_proof_extmem;
  RAISE WARNING '${PROOF_MARKER} before schemas=% relations=% extensions=% extension_members=%', sc, rel, ext, mem;
END $afldb_proof$;

-- 4b. MARKER (AFLDB-ISSUE-237 P-M point 2) — set a throwaway COMMENT ON DATABASE and
--     confirm it reads back exactly, INSIDE this same transaction, before the reset runs.
COMMENT ON DATABASE ${PROOF_EXPECTED_DATABASE} IS '${PROOF_MARKER_COMMENT}';

DO $afldb_proof$
DECLARE marker text;
BEGIN
  SELECT shobj_description(oid, 'pg_database') INTO marker
    FROM pg_database WHERE datname = current_database();
  IF marker IS DISTINCT FROM '${PROOF_MARKER_COMMENT}' THEN
    RAISE EXCEPTION '${PROOF_MARKER} marker_set: comment did not read back as set (got %)', coalesce(marker, '(null)');
  END IF;
  RAISE WARNING '${PROOF_MARKER} marker_set status=ok';
END $afldb_proof$;

-- 5. THE RESET — the exact RESET_SQL constant from tools/db/rebuild-test.ts.
${RESET_SQL.trim()}

-- 6. POST-RESET CENSUS. Every count excludes extension members, so a surviving pg_trgm
--    function is not mistaken for rebuild debris — and a DROPPED one fails step 7 instead.
DO $afldb_proof$
DECLARE sc int; tb int; vw int; sq int; ft int; rt int; ty int; pub int; mig boolean;
BEGIN
  SELECT count(*) INTO sc FROM pg_namespace n
   WHERE n.nspname NOT IN ('pg_catalog', 'information_schema', 'public')
     AND n.nspname !~ '^pg_'
     AND NOT EXISTS (SELECT 1 FROM pg_depend d
                      WHERE d.classid = 'pg_namespace'::regclass
                        AND d.objid = n.oid AND d.deptype = 'e');
  SELECT count(*) INTO tb FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
   WHERE c.relkind IN ('r', 'p')
     AND NOT EXISTS (SELECT 1 FROM pg_depend d
                      WHERE d.classid = 'pg_class'::regclass
                        AND d.objid = c.oid AND d.deptype = 'e');
  SELECT count(*) INTO vw FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
   WHERE c.relkind IN ('v', 'm')
     AND NOT EXISTS (SELECT 1 FROM pg_depend d
                      WHERE d.classid = 'pg_class'::regclass
                        AND d.objid = c.oid AND d.deptype = 'e');
  SELECT count(*) INTO sq FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
   WHERE c.relkind = 'S'
     AND NOT EXISTS (SELECT 1 FROM pg_depend d
                      WHERE d.classid = 'pg_class'::regclass
                        AND d.objid = c.oid AND d.deptype = 'e');
  SELECT count(*) INTO ft FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
   WHERE c.relkind = 'f'
     AND NOT EXISTS (SELECT 1 FROM pg_depend d
                      WHERE d.classid = 'pg_class'::regclass
                        AND d.objid = c.oid AND d.deptype = 'e');
  SELECT count(*) INTO rt FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace AND n.nspname = 'public'
   WHERE NOT EXISTS (SELECT 1 FROM pg_depend d
                      WHERE d.objid = p.oid AND d.deptype = 'e');
  SELECT count(*) INTO ty FROM pg_type t
    JOIN pg_namespace n ON n.oid = t.typnamespace AND n.nspname = 'public'
   WHERE t.typtype IN ('e', 'd', 'c')
     AND NOT EXISTS (SELECT 1 FROM pg_depend d
                      WHERE d.objid = t.oid AND d.deptype = 'e')
     AND NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.reltype = t.oid);
  SELECT count(*) INTO pub FROM pg_namespace n WHERE n.nspname = 'public';
  mig := to_regclass('afldb_meta.schema_migrations') IS NOT NULL;

  IF sc <> 0 THEN RAISE EXCEPTION '${PROOF_MARKER} census: % application schema(s) survived the reset', sc; END IF;
  IF tb <> 0 THEN RAISE EXCEPTION '${PROOF_MARKER} census: % table(s) survived the reset', tb; END IF;
  IF vw <> 0 THEN RAISE EXCEPTION '${PROOF_MARKER} census: % view(s)/matview(s) survived the reset', vw; END IF;
  IF sq <> 0 THEN RAISE EXCEPTION '${PROOF_MARKER} census: % sequence(s) survived the reset', sq; END IF;
  IF ft <> 0 THEN RAISE EXCEPTION '${PROOF_MARKER} census: % foreign table(s) survived the reset', ft; END IF;
  IF rt <> 0 THEN RAISE EXCEPTION '${PROOF_MARKER} census: % routine(s) survived the reset', rt; END IF;
  IF ty <> 0 THEN RAISE EXCEPTION '${PROOF_MARKER} census: % type(s) survived the reset', ty; END IF;
  IF mig THEN RAISE EXCEPTION '${PROOF_MARKER} census: afldb_meta.schema_migrations survived the reset; migrations would be skipped as already applied against an empty database'; END IF;
  IF pub <> 1 THEN RAISE EXCEPTION '${PROOF_MARKER} census: the public schema was removed; the extensions live there and the migrations expect it'; END IF;

  RAISE WARNING '${PROOF_MARKER} census schemas=% tables=% views=% sequences=% foreign_tables=% routines=% types=% public_schemas=% migrations=%', sc, tb, vw, sq, ft, rt, ty, pub, mig;
END $afldb_proof$;

-- 6b. MARKER SURVIVAL (P-M point 2) — the comment must read back UNCHANGED after
--     RESET_SQL. RESET_SQL drops only schema-owned application objects in this database;
--     it must never touch the shared pg_shdescription catalog the comment lives in.
DO $afldb_proof$
DECLARE marker text;
BEGIN
  SELECT shobj_description(oid, 'pg_database') INTO marker
    FROM pg_database WHERE datname = current_database();
  IF marker IS DISTINCT FROM '${PROOF_MARKER_COMMENT}' THEN
    RAISE EXCEPTION '${PROOF_MARKER} marker_after: comment did NOT survive RESET_SQL (got %)', coalesce(marker, '(null)');
  END IF;
  RAISE WARNING '${PROOF_MARKER} marker_after status=ok';
END $afldb_proof$;

-- 7. EXTENSION PRESERVATION, against the snapshot taken in this same transaction. Nothing
--    is hard-coded: the expected set is whatever this database carried moments ago.
DO $afldb_proof$
DECLARE lost int; gained int; lost_mem int; gained_mem int; n_ext int; n_mem int;
BEGIN
  SELECT count(*) INTO lost FROM (
    SELECT extname, extversion, extschema FROM afldb_proof_ext
    EXCEPT SELECT e.extname, e.extversion, n.nspname
      FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace) q;
  SELECT count(*) INTO gained FROM (
    SELECT e.extname, e.extversion, n.nspname
      FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace
    EXCEPT SELECT extname, extversion, extschema FROM afldb_proof_ext) q;
  SELECT count(*) INTO lost_mem FROM (
    SELECT classid, objid, objsubid, refobjid FROM afldb_proof_extmem
    EXCEPT SELECT d.classid, d.objid, d.objsubid, d.refobjid
      FROM pg_depend d WHERE d.deptype = 'e') q;
  SELECT count(*) INTO gained_mem FROM (
    SELECT d.classid, d.objid, d.objsubid, d.refobjid
      FROM pg_depend d WHERE d.deptype = 'e'
    EXCEPT SELECT classid, objid, objsubid, refobjid FROM afldb_proof_extmem) q;

  IF lost <> 0 OR gained <> 0 THEN
    RAISE EXCEPTION '${PROOF_MARKER} extensions: the reset changed the extension set (% lost, % gained)', lost, gained;
  END IF;
  IF lost_mem <> 0 OR gained_mem <> 0 THEN
    RAISE EXCEPTION '${PROOF_MARKER} extensions: the reset dropped % extension-owned object(s) (% gained)', lost_mem, gained_mem;
  END IF;

  SELECT count(*) INTO n_ext FROM afldb_proof_ext;
  SELECT count(*) INTO n_mem FROM afldb_proof_extmem;
  RAISE WARNING '${PROOF_MARKER} extensions preserved=% members=%', n_ext, n_mem;
END $afldb_proof$;

-- 8. ALWAYS ABORT. Reached only when every assertion above has passed, so the success path
--    aborts exactly as any failure path does: psql does not commit an errored stream, and
--    PostgreSQL rolls back an aborted transaction even if COMMIT were sent.
DO $afldb_proof$
BEGIN
  RAISE EXCEPTION '${PROOF_ROLLBACK_SENTINEL}: every assertion passed; aborting deliberately so nothing is committed';
END $afldb_proof$;
`;
}

// ---------------------------------------------------------------------------
// Pure assertions
// ---------------------------------------------------------------------------

export type Identity = {
  database: string;
  role_name: string;
  session_role_name: string;
  role_is_superuser?: unknown;
  session_is_superuser?: unknown;
  server_addr?: string;
  server_port?: string;
  server_version?: string;
};

/**
 * Identity is taken from the SERVER, then cross-checked against the DSN. The target-name
 * contract itself is the rebuild's, imported rather than copied.
 *
 * The superuser rules are refusals, not warnings. `afldb_owner` is created
 * `LOGIN NOSUPERUSER` (tools/maintenance/00_install_postgres.sh:57) and nothing in this
 * repository issues SET ROLE, so a superuser — direct or via SET ROLE from a superuser
 * session — is not part of the credential model at all. It would also bypass exactly the
 * ownership rules the real reset depends on, masking a failure the rebuild would hit.
 */
export function assertProofIdentity(identity: Identity, dsnDatabase: string): void {
  assertRebuildTargetName(dsnDatabase);

  if (identity.database !== PROOF_EXPECTED_DATABASE) {
    throw new ProofRefused(
      `Connected to '${identity.database}', but this proof only ever runs against `
      + `'${PROOF_EXPECTED_DATABASE}'. Nothing has been executed.`);
  }
  if (identity.database !== dsnDatabase) {
    throw new ProofRefused(
      `The DSN names database '${dsnDatabase}' but the server reports `
      + `'${identity.database}'. Nothing has been executed.`);
  }
  if (identity.role_name !== PROOF_EXPECTED_ROLE) {
    throw new ProofRefused(
      `Connected as current_user '${identity.role_name}', but the rebuild resets `
      + `'${PROOF_EXPECTED_DATABASE}' as '${PROOF_EXPECTED_ROLE}'. Proving the reset under `
      + 'another role would prove the wrong thing. Nothing has been executed.');
  }
  if (identity.session_role_name !== PROOF_EXPECTED_ROLE) {
    throw new ProofRefused(
      `session_user is '${identity.session_role_name}', not '${PROOF_EXPECTED_ROLE}'. `
      + 'SET ROLE is not part of the AFLDB credential model, so a session that reaches '
      + `${PROOF_EXPECTED_ROLE} indirectly is refused. Nothing has been executed.`);
  }
  if (isTrue(identity.role_is_superuser)) {
    throw new ProofRefused(
      `current_user '${identity.role_name}' is a SUPERUSER. ${PROOF_EXPECTED_ROLE} is `
      + 'created NOSUPERUSER; a superuser bypasses the ownership rules the reset depends '
      + 'on and would mask a failure the real rebuild would hit. Nothing has been executed.');
  }
  if (isTrue(identity.session_is_superuser)) {
    throw new ProofRefused(
      `session_user '${identity.session_role_name}' is a SUPERUSER. Nothing has been `
      + 'executed.');
  }
}

export type SessionRow = {
  pid: string; usename: string; application_name: string; state: string; backend_type: string;
};

/**
 * Fail closed on any other client backend. A reset that will be rolled back still takes
 * ACCESS EXCLUSIVE locks on every object it touches: it would block the application, the
 * test workers and the importers, and an idle-in-transaction session would block IT until
 * lock_timeout fires. Nothing is terminated automatically — no repository safety contract
 * authorises that, and the operator can see exactly which backends to close.
 *
 * Returns the tolerated sessions so the caller can report them.
 */
export function assertExclusiveAccess(sessions: SessionRow[]): SessionRow[] {
  const tolerated = sessions.filter((s) => TOLERATED_BACKEND_TYPES.includes(s.backend_type));
  const blocking = sessions.filter((s) => !TOLERATED_BACKEND_TYPES.includes(s.backend_type));
  if (blocking.length === 0) return tolerated;
  const who = blocking
    .map((s) => `pid ${s.pid} (${s.usename}, ${s.application_name}, ${s.state})`)
    .join('; ');
  throw new ProofRefused(
    `${blocking.length} other session(s) are connected to ${PROOF_EXPECTED_DATABASE}: ${who}. `
    + 'The reset takes ACCESS EXCLUSIVE locks on every object it drops, so this proof '
    + 'requires exclusive access. Close them and re-run. Nothing has been executed.');
}

// ---------------------------------------------------------------------------
// Interpreting what psql reported
// ---------------------------------------------------------------------------

export type Census = {
  schemas: number; tables: number; views: number; sequences: number;
  foreign_tables: number; routines: number; types: number; public_schemas: number;
};

export const CENSUS_KEYS: (keyof Census)[] = [
  'schemas', 'tables', 'views', 'sequences', 'foreign_tables', 'routines', 'types',
  'public_schemas',
];

/** `AFLDB-PROOF census tables=0 views=0 …` → `{ tables: '0', views: '0', … }`. */
export function parseMarker(output: string, kind: string): Record<string, string> | undefined {
  const line = output.split('\n')
    .find((l) => l.includes(`${PROOF_MARKER} ${kind} `));
  if (!line) return undefined;
  const values: Record<string, string> = {};
  for (const [, key, value] of line.matchAll(/([a-z_]+)=(\S+)/g)) values[key] = value;
  return values;
}

/**
 * Decide what psql's result means. Deliberately inverted relative to every other command in
 * this repository: a ZERO exit is a FAILURE here, because the stream's last statement always
 * raises. Exit 0 would mean the stream did not abort — and therefore that psql committed it.
 */
export function assertProofOutcome(result: PsqlResult): {
  census: Census; migrationsPresent: boolean; extensions: Record<string, string>;
  before: Record<string, string>; identity: Record<string, string>;
  markerSet: Record<string, string>; markerAfter: Record<string, string>;
} {
  const output = `${result.stdout}\n${result.stderr}`;
  // Never discard psql's own words. The first live attempt refused on the exit status
  // alone and threw away the only evidence that could have explained it.
  const said = `\npsql exit ${result.status}. psql said:\n`
    + `${redact(output.trim()) || '(nothing at all)'}`;
  const delivered = output.includes(`${PROOF_MARKER} ${PROOF_DELIVERY_MARKER} `);

  if (result.status === 0) {
    if (!delivered) {
      throw new ProofRefused(
        'psql exited 0 and never emitted the delivery marker, so it did NOT execute the '
        + 'stream: the SQL on stdin was discarded. Nothing ran, and therefore nothing was '
        + `committed — but the reset is UNPROVEN.${said}`);
    }
    throw new ProofRefused(
      'psql exited 0 having STARTED the stream. The stream ends in RAISE EXCEPTION '
      + `'${PROOF_ROLLBACK_SENTINEL}', so a clean exit means it did not run to the end. `
      + 'The commit trap should have turned any COMMIT into an error, so a commit is not '
      + 'expected — but this outcome is not understood. Treat the database state as '
      + `UNKNOWN and verify it with 'npm run db:test:fingerprint' before anything else.${said}`);
  }
  if (!delivered) {
    throw new ProofRefused(
      `psql exited ${result.status} without ever emitting the delivery marker, so the `
      + `stream did not begin executing. Nothing was committed.${said}`);
  }
  if (!output.includes(PROOF_ROLLBACK_SENTINEL)) {
    throw new ProofRefused(
      'The proof stream began but failed before its deliberate abort. The transaction was '
      + `rolled back and nothing was committed.${said}`);
  }

  const markers: Record<string, Record<string, string>> = {};
  for (const kind of PROOF_REQUIRED_MARKERS) {
    const parsed = parseMarker(output, kind);
    if (!parsed) {
      throw new ProofRefused(
        `The proof stream reached its abort without emitting the '${kind}' marker, so that `
        + 'assertion did not run. Treat the reset as UNPROVEN.');
    }
    markers[kind] = parsed;
  }

  // Re-assert the census in Node. The stream already raised on any non-zero count; this
  // catches a stream that reported numbers its own IF tests somehow did not act on.
  const census = {} as Census;
  for (const key of CENSUS_KEYS) {
    const value = Number(markers.census[key]);
    if (!Number.isInteger(value)) {
      throw new ProofRefused(
        `The post-reset census reported a non-integer '${key}'. Treat the reset as UNPROVEN.`);
    }
    census[key] = value;
  }
  const migrationsPresent = isTrue(markers.census.migrations)
    || markers.census.migrations === 't';
  assertPostResetState(census, migrationsPresent);

  // Re-assert the marker statuses in Node, same reasoning as the census re-assert above:
  // the stream already raised on a mismatch, so reaching here means both said 'ok' — this
  // catches a stream whose own IF somehow did not act on a bad read-back.
  if (markers.marker_set.status !== 'ok') {
    throw new ProofRefused(
      `The marker_set assertion did not report 'ok' (got '${markers.marker_set.status}'). `
      + 'Treat the marker proof as UNPROVEN.');
  }
  if (markers.marker_after.status !== 'ok') {
    throw new ProofRefused(
      `The marker_after assertion did not report 'ok' (got '${markers.marker_after.status}'). `
      + 'Treat the marker proof as UNPROVEN.');
  }

  return {
    census,
    migrationsPresent,
    extensions: markers.extensions,
    before: markers.before,
    identity: markers.identity,
    markerSet: markers.marker_set,
    markerAfter: markers.marker_after,
  };
}

/** Every object class the rebuild owns must be gone; `public` itself must remain. */
export function assertPostResetState(census: Census, migrationTablePresent: boolean): void {
  const mustBeZero: [keyof Census, string][] = [
    ['schemas', 'non-public application schemas (staging, staging_aflw, aflw, afldb_meta)'],
    ['tables', 'tables in public'],
    ['views', 'views and materialized views in public'],
    ['sequences', 'sequences in public'],
    ['foreign_tables', 'foreign tables in public'],
    ['routines', 'routines in public'],
    ['types', 'enum, domain and composite types in public'],
  ];
  for (const [key, what] of mustBeZero) {
    if (census[key] !== 0) {
      throw new ProofRefused(
        `RESET_SQL left ${census[key]} ${what}. The reset is NOT a clean slate.`);
    }
  }
  if (migrationTablePresent) {
    throw new ProofRefused(
      'RESET_SQL left afldb_meta.schema_migrations in place. Migrations would then be '
      + 'skipped as already applied against an empty database.');
  }
  if (census.public_schemas !== 1) {
    throw new ProofRefused(
      'RESET_SQL removed the public schema. The extensions live there and the migrations '
      + 'expect it to exist.');
  }
}

// ---------------------------------------------------------------------------
// The proof
// ---------------------------------------------------------------------------

export type ProofDeps = {
  /**
   * Opens a FRESH read-only session, runs `fn`, and CLOSES it before returning.
   *
   * A session, not a connection handle, precisely because of the 2026-08-27 self-collision
   * (§20.14): the harness used to hold ONE postgres.js connection open across the whole
   * proof, so when psql ran its own `pg_stat_activity` check it correctly counted the
   * observer as a client backend and refused. Observation must be finished and closed
   * before psql starts, and re-opened fresh afterwards. Nothing may span the psql run.
   */
  withSession: <T>(fn: (query: Query) => Promise<T>) => Promise<T>;
  /** Prove psql can be launched AND can reach the target, through the reset's own argv. */
  assertPsqlReachable: () => void;
  /** The SHARED psql path — same binary, same argv as the real destructive reset. */
  runPsql: (sql: string) => PsqlResult;
  log: (line: string) => void;
  /** The database named by the supplied DSN, for the identity cross-check. */
  dsnDatabase: string;
};

export type ProofReport = {
  identity: Identity;
  before: Fingerprint;
  after: Fingerprint;
  census: Census;
  extensions: Record<string, string>;
  psqlStatus: number;
  elapsedMs: number;
  rolledBack: true;
  committed: false;
  /** P-M point 2: the marker survived RESET_SQL and the pre-existing comment was restored. */
  commentMarkerProven: true;
};

/**
 * The whole proof. Dependency-injected end to end: the test suite runs it against a fake
 * psql and a fake catalog, and proves the refusals, the ordering, the abort and the absence
 * of any commit path without PostgreSQL.
 */
export async function runResetProof(deps: ProofDeps): Promise<ProofReport> {
  // ---- PHASE 1: observation. One session, opened and CLOSED before psql exists. --------
  //
  // Everything postgres.js needs to see happens here and nowhere else. The session is shut
  // before any psql process starts, because psql's own exclusivity check counts client
  // backends and would otherwise count this one — which is exactly what happened on
  // 2026-08-27 (§20.14). No observer may span the psql run.
  const pre = await deps.withSession(async (query) => {
    const identity = (await query(IDENTITY_SQL))[0] as unknown as Identity;
    assertProofIdentity(identity, deps.dsnDatabase);

    const sessions = (await query(OTHER_SESSIONS_SQL)) as unknown as SessionRow[];
    const tolerated = assertExclusiveAccess(sessions);

    const sections = await collectSections(query);
    const commentRow = (await query(DATABASE_COMMENT_SQL))[0] as { comment: string | null } | undefined;
    const preComment = commentRow?.comment ?? null;
    return { identity, tolerated, sections, preComment };
  });
  // The observation session is closed from here on.

  const { identity, preComment } = pre;
  const before = fingerprintOf(pre.sections);
  deps.log(`  database      : ${identity.database}`);
  deps.log(`  role          : current_user ${identity.role_name}, `
    + `session_user ${identity.session_role_name}, superuser no`);
  deps.log(`  server        : ${identity.server_addr}:${identity.server_port} `
    + `PostgreSQL ${identity.server_version}`);
  deps.log(pre.tolerated.length === 0
    ? '  other sessions: 0 (exclusive access)'
    : `  other sessions: 0 client backends; ${pre.tolerated.length} tolerated `
      + `(${pre.tolerated.map((s) => s.backend_type).join(', ')}) — bounded by lock_timeout`);
  deps.log(`  fingerprint   : ${before.overall}`);
  deps.log(`  db comment    : ${preComment === null ? '(none)' : 'present'} before this proof `
    + '(content not logged; restored exactly by the mandatory rollback)');
  deps.log('  observer      : closed before psql starts (no session spans the reset)');

  // ---- PHASE 2: psql only. No postgres.js connection is open. --------------------------
  //
  // Both calls are synchronous spawns, so each psql process has fully exited before the
  // next step begins — the probe cannot still be connected when the proof stream runs.
  deps.assertPsqlReachable();
  deps.log("  psql          : reachable, and answered through the reset's own argv");

  const started = Date.now();
  const result = deps.runPsql(buildProofSql());
  const elapsedMs = Date.now() - started;
  const outcome = assertProofOutcome(result);
  deps.log(`  psql exit     : ${result.status} (the deliberate abort — this is success)`);

  // ---- PHASE 3: a FRESH observation session, after psql has gone. ----------------------
  const post = await deps.withSession(async (query) => {
    const commentRow = (await query(DATABASE_COMMENT_SQL))[0] as { comment: string | null } | undefined;
    return {
      sections: await collectSections(query),
      health: (await query(HEALTH_SQL))[0],
      postComment: commentRow?.comment ?? null,
    };
  });

  // P-M point 2: the rollback must restore the EXACT pre-existing comment, whatever it was
  // (including none). Compared as free text from a fresh session, never parsed out of a
  // psql marker line, so arbitrary content (spaces, punctuation) cannot mask a mismatch.
  if (post.postComment !== preComment) {
    throw new ProofRefused(
      'The rollback did NOT restore the pre-existing database comment exactly '
      + `(was ${preComment === null ? '(none)' : 'present'}, now `
      + `${post.postComment === null ? '(none)' : 'present'} and different). Do NOT run the `
      + 'rebuild; investigate before anything else touches this database.');
  }

  // Cross-check that the psql transaction saw the database the PRE-RESET fingerprint
  // describes. Compared against the sections already collected, never against a fresh
  // query — a post-rollback re-read would compare the wrong side and mask real drift.
  const seenRelations = Number(outcome.before.relations);
  const fingerprintedRelations = pre.sections.relations.length;
  if (seenRelations !== fingerprintedRelations) {
    throw new ProofRefused(
      `The psql transaction saw ${seenRelations} relations but the pre-reset fingerprint `
      + `describes ${fingerprintedRelations}. The database changed underneath the proof. `
      + 'Treat the reset as UNPROVEN.');
  }

  const after = fingerprintOf(post.sections);
  if (after.overall !== before.overall) {
    throw new ProofRefused(
      'The rollback did NOT restore the database. Drifted sections: '
      + `${describeFingerprintDrift(before, after).join(', ')}. `
      + 'Do NOT run the rebuild; restore from backup and investigate.');
  }

  if (!post.health || post.health.database !== PROOF_EXPECTED_DATABASE) {
    throw new ProofRefused('The post-rollback health query did not answer as expected.');
  }
  deps.log(`  post-rollback : ${after.overall} (identical)`);
  deps.log('  db comment    : restored to the pre-existing value exactly (P-M point 2 proven)');
  deps.log(`  health        : ${String(post.health.relations)} relations, `
    + `${String(post.health.extensions)} extensions`);

  return {
    identity, before, after, census: outcome.census, extensions: outcome.extensions,
    psqlStatus: result.status, elapsedMs, rolledBack: true, committed: false,
    commentMarkerProven: true,
  };
}

export default { runResetProof, buildProofSql };

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

const REPO_ROOT = process.cwd();

async function main(): Promise<number> {
  if (process.argv.length > 2) {
    throw new ProofRefused(
      `Unknown argument: ${process.argv[2]}. This proof takes no options: it always runs `
      + `against ${PROOF_EXPECTED_DATABASE} and always rolls back.`);
  }

  const { spawnSync } = await import('node:child_process');

  // .env without a dotenv dependency, matching tools/db/rebuild-test.ts and tests/setup.ts.
  try {
    for (const line of readFileSync(join(REPO_ROOT, '.env'), 'utf8').split('\n')) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#') || !trimmed.includes('=')) continue;
      const [key, ...rest] = trimmed.split('=');
      if (!process.env[key.trim()]) process.env[key.trim()] = rest.join('=').trim();
    }
  } catch { /* CI supplies the variables directly */ }

  const dsn = process.env.AFLDB_TEST_DATABASE_URL;
  if (!dsn) {
    throw new ProofRefused(
      'AFLDB_TEST_DATABASE_URL is not set. This proof runs against the test database only '
      + 'and will not fall back to any other target.');
  }
  let dsnDatabase: string;
  try {
    dsnDatabase = databaseOf(dsn);
  } catch {
    throw new ProofRefused('AFLDB_TEST_DATABASE_URL is not a valid connection URL.');
  }
  // Refuse on the NAME before a connection is even opened.
  assertRebuildTargetName(dsnDatabase);
  // AFLDB-ISSUE-278: and on a DSN libpq would read as another database or server, with the
  // rebuild's own refusal, so the proof cannot accept a DSN the rebuild would refuse.
  assertDsnPinsTarget(dsn, 'AFLDB_TEST_DATABASE_URL');
  // AFLDB-ISSUE-313: and on the CREDENTIAL, before any session is opened or psql launched.
  try {
    psqlConnection(dsn, {});
  } catch (error) {
    if (!(error instanceof PsqlCredentialRefused)) throw error;
    throw new ProofRefused(`AFLDB_TEST_DATABASE_URL cannot be used with psql. ${error.message}`);
  }

  // AFLDB-ISSUE-278: `pinned`, exactly as the rebuild's createCliDeps runs psql, so the proof
  // and the reset cannot differ in which server the environment sends them to.
  const psqlDeps = { spawn: spawnSync as never, cwd: REPO_ROOT, pinned: true };
  const postgres = (await import('postgres')).default;

  /**
   * One connection per phase, opened here and CLOSED before this returns.
   *
   * Never a long-lived client. psql's in-stream exclusivity check counts client backends,
   * and a postgres.js observer held open across the psql run is itself one — the
   * 2026-08-27 self-collision (§20.14). `await sql.end()` waits for the socket to close,
   * so the backend is gone before psql is spawned.
   */
  const withSession = async <T>(fn: (query: Query) => Promise<T>): Promise<T> => {
    const sql = postgres(dsn, {
      max: 1,
      onnotice: () => {},
      connection: { application_name: 'afldb-reset-proof' },
    });
    try {
      return await fn((text) => sql.unsafe(text).then((rows) => rows as unknown as Row[]));
    } finally {
      await sql.end({ timeout: 5 });
    }
  };

  console.log('AFLDB RESET_SQL proof (AFLDB-ISSUE-093 §20)');
  console.log('  mode          : ROLLBACK-ONLY — nothing is committed, nothing is rebuilt');
  console.log('  reset path    : psql (tools/db/psql.ts) — the same helper, binary and argv');
  console.log('                  the destructive rebuild uses');

  {
    const report = await runResetProof({
      dsnDatabase,
      withSession,
      assertPsqlReachable: () => assertPsqlReachable(dsn, psqlDeps),
      runPsql: (text) => runPsql(dsn, text, psqlDeps),
      log: (line) => console.log(line),
    });

    console.log('\n  post-reset census (inside the aborted transaction):');
    console.log(`    application schemas ${report.census.schemas}   `
      + `tables ${report.census.tables}   views ${report.census.views}   `
      + `sequences ${report.census.sequences}`);
    console.log(`    routines ${report.census.routines}   types ${report.census.types}   `
      + `foreign tables ${report.census.foreign_tables}   `
      + `public schema kept ${report.census.public_schemas === 1 ? 'yes' : 'NO'}`);
    console.log(`    extensions preserved ${report.extensions.preserved}, `
      + `extension-owned objects ${report.extensions.members}`);
    console.log(`    reset stream completed in ${report.elapsedMs} ms`);
    console.log(`    comment marker survived RESET_SQL and the pre-existing comment was `
      + `restored exactly: ${report.commentMarkerProven ? 'yes' : 'NO'} (P-M point 2)`);
    console.log('\nRESET_SQL PROVEN through the real psql path — clean slate inside the');
    console.log('transaction, extensions intact, rollback restored the database');
    console.log('byte-identical by fingerprint, and the database-level comment marker');
    console.log('survived the reset with the pre-existing comment restored exactly.');
    console.log('THIS WAS A ROLLBACK-ONLY PROOF. Nothing was committed. Nothing was rebuilt.');
    return 0;
  }
}

// Only run when invoked directly, so the module stays importable by tests.
if (process.argv[1] && /prove-reset\.ts$/.test(process.argv[1])) {
  main()
    .then((code) => process.exit(code))
    .catch((error) => {
      const refused = error instanceof ProofRefused
        || error instanceof RebuildRefused
        || error instanceof PsqlUnavailable;
      console.error(refused ? `REFUSED: ${(error as Error).message}` : error);
      console.error('\nNothing was committed. The database is unchanged.');
      process.exit(1);
    });
}

/**
 * AFLDB-ISSUE-093 §20 — the ONE psql execution path.
 *
 * The clean rebuild's destructive DATABASE RESET and the rollback-only proof of that same
 * reset both run their SQL through this module, with the SAME binary, the SAME argument
 * vector and the SAME error handling. That is the whole point of the file: a proof that
 * exercised a different execution mechanism from the real reset would prove the SQL and
 * leave the mechanism untested, which is exactly the gap this stage exists to close.
 *
 * The two callers differ in ONE respect, and it is the safety-relevant one:
 *
 *   real reset  — the SQL stream ends normally, so psql's --single-transaction COMMITs.
 *   proof       — the SQL stream always ends in RAISE EXCEPTION, so the transaction is
 *                 already ABORTED when psql reaches the end. COMMIT is unreachable.
 *
 * Nothing here ever prints a DSN or a password. psql's own diagnostics name relations,
 * roles and hosts, never the connection string it was handed.
 *
 * AFLDB-ISSUE-313: nor does the password ever reach psql's ARGUMENT VECTOR. argv is readable
 * by every local user (`ps`, `/proc/<pid>/cmdline`) for the whole life of the child, so
 * `psqlConnection` splits a URI DSN into a password-free `-d` value and a child environment
 * carrying `PGPASSWORD` (readable only by the process owner). Every psql this repository
 * launches from TypeScript takes its connection from that one function.
 */

/** The executable. Not a path: the repository already relies on psql being on PATH. */
export const PSQL_BIN = 'psql';

/** psql could not be launched at all — missing binary, permissions, spawn failure. */
export class PsqlUnavailable extends Error {}

/**
 * A connection string that cannot be handed to psql without leaving its password on the
 * command line, or whose password cannot be moved off it WITHOUT guessing what libpq would
 * have done. A refusal, never a fallback: the alternative is a silently different connection
 * or a leaked credential. Messages name the problem, never the DSN or any part of it.
 *
 * A subclass of PsqlUnavailable so the callers that already fail closed on "psql cannot be
 * used" (the reset proof) fail closed on this too, before anything is executed.
 */
export class PsqlCredentialRefused extends PsqlUnavailable {}

/** Any string-keyed environment; `NodeJS.ProcessEnv` is stricter than a test fixture needs. */
export type EnvLike = Record<string, string | undefined>;

/**
 * AFLDB-ISSUE-278: the libpq environment variables that choose WHERE a connection goes, as which
 * role, with which session options (PostgreSQL 16, "Environment Variables"). libpq applies each
 * only to a parameter the connection string left UNSET, but `PGHOSTADDR` is such a parameter even
 * when the URI names a host: with both set, `hostaddr` gives the network address and `host` is
 * demoted to an authentication name (fe-connect.c `pqConnectOptions2`, CHT_HOST_ADDRESS first).
 * `PGSERVICE` / `PGSERVICEFILE` / `PGSYSCONFDIR` select a service file that fills unset
 * parameters, and `PGPORT` fills an omitted port. postgres.js reads neither `PGHOSTADDR` nor
 * `PGSERVICE`, and uses `PGHOST` / `PGPORT` only when the URL omits them, so an inherited value
 * can point psql and a postgres.js observer at DIFFERENT servers.
 *
 * Deliberately NOT here: `PGPASSWORD` and `PGPASSFILE` (credentials, not routing: ISSUE-313 keeps
 * an ambient password working), and the transport-security variables.
 */
export const LIBPQ_ROUTING_ENV: readonly string[] = [
  'PGHOST', 'PGHOSTADDR', 'PGPORT', 'PGDATABASE', 'PGUSER', 'PGSERVICE', 'PGSERVICEFILE',
  'PGSYSCONFDIR', 'PGOPTIONS', 'PGTARGETSESSIONATTRS', 'PGLOADBALANCEHOSTS',
];

/**
 * A COPY of `parentEnv` without any LIBPQ_ROUTING_ENV variable (matched case-insensitively,
 * because a Windows environment is). The parent is never modified.
 */
export function withoutLibpqRouting(parentEnv: EnvLike): NodeJS.ProcessEnv {
  const routing = new Set(LIBPQ_ROUTING_ENV);
  const copy = { ...parentEnv } as NodeJS.ProcessEnv;
  for (const name of Object.keys(copy)) if (routing.has(name.toUpperCase())) delete copy[name];
  return copy;
}

/**
 * `pinned` (AFLDB-ISSUE-278) is opt-in, because other tools legitimately lean on an ambient
 * `PGHOST` / service file with a host-less DSN. The destructive rebuild and its proof opt in:
 * the child environment loses LIBPQ_ROUTING_ENV and psql is started with `-X`, so neither the
 * environment nor a `psqlrc` `\connect` can move the connection off the URL.
 */
export type PsqlPinning = { pinned?: boolean };

export type PsqlConnection = {
  /** The `-d` value. Carries no password; safe to appear in argv and in error text. */
  dsn: string;
  /**
   * The child process environment: a COPY of the parent's, plus `PGPASSWORD` when the DSN
   * carried a password. The parent's own environment is never modified. NEVER log this.
   */
  env: NodeJS.ProcessEnv;
};

const URI_SCHEME = /^postgres(?:ql)?:\/\//;   // libpq's own test: exactly these two, lower case

function refuse(reason: string): never {
  throw new PsqlCredentialRefused(
    `Refusing to hand this connection string to psql: ${reason}. The password cannot be moved `
    + 'off the psql command line without guessing what libpq would do with it. Use a postgres '
    + 'URL with the password in its user:password userinfo (the form .env.example documents) and '
    + 'no other password source, or put the credential in PGPASSWORD / a .pgpass file yourself. '
    + 'Nothing has been executed.');
}

function decodeSecret(raw: string): string {
  let decoded: string;
  try {
    decoded = decodeURIComponent(raw);
  } catch {
    return refuse('the password is not valid percent-encoded UTF-8');
  }
  // An environment value cannot hold NUL, and Node's error for one would quote the value.
  if (decoded.includes('\0')) return refuse('the password contains a NUL character');
  return decoded;
}

function decodeKeyword(raw: string): string {
  try {
    return decodeURIComponent(raw);
  } catch {
    return raw;   // libpq refuses an undecodable keyword outright; it cannot be `password`
  }
}

/**
 * Split a DSN into what may appear on a command line and the password that may not.
 *
 * The rule that keeps this from guessing at libpq: a password SOURCE is the userinfo's text
 * after ':' and every `password` query parameter. If no source holds any text there is no
 * secret, and the string is returned untouched. If exactly ONE source holds text and it is the
 * only source, that text moves to the environment and its source is cut out. Anything else —
 * two sources, a source beside an empty one, a secret that libpq would not parse the way this
 * code does — is refused, because resolving it would need libpq's precedence and empty-value
 * rules, which are not assumed here.
 *
 *   userinfo      `postgres://user:PASSWORD@host/db` — located as libpq locates it (the first
 *                 '@' before the first '/'), percent-decoded.
 *   query         `?password=PASSWORD` — the keyword is percent-decoded before it is compared
 *                 (`pass%77ord` is `password`); `&` separates parameters.
 *   sslpassword   a secret with no environment variable to carry it: refused.
 *   key=value     `host=h password=…` — not parsed. Refused if it names a password keyword,
 *                 passed through untouched otherwise (a bare database name, say).
 *
 * Everything else in the string — scheme, user, host list, port, database, every other
 * parameter, its spelling and its order — is returned byte for byte.
 */
function splitDsn(dsn: string): { safe: string; password: string | undefined } {
  const scheme = URI_SCHEME.exec(dsn);
  if (!scheme) {
    if (/(?:^|\s)(?:ssl)?password\s*=/i.test(dsn)) {
      refuse('a key=value connection string names a password keyword');
    }
    return { safe: dsn, password: undefined };
  }

  const body = dsn.slice(scheme[0].length);

  // userspec: '@' before the first '/' ends it, and the user ends at the first ':' or '@'.
  let at = 0;
  while (at < body.length && body[at] !== '@' && body[at] !== '/') at += 1;
  const hasUserspec = body[at] === '@';
  const userspec = hasUserspec ? body.slice(0, at) : '';
  const colon = userspec.indexOf(':');
  const userinfoRaw = colon === -1 ? undefined : userspec.slice(colon + 1);
  const afterUserspec = hasUserspec ? at + 1 : 0;
  const rest = body.slice(afterUserspec);

  const mark = rest.indexOf('?');
  const elements = mark === -1 ? [] : rest.slice(mark + 1).split('&');
  const queryRaw = new Map<number, string>();          // element index -> raw (still encoded) value
  elements.forEach((element, index) => {
    const eq = element.indexOf('=');
    const keyword = decodeKeyword(eq === -1 ? element : element.slice(0, eq));
    if (keyword === 'sslpassword') {
      refuse('it carries an sslpassword parameter, which has no environment-variable equivalent');
    }
    if (keyword === 'password') queryRaw.set(index, eq === -1 ? '' : element.slice(eq + 1));
  });

  const sources = [...(userinfoRaw === undefined ? [] : [userinfoRaw]), ...queryRaw.values()];
  if (!sources.some((text) => text !== '')) return { safe: dsn, password: undefined };
  if (sources.length > 1) refuse('it has more than one password source');

  if (userinfoRaw) {
    // Cut ":PASSWORD" out of the userinfo; keep the user, the '@' and everything after.
    return {
      safe: scheme[0] + userspec.slice(0, colon) + body.slice(at),
      password: decodeSecret(userinfoRaw),
    };
  }
  const [[index, raw]] = [...queryRaw];
  if (raw.includes('=')) refuse('a password query parameter is malformed');
  const kept = elements.filter((_, i) => i !== index);
  return {
    safe: scheme[0] + body.slice(0, afterUserspec) + rest.slice(0, mark)
      + (kept.length ? `?${kept.join('&')}` : ''),
    password: decodeSecret(raw),
  };
}

/**
 * The connection psql is launched with: a password-free `-d` value and the environment that
 * carries the password instead. `parentEnv` is copied, never modified; when the DSN carries
 * no password the child's environment is the parent's (so an ambient PGPASSWORD / PGPASSFILE
 * keeps working exactly as it did when the DSN went straight to psql).
 */
export function psqlConnection(
  dsn: string,
  parentEnv: EnvLike = process.env,
  pinning: PsqlPinning = {},
): PsqlConnection {
  const { safe, password } = splitDsn(dsn);
  const env = (pinning.pinned ? withoutLibpqRouting(parentEnv) : { ...parentEnv }) as NodeJS.ProcessEnv;
  if (password !== undefined) {
    // Windows environment names are case-insensitive; a copy of process.env is a plain
    // object, so a differently-cased parent PGPASSWORD would otherwise sit beside ours.
    if (process.platform === 'win32') {
      for (const name of Object.keys(env)) if (name.toUpperCase() === 'PGPASSWORD') delete env[name];
    }
    env.PGPASSWORD = password;
  }
  return { dsn: safe, env };
}

/**
 * The argument vector, built in one place so the two callers cannot drift apart.
 *
 *   -d <dsn>             the target, as an OPTION and never as a positional operand. The value
 *                        is the PASSWORD-FREE form (ISSUE-313): the password travels in the
 *                        child environment from `psqlConnection`, never in this vector.
 *   ON_ERROR_STOP=1      any SQL error is a non-zero exit, not a warning on stdout.
 *   --single-transaction the whole stream is one transaction: the real reset is
 *                        all-or-nothing, and the proof's abort discards everything.
 *   -q                   suppress command tags; errors and RAISE output are unaffected.
 *   -f -                 read the stream from stdin, so no SQL is ever written to disk.
 *
 * `-d <dsn>` rather than the bare `psql <dsn> …` this repository uses elsewhere, and that
 * is not cosmetic. psql's usage is `psql [OPTION]... [DBNAME [USERNAME]]`, and psql does
 * NOT always use GNU getopt: `src/port/getopt_long.c`, which PostgreSQL builds on Windows
 * and anywhere the system getopt_long is missing, **stops at the first non-option argument
 * and does not permute**. With the DSN leading, every flag after it can then be consumed as
 * an operand instead of an option — silently, because psql only warns about extras. A psql
 * that ignored `--single-transaction` and `ON_ERROR_STOP=1` would autocommit each statement
 * and still exit 0, which is exactly the shape of the 2026-08-27 incident (§20.12). With no
 * positional operand at all there is nothing for a non-permuting getopt to stop at.
 *
 *   -X (pinned only)     do not read the system or user psqlrc. psql reads them even for
 *                        `-f -`, AFTER connecting and BEFORE the stream, so a `\connect` there
 *                        would move the stream to another database or server (PostgreSQL 16
 *                        src/bin/psql/startup.c: `if (!options.no_psqlrc) process_psqlrc()`).
 */
export function psqlArgv(dsn: string, pinning: PsqlPinning = {}): string[] {
  return [
    ...(pinning.pinned ? ['-X'] : []),
    '-d', psqlConnection(dsn).dsn, '-v', 'ON_ERROR_STOP=1', '--single-transaction', '-q', '-f', '-',
  ];
}

/**
 * Strip anything that looks like a connection string out of text before it is printed.
 * psql's own diagnostics name relations, roles and hosts rather than the DSN, but a
 * "psql said:" relay must not depend on that being true of every future message.
 */
export function redact(text: string): string {
  return text
    .replace(/\b[a-z][a-z0-9+.-]*:\/\/[^\s'"]*/gi, '<redacted-dsn>')
    .replace(/\b(password|PGPASSWORD)\s*=\s*\S+/gi, '$1=<redacted>');
}

export type PsqlResult = { status: number; stdout: string; stderr: string };

export type SpawnSyncLike = (
  command: string,
  args: string[],
  options: { input: string; encoding: 'utf8'; cwd?: string; env?: NodeJS.ProcessEnv },
) => { status: number | null; stdout: string | null; stderr: string | null; error?: Error };

export type PsqlDeps = { spawn: SpawnSyncLike; cwd?: string } & PsqlPinning;

/**
 * Run one SQL stream through psql. Returns the exit status rather than throwing on a SQL
 * error, because BOTH outcomes are meaningful: the rebuild treats non-zero as a failed
 * reset, and the proof REQUIRES non-zero (its stream always aborts deliberately).
 *
 * Throws only when psql itself could not run — or, before anything is spawned, when the DSN's
 * password cannot be moved off the command line (PsqlCredentialRefused).
 */
export function runPsql(dsn: string, sql: string, deps: PsqlDeps): PsqlResult {
  const connection = psqlConnection(dsn, process.env, { pinned: deps.pinned });
  const result = deps.spawn(PSQL_BIN, psqlArgv(dsn, { pinned: deps.pinned }), {
    input: sql, encoding: 'utf8', cwd: deps.cwd, env: connection.env,
  });
  if (result.error) {
    throw new PsqlUnavailable(
      `Could not run '${PSQL_BIN}': ${result.error.message}. It must be on PATH — the same `
      + 'dependency `npm run db:privileges:test` and tools/maintenance/restore-test.sh '
      + 'already have. Nothing has been executed.');
  }
  return {
    status: result.status ?? 1,
    stdout: result.stdout ?? '',
    stderr: result.stderr ?? '',
  };
}

/**
 * The probe. It proves THREE things about the execution path, and every one of them was
 * assumed rather than proven by the first live attempt on 2026-08-27:
 *
 *   1. psql launches                      — spawnSync returns no `error`;
 *   2. psql RECEIVES THE STREAM ON STDIN  — the OK token comes back;
 *   3. a SQL error becomes a NON-ZERO EXIT — the abort token comes back with status != 0.
 *
 * (2) and (3) are the point. The earlier probe ran `SELECT 1` and accepted exit 0 — but an
 * EMPTY or undelivered stdin also exits 0, and so does an errored script when
 * ON_ERROR_STOP is not in force. The probe therefore could not distinguish a working path
 * from a path that silently discards the SQL, which is exactly the ambiguity that made the
 * first live proof unexplainable. It now deliberately fails, and demands proof of the
 * failure. Nothing it does touches a single application object.
 */
export const PSQL_PROBE_OK = 'AFLDB-PSQL-PROBE-STDIN-OK';
export const PSQL_PROBE_ABORT = 'AFLDB-PSQL-PROBE-ABORT';

export const PSQL_PROBE_SQL = `DO $afldb_probe$ BEGIN
  RAISE WARNING '${PSQL_PROBE_OK}';
END $afldb_probe$;
DO $afldb_probe$ BEGIN
  RAISE EXCEPTION '${PSQL_PROBE_ABORT}';
END $afldb_probe$;
`;

export function assertPsqlReachable(dsn: string, deps: PsqlDeps): void {
  const result = runPsql(dsn, PSQL_PROBE_SQL, deps);   // throws PsqlUnavailable if missing
  const output = `${result.stdout}\n${result.stderr}`;

  if (!output.includes(PSQL_PROBE_OK)) {
    throw new PsqlUnavailable(
      `psql launched (exit ${result.status}) but did NOT execute the SQL supplied on its `
      + 'stdin: the probe token never came back. The reset stream would be silently '
      + 'discarded the same way. Check that this psql is a real client and not a wrapper '
      + 'that drops stdin, and that `-f -` is reaching it.\n'
      + `psql said: ${redact(output.trim()) || '(nothing at all)'}`);
  }
  if (result.status === 0) {
    throw new PsqlUnavailable(
      'psql executed the stream but returned exit 0 for a script that deliberately raised '
      + 'an exception, so ON_ERROR_STOP is not in force on this path. A failed reset would '
      + `be reported as a success.\npsql said: ${redact(output.trim())}`);
  }
  if (!output.includes(PSQL_PROBE_ABORT)) {
    throw new PsqlUnavailable(
      `psql exited ${result.status} but never reported the probe's deliberate error, so `
      + 'PostgreSQL diagnostics are not reaching this process.\n'
      + `psql said: ${redact(output.trim())}`);
  }
}

export default { PSQL_BIN, psqlArgv, psqlConnection, runPsql, assertPsqlReachable, redact };

/**
 * AFLDB-ISSUE-093 §10 — the canonical clean rebuild of `afldb_test`.
 *
 *     npm run db:test:rebuild -- --acknowledge-destroy afldb_test
 *
 * AFLDB-ISSUE-146 — the same runner, the same stage graph, against the disposable
 * full-rebuild rehearsal database `code_test_db`, selected ONLY by an explicit flag:
 *
 *     npm run db:test:rebuild -- --target code_test_db --acknowledge-destroy code_test_db
 *
 * AFLDB-ISSUE-237 L2 adds ONE rehearsal-only control, valid on `code_test_db` alone: stop
 * deliberately after the real `recreate` succeeds, before `migrations`, leaving the marker and
 * the pending capture for a separate `--recover-afl-api-adjudications` run (exit code 86):
 *
 *     npm run db:test:rebuild -- --target code_test_db --acknowledge-destroy code_test_db \
 *       --rehearsal-stop-after recreate
 *
 * This is the ONE supported rebuild entry point. It runs the fixed dependency order,
 * fails closed at the first problem, and never touches `afldb_dev` or production. The
 * destructive targets are an explicit allowlist (REBUILD_TARGETS); the default is still
 * `afldb_test`, each target has its OWN dedicated DSN variables, and the target is never
 * inferred from a DSN — the DSN must name the target the operator selected.
 *
 * The core source is NOT named on the command line: it is the single accepted canonical
 * baseline in data/reference/fitzroy-accepted-baselines.json. Partial/trial core data stays
 * available for bounded testing, but only via an explicit
 * `--fitzroy-label <label> --acknowledge-partial-fitzroy`, and is never selected
 * implicitly — there is no 'latest label' fallback anywhere in this file.
 *
 * §10 contract, implemented here point for point:
 *   1. explicit named-target map, refusing anything unrecognised   -> resolveTarget()
 *   2. destination-must-equal-known-safe-name                      -> resolveTarget()
 *   3. refuse every target outside the allowlist (afldb_test, and
 *      code_test_db under --target); reject dev/prod by name       -> resolveTarget()
 *   4. full preflight BEFORE destruction or any database contact   -> stage 1
 *   5. explicit destructive acknowledgement before drop/reset      -> --acknowledge-destroy
 *   6. apply the complete tracked migration set via migrate.ts,
 *      with no hard-coded terminal migration number                -> stage 3
 *   7. fixed dependency order, failing closed on a missing source  -> planStages()
 *   8. per-domain fingerprints and row counts                      -> stage 9
 *   9. never reference AFLDB_LEGACY_SQLITE                         -> nothing here does
 *
 * AFLDB-ISSUE-235 OD-5 adds the one piece of HUMAN state this rebuild carries across the
 * reset: the `afl_api` identity adjudication ledger. It is captured after PRECHECK and before
 * the reset, reinstated and replayed after `draftguru`, and bijection-checked straight after
 * (see planStages() and tools/migration/rebuild_afl_api_adjudications.ts). AFLDB-ISSUE-237
 * adds the importer-created `afl_api` identities to that same capture, and AFLDB-ISSUE-245 the
 * manual/post-baseline player REGISTRATIONS (`data_overrides` creation records): reinstated,
 * replayed through the production `replay_admin_overrides(players)` and verified by three
 * stages of their own, BEFORE `draftguru` and so before any player-dependent replay.
 *
 * Two repository facts shape the destructive step, and neither was invented here:
 *
 *   * No DSN in the credential model can DROP/CREATE a database. `afldb_test` is created
 *     once at host bootstrap by `sudo -u postgres createdb -O afldb_owner`
 *     (tools/maintenance/00_install_postgres.sh:88). So "recreate" is an in-place RESET
 *     over the existing test DSN — which is what §10's own cited pattern,
 *     tools/maintenance/restore-test.sh:104-118, does.
 *   * That pattern drops tables individually rather than `DROP SCHEMA public CASCADE`,
 *     because pg_trgm and unaccent live in public and are owned by another role. This
 *     reset goes further than restore-test.sh — it also removes non-public schemas,
 *     routines and types — because the migrations must re-run from nothing, but it keeps
 *     the same extension-preserving discipline.
 *
 * Everything below the argument parsing is pure or dependency-injected, so the whole
 * safety and ordering contract is tested without a database (tests/db-test-rebuild.test.ts).
 *
 * RESET_SQL itself is proven separately and non-destructively by
 * `npm run db:test:prove-reset` (tools/db/prove-reset.ts, AFLDB-ISSUE-093 §20): it runs
 * this exact constant inside one transaction and ALWAYS rolls back. Nothing in that path
 * can reach any stage below — it is a different entry point with no stage graph at all.
 */

