/**
 * `capture` and `reinstate` are AFLDB-ISSUE-235 OD-5's: the only two stages that run with
 * the OWNER DSN outside the schema/privilege/reset path. Capture reads `auth_users` and
 * reinstate writes ledger ids, the sequence and attribution-only actors — none of which
 * afldb_import may do — so they are their own kinds rather than `data` stages quietly
 * holding more privilege than every other data stage. AFLDB-ISSUE-245's
 * `manual-registrations-reinstate` is a `reinstate` stage for the same reason (it writes
 * `data_overrides` and attribution-only actors), and `manual-registrations-verify` is the one
 * `validation` stage on the owner DSN: it must read each creation record's actor email from
 * `auth_users`, which afldb_import cannot, and it proves a READ ONLY transaction first.
 */
export type StageKind =
  | 'precheck' | 'capture' | 'destructive' | 'schema' | 'privileges' | 'data' | 'reinstate'
  | 'validation';

export type Stage = {
  /** Stable identifier used by tests and by the run report. */
  id: string;
  name: string;
  kind: StageKind;
  /**
   * How the stage does its work.
   *
   *   command  — a child process; non-zero exit fails the stage.
   *   sql      — the DESTRUCTIVE reset, through deps.runSql.
   *   validate — a READ-ONLY assertion stream, through deps.runValidation. Separate from
   *              `sql` so nothing can route a validation stream into the destructive
   *              runner, or vice versa, by editing one field.
   *   internal — done by the runner outside the stage loop (PRECHECK; see runPreflight).
   */
  run: 'command' | 'sql' | 'validate' | 'internal';
  argv?: string[];
  /** The stream for a `validate` stage. */
  sql?: string;
  /** Explicit child-process environment. Data stages get the TEST import DSN here. */
  envOverlay?: Record<string, string>;
};

export type ResolvedTarget = {
  /** The database name, e.g. `afldb_test`. */
  database: string;
  /** Owner/admin DSN for schema, privileges and the reset. Never logged. */
  adminDsn: string;
  /** Restricted import DSN handed to every data stage. Never logged. */
  importDsn: string;
  /** True when importDsn is the owner DSN under an explicit acknowledgement. */
  importIsOwnerSubstitution: boolean;
  /**
   * V2 Launch F: set ONLY by resolveIsolatedTarget(), for a database on the isolated local
   * cluster (tools/v2/isolated-pg.ts). executeRebuild() re-proves the DSNs and the live server
   * against this before any stage runs.
   */
  isolated?: { port: number };
};

export type FitzroySource = {
  label: string;
  fullHistory: boolean;
  acknowledgedPartial: boolean;
  /** True when the label came from (or matches) the tracked acceptance register. */
  accepted: boolean;
  /** How the label was chosen, for the banner and for tests. */
  selection: 'accepted-baseline' | 'explicit-partial';
};

export type Options = {
