  const argv = ['npx', 'tsx', AFL_API_ADJUDICATION_TOOL, step];
  if (step === 'capture' && recover) argv.push('--recover');
  return argv;
}

/**
 * The stage environment. Capture and reinstate need the OWNER DSN (see StageKind); the
 * read-only bijection check runs as the restricted import role, like every other
 * validation command stage. Always the selected target's own DSNs. AFLDB-ISSUE-245: both
 * registration steps take the owner DSN (see StageKind for why verify does).
 */
export function aflApiAdjudicationEnv(
  target: ResolvedTarget, step: AflApiAdjudicationStep,
): Record<string, string> {
  return {
    [AFL_API_ADJUDICATION_TARGET_ENV]: target.database,
    [AFL_API_ADJUDICATION_DSN_ENV]: step === 'bijection' ? target.importDsn : target.adminDsn,
  };
}

/**
 * AFLDB-ISSUE-233 D-233-3. The rebuild recreates every completed season in its scope as AFL
 * Tables rows, so it must preserve `afl_api` ownership or refuse. Until an ownership-replay
 * design exists it refuses: this read-only stage counts, on the database about to be reset,
 * the canonical `matches` owned by source `afl_api` in each completed season of the rebuild
 * scope, and fails the run on any non-zero season, naming every season and count. It runs
 * after PRECHECK and BEFORE the adjudication capture (which sets the rebuild marker) and the
 * reset, so a refusal leaves nothing captured, marked or destroyed. There is no override.
 */
export const AFL_API_OWNERSHIP_CENSUS_STAGE = 'afl-api-ownership-census';
const SEASONS_REFERENCE = join('data', 'reference', 'seasons.json');

/**
 * The census scope, from the tracked documents the rebuild is bound to: the fitzRoy
 * contract's `full_history.season_range` minus every in-progress season. Read at plan time,
 * like every other tracked pin; a missing or malformed document refuses.
 */
export function aflApiOwnershipCensusScope(
  readJson: (path: string) => Record<string, unknown> = (path) =>
    JSON.parse(readFileSync(join(REPO_ROOT, path), 'utf8')) as Record<string, unknown>,
): CensusScope {
  try {
    return rebuildCensusScope(readJson(FITZROY_CONTRACT), readJson(SEASONS_REFERENCE));
  } catch (error) {
    if (error instanceof AflApiOwnershipCensusError) {
      throw new RebuildRefused(`AFL API ownership census: ${error.message} Nothing has been destroyed.`);
    }
    throw error;
  }
}

/** The ENFORCING census stream the stage runs: any in-scope `afl_api` match is a psql error. */
export function aflApiOwnershipCensusSql(scope: CensusScope = aflApiOwnershipCensusScope()): string {
  return buildAflApiOwnershipCensusSql(scope, 'enforce');
}

export const BROWNLOW_SEASON_PREFLIGHT_FILES = [
  'data/brownlow/season-votes.csv',
  'data/brownlow/season-votes.manifest.json',
  'data/brownlow/player-identity.csv',
];

// ---------------------------------------------------------------------------
// Safety — every refusal happens before any destruction
// ---------------------------------------------------------------------------

export function databaseOf(dsn: string): string {
  return new URL(dsn).pathname.replace(/^\//, '');
}

/**
 * AFLDB-ISSUE-313: refuse, before any stage, a DSN whose password psql cannot be given
 * privately (tools/db/psql.ts `psqlConnection`). Only the refusal is of interest; the result
 * is discarded and nothing is spawned. The message never contains the DSN.
 */
export function assertPsqlCanCarry(dsn: string, name: string): void {
  try {
    psqlConnection(dsn, {});
  } catch (error) {
    if (!(error instanceof PsqlCredentialRefused)) throw error;
    throw new RebuildRefused(`${name} cannot be used with psql. ${error.message}`);
  }
}

/**
 * AFLDB-ISSUE-278: libpq keywords that can move a connection off the host, port, database or
 * role the URL names. In a URI the QUERY string is parsed after the path and authority and
 * `conninfo_storeval` frees and replaces the earlier value (PostgreSQL 16 fe-connect.c,
 * `conninfo_uri_parse_options` / `conninfo_uri_parse_params`), so `…/afldb_test?dbname=afldb_dev`
 * connects psql to afldb_dev while `databaseOf` still reads `afldb_test`. postgres.js ignores
 * these keys (it reads the path and the authority only), so the two disagree.
 */
const LIBPQ_REDIRECT_KEYWORDS = new Set([
  'dbname', 'host', 'hostaddr', 'port', 'service', 'user', 'options',
]);

/**
 * AFLDB-ISSUE-278: refuse, before any stage, a DSN whose libpq reading can differ from the
 * database name `databaseOf` validated. Each check is a refusal and none a guess:
 *
 *   - the scheme is libpq's own URI test (lower-case `postgres://` or `postgresql://`); any other
 *     spelling is read by libpq as a database name or a key/value string;
 *   - the authority names ONE literal host AND an explicit port, so no routing parameter is left
 *     unset for PGHOST / PGHOSTADDR / PGPORT / a service file / a socket default to fill;
 *   - the query carries none of LIBPQ_REDIRECT_KEYWORDS (keyword percent-decoded, as libpq does);
 *   - the database libpq extracts from the path (percent-decoded) equals `databaseOf`, so an
 *     escape, a dot segment or a fragment cannot make the two readings differ.
 *
 * COMPATIBILITY: a rebuild / proof DSN must therefore be
 * `postgres(ql)://user[:password]@HOST:PORT/DATABASE` with a literal host name or IP and a
 * numeric port. A Unix-socket, host-less or default-port DSN is refused. An inherited
 * PGHOSTADDR, which would override even an explicit host, is handled by the child environment
 * (psql.ts `withoutLibpqRouting`), not here.
 *
 * What it cannot see: the same host NAME resolving differently for libpq and for a postgres.js
 * observer (DNS, IPv4 against IPv6), and a second server answering at the named address. The
 * in-stream identity guard (`rebuildIdentityGuardSql`) names the database and role, not the
 * server. Messages never contain the DSN.
 */
export function assertDsnPinsTarget(dsn: string, name: string): void {
  const scheme = /^postgres(?:ql)?:\/\//.exec(dsn);
  if (!scheme) {
    throw new RebuildRefused(
      `${name} must be a postgres:// or postgresql:// URL in lower case: libpq reads any other `
      + 'spelling as a database name or a key/value string, not as the URL this runner validated.');
  }
  const body = dsn.slice(scheme[0].length);

  // libpq's userspec rule (and tools/db/psql.ts): an '@' before the first '/' ends it.
  let at = 0;
  while (at < body.length && body[at] !== '@' && body[at] !== '/') at += 1;
  const afterUserspec = body[at] === '@' ? at + 1 : 0;
  const rest = body.slice(afterUserspec);

  const hostEnd = rest.search(/[/?]/);
  const hostSpec = hostEnd === -1 ? rest : rest.slice(0, hostEnd);
  if (hostSpec.includes(',')) {
    throw new RebuildRefused(
      `${name} names more than one host. libpq tries a host list in turn, so the server it `
      + 'reaches is not the one this runner validated; use a single host.');
  }
  // Nothing may be left for the environment, a service file or a socket default to fill: a
  // missing host is a Unix-domain socket or PGHOST / PGHOSTADDR / a service file to libpq, and
  // a missing port is PGPORT, a service file or the compiled-in default.
  if (hostSpec === '') {
    throw new RebuildRefused(
      `${name} names no host. libpq would take the server from PGHOST, PGHOSTADDR, a service `
      + 'file or a local socket, none of which this runner validated; write host:port in the URL.');
  }
  const hostAndPort = /^(?:\[[0-9A-Fa-f:.]+\]|[A-Za-z0-9._-]+)(?::(\d*))?$/.exec(hostSpec);
  if (!hostAndPort) {
    throw new RebuildRefused(
      `${name} has a host that is not a plain host name or IP address (a percent-encoded host `
      + 'is a Unix-domain socket path to libpq); write host:port in the URL.');
  }
  const port = hostAndPort[1];
  if (!port || Number(port) < 1 || Number(port) > 65535) {
    throw new RebuildRefused(
      `${name} names no usable port (1-65535). libpq would take an omitted port from PGPORT, a `
      + 'service file or its compiled-in default; write the port in the URL.');
  }

  const mark = rest.indexOf('?');
  const pathSpan = hostEnd === -1 || rest[hostEnd] === '?'
    ? '' : rest.slice(hostEnd + 1, mark === -1 ? undefined : mark);
  if (mark !== -1) {
    for (const element of rest.slice(mark + 1).split('&')) {
      const eq = element.indexOf('=');
      const raw = eq === -1 ? element : element.slice(0, eq);
      let keyword: string;
      try {
        keyword = decodeURIComponent(raw).toLowerCase();
      } catch {
        throw new RebuildRefused(`${name} has a query parameter name that is not valid percent-encoding.`);
      }
      if (LIBPQ_REDIRECT_KEYWORDS.has(keyword)) {
        throw new RebuildRefused(
          `${name} carries the '${keyword}' query parameter. libpq lets a query parameter override `
          + 'the host, port, database or role in the URL, so psql could reach a database other than '
          + 'the one this runner validated. Remove it; the URL path and authority must say it all.');
      }
    }
  }

  let libpqDatabase: string;
  try {
    libpqDatabase = decodeURIComponent(pathSpan);
  } catch {
    throw new RebuildRefused(`${name} has a database name that is not valid percent-encoding.`);
  }
  let validated: string;
  try {
    validated = databaseOf(dsn);
  } catch {
    throw new RebuildRefused(`${name} is not a valid connection URL.`);
  }
  if (libpqDatabase !== validated) {
    throw new RebuildRefused(
      `${name} names its database in a form libpq and this runner read differently `
      + '(percent-escape, dot segment or fragment). Write the plain database name in the URL path.');
  }
}

/** The role every rebuild target is owned by, and the one the reset runs as. */
export const REBUILD_OWNER_ROLE = 'afldb_owner';
export const REBUILD_IDENTITY_MARKER = 'AFLDB-REBUILD-IDENTITY';

/**
 * AFLDB-ISSUE-278: the identity assertion the destroying and validating psql streams begin with,
 * so the connection that acts is checked, not the URL that was parsed. It raises unless the
 * session is connected to `database` as `afldb_owner` with no SET ROLE in force, exactly as the
 * rollback-only proof (tools/db/prove-reset.ts, "1. IDENTITY") asserts for the same stream.
 * `database` must be an allowlisted rebuild target, so it is a plain identifier that is safe to
 * inline. `RESET_SQL` itself is not altered: the proof embeds it verbatim.
 */
export function rebuildIdentityGuardSql(
  database: string, env: Readonly<Record<string, string | undefined>> = process.env,
): string {
  assertRebuildTargetName(database, env);
  if (!/^[a-z][a-z0-9_]*$/.test(database)) {
    throw new RebuildRefused(`Refusing to assert identity for '${database}': not a plain identifier.`);
  }
  const m = REBUILD_IDENTITY_MARKER;
  return `-- AFLDB-ISSUE-278: identity of the connection that acts, asserted in its own session.
DO $afldb_identity$
DECLARE db text; cu text; su text;
BEGIN
  SELECT current_database(), current_user, session_user INTO db, cu, su;
  IF db <> '${database}' THEN
    RAISE EXCEPTION '${m} connected to database %, not ${database}', db;
  END IF;
  IF cu <> '${REBUILD_OWNER_ROLE}' THEN
    RAISE EXCEPTION '${m} current_user is %, not ${REBUILD_OWNER_ROLE}', cu;
  END IF;
  IF su <> '${REBUILD_OWNER_ROLE}' THEN
    RAISE EXCEPTION '${m} session_user is %, not ${REBUILD_OWNER_ROLE}; SET ROLE is not part of the AFLDB credential model', su;
  END IF;
  RAISE WARNING '${m} database=% current_user=% session_user=%', db, cu, su;
END $afldb_identity$;
`;
}

/**
 * The target-name contract, §10 points 1-3, in ONE place.
 *
 * `resolveTarget` below and the rollback-only reset proof (tools/db/prove-reset.ts) both
 * call this, so the proof cannot drift into a weaker duplicate of the rebuild's own
 * refusals. Never includes a DSN or password in any message.
 */
export function assertRebuildTargetName(
  database: string, env: Readonly<Record<string, string | undefined>> = process.env,
): void {
  if (FORBIDDEN_DATABASES.includes(database)) {
    throw new RebuildRefused(
      `Refusing to rebuild '${database}': this database is rejected by name.`);
  }
  if (/prod/i.test(database)) {
    throw new RebuildRefused(
      `Refusing to rebuild '${database}': the name looks like production.`);
  }
  if (/pre_rebuild/i.test(database)) {
    throw new RebuildRefused(
      `Refusing to touch '${database}': preserved pre-rebuild databases are read-only.`);
  }
  // An allowlist, not a suffix rule: `random_test` is refused exactly as `afldb_scratch`
  // is. The former `_test` suffix check is subsumed — every allowed name is listed.
  // V2 Launch F: the isolated family is admitted by NAME only inside an isolated run
  // (isolatedRunPort); resolveIsolatedTarget() and executeRebuild() add the DSN and live-server
  // proofs, and a child stage handed an isolated name proves its own DSN (assertIsolatedRebuildDsn).
  const isolatedName = isIsolatedRebuildName(database) && isolatedRunPort(env) !== null;
  if (!isRebuildTarget(database) && !isolatedName) {
    throw new RebuildRefused(
      `Refusing to rebuild '${database}': the only explicit rebuild targets are `
      + `${describeRebuildTargets()}. A target is never inferred from a DSN.`);
  }
}

/**
 * Resolve and validate the rebuild target. Throws rather than returning a bad target,
 * and never includes a DSN or password in any message.
 *
 * Order matters and is deliberate: the SELECTED name is checked before any environment
 * variable is read (so `--target afldb_dev` is refused even on a host with no DSN at
 * all), then the selected target's OWN dedicated DSN is read, and the database that DSN
 * names must equal the selection. Nothing here consults another target's variables.
 */
export function resolveTarget(
  env: Record<string, string | undefined>,
  opts: { target?: string; allowOwnerImportDsn?: boolean; acknowledgeDestroy?: string } = {},
): ResolvedTarget {
  // V2 Launch F: the isolated family has its own, stricter resolution. Only the literal
  // `--target isolated` reaches it; every other value takes the unchanged path below.
  if (opts.target === ISOLATED_REBUILD_TARGET) return resolveIsolatedTarget(env, opts);
  const requested = opts.target ?? DEFAULT_TARGET;
  assertRebuildTargetName(requested);
  if (!isRebuildTarget(requested)) {
    // Unreachable after the assertion; keeps the lookup below fully typed.
    throw new RebuildRefused(`Refusing to rebuild '${requested}'.`);
  }
  const spec = REBUILD_TARGETS[requested];

  const adminDsn = env[spec.adminEnv];
  if (!adminDsn) {
    throw new RebuildRefused(
      `${spec.adminEnv} is not set. Target '${requested}' is rebuilt only through its own `
      + 'dedicated DSN; this runner never falls back to another database\'s connection.');
  }

  let database: string;
  try {
    database = databaseOf(adminDsn);
  } catch {
    throw new RebuildRefused(`${spec.adminEnv} is not a valid connection URL.`);
  }

  assertRebuildTargetName(database);
  if (database !== requested) {
    throw new RebuildRefused(
      `${spec.adminEnv} names database '${database}', not the selected target `
      + `'${requested}'. The target is never inferred from a DSN; fix the variable or the `
      + '--target flag so they agree.');
  }

  // AFLDB-ISSUE-313: the reset, the validation streams and (through the same variable) the
  // PRIVILEGES stage all hand this DSN to psql, which now refuses one whose password cannot be
  // moved off the command line. Find that here, before anything runs, rather than at the
  // PRIVILEGES stage two steps after the destructive reset.
  assertPsqlCanCarry(adminDsn, spec.adminEnv);
  // AFLDB-ISSUE-278: and refuse a DSN libpq would read as a different database or server than
  // the path just validated (the stream's own identity guard is the second line, not the first).
  assertDsnPinsTarget(adminDsn, spec.adminEnv);

  // Data stages must run as the restricted import role, never as owner and NEVER with the
  // development DSN this repository's .env sets. ISSUE-083 tracks the missing test import
  // credential; this runner fails closed rather than silently substituting owner access.
  // The import DSN is the target's OWN variable — never another target's, never the dev one.
  const restrictedImportDsn = env[spec.importEnv];
  let importDsn: string;
  let importIsOwnerSubstitution = false;

  if (restrictedImportDsn) {
    let importDatabase: string;
    try {
      importDatabase = databaseOf(restrictedImportDsn);
    } catch {
      throw new RebuildRefused(`${spec.importEnv} is not a valid connection URL.`);
    }
    if (importDatabase !== database) {
      throw new RebuildRefused(
        `${spec.importEnv} names a different database from ${spec.adminEnv}. `
        + `Both must point at '${requested}'.`);
    }
    // The importers (Python/psycopg) read this through libpq too.
    assertDsnPinsTarget(restrictedImportDsn, spec.importEnv);
    importDsn = restrictedImportDsn;
  } else if (opts.allowOwnerImportDsn) {
    importDsn = adminDsn;
    importIsOwnerSubstitution = true;
  } else {
    throw new RebuildRefused(
      `${spec.importEnv} is not set, so there is no restricted import credential for the `
      + `data stages. Set it to an afldb_import DSN for '${requested}', or pass `
      + '--allow-owner-import-dsn to run them as owner deliberately (that is the '
      + 'AFLDB-ISSUE-083 gap: a missing grant would then pass here and fail in production).');
  }

  return { database, adminDsn, importDsn, importIsOwnerSubstitution };
}

/** host:port of a DSN as postgres.js and the isolated guard read it (already proven to parse). */
function serverOf(dsn: string): string {
  const url = new URL(dsn);
  return `${url.hostname}:${url.port}`;
}

/**
 * V2 Launch F: resolve `--target isolated`. Every condition in the ISOLATED_REBUILD_TARGET
 * comment is checked here except the live-server one, which executeRebuild() runs before any
 * stage. Order: the environment declares an isolated run, then the operator's NAMED database,
 * then each DSN. Messages never contain a DSN.
 */
export function resolveIsolatedTarget(
  env: Record<string, string | undefined>,
  opts: { allowOwnerImportDsn?: boolean; acknowledgeDestroy?: string } = {},
): ResolvedTarget {
  const port = isolatedRunPort(env);
  if (port === null) {
    throw new RebuildRefused(
      `--target ${ISOLATED_REBUILD_TARGET} runs only inside an isolated run: AFLDB_V2_ISOLATED_PG=1 and a `
      + 'valid AFLDB_V2_ISOLATED_PORT must be set, as `npx tsx tools/v2/isolated-pg.ts run <name> -- ...` '
      + 'sets them. Nothing has been destroyed.');
  }
  if (opts.allowOwnerImportDsn) {
    throw new RebuildRefused(
      `--allow-owner-import-dsn is refused with --target ${ISOLATED_REBUILD_TARGET}: the isolated cluster `
      + 'always has the restricted afldb_import credential. Nothing has been destroyed.');
  }
  const named = opts.acknowledgeDestroy;
  if (!named) {
    throw new RebuildRefused(
      `--target ${ISOLATED_REBUILD_TARGET} needs --acknowledge-destroy <database>: the operator names the `
      + 'isolated database; it is never inferred from a DSN. Nothing has been destroyed.');
  }
  assertRebuildTargetName(named, env);
  if (!isIsolatedRebuildName(named)) {
    throw new RebuildRefused(
      `Refusing to rebuild '${named}' as an isolated target: the only isolated rebuild databases are `
      + `'${ISOLATED_REBUILD_DATABASE}' and names matching ${String(ISOLATED_REBUILD_NAME_PATTERN)}. `
      + 'Nothing has been destroyed.');
  }

  const spec = ISOLATED_REBUILD_SPEC;
  const adminDsn = env[spec.adminEnv];
  if (!adminDsn) {
    throw new RebuildRefused(`${spec.adminEnv} is not set (target ${ISOLATED_REBUILD_TARGET} '${named}').`);
  }
  let database: string;
  try {
    database = databaseOf(adminDsn);
  } catch {
    throw new RebuildRefused(`${spec.adminEnv} is not a valid connection URL.`);
  }
  if (database !== named) {
    throw new RebuildRefused(
      `${spec.adminEnv} names database '${database}', not the acknowledged isolated database '${named}'. `
      + 'Nothing has been destroyed.');
  }
  assertIsolatedRebuildDsn(adminDsn, port, spec.adminEnv);
  assertPsqlCanCarry(adminDsn, spec.adminEnv);
  assertDsnPinsTarget(adminDsn, spec.adminEnv);

  const importDsn = env[spec.importEnv];
  if (!importDsn) {
    throw new RebuildRefused(
      `${spec.importEnv} is not set, so there is no restricted import credential for the data stages `
      + `of '${named}'. Nothing has been destroyed.`);
  }
  let importDatabase: string;
  try {
    importDatabase = databaseOf(importDsn);
  } catch {
    throw new RebuildRefused(`${spec.importEnv} is not a valid connection URL.`);
  }
  if (importDatabase !== database) {
    throw new RebuildRefused(
      `${spec.importEnv} names a different database from ${spec.adminEnv}. Both must point at '${named}'.`);
  }
  assertIsolatedRebuildDsn(importDsn, port, spec.importEnv);
  assertDsnPinsTarget(importDsn, spec.importEnv);
  if (serverOf(importDsn) !== serverOf(adminDsn)) {
    throw new RebuildRefused(
      `${spec.importEnv} and ${spec.adminEnv} name different servers. Both must name the isolated `
      + 'cluster the same way. Nothing has been destroyed.');
  }

  return { database, adminDsn, importDsn, importIsOwnerSubstitution: false, isolated: { port } };
}

/**
 * V2 Launch F: the read-only stream behind Deps.isolatedServerFacts — the one row of
 * ISOLATED_SERVER_FACTS_SQL as COPY text, so nothing but data reaches stdout.
 */
export const ISOLATED_SERVER_FACTS_COPY_SQL =
  `COPY (${ISOLATED_SERVER_FACTS_SQL}) TO STDOUT;\n`;

/** Parse the COPY text row (tab-separated, `\N` for NULL). Throws on anything but one row of three. */
export function parseIsolatedServerFacts(stdout: string): IsolatedServerFacts {
  const lines = stdout.split(/\r?\n/).filter((line) => line !== '');
  const fields = lines.length === 1 ? lines[0].split('\t') : [];
  if (fields.length !== 3) {
    throw new RebuildRefused(
      `The isolated server facts query returned ${lines.length} line(s), not one row of three fields. `
      + 'Nothing has been destroyed.');
  }
  const value = (field: string) => (field === '\\N' ? null : field);
  return {
    clusterName: value(fields[0]),
    databaseComment: value(fields[1]),
    currentDatabase: value(fields[2]),
  };
}

/** Name-check environment for an isolated target, derived from the resolved target only. */
function isolatedNameEnv(target: ResolvedTarget): Record<string, string | undefined> {
  return target.isolated
    ? { AFLDB_V2_ISOLATED_PG: '1', AFLDB_V2_ISOLATED_PORT: String(target.isolated.port) }
    : process.env;
}

/**
 * V2 Launch F: the isolated target's last gate, run by executeRebuild() before ANY stage. It
 * re-proves both DSNs (a ResolvedTarget can be built by hand) and asks the live server who it
 * is. Any doubt is a refusal; nothing has run when it throws.
 */
export function assertIsolatedTargetLive(target: ResolvedTarget, deps: Deps): void {
  if (!target.isolated) {
    throw new RebuildRefused(
      `'${target.database}' is an isolated-cluster name but the target was not resolved by `
      + `--target ${ISOLATED_REBUILD_TARGET}. Nothing has been run.`);
  }
  if (!isIsolatedRebuildName(target.database)) {
    throw new RebuildRefused(
      `'${target.database}' is not an isolated rebuild database. Nothing has been run.`);
  }
  const { port } = target.isolated;
  for (const [dsn, name] of [[target.adminDsn, 'The admin DSN'], [target.importDsn, 'The import DSN']] as const) {
    assertIsolatedRebuildDsn(dsn, port, name);
    if (databaseOf(dsn) !== target.database) {
      throw new RebuildRefused(`${name} does not name '${target.database}'. Nothing has been run.`);
    }
  }
  if (serverOf(target.importDsn) !== serverOf(target.adminDsn)) {
    throw new RebuildRefused('The admin and import DSNs name different servers. Nothing has been run.');
  }
  if (!deps.isolatedServerFacts) {
    throw new RebuildRefused(
      'An isolated rebuild needs the live server check (Deps.isolatedServerFacts) and none is wired. '
      + 'Nothing has been run.');
  }
  let facts: IsolatedServerFacts;
  try {
    facts = deps.isolatedServerFacts(target.adminDsn);
  } catch (error) {
    throw new RebuildRefused(
      `Could not read the isolated server facts: ${(error as Error).message}. Nothing has been run.`);
  }
  const findings = checkIsolatedTestServer(target.database, facts);
  if (findings.length) {
    throw new RebuildRefused(
      `The server behind '${target.database}' is not the isolated cluster: ${describeFindings(findings)}. `
      + 'Nothing has been run.');
  }
  deps.log(`    isolated server verified: cluster ${facts.clusterName}, marker present, `
    + `current_database ${facts.currentDatabase}`);
}

/**
 * AFLDB-ISSUE-237 L2: `--rehearsal-stop-after` is valid ONLY with an explicit
 * `--target code_test_db` whose resolved database is `code_test_db`, and never together with
 * `--recover-afl-api-adjudications` (the halted run leaves a state only a SEPARATE, normal
 * `--recover` run may resolve). Called on the options before any environment variable is read,
 * again on the resolved target, and by executeRebuild() itself before any stage runs.
 */
export function assertRehearsalStop(
  opts: Pick<Options, 'target' | 'rehearsalStopAfter' | 'recoverAflApiAdjudications'>,
  resolvedDatabase?: string,
): void {
  if (opts.rehearsalStopAfter === undefined) return;
  if (!(REHEARSAL_STOP_BOUNDARIES as readonly string[]).includes(opts.rehearsalStopAfter)) {
    throw new RebuildRefused(
      `--rehearsal-stop-after '${String(opts.rehearsalStopAfter)}' is not a rehearsal boundary; the only one is 'recreate'.`);
  }
  if (opts.target !== REHEARSAL_STOP_TARGET) {
    throw new RebuildRefused(
      `--rehearsal-stop-after is an AFLDB-ISSUE-237 rehearsal control, valid only with an explicit `
      + `--target ${REHEARSAL_STOP_TARGET}; refusing it for '${opts.target ?? DEFAULT_TARGET}'`
      + `${opts.target === undefined ? ' (the default target)' : ''}. Nothing has been destroyed.`);
  }
  if (resolvedDatabase !== undefined && resolvedDatabase !== REHEARSAL_STOP_TARGET) {
    throw new RebuildRefused(
      `--rehearsal-stop-after resolved to database '${resolvedDatabase}', not ${REHEARSAL_STOP_TARGET}. `
      + 'Nothing has been destroyed.');
  }
  if (opts.recoverAflApiAdjudications) {
    throw new RebuildRefused(
      '--rehearsal-stop-after cannot be combined with --recover-afl-api-adjudications: the recovery '
      + 'run is always a separate, normal run. Nothing has been destroyed.');
  }
}

/** §10 point 5: destruction requires the operator to name the database explicitly. */
export function assertDestructiveAcknowledgement(
  target: ResolvedTarget,
  acknowledgeDestroy: string | undefined,
): void {
  if (acknowledgeDestroy !== target.database) {
    throw new RebuildRefused(
      `This rebuild DROPS every table, schema, routine and type in '${target.database}'. `
      + `Re-run with --acknowledge-destroy ${target.database} to confirm.`);
  }
}

/**
 * Select THE accepted baseline from the tracked acceptance register.
 *
 * Zero and many accepted baselines are BOTH refusals. There is deliberately no 'latest
 * label', filename-ordering or date tiebreak: deterministic selection among several
 * accepted baselines is not tracked policy, so this fails closed and a human decides.
 */
export function selectAcceptedBaseline(
  register: Record<string, unknown> | null,
): { label: string } {
  if (!register) {
    throw new RebuildRefused(
      `No fitzRoy acceptance register at ${ACCEPTED_BASELINES}. The rebuild has no canonical `
      + 'core source and will not guess one.');
  }
  if (register.contract !== 'afldb.fitzroy.accepted_baselines') {
    throw new RebuildRefused(
      `${ACCEPTED_BASELINES} is not an afldb.fitzroy.accepted_baselines document.`);
  }
  const policy = (register.selection_policy as Record<string, unknown> | undefined)?.rule;
  if (policy !== 'exactly_one_accepted') {
    throw new RebuildRefused(
      `The acceptance register declares selection policy '${String(policy)}', but the only `
      + "policy this rebuild implements is 'exactly_one_accepted'.");
  }
  const baselines = (register.baselines ?? []) as Array<Record<string, unknown>>;
  const accepted = baselines.filter((b) => b.acceptance_status === 'accepted');
  if (accepted.length === 0) {
    throw new RebuildRefused(
      `No fitzRoy baseline is marked accepted in ${ACCEPTED_BASELINES}. Validate and accept `
      + 'a full-history acquisition first.');
  }
  if (accepted.length > 1) {
    const names = accepted.map((b) => String(b.snapshot_label)).sort().join(', ');
    throw new RebuildRefused(
      `${accepted.length} fitzRoy baselines are marked accepted (${names}). Deterministic `
      + 'selection among several accepted baselines is not defined policy; mark exactly one '
      + 'accepted.');
  }
  return { label: String(accepted[0].snapshot_label) };
}

/**
 * Resolve the fitzRoy source for this rebuild.
 *
 * The NORMAL path takes no label: it resolves the accepted canonical baseline from the
 * tracked register, so `npm run db:test:rebuild` needs neither --fitzroy-label nor
 * --acknowledge-partial-fitzroy. Partial/trial data is still available for bounded testing
 * but only by naming the label AND acknowledging it — it is never selected implicitly.
 *
 * Nothing here is a verdict. The acceptance register BINDS (which acquisition, which
 * hashes, which contract version, which measured fingerprint); it never blesses. The sole
 * adjudicator remains `import_fitzroy_core.py --require-full-history`, which PRECHECK runs
 * before anything is destroyed — and which `--require-accepted-baseline` implies, so a
 * hand-edited register cannot bypass the gates it claims were passed.
 */
export function resolveFitzroySource(
  opts: { fitzroyLabel?: string; acknowledgePartialFitzroy?: boolean },
  deps: {
    readManifest?: (label: string) => Record<string, unknown> | null;
    readAcceptedRegister?: () => Record<string, unknown> | null;
  } = {},
): FitzroySource {
  const readJson = (path: string) => (existsSync(path)
    ? JSON.parse(readFileSync(path, 'utf8')) as Record<string, unknown>
    : null);
  const read = deps.readManifest
    ?? ((l: string) => readJson(join(REPO_ROOT, FITZROY_MANIFEST_DIR, `${l}.json`)));
  const readRegister = deps.readAcceptedRegister
    ?? (() => readJson(join(REPO_ROOT, ACCEPTED_BASELINES)));

  // Explicit partial/trial mode: opt-in only, and it must name its label.
  if (opts.acknowledgePartialFitzroy) {
    if (!opts.fitzroyLabel) {
      throw new RebuildRefused(
        '--acknowledge-partial-fitzroy needs --fitzroy-label <label>: partial mode never '
        + 'falls back to the accepted baseline, and the accepted baseline is never rebuilt '
        + 'as a partial.');
    }
    if (!read(opts.fitzroyLabel)) {
      throw new RebuildRefused(
        `No tracked fitzRoy manifest for label '${opts.fitzroyLabel}' under `
        + `${FITZROY_MANIFEST_DIR}/.`);
    }
    return {
      label: opts.fitzroyLabel,
      fullHistory: false,
      acknowledgedPartial: true,
      accepted: false,
      selection: 'explicit-partial',
    };
  }

  const acceptedLabel = selectAcceptedBaseline(readRegister()).label;

  if (opts.fitzroyLabel && opts.fitzroyLabel !== acceptedLabel) {
    const trial = KNOWN_TRIAL_LABELS.includes(opts.fitzroyLabel)
      ? ` '${opts.fitzroyLabel}' is a known trial snapshot and can never satisfy `
        + 'full-history mode.'
      : '';
    throw new RebuildRefused(
      `fitzRoy snapshot '${opts.fitzroyLabel}' is not the accepted canonical baseline `
      + `('${acceptedLabel}').${trial} Accept it in ${ACCEPTED_BASELINES}, or pass `
      + '--acknowledge-partial-fitzroy to rebuild deliberately from partial core data.');
  }

  if (!read(acceptedLabel)) {
    throw new RebuildRefused(
      `The accepted baseline '${acceptedLabel}' has no tracked acquisition manifest under `
      + `${FITZROY_MANIFEST_DIR}/.`);
  }

  return {
    label: acceptedLabel,
    fullHistory: true,
    acknowledgedPartial: false,
    accepted: true,
    selection: 'accepted-baseline',
  };
}

