/** The platform-local project interpreter, unchanged: this stays the default. */
export const DEFAULT_VENV_PYTHON = process.platform === 'win32'
  ? join('.venv', 'Scripts', 'python.exe')
  : join('.venv', 'bin', 'python');

/**
 * The Python interpreter every Python stage runs under.
 *
 * `AFLDB_PYTHON` is the portable override AFLDB already uses for exactly this case — a
 * checkout whose usable interpreter is not the in-tree `.venv`, which is the normal state
 * of a git worktree, since `.venv/` is not part of a checkout. Seven existing test suites
 * resolve Python the same way; this brings the rebuild harness onto the same contract
 * instead of hard-failing with a bare "The system cannot find the path specified."
 *
 * Deliberately NOT resolved by searching parent or sibling directories: an interpreter
 * found by walking out of the repository is an interpreter nobody chose, and this harness
 * drives a destructive rebuild. Explicit override, or the platform-local default.
 *
 * Read at call time, never captured at module load, so the environment a stage actually
 * runs under is the one that selected the interpreter.
 */
export function resolvePython(
  env: Readonly<Record<string, string | undefined>> = process.env,
): string {
  const override = (env.AFLDB_PYTHON ?? '').trim();
  return override !== '' ? override : DEFAULT_VENV_PYTHON;
}

/**
 * The fixed dependency order. Pure: given a target and sources it returns the exact
 * stages, so ordering and command construction are tested without running anything.
 */
export function planStages(target: ResolvedTarget, fitzroy: FitzroySource,
                           opts: Options): Stage[] {
  const dataEnv = { AFLDB_IMPORT_DATABASE_URL: target.importDsn };
  // One resolution for the whole graph, so no two stages can disagree.
  const python = resolvePython();

  // The schema and privilege stages run through package scripts, and each target has its
  // own pair bound to its own DSN variable. A ResolvedTarget only ever carries an
  // allowlisted name, but the graph refuses rather than guesses if it does not. V2 Launch F:
  // an isolated target (resolved only by resolveIsolatedTarget) uses ISOLATED_REBUILD_SPEC.
  const spec = rebuildSpecFor(target);
  const censusScope = aflApiOwnershipCensusScope();

  return [
    {
      id: 'precheck',
      name: 'PRECHECK — every required input, before anything is destroyed',
      kind: 'precheck',
      run: 'internal',
    },
    {
      // AFLDB-ISSUE-233 D-233-3. Read-only, on the database about to be reset, before the
      // capture writes its marker and before the reset. Unconditional: no option skips it.
      id: AFL_API_OWNERSHIP_CENSUS_STAGE,
      name: `AFL API OWNERSHIP CENSUS — refuse if any completed season in `
        + `${describeScope(censusScope)} holds an afl_api-owned canonical match `
        + '(read-only, before anything is captured or destroyed)',
      kind: 'validation',
      run: 'validate',
      sql: aflApiOwnershipCensusSql(censusScope),
    },
    {
      // AFLDB-ISSUE-235 OD-5 (i). The human afl_api adjudication ledger is the one piece of
      // state here that no tracked source can rebuild, so it is captured AFTER every input
      // is proven and BEFORE the reset. A capture failure is a stage failure: the reset
      // below never runs. An empty ledger (or a database before migration 104) is captured
      // as empty; a pending capture an earlier failed run never reinstated is refused
      // rather than overwritten (--recover-afl-api-adjudications adopts it instead), and
      // one the live ledger already equals is verified as reinstated, read-only, before
      // it is archived (the post-commit/pre-archive crash).
      id: 'afl-api-adjudications-capture',
      name: 'AFL API ADJUDICATIONS — capture the human identity ledger, the importer-created '
        + 'identities AND the manual player registrations before anything is destroyed'
        + (opts.recoverAflApiAdjudications ? ' (RECOVER: adopt the pending capture)' : ''),
      kind: 'capture',
      run: 'command',
      argv: aflApiAdjudicationArgv('capture', opts.recoverAflApiAdjudications),
      envOverlay: aflApiAdjudicationEnv(target, 'capture'),
    },
    {
      id: 'recreate',
      name: `DATABASE RESET — clear ${target.database}`,
      kind: 'destructive',
      run: 'sql',
    },
    {
      id: 'migrations',
      name: 'MIGRATIONS — the complete tracked set',
      kind: 'schema',
      run: 'command',
      argv: ['npm', 'run', spec.migrateScript],
      envOverlay: { AFLDB_MIGRATE_TARGET: spec.migrateTarget },
    },
    {
      id: 'privileges',
      name: 'PRIVILEGES — reconcile roles from the registries',
      kind: 'privileges',
      run: 'command',
      argv: ['npm', 'run', spec.privilegesScript],
    },
    {
      id: 'reference',
      name: 'REFERENCE DATA — tracked canonical datasets',
      kind: 'data',
      run: 'command',
      argv: [python, 'tools/migration/load_reference_data.py'],
      envOverlay: dataEnv,
    },
    {
      id: 'fitzroy',
      name: `FITZROY CORE — ${fitzroy.label}`,
      kind: 'data',
      run: 'command',
      argv: [python, 'tools/migration/import_fitzroy_core.py',
             '--label', fitzroy.label],
      envOverlay: dataEnv,
    },
    {
