/**
 * The DraftGuru snapshot used when --draftguru-label is not given. It is the runner's
 * single default; import_draftguru.py's own STAGE_A_LABEL is never relied on, because the
 * runner now always passes --label explicitly to BOTH the preflight and the data stage.
 */
export const DEFAULT_DRAFTGURU_LABEL = 'annual-html-20260826';

export function parseArgs(argv: string[]): Options {
  const opts: Options = {
    draftguruLabel: DEFAULT_DRAFTGURU_LABEL,
    planOnly: false,
  };
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--target') {
      // A bare `--target` must not silently fall through to the default database.
      const value = argv[i + 1];
      if (!value || value.startsWith('--')) {
        throw new RebuildRefused(
          `--target needs a database name: one of ${describeRebuildTargets()}.`);
      }
      opts.target = value;
      i += 1;
    } else if (arg === '--fitzroy-label') opts.fitzroyLabel = argv[++i];
    else if (arg === '--draftguru-label') opts.draftguruLabel = argv[++i];
    else if (arg === '--draftguru-bridge') opts.draftguruBridge = argv[++i];
    else if (arg === '--acknowledge-destroy') opts.acknowledgeDestroy = argv[++i];
    else if (arg === '--acknowledge-partial-fitzroy') opts.acknowledgePartialFitzroy = true;
    else if (arg === '--allow-owner-import-dsn') opts.allowOwnerImportDsn = true;
    else if (arg === '--recover-afl-api-adjudications') opts.recoverAflApiAdjudications = true;
    else if (arg === '--rehearsal-stop-after') {
      // Exactly one closed value; an arbitrary stage name is never accepted.
      const value = argv[i + 1];
      if (opts.rehearsalStopAfter !== undefined) {
        throw new RebuildRefused('--rehearsal-stop-after may be given only once.');
      }
      if (!(REHEARSAL_STOP_BOUNDARIES as readonly (string | undefined)[]).includes(value)) {
        throw new RebuildRefused(
          `--rehearsal-stop-after accepts exactly 'recreate' (got '${value ?? ''}'); no other stage `
          + 'is a rehearsal boundary.');
      }
      opts.rehearsalStopAfter = value as RehearsalStopBoundary;
      i += 1;
    } else if (arg === '--plan') opts.planOnly = true;
    else throw new RebuildRefused(`Unknown argument: ${arg}`);
  }
  return opts;
}

// FINGERPRINT_QUERIES lived here: six unscoped `count(*)`s, exported and never called by
// anything, with no expected values to compare against. It is replaced by
// finalValidationChecks()/buildFinalValidationSql() above, which are bound to the accepted
// register and actually fail the run. Removed rather than left as a decorative export.

/**
 * The CLI's real dependencies: child processes from the repository root, the destructive
 * reset and the read-only validation stream through the shared psql helper. Exported so the
 * AFLDB-ISSUE-249 code_test_db rehearsal (tools/records/first-kick-goal-rehearsal.ts) can
 * dispatch a planned stage through exactly this path rather than a copy of it.
 */
export function createCliDeps(spawnSync: typeof import('node:child_process').spawnSync): Deps {
  return {
    runCommand: (argv, env) => {
      const [command, ...args] = argv;
      const result = spawnSync(command, args, {
        cwd: REPO_ROOT,
        encoding: 'utf8',
        shell: process.platform === 'win32',
        // The child gets an EXPLICIT import DSN. It never inherits the development value.
        // AFLDB-ISSUE-278: nor an inherited libpq routing variable (PGHOSTADDR, PGPORT,
        // PGSERVICE, ...): the importers read their DSN through libpq (psycopg), which would
        // apply it to anything the URL leaves unset. The parent environment is not modified.
        env: { ...withoutLibpqRouting(process.env), ...env },
      });
      if (result.stdout) process.stdout.write(result.stdout);
      if (result.stderr) process.stderr.write(result.stderr);
      return { status: result.status ?? 1, stdout: result.stdout ?? '', stderr: result.stderr ?? '' };
    },
    // psql, not postgres.js, and via the SHARED helper in tools/db/psql.ts — the same
    // binary, argv and error handling the rollback-only proof uses, so proving the proof
    // proves this path too.
    //
    // `executeRebuild` is synchronous by design (the whole stage graph is) and Node cannot
    // await inside it. The previous postgres.js form (`void client.unsafe(sql)`) never
    // called .then/.execute(), so postgres.js NEVER SENT THE RESET and the stage reported
    // success against an untouched database.
    runSql: (dsn, sql) => {
      // `pinned` (AFLDB-ISSUE-278): no inherited routing variable, no psqlrc. The proof does the same.
      const result = runPsql(dsn, sql, { spawn: spawnSync as SpawnSyncLike, cwd: REPO_ROOT, pinned: true });
      if (result.stdout) process.stdout.write(result.stdout);
      if (result.status !== 0) {
        // psql error text names relations and roles, never the DSN or a password.
        throw new Error(`psql exited ${result.status}: ${result.stderr.trim()}`);
      }
    },
    // The final validation reports every measured value through RAISE WARNING, which psql
    // writes to STDERR — so unlike the reset, this stream's output must be relayed on the
    // SUCCESS path too. Without it a passing run would print a verdict and no evidence.
    runValidation: (dsn, sql) => {
      const result = runPsql(dsn, sql, { spawn: spawnSync as SpawnSyncLike, cwd: REPO_ROOT, pinned: true });
      if (result.stdout) process.stdout.write(result.stdout);
      if (result.stderr) process.stderr.write(result.stderr);
      if (result.status !== 0) {
        // AFLDB-ISSUE-233: the same read-only path carries the pre-reset ownership census,
        // whose failure is a refusal of an UNTOUCHED database, not a bad rebuild.
        if (sql.includes(AFL_API_OWNERSHIP_CENSUS_MARKER)) {
          throw new Error(
            `AFL API OWNERSHIP CENSUS refused (psql exited ${result.status}). The ${AFL_API_OWNERSHIP_CENSUS_MARKER} `
            + 'lines above name every affected season and its count. Nothing has been captured or destroyed.');
        }
        throw new Error(
          `FINAL VALIDATION did not pass (psql exited ${result.status}). The rebuilt `
          + 'database does not match the accepted contracts; treat the rebuild as FAILED.');
      }
    },
    // AFLDB_PYTHON is normally an ABSOLUTE path, and path.join does not reset on one:
    // join('D:/repo', 'C:/py.exe') yields 'D:/repo/C:/py.exe'. Resolving relative to
    // the repo root unconditionally would have rejected every valid override.
    fileExists: (path) => existsSync(isAbsolute(path) ? path : join(REPO_ROOT, path)),
    log: (line) => console.log(line),
    // V2 Launch F: read-only, through the same pinned psql path; only used for isolated targets.
    isolatedServerFacts: (dsn) => {
      const result = runPsql(dsn, ISOLATED_SERVER_FACTS_COPY_SQL,
        { spawn: spawnSync as SpawnSyncLike, cwd: REPO_ROOT, pinned: true });
      if (result.status !== 0) throw new Error(`psql exited ${result.status}: ${result.stderr.trim()}`);
      return parseIsolatedServerFacts(result.stdout);
    },
  };
}

